INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dzhechko/2026-jan-pu-Intercom-clone-02/goap-research-ed25519', 'goap-research-ed25519', 'dzhechko', '2026-jan-pu-Intercom-clone-02', 'community', 'goap-research-ed25519 dzhechko 2026-jan-pu-Intercom-clone-02 community The goap-research-ed25519 skill combines GOAP with Ed25519 cryptographic verification for advanced research systems, benefiting developers and researchers seeking robust anti-hallucination protection. GOAP 研究技能 Ed25519 验证是一种高级研究系统，结合 Goal-Oriented Action Planning 和 Ed25519 加密验证 GOAP 研究スキル Ed25519 検証は、目標指向アクションプランニングと Ed25519 暗号検証を組み合わせた高度な研究システムです GOAP 연구 스킬 Ed25519 검증은 목표 지향 액션 계획과 Ed25519 암호화 검증을 결합한 고급 연구 시스템입니다 goap-research-ed25519 combina la planificación de acciones orientadas a objetivos con verificación criptográfica Ed25519 para una protección anti-hallucinación avanzada goap-research-ed25519 combine la planification d''actions orientées vers les objectifs avec la vérification cryptographique Ed25519 pour une protection anti-hallucination avancée goap-research-ed25519 kombiniert die zielorientierte Aktionsplanung mit der Ed25519-kryptographischen Verifizierung für einen erweiterten Anti-Halluzinationsschutz O goap-research-ed25519 é um sistema de pesquisa avançado que combina o planejamento de ações orientado a objetivos com verificação criptográfica Ed25519. goap-research-ed25519 - это продвинутая система исследования, сочетающая планирование действий, ориентированное на цели, с криптографической верификацией Ed25519. goap-research-ed25519 هو نظام البحث المتقدم الذي يجمع بين التخطيط الإجرائي الموجه للغرض مع التحقق الكريپتوجرافي Ed25519. how to use goap-research-ed25519 goap-research-ed25519 setup guide Ed25519 cryptographic verification Goal-Oriented Action Planning (GOAP) goap-research-ed25519 alternative goap-research-ed25519 vs standard GOAP GOAP 研究技能 Ed25519 验证 AIエージェント 加密签名 可靠性评分 跨引用验证 签名链验证 Combines Goal-Oriented Action Planning (GOAP) with Ed25519 cryptographic verification Utilizes cryptographic signatures for source trust and claim verification Employs a signature chain for enhanced cross-reference and verification Provides advanced anti-hallucination protection for research systems Integrates reliability scoring with cryptographic signatures for robust verification goap-research-ed25519 is an advanced research system that integrates Goal-Oriented Action Planning (GOAP) with Ed25519 cryptographic verification for enhanced security and anti-hallucination protection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Tupatuko2023/Python-R-Scripts/fof-qc-summarizer', 'community', 'Tupatuko2023', 'Python-R-Scripts', 'Tupatuko2023/Python-R-Scripts', 'fof-qc-summarizer', 0, 0, 54, '2026-03-06T12:59:22.233Z', '2026-03-06T14:22:15.528Z', 'a185ead4e3288f215813854caf8cc90c4f62f8dca21dc362efb42d0fa462d7dc', '{"id":"Tupatuko2023/Python-R-Scripts/fof-qc-summarizer","name":"fof-qc-summarizer","description":{"en":"The fof-qc-summarizer skill generates QC summaries using R scripts, benefiting developers working with Fear-of-Falling projects. It provides optional overrides for custom directory paths and script labels.","zh":"fof-qc-summarizer 是一个用于总结 QC 输出的 AI 工具，通过 R 脚本实现","ja":"fof-qc-summarizer は QC 出力を要約する AI エージェントで、R スクリプトで実装されています","ko":"fof-qc-summarizer는 QC 출력을 요약하는 인공지능 툴로 R 스크립트로 구현됩니다","es":"fof-qc-summarizer es una herramienta para resumir salidas de calidad con Rscript. Se ejecuta desde la raíz del subproyecto Fear-of-Falling o la raíz del repositorio","fr":"fof-qc-summarizer est un outil pour résumer les sorties de qualité avec Rscript. Il s''exécute à partir de la racine du sous-projet Fear-of-Falling ou de la racine du référentiel","de":"fof-qc-summarizer ist ein Tool zur Zusammenfassung von Qualitätsausgaben mit Rscript. Es wird vom Root des Fear-of-Falling-Subprojekts oder des Repository-Roots aus ausgeführt","pt":"O fof-qc-summarizer é uma ferramenta que resume saídas de QC. Execute-o com Rscript e personalize a saída.","ru":"fof-qc-summarizer - это инструмент, который суммирует выводы QC. Запустите его с помощью Rscript и настройте вывод.","ar":"فوف-qc-summarizer هو أداة تلخص إخراجات QC. يمكن تشغيله مع Rscript وتخصيص الإخراج."},"seo":{"title":{"en":"fof-qc-summarizer: R Script Setup Guide | AI Agent Skill","zh":"fof-qc-summarizer 设置指南 - AI工具","ja":"fof-qc-summarizer のベストプラクティス - AIエージェント","ko":"fof-qc-summarizer 사용 가이드 - 인공지능 툴","es":"Guía de configuración de fof-qc-summarizer para resúmenes...","fr":"Guide d''installation de fof-qc-summarizer pour les résumé...","de":"Einrichtungsleitfaden für fof-qc-summarizer zur Qualitäts...","pt":"Guia de Configuração do fof-qc-summarizer","ru":"Настройка ИИ Агента fof-qc-summarizer","ar":"دليل إعداد فوف-qc-summarizer"},"description":{"en":"Discover how to run fof-qc-summarizer from the Fear-of-Falling subproject root. Learn to override default settings and generate QC summaries with ease. Get s...","zh":"了解如何使用 fof-qc-summarizer AI工具来提高您的开发效率","ja":"fof-qc-summarizer AIエージェントの使い方と最適な設定方法","ko":"fof-qc-summarizer 인공지능 툴을 사용하여 개발 생산성을 높이세요","es":"Aprende a utilizar fof-qc-summarizer para resumir salidas de calidad con Rscript y opciones de sobrescritura","fr":"Découvrez comment utiliser fof-qc-summarizer pour résumer les sorties de qualité avec Rscript et options de substitution","de":"Erfahren Sie, wie Sie fof-qc-summarizer verwenden, um Qualitätsausgaben mit Rscript und Überschreibungsoptionen zusammenzufassen","pt":"Aprenda a usar o fof-qc-summarizer com o Rscript e descubra como personalizar a saída com overrides","ru":"Узнайте, как использовать fof-qc-summarizer с помощью Rscript и настройте вывод с помощью переопределений","ar":"تعرف على كيفية استخدام فوف-qc-summarizer مع Rscript وكيفية تخصيص الإخراج باستخدام الإعدادات المسبقة"},"definition":{"en":"fof-qc-summarizer is a skill that utilizes R scripts to summarize QC outputs, supporting custom directory paths and script labels for flexible execution.","zh":"fof-qc-summarizer 是一个 AI 工具，用于总结 QC 输出","ja":"fof-qc-summarizer は QC 出力を要約する AI エージェントです","ko":"fof-qc-summarizer는 QC 출력을 요약하는 인공지능 툴입니다","es":"fof-qc-summarizer es una herramienta de resumen de calidad que utiliza Rscript para procesar salidas de calidad","fr":"fof-qc-summarizer est un outil de résumé de qualité qui utilise Rscript pour traiter les sorties de qualité","de":"fof-qc-summarizer ist ein Qualitätszusammenfassungstool, das Rscript zur Verarbeitung von Qualitätsausgaben verwendet","pt":"O que é fof-qc-summarizer? É uma ferramenta de resumo de saídas de QC.","ru":"Что такое fof-qc-summarizer? Это инструмент для суммирования выводов QC.","ar":"ما هو فوف-qc-summarizer؟ هو أداة تلخص إخراجات QC."},"features":{"en":["Runs from the Fear-of-Falling subproject root or repo root using Rscript","Supports optional overrides for QC directory, output directory, and script label","Utilizes R scripts for QC summary generation, such as qc_summarize.R","Scans for init.R files with append_manifest() and manifest_row() for manifest helpers","Processes QC outputs under Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/"],"zh":["使用 R 脚本实现 QC 输出总结","支持自定义 QC 目录和输出目录","支持脚本标签的设置","可以扫描 init.R 文件以发现 manifest 帮助器"],"ja":["R スクリプトで QC 出力を要約する","QC ディレクトリと出力ディレクトリのカスタマイズをサポート","スクリプトラベルを設定する機能","init.R ファイルをスキャンしてマニフェストヘルパーを発見"],"ko":["R 스크립트로 QC 출력을 요약하는 기능","QC 디렉토리와 출력 디렉토리의 설정을 지원","스크립트 레이블을 설정하는 기능","init.R 파일을 스캔하여 매니페스트 헬퍼를 발견"],"es":["Ejecución con Rscript","Opciones de sobrescritura para directorios y etiquetas","Procesamiento de salidas de calidad en Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/","Descubrimiento de helpers de manifiesto mediante la búsqueda de init.R","Compatibilidad con append_manifest() y manifest_row()"],"fr":["Exécution avec Rscript","Options de substitution pour les répertoires et les étiquettes","Traitement des sorties de qualité dans Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/","Découverte des helpers de manifeste via la recherche de init.R","Compatibilité avec append_manifest() et manifest_row()"],"de":["Ausführung mit Rscript","Überschreibungsoptionen für Verzeichnisse und Labels","Verarbeitung von Qualitätsausgaben in Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/","Entdeckung von Manifest-Helfern durch die Suche nach init.R","Kompatibilität mit append_manifest() und manifest_row()"],"pt":["Execução com Rscript","Personalização da saída com overrides","Leitura de saídas de QC em diretórios personalizados","Saída personalizada com rótulos de script","Descoberta de ajudantes de manifesto por meio de scanning de init.R","Uso de append_manifest() e manifest_row() para ajudantes de manifesto"],"ru":["Запуск с помощью Rscript","Настройка вывода с помощью переопределений","Чтение выводов QC из пользовательских директорий","Пользовательский вывод с метками скрипта","Обнаружение помощников манифеста путем сканирования init.R","Использование append_manifest() и manifest_row() для помощников манифеста"],"ar":["تشغيل مع Rscript","تخصيص الإخراج باستخدام الإعدادات المسبقة","قراءة إخراجات QC من الدلائل المخصصة","إخراج مخصص مع تسميات البرامج النصية","اكتشاف مساعدي الملف الشخصي من خلال مسح init.R","استخدام append_manifest() و manifest_row() لمساعدي الملف الشخصي"]},"keywords":{"en":["how to use fof-qc-summarizer","fof-qc-summarizer setup guide","R script for QC summary","Fear-of-Falling project tools","fof-qc-summarizer alternative","QC summary generation","Rscript command","custom directory paths for fof-qc-summarizer"],"zh":["fof-qc-summarizer","AI工具","R脚本","QC输出总结","自定义QC目录","脚本标签设置"],"ja":["fof-qc-summarizer","AIエージェント","Rスクリプト","QC出力要約","QCディレクトリのカスタマイズ","スクリプトラベル設定"],"ko":["fof-qc-summarizer","인공지능 툴","R 스크립트","QC 출력 요약","QC 디렉토리 설정","스크립트 레이블 설정"],"es":["fof-qc-summarizer","Rscript","resumen de calidad","Fear-of-Falling","salidas de calidad","herramientas de calidad","Agentes de Inteligencia Artificial","Herramientas de AI"],"fr":["fof-qc-summarizer","Rscript","résumé de qualité","Fear-of-Falling","sorties de qualité","outils de qualité","Agents d''Intelligence Artificielle","Outils d''IA"],"de":["fof-qc-summarizer","Rscript","Qualitätszusammenfassung","Fear-of-Falling","Qualitätsausgaben","Qualitätstools","Künstliche Intelligenz Agenten","KI-Tools"],"pt":["fof-qc-summarizer","Rscript","QC","resumo de saídas","personalização de saída","overrides","diretórios personalizados","ajudantes de manifesto","append_manifest()","manifest_row()"],"ru":["fof-qc-summarizer","Rscript","QC","суммирование выводов","настройка вывода","переопределения","пользовательские директории","помощники манифеста","append_manifest()","manifest_row()"],"ar":["فوف-qc-summarizer","Rscript","QC","تلخيص إخراجات","تخصيص الإخراج","الإعدادات المسبقة","الدلائل المخصصة","مساعدي الملف الشخصي","append_manifest()","manifest_row()"]}},"owner":"Tupatuko2023","repo":"Python-R-Scripts","repoPath":"Tupatuko2023/Python-R-Scripts","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.233Z","topics":[],"category":"community","skillMd":{"name":"fof-qc-summarizer","description":"Aggregate-only summarizer for K18 QC artifacts; produces summary outputs and appends manifest rows when format is confirmed.","bodyPreview":"## How to use\n\nRun from the Fear-of-Falling subproject root or repo root.\n\nExample:\n\n```bash\nRscript .codex/skills/fof-qc-summarizer/scripts/qc_summarize.R\n```\n\nOptional overrides:\n\n```bash\nRscript .codex/skills/fof-qc-summarizer/scripts/qc_summarize.R --qc-dir PATH --out-dir PATH --script-label K18_QC_SUMMARY\n```\n\n## Inputs\n\n- QC outputs under `Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/`.\n- Manifest helpers discovered by scanning for `init.R` with `append_manifest()` and `manifest_row()`.","body":"## How to use\n\nRun from the Fear-of-Falling subproject root or repo root.\n\nExample:\n\n```bash\nRscript .codex/skills/fof-qc-summarizer/scripts/qc_summarize.R\n```\n\nOptional overrides:\n\n```bash\nRscript .codex/skills/fof-qc-summarizer/scripts/qc_summarize.R --qc-dir PATH --out-dir PATH --script-label K18_QC_SUMMARY\n```\n\n## Inputs\n\n- QC outputs under `Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/`.\n- Manifest helpers discovered by scanning for `init.R` with `append_manifest()` and `manifest_row()`.\n- Policy sources: `Fear-of-Falling/CLAUDE.md`, `Fear-of-Falling/QC_CHECKLIST.md`.\n\n## Outputs\n\n- `Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc_summary/qc_summary.csv`\n- `Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc_summary/qc_summary.txt`\n- One manifest row per new artifact (if manifest format is confirmed).\n\n## Failure modes\n\n- Fear-of-Falling project root not found.\n- QC outputs directory missing.\n- Manifest helpers missing.\n- Manifest header mismatch (fail closed).\n- No eligible aggregate QC artifacts to summarize.\n\n## Safety/guardrails\n\n- FAIL CLOSED: if manifest helpers or format are not verifiable, the script exits 1.\n- Privacy: skips any file with `ids`, `row_level`, or `participant` in the name or\n  an `id`-like column; never writes participant-level rows.\n- No external APIs or network calls.\n- Does not modify raw data or QC inputs.\n\nSources: `Fear-of-Falling/CLAUDE.md`, `Fear-of-Falling/QC_CHECKLIST.md`.\n"},"lastSynced":"2026-03-06T14:22:15.528Z","agentAnalysis":{"suitability":{"en":"Perfect for R Script Agents needing advanced QC summary generation for Fear-of-Falling projects.","zh":"适用于需要高级 QC 摘要生成的 Fear-of-Falling 项目的 R Script Agents。","ja":"Fear-of-Falling プロジェクトの高度な QC サマリ生成を必要とする R スクリプト エージェントに最適です。","ko":"Fear-of-Falling 프로젝트에 대한 고급 QC 요약 생성이 필요한 R Script 에이전트에 적합합니다.","es":"Perfecto para Agentes de Script R que necesitan la generación avanzada de resúmenes de control de calidad para proyectos de Miedo a Caerse.","fr":"Parfait pour les agents de script R ayant besoin d''une génération de résumés de contrôle qualité avancée pour les projets de Peur de Tomber.","de":"Perfekt für R-Script-Agents, die eine erweiterte QC-Zusammenfassungsgenerierung für Fear-of-Falling-Projekte benötigen.","pt":"Perfeito para Agentes de Script R que necessitam de geração avançada de resumo de QC para projetos de Medo de Queda.","ru":"Идеально подходит для агентов скриптов R, которым требуется продвинутая генерация сводки контроля качества для проектов Страха падения.","ar":"مثالي لعميل البرامج النصية R الذين يحتاجون إلى توليد ملخص QC متقدم لمشاريع خوف السقوط."},"recommendation":{"en":"Empowers agents to generate QC summaries using R scripts, providing optional overrides for custom directory paths and script labels, and leveraging manifest helpers discovered by scanning for init.R files with append_manifest() and manifest_row() functions.","zh":"赋予代理生成 QC 摘要的能力，使用 R 脚本，并提供自定义目录路径和脚本标签的可选覆盖，并利用通过扫描带有 append_manifest() 和 manifest_row() 函数的 init.R 文件发现的 manifest 辅助工具。","ja":"エージェントに QC サマリを生成する能力を与え、R スクリプトを使用し、カスタム ディレクトリ パスとスクリプト ラベルに対するオプションのオーバーライドを提供し、append_manifest() と manifest_row() 関数を使用した init.R ファイルのスキャンにより発見されたマニフェスト ヘルパーを利用します。","ko":"에이전트가 R 스크립트를 사용하여 QC 요약을 생성할 수 있도록 하며, 사용자 지정 디렉토리 경로 및 스크립트 레이블에 대한 선택적 오버라이드를 제공하며, append_manifest() 및 manifest_row() 함수를 사용하여 init.R 파일을 스캔하여 발견된 매니페스트 도우미를 활용합니다.","es":"Habilita a los agentes a generar resúmenes de control de calidad utilizando scripts R, proporcionando anulaciones opcionales para rutas de directorios personalizados y etiquetas de script, y aprovechando los ayudantes de manifiesto descubiertos mediante el análisis de archivos init.R con las funciones append_manifest() y manifest_row().","fr":"Permet aux agents de générer des résumés de contrôle qualité en utilisant des scripts R, en fournissant des substitutions optionnelles pour les chemins de répertoires personnalisés et les libellés de script, et en exploitant les aides de manifeste découvertes en analysant les fichiers init.R avec les fonctions append_manifest() et manifest_row().","de":"Ermöglicht es Agenten, QC-Zusammenfassungen mit R-Skripten zu generieren, optional Überprüfungen für benutzerdefinierte Verzeichnispfade und Skriptetiketten bereitzustellen und manifest-Helfer zu nutzen, die durch die Analyse von init.R-Dateien mit den Funktionen append_manifest() und manifest_row() entdeckt wurden.","pt":"Habilita os agentes a gerar resumos de QC usando scripts R, fornecendo opções de substituição para caminhos de diretório personalizados e rótulos de script, e aproveitando os ajudantes de manifesto descobertos digitalizando arquivos init.R com as funções append_manifest() e manifest_row().","ru":"Предоставляет агентам возможность генерировать сводки контроля качества с помощью скриптов R, предлагая необязательные переопределения для пользовательских путей директорий и меток скриптов, а также использует помощников манифеста, обнаруженных при сканировании файлов init.R с функциями append_manifest() и manifest_row().","ar":"تمكّن الوكيل من توليد ملخصات QC باستخدام برامج نصية R ، و يوفر خيارات بديلة لمسارات الدلائل المخصصة وملصقات البرامج النصية ، و يستفيد من مساعدي الملفات المكتشفة من خلال مسح ملفات init.R مع وظائف append_manifest() و manifest_row()."},"useCases":{"en":["Generating QC summaries for Fear-of-Falling projects","Customizing QC summary outputs using optional directory path overrides","Automating manifest helper discovery for streamlined QC summary generation"],"zh":["为 Fear-of-Falling 项目生成 QC 摘要","使用可选的目录路径覆盖自定义 QC 摘要输出","自动化 manifest 辅助工具发现以实现 QC 摘要生成的简化"],"ja":["Fear-of-Falling プロジェクトの QC サマリを生成する","オプションのディレクトリ パス オーバーライドを使用して QC サマリの出力をカスタマイズする","マニフェスト ヘルパーの自動発見を使用して QC サマリの生成を簡素化する"],"ko":["Fear-of-Falling 프로젝트에 대한 QC 요약 생성","선택적 디렉토리 경로 오버라이드를 사용하여 QC 요약 출력 사용자 정의","매니페스트 도우미 자동 발견을 사용하여 QC 요약 생성 단순화"],"es":["Generación de resúmenes de control de calidad para proyectos de Miedo a Caerse","Personalización de las salidas de resúmenes de control de calidad mediante anulaciones de rutas de directorios opcionales","Automatización de la descubierta de ayudantes de manifiesto para una generación de resúmenes de control de calidad optimizada"],"fr":["Génération de résumés de contrôle qualité pour les projets de Peur de Tomber","Personnalisation des sorties de résumés de contrôle qualité à l''aide de substitutions de chemins de répertoires optionnelles","Automatisation de la découverte d''aides de manifeste pour une génération de résumés de contrôle qualité rationalisée"],"de":["Erstellung von QC-Zusammenfassungen für Fear-of-Falling-Projekte","Anpassung der QC-Zusammenfassungsausgaben mithilfe optionaler Verzeichnispfadanulierungen","Automatisierung der Entdeckung von Manifest-Helfern für eine optimierte QC-Zusammenfassungsgenerierung"],"pt":["Geração de resumos de QC para projetos de Medo de Queda","Personalização de saídas de resumo de QC usando opções de substituição de caminho de diretório","Automação da descoberta de ajudantes de manifesto para geração de resumo de QC otimizada"],"ru":["Генерация сводок контроля качества для проектов Страха падения","Настройка выходных данных сводки контроля качества с помощью опциональных переопределений пути директории","Автоматизация обнаружения помощников манифеста для оптимизированной генерации сводки контроля качества"],"ar":["توليد ملخصات QC لمشاريع خوف السقوط","تخصيص مخرجات ملخص QC باستخدام خيارات بديلة لمسارات الدلائل","آليّة اكتشاف مساعدي الملفات من أجل توليد ملخص QC المُثلى"]},"limitations":{"en":["Requires R script execution capabilities","Limited to Fear-of-Falling project structures","Dependent on specific directory paths and file structures (e.g., Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"zh":["需要 R 脚本执行能力","仅限 Fear-of-Falling 项目结构","依赖于特定的目录路径和文件结构（例如，Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/）"],"ja":["R スクリプトの実行機能が必要","Fear-of-Falling プロジェクト構造に限定される","特定のディレクトリ パスとファイル構造（例：Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/）に依存する"],"ko":["R 스크립트 실행 기능이 필요함","Fear-of-Falling 프로젝트 구조에만 제한됨","특정 디렉토리 경로 및 파일 구조（예：Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/）에 의존"],"es":["Requiere capacidades de ejecución de scripts R","Limitado a estructuras de proyectos de Miedo a Caerse","Dependiente de rutas de directorios y estructuras de archivos específicas (por ejemplo, Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"fr":["Nécessite des capacités d''exécution de scripts R","Limité aux structures de projets de Peur de Tomber","Dépendant de chemins de répertoires et de structures de fichiers spécifiques (par exemple, Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"de":["Benötigt R-Script-Ausführungsfähigkeiten","Begrenzt auf Fear-of-Falling-Projektstrukturen","Abhängig von spezifischen Verzeichnispfaden und Dateistrukturen (z.B. Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"pt":["Exige capacidades de execução de scripts R","Limitado a estruturas de projetos de Medo de Queda","Dependente de caminhos de diretório e estruturas de arquivo específicos (por exemplo, Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"ru":["Требует возможностей выполнения скриптов R","Ограничен структурами проектов Страха падения","Зависит от определенных путей директорий и структур файлов (например, Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"],"ar":["يتطلب khảيات تشغيل برامج نصية R","محدود بهياكل مشاريع خوف السقوط","يعتمد على مسارات دلائل و هياكل ملفات محددة (على سبيل المثال Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/)"]},"version":4},"contentHash":"a185ead4e3288f215813854caf8cc90c4f62f8dca21dc362efb42d0fa462d7dc","qualityScore":54}');
