INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Tupatuko2023/Python-R-Scripts/fof-qc-summarizer', 'fof-qc-summarizer', 'Tupatuko2023', 'Python-R-Scripts', 'community', 'fof-qc-summarizer Tupatuko2023 Python-R-Scripts community The fof-qc-summarizer skill generates QC summaries using R scripts, benefiting developers working with Fear-of-Falling projects. It provides optional overrides for custom directory paths and script labels. fof-qc-summarizer 是一个用于总结 QC 输出的 AI 工具，通过 R 脚本实现 fof-qc-summarizer は QC 出力を要約する AI エージェントで、R スクリプトで実装されています fof-qc-summarizer는 QC 출력을 요약하는 인공지능 툴로 R 스크립트로 구현됩니다 fof-qc-summarizer es una herramienta para resumir salidas de calidad con Rscript. Se ejecuta desde la raíz del subproyecto Fear-of-Falling o la raíz del repositorio fof-qc-summarizer est un outil pour résumer les sorties de qualité avec Rscript. Il s''exécute à partir de la racine du sous-projet Fear-of-Falling ou de la racine du référentiel fof-qc-summarizer ist ein Tool zur Zusammenfassung von Qualitätsausgaben mit Rscript. Es wird vom Root des Fear-of-Falling-Subprojekts oder des Repository-Roots aus ausgeführt O fof-qc-summarizer é uma ferramenta que resume saídas de QC. Execute-o com Rscript e personalize a saída. fof-qc-summarizer - это инструмент, который суммирует выводы QC. Запустите его с помощью Rscript и настройте вывод. فوف-qc-summarizer هو أداة تلخص إخراجات QC. يمكن تشغيله مع Rscript وتخصيص الإخراج. how to use fof-qc-summarizer fof-qc-summarizer setup guide R script for QC summary Fear-of-Falling project tools fof-qc-summarizer alternative QC summary generation Rscript command custom directory paths for fof-qc-summarizer fof-qc-summarizer AI工具 R脚本 QC输出总结 自定义QC目录 脚本标签设置 Runs from the Fear-of-Falling subproject root or repo root using Rscript Supports optional overrides for QC directory, output directory, and script label Utilizes R scripts for QC summary generation, such as qc_summarize.R Scans for init.R files with append_manifest() and manifest_row() for manifest helpers Processes QC outputs under Fear-of-Falling/R-scripts/K18/outputs/K18_QC/qc/ fof-qc-summarizer is a skill that utilizes R scripts to summarize QC outputs, supporting custom directory paths and script labels for flexible execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agusruiz11/posicionarte-2026/cqrs-implementation', 'community', 'agusruiz11', 'posicionarte-2026', 'agusruiz11/posicionarte-2026', 'cqrs-implementation', 0, 0, 54, '2026-03-06T22:09:43Z', '2026-03-07T13:13:48.451Z', '884c5d29fcc20fae096e703e7e30ed7f16ccf6f0071af9b62f58f10094865696', '{"id":"agusruiz11/posicionarte-2026/cqrs-implementation","name":"cqrs-implementation","description":{"en":"The cqrs-implementation skill provides a comprehensive guide to implementing Command Query Responsibility Segregation patterns, ideal for developers building event-sourced systems or optimizing complex query scenarios.","zh":"CQRS实现是将读写责任分离的设计模式，适用于大规模系统和复杂查询场景","ja":"CQRS実装は、読み書きの責任を分離する設計パターンで、大規模なシステムや複雑なクエリシナリオに適しています","ko":"CQRS 구현은 읽기 및 쓰기 책임을 분리하는 설계 패턴으로 대규모 시스템 및 복잡한 쿼리 시나리오에 적합합니다","es":"La implementación de CQRS permite separar las preocupaciones de lectura y escritura, mejorar el rendimiento y optimizar consultas complejas. Aprende a implementar este patrón con nuestra guía","fr":"La mise en œuvre de CQRS permet de séparer les préoccupations de lecture et d''écriture, d''améliorer les performances et d''optimiser les requêtes complexes. Découvrez comment avec notre guide","de":"Die Implementierung von CQRS ermöglicht die Trennung von Lese- und Schreibbelangen, die Verbesserung der Leistung und die Optimierung komplexer Abfragen. Erfahren Sie, wie Sie dieses Muster implementieren","pt":"O padrão CQRS é uma abordagem arquitetônica que separa as preocupações de leitura e escrita, permitindo escalonar leituras independentemente de escritas.","ru":"Шаблон CQRS — это архитектурный подход, который разделяет задачи чтения и записи, позволяя масштабировать чтение независимо от записи.","ar":"نمط سيQRS هو نهج معماري يفصل بين اهتمامات القراءة والكتابة، مما يسمح بتوسيع نطاق القراءات بشكل مستقل عن الكتابات"},"seo":{"title":{"en":"cqrs-implementation: CQRS Pattern Setup Guide | AI Agent ...","zh":"CQRS实现最佳实践","ja":"CQRS実装ガイド - AIエージェント","ko":"CQRS 구현 안내 - AI Tools","es":"Guía de implementación de CQRS para desarrolladores","fr":"Mise en œuvre de CQRS : Guide de démarrage","de":"CQRS-Implementierung: Leitfaden für Entwickler","pt":"Guia de Implementação de CQRS: Melhores Práticas","ru":"Реализация CQRS: Настройка и Лучшие Практики для ИИ Агентов","ar":"دليل تنفيذ سيQRS: إرشادات وافضل الممارسات للعمليات المتقدمة"},"description":{"en":"Unlock scalable architecture with our cqrs-implementation skill, learn how to separate read and write concerns for high-performance reporting","zh":"了解CQRS实现的核心概念，包括CQRS架构、事件源和读写分离","ja":"CQRS実装のベストプラクティスを学ぶ - AIエージェントによるスケーラブルなシステム設計","ko":"CQRS 구현을 위한 핵심 개념 및 기술 - AI Tools를 활용한 고성능 시스템 구축","es":"Aprende a implementar patrones de CQRS para separar preocupaciones de lectura y escritura, mejorar el rendimiento y optimizar consultas complejas con herrami...","fr":"Découvrez comment mettre en œuvre les modèles de CQRS pour séparer les préoccupations de lecture et d''écriture, améliorer les performances et optimiser les r...","de":"Erfahren Sie, wie Sie CQRS-Muster implementieren, um Lese- und Schreibbelange zu trennen, die Leistung zu verbessern und komplexe Abfragen zu optimieren mit ...","pt":"Aprenda a implementar o padrão CQRS para separar preocupações de leitura e escrita, escalonar leituras independentemente de escritas e construir sistemas bas...","ru":"Узнайте, как реализовать шаблон CQRS для разделения задач чтения и записи, масштабирования чтения независимо от записи и построения событийно-ориентированных...","ar":"تعرف على كيفية تنفيذ نمط سيQRS لفصل اهتمامات القراءة والكتابة وتوسيع نطاق القراءات بشكل مستقل عن الكتابات وبناء أنظمة مبنية على الأحداث"},"definition":{"en":"cqrs-implementation is a software design pattern that segregates an application into separate responsibilities for handling commands and queries","zh":"CQRS是Command Query Responsibility Segregation的缩写，指的是将读写责任分离的设计模式","ja":"CQRSはCommand Query Responsibility Segregationの略で、読み書きの責任を分離する設計パターンを指します","ko":"CQRS는 Command Query Responsibility Segregation의 약자로 읽기 및 쓰기 책임을 분리하는 설계 패턴을 의미합니다","es":"CQRS es un patrón de diseño que separa las preocupaciones de lectura y escritura en un sistema","fr":"CQRS est un modèle de conception qui sépare les préoccupations de lecture et d''écriture dans un système","de":"CQRS ist ein Entwurfsmuster, das die Belange von Lese- und Schreibvorgängen in einem System trennt","pt":"CQRS é um padrão de arquitetura que separa as responsabilidades de comando e consulta.","ru":"CQRS — это шаблон архитектуры, который разделяет ответственность за команды и запросы.","ar":"سيQRS هو نمط معماري يفصل بين مسؤولية الأوامر والاستفسارات"},"features":{"en":["Separates read and write concerns for scalable architecture","Supports building event-sourced systems with optimized query scenarios","Enables different read/write data models for high-performance reporting","Allows scaling reads independently from writes for improved performance","Optimizes complex query scenarios for better data retrieval","Provides a comprehensive guide to CQRS architecture implementation"],"zh":["CQRS架构","事件源系统","读写分离","高性能报告","复杂查询优化"],"ja":["CQRSアーキテクチャ","イベントソーシング","読み書きの分離","高性能レポート","複雑なクエリの最適化"],"ko":["CQRS 아키텍처","이벤트 소싱","읽기 및 쓰기 분리","고성능 보고","복잡한 쿼리 최적화"],"es":["Arquitectura de CQRS para separar preocupaciones de lectura y escritura","Escalabilidad de lecturas de forma independiente a las escrituras","Construcción de sistemas con origen de eventos","Optimización de escenarios de consultas complejas","Modelos de datos de lectura y escritura diferenciados","Requisitos de informes de alto rendimiento"],"fr":["Architecture CQRS pour séparer les préoccupations de lecture et d''écriture","Évolutivité des lectures de manière indépendante des écritures","Construction de systèmes à source d''événements","Optimisation de scénarios de requêtes complexes","Modèles de données de lecture et d''écriture différenciés","Exigences de rapports de haute performance"],"de":["CQRS-Architektur zur Trennung von Lese- und Schreibbelangen","Skalierbarkeit von Lesevorgängen unabhängig von Schreibvorgängen","Bau von Systemen mit Ereignisquelle","Optimierung komplexer Abfrageszenarien","Lesen und Schreiben von Datenmodellen","Anforderungen an Hochleistungsberichte"],"pt":["Separação de preocupações de leitura e escrita","Escala leituras independentemente de escritas","Construção de sistemas baseados em eventos","Otimização de cenários de consulta complexos","Modelos de dados de leitura e escrita diferentes"],"ru":["Разделение задач чтения и записи","Масштабирование чтения независимо от записи","Построение событийно-ориентированных систем","Оптимизация сложных сценариев запросов","Разные модели данных для чтения и записи"],"ar":["فصل اهتمامات القراءة والكتابة","توسيع نطاق القراءات بشكل مستقل عن الكتابات","بناء أنظمة مبنية على الأحداث","تحسين سيناريوهات الاستفسار المعقدة","نماذج بيانات مختلفة للقراءة والكتابة"]},"keywords":{"en":["how to implement cqrs-implementation","cqrs-implementation vs event sourcing","cqrs-implementation setup guide","what is cqrs-implementation pattern","cqrs-implementation alternative to monolithic architecture","cqrs-implementation install for high-performance reporting"],"zh":["CQRS实现","读写分离","事件源系统","高性能报告","复杂查询优化","CQRS架构","大规模系统设计","AI工具"],"ja":["CQRS実装","読み書きの分離","イベントソーシング","高性能レポート","複雑なクエリの最適化","CQRSアーキテクチャ","大規模なシステム設計","AIエージェント"],"ko":["CQRS 구현","읽기 및 쓰기 분리","이벤트 소싱","고성능 보고","복잡한 쿼리 최적화","CQRS 아키텍처","대규모 시스템 설계","AI Tools"],"es":["CQRS","patrones de diseño","arquitectura de software","separación de preocupaciones","escalabilidad","sistemas de eventos","optimización de consultas","modelos de datos","herramientas de inteligencia artificial"],"fr":["CQRS","modèles de conception","architecture logicielle","séparation des préoccupations","évolutivité","systèmes à source d''événements","optimisation de requêtes","modèles de données","outils d''intelligence artificielle"],"de":["CQRS","Entwurfsmuster","Softwarearchitektur","Trennung von Belangen","Skalierbarkeit","Systeme mit Ereignisquelle","Optimierung von Abfragen","Datenmodelle","KI-Tools"],"pt":["cqrs","padrão cqrs","implementação cqrs","arquitetura cqrs","desenvolvimento de software","padrões de arquitetura","sistemas baseados em eventos","leitura e escrita de dados"],"ru":["cqrs","шаблон cqrs","реализация cqrs","архитектура cqrs","разработка программного обеспечения","шаблоны архитектуры","событийно-ориентированные системы","чтение и запись данных","ИИ Агенты"],"ar":["سيQRS","نمط سيQRS","تنفيذ سيQRS","هندسة سيQRS","تطوير البرمجيات","أنماط الهندسة","أنظمة مبنية على الأحداث","قراءة وكتابة البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"agusruiz11","repo":"posicionarte-2026","repoPath":"agusruiz11/posicionarte-2026","stars":0,"forks":0,"updatedAt":"2026-03-06T22:09:43Z","topics":[],"category":"community","skillMd":{"name":"cqrs-implementation","description":"Implement Command Query Responsibility Segregation for scalable architectures. Use when separating read and write models, optimizing query performance, or building event-sourced systems.","bodyPreview":"# CQRS Implementation\r\n\r\nComprehensive guide to implementing CQRS (Command Query Responsibility Segregation) patterns.\r\n\r\n## When to Use This Skill\r\n\r\n- Separating read and write concerns\r\n- Scaling reads independently from writes\r\n- Building event-sourced systems\r\n- Optimizing complex query scenarios\r\n- Different read/write data models needed\r\n- High-performance reporting requirements\r\n\r\n## Core Concepts\r\n\r\n### 1. CQRS Architecture\r\n\r\n```\r\n                    ┌─────────────┐","body":"# CQRS Implementation\r\n\r\nComprehensive guide to implementing CQRS (Command Query Responsibility Segregation) patterns.\r\n\r\n## When to Use This Skill\r\n\r\n- Separating read and write concerns\r\n- Scaling reads independently from writes\r\n- Building event-sourced systems\r\n- Optimizing complex query scenarios\r\n- Different read/write data models needed\r\n- High-performance reporting requirements\r\n\r\n## Core Concepts\r\n\r\n### 1. CQRS Architecture\r\n\r\n```\r\n                    ┌─────────────┐\r\n                    │   Client    │\r\n                    └──────┬──────┘\r\n                           │\r\n              ┌────────────┴────────────┐\r\n              │                         │\r\n              ▼                         ▼\r\n       ┌─────────────┐          ┌─────────────┐\r\n       │  Commands   │          │   Queries   │\r\n       │    API      │          │    API      │\r\n       └──────┬──────┘          └──────┬──────┘\r\n              │                         │\r\n              ▼                         ▼\r\n       ┌─────────────┐          ┌─────────────┐\r\n       │  Command    │          │   Query     │\r\n       │  Handlers   │          │  Handlers   │\r\n       └──────┬──────┘          └──────┬──────┘\r\n              │                         │\r\n              ▼                         ▼\r\n       ┌─────────────┐          ┌─────────────┐\r\n       │   Write     │─────────►│    Read     │\r\n       │   Model     │  Events  │   Model     │\r\n       └─────────────┘          └─────────────┘\r\n```\r\n\r\n### 2. Key Components\r\n\r\n| Component           | Responsibility                  |\r\n| ------------------- | ------------------------------- |\r\n| **Command**         | Intent to change state          |\r\n| **Command Handler** | Validates and executes commands |\r\n| **Event**           | Record of state change          |\r\n| **Query**           | Request for data                |\r\n| **Query Handler**   | Retrieves data from read model  |\r\n| **Projector**       | Updates read model from events  |\r\n\r\n## Templates\r\n\r\n### Template 1: Command Infrastructure\r\n\r\n```python\r\nfrom abc import ABC, abstractmethod\r\nfrom dataclasses import dataclass\r\nfrom typing import TypeVar, Generic, Dict, Any, Type\r\nfrom datetime import datetime\r\nimport uuid\r\n\r\n# Command base\r\n@dataclass\r\nclass Command:\r\n    command_id: str = None\r\n    timestamp: datetime = None\r\n\r\n    def __post_init__(self):\r\n        self.command_id = self.command_id or str(uuid.uuid4())\r\n        self.timestamp = self.timestamp or datetime.utcnow()\r\n\r\n\r\n# Concrete commands\r\n@dataclass\r\nclass CreateOrder(Command):\r\n    customer_id: str\r\n    items: list\r\n    shipping_address: dict\r\n\r\n\r\n@dataclass\r\nclass AddOrderItem(Command):\r\n    order_id: str\r\n    product_id: str\r\n    quantity: int\r\n    price: float\r\n\r\n\r\n@dataclass\r\nclass CancelOrder(Command):\r\n    order_id: str\r\n    reason: str\r\n\r\n\r\n# Command handler base\r\nT = TypeVar(''T'', bound=Command)\r\n\r\nclass CommandHandler(ABC, Generic[T]):\r\n    @abstractmethod\r\n    async def handle(self, command: T) -> Any:\r\n        pass\r\n\r\n\r\n# Command bus\r\nclass CommandBus:\r\n    def __init__(self):\r\n        self._handlers: Dict[Type[Command], CommandHandler] = {}\r\n\r\n    def register(self, command_type: Type[Command], handler: CommandHandler):\r\n        self._handlers[command_type] = handler\r\n\r\n    async def dispatch(self, command: Command) -> Any:\r\n        handler = self._handlers.get(type(command))\r\n        if not handler:\r\n            raise ValueError(f\"No handler for {type(command).__name__}\")\r\n        return await handler.handle(command)\r\n\r\n\r\n# Command handler implementation\r\nclass CreateOrderHandler(CommandHandler[CreateOrder]):\r\n    def __init__(self, order_repository, event_store):\r\n        self.order_repository = order_repository\r\n        self.event_store = event_store\r\n\r\n    async def handle(self, command: CreateOrder) -> str:\r\n        # Validate\r\n        if not command.items:\r\n            raise ValueError(\"Order must have at least one item\")\r\n\r\n        # Create aggregate\r\n        order = Order.create(\r\n            customer_id=command.customer_id,\r\n            items=command.items,\r\n            shipping_address=command.shipping_address\r\n        )\r\n\r\n        # Persist events\r\n        await self.event_store.append_events(\r\n            stream_id=f\"Order-{order.id}\",\r\n            stream_type=\"Order\",\r\n            events=order.uncommitted_events\r\n        )\r\n\r\n        return order.id\r\n```\r\n\r\n### Template 2: Query Infrastructure\r\n\r\n```python\r\nfrom abc import ABC, abstractmethod\r\nfrom dataclasses import dataclass\r\nfrom typing import TypeVar, Generic, List, Optional\r\n\r\n# Query base\r\n@dataclass\r\nclass Query:\r\n    pass\r\n\r\n\r\n# Concrete queries\r\n@dataclass\r\nclass GetOrderById(Query):\r\n    order_id: str\r\n\r\n\r\n@dataclass\r\nclass GetCustomerOrders(Query):\r\n    customer_id: str\r\n    status: Optional[str] = None\r\n    page: int = 1\r\n    page_size: int = 20\r\n\r\n\r\n@dataclass\r\nclass SearchOrders(Query):\r\n    query: str\r\n    filters: dict = None\r\n    sort_by: str = \"created_at\"\r\n    sort_order: str = \"desc\"\r\n\r\n\r\n# Query result types\r\n@dataclass\r\nclass OrderView:\r\n    order_id: str\r\n    customer_id: str\r\n    status: str\r\n    total_amount: float\r\n    item_count: int\r\n    created_at: datetime\r\n    shipped_at: Optional[datetime] = None\r\n\r\n\r\n@dataclass\r\nclass PaginatedResult(Generic[T]):\r\n    items: List[T]\r\n    total: int\r\n    page: int\r\n    page_size: int\r\n\r\n    @property\r\n    def total_pages(self) -> int:\r\n        return (self.total + self.page_size - 1) // self.page_size\r\n\r\n\r\n# Query handler base\r\nT = TypeVar(''T'', bound=Query)\r\nR = TypeVar(''R'')\r\n\r\nclass QueryHandler(ABC, Generic[T, R]):\r\n    @abstractmethod\r\n    async def handle(self, query: T) -> R:\r\n        pass\r\n\r\n\r\n# Query bus\r\nclass QueryBus:\r\n    def __init__(self):\r\n        self._handlers: Dict[Type[Query], QueryHandler] = {}\r\n\r\n    def register(self, query_type: Type[Query], handler: QueryHandler):\r\n        self._handlers[query_type] = handler\r\n\r\n    async def dispatch(self, query: Query) -> Any:\r\n        handler = self._handlers.get(type(query))\r\n        if not handler:\r\n            raise ValueError(f\"No handler for {type(query).__name__}\")\r\n        return await handler.handle(query)\r\n\r\n\r\n# Query handler implementation\r\nclass GetOrderByIdHandler(QueryHandler[GetOrderById, Optional[OrderView]]):\r\n    def __init__(self, read_db):\r\n        self.read_db = read_db\r\n\r\n    async def handle(self, query: GetOrderById) -> Optional[OrderView]:\r\n        async with self.read_db.acquire() as conn:\r\n            row = await conn.fetchrow(\r\n                \"\"\"\r\n                SELECT order_id, customer_id, status, total_amount,\r\n                       item_count, created_at, shipped_at\r\n                FROM order_views\r\n                WHERE order_id = $1\r\n                \"\"\",\r\n                query.order_id\r\n            )\r\n            if row:\r\n                return OrderView(**dict(row))\r\n            return None\r\n\r\n\r\nclass GetCustomerOrdersHandler(QueryHandler[GetCustomerOrders, PaginatedResult[OrderView]]):\r\n    def __init__(self, read_db):\r\n        self.read_db = read_db\r\n\r\n    async def handle(self, query: GetCustomerOrders) -> PaginatedResult[OrderView]:\r\n        async with self.read_db.acquire() as conn:\r\n            # Build query with optional status filter\r\n            where_clause = \"customer_id = $1\"\r\n            params = [query.customer_id]\r\n\r\n            if query.status:\r\n                where_clause += \" AND status = $2\"\r\n                params.append(query.status)\r\n\r\n            # Get total count\r\n            total = await conn.fetchval(\r\n                f\"SELECT COUNT(*) FROM order_views WHERE {where_clause}\",\r\n                *params\r\n            )\r\n\r\n            # Get paginated results\r\n            offset = (query.page - 1) * query.page_size\r\n            rows = await conn.fetch(\r\n                f\"\"\"\r\n                SELECT order_id, customer_id, status, total_amount,\r\n                       item_count, created_at, shipped_at\r\n                FROM order_views\r\n                WHERE {where_clause}\r\n                ORDER BY created_at DESC\r\n                LIMIT ${len(params) + 1} OFFSET ${len(params) + 2}\r\n                \"\"\",\r\n                *params, query.page_size, offset\r\n            )\r\n\r\n            return PaginatedResult(\r\n                items=[OrderView(**dict(row)) for row in rows],\r\n                total=total,\r\n                page=query.page,\r\n                page_size=query.page_size\r\n            )\r\n```\r\n\r\n### Template 3: FastAPI CQRS Application\r\n\r\n```python\r\nfrom fastapi import FastAPI, HTTPException, Depends\r\nfrom pydantic import BaseModel\r\nfrom typing import List, Optional\r\n\r\napp = FastAPI()\r\n\r\n# Request/Response models\r\nclass CreateOrderRequest(BaseModel):\r\n    customer_id: str\r\n    items: List[dict]\r\n    shipping_address: dict\r\n\r\n\r\nclass OrderResponse(BaseModel):\r\n    order_id: str\r\n    customer_id: str\r\n    status: str\r\n    total_amount: float\r\n    item_count: int\r\n    created_at: datetime\r\n\r\n\r\n# Dependency injection\r\ndef get_command_bus() -> CommandBus:\r\n    return app.state.command_bus\r\n\r\n\r\ndef get_query_bus() -> QueryBus:\r\n    return app.state.query_bus\r\n\r\n\r\n# Command endpoints (POST, PUT, DELETE)\r\n@app.post(\"/orders\", response_model=dict)\r\nasync def create_order(\r\n    request: CreateOrderRequest,\r\n    command_bus: CommandBus = Depends(get_command_bus)\r\n):\r\n    command = CreateOrder(\r\n        customer_id=request.customer_id,\r\n        items=request.items,\r\n        shipping_address=request.shipping_address\r\n    )\r\n    order_id = await command_bus.dispatch(command)\r\n    return {\"order_id\": order_id}\r\n\r\n\r\n@app.post(\"/orders/{order_id}/items\")\r\nasync def add_item(\r\n    order_id: str,\r\n    product_id: str,\r\n    quantity: int,\r\n    price: float,\r\n    command_bus: CommandBus = Depends(get_command_bus)\r\n):\r\n    command = AddOrderItem(\r\n        order_id=order_id,\r\n        product_id=product_id,\r\n        quantity=quantity,\r\n        price=price\r\n    )\r\n    await command_bus.dispatch(command)\r\n    return {\"status\": \"item_added\"}\r\n\r\n\r\n@app.delete(\"/orders/{order_id}\")\r\nasync def cancel_order(\r\n    order_id: str,\r\n    reason: str,\r\n    command_bus: CommandBus = Depends(get_command_bus)\r\n):\r\n    command = CancelOrder(order_id=order_id, reason=reason)\r\n    await command_bus.dispatch(command)\r\n    return {\"status\": \"cancelled\"}\r\n\r\n\r\n# Query endpoints (GET)\r\n@app.get(\"/orders/{order_id}\", response_model=OrderResponse)\r\nasync def get_order(\r\n    order_id: str,\r\n    query_bus: QueryBus = Depends(get_query_bus)\r\n):\r\n    query = GetOrderById(order_id=order_id)\r\n    result = await query_bus.dispatch(query)\r\n    if not result:\r\n        raise HTTPException(status_code=404, detail=\"Order not found\")\r\n    return result\r\n\r\n\r\n@app.get(\"/customers/{customer_id}/orders\")\r\nasync def get_customer_orders(\r\n    customer_id: str,\r\n    status: Optional[str] = None,\r\n    page: int = 1,\r\n    page_size: int = 20,\r\n    query_bus: QueryBus = Depends(get_query_bus)\r\n):\r\n    query = GetCustomerOrders(\r\n        customer_id=customer_id,\r\n        status=status,\r\n        page=page,\r\n        page_size=page_size\r\n    )\r\n    return await query_bus.dispatch(query)\r\n\r\n\r\n@app.get(\"/orders/search\")\r\nasync def search_orders(\r\n    q: str,\r\n    sort_by: str = \"created_at\",\r\n    query_bus: QueryBus = Depends(get_query_bus)\r\n):\r\n    query = SearchOrders(query=q, sort_by=sort_by)\r\n    return await query_bus.dispatch(query)\r\n```\r\n\r\n### Template 4: Read Model Synchronization\r\n\r\n```python\r\nclass ReadModelSynchronizer:\r\n    \"\"\"Keeps read models in sync with events.\"\"\"\r\n\r\n    def __init__(self, event_store, read_db, projections: List[Projection]):\r\n        self.event_store = event_store\r\n        self.read_db = read_db\r\n        self.projections = {p.name: p for p in projections}\r\n\r\n    async def run(self):\r\n        \"\"\"Continuously sync read models.\"\"\"\r\n        while True:\r\n            for name, projection in self.projections.items():\r\n                await self._sync_projection(projection)\r\n            await asyncio.sleep(0.1)\r\n\r\n    async def _sync_projection(self, projection: Projection):\r\n        checkpoint = await self._get_checkpoint(projection.name)\r\n\r\n        events = await self.event_store.read_all(\r\n            from_position=checkpoint,\r\n            limit=100\r\n        )\r\n\r\n        for event in events:\r\n            if event.event_type in projection.handles():\r\n                try:\r\n                    await projection.apply(event)\r\n                except Exception as e:\r\n                    # Log error, possibly retry or skip\r\n                    logger.error(f\"Projection error: {e}\")\r\n                    continue\r\n\r\n            await self._save_checkpoint(projection.name, event.global_position)\r\n\r\n    async def rebuild_projection(self, projection_name: str):\r\n        \"\"\"Rebuild a projection from scratch.\"\"\"\r\n        projection = self.projections[projection_name]\r\n\r\n        # Clear existing data\r\n        await projection.clear()\r\n\r\n        # Reset checkpoint\r\n        await self._save_checkpoint(projection_name, 0)\r\n\r\n        # Rebuild\r\n        while True:\r\n            checkpoint = await self._get_checkpoint(projection_name)\r\n            events = await self.event_store.read_all(checkpoint, 1000)\r\n\r\n            if not events:\r\n                break\r\n\r\n            for event in events:\r\n                if event.event_type in projection.handles():\r\n                    await projection.apply(event)\r\n\r\n            await self._save_checkpoint(\r\n                projection_name,\r\n                events[-1].global_position\r\n            )\r\n```\r\n\r\n### Template 5: Eventual Consistency Handling\r\n\r\n```python\r\nclass ConsistentQueryHandler:\r\n    \"\"\"Query handler that can wait for consistency.\"\"\"\r\n\r\n    def __init__(self, read_db, event_store):\r\n        self.read_db = read_db\r\n        self.event_store = event_store\r\n\r\n    async def query_after_command(\r\n        self,\r\n        query: Query,\r\n        expected_version: int,\r\n        stream_id: str,\r\n        timeout: float = 5.0\r\n    ):\r\n        \"\"\"\r\n        Execute query, ensuring read model is at expected version.\r\n        Used for read-your-writes consistency.\r\n        \"\"\"\r\n        start_time = time.time()\r\n\r\n        while time.time() - start_time < timeout:\r\n            # Check if read model is caught up\r\n            projection_version = await self._get_projection_version(stream_id)\r\n\r\n            if projection_version >= expected_version:\r\n                return await self.execute_query(query)\r\n\r\n            # Wait a bit and retry\r\n            await asyncio.sleep(0.1)\r\n\r\n        # Timeout - return stale data with warning\r\n        return {\r\n            \"data\": await self.execute_query(query),\r\n            \"_warning\": \"Data may be stale\"\r\n        }\r\n\r\n    async def _get_projection_version(self, stream_id: str) -> int:\r\n        \"\"\"Get the last processed event version for a stream.\"\"\"\r\n        async with self.read_db.acquire() as conn:\r\n            return await conn.fetchval(\r\n                \"SELECT last_event_version FROM projection_state WHERE stream_id = $1\",\r\n                stream_id\r\n            ) or 0\r\n```\r\n\r\n## Best Practices\r\n\r\n### Do''s\r\n\r\n- **Separate command and query models** - Different needs\r\n- **Use eventual consistency** - Accept propagation delay\r\n- **Validate in command handlers** - Before state change\r\n- **Denormalize read models** - Optimize for queries\r\n- **Version your events** - For schema evolution\r\n\r\n### Don''ts\r\n\r\n- **Don''t query in commands** - Use only for writes\r\n- **Don''t couple read/write schemas** - Independent evolution\r\n- **Don''t over-engineer** - Start simple\r\n- **Don''t ignore consistency SLAs** - Define acceptable lag\r\n\r\n## Resources\r\n\r\n- [CQRS Pattern](https://martinfowler.com/bliki/CQRS.html)\r\n- [Microsoft CQRS Guidance](https://docs.microsoft.com/en-us/azure/architecture/patterns/cqrs)\r\n"},"lastSynced":"2026-03-07T13:13:48.451Z","agentAnalysis":{"suitability":{"en":"Ideal for Event-Driven Architecture Agents requiring scalable and optimized data processing using Command Query Responsibility Segregation patterns","zh":"适用于需要使用命令查询责任分离模式进行可扩展和优化数据处理的事件驱动架构代理","ja":"イベント駆動型アーキテクチャエージェントがスケーラブルで最適化されたデータ処理を必要とする場合に最適","ko":"이벤트 驅動 아키텍처 에이전트가 확장 가능하고 최적화된 데이터 처리를 필요로 하는 경우에 적합","es":"Ideal para agentes de Arquitectura Orientada a Eventos que requieren un procesamiento de datos escalable y optimizado utilizando patrones de Segregación de Responsabilidad de Consulta de Comando","fr":"Idéal pour les agents d''Architecture Orientée aux Événements nécessitant un traitement de données évolutif et optimisé en utilisant des modèles de ségrégation de responsabilité de requête de commande","de":"Ideal für Agenten von Ereignisgesteuerten Architekturen, die ein skalierbares und optimiertes Datenverarbeitung unter Verwendung von Command Query Responsibility Segregation-Mustern erfordern","pt":"Ideal para Agentes de Arquitetura Orientada a Eventos que exigem processamento de dados escalável e otimizado usando padrões de Segregação de Responsabilidade de Consulta de Comando","ru":"Идеально подходит для агентов архитектуры, ориентированной на события, требующих масштабируемой и оптимизированной обработки данных с использованием шаблонов сегрегации ответственности запроса команды","ar":"مثالي لعميليات هندسة معمارية مدفوعة بالأحداث التي تتطلب معالجة بيانات قابلة للتوسيع ومُحسّنة باستخدام أنماط فصل مسؤولية استعلام الأوامر"},"recommendation":{"en":"Empowers agents to implement CQRS architectures, enabling the separation of read and write concerns, scaling reads independently from writes, and optimizing complex query scenarios using event-sourced systems and high-performance reporting requirements","zh":"赋予代理实现 CQRS 架构的能力，实现读写关注点的分离，独立于写入来扩展读取，并使用事件源系统和高性能报告需求来优化复杂的查询场景","ja":"CQRS アーキテクチャの実装をエージェントに可能にし、読み取りと書き込みの関心事を分離し、読み取りを書き込みから独立してスケールし、イベントソーシングシステムとハイパフォーマンスのレポート要件を使用して複雑なクエリシナリオを最適化","ko":"에이전트가 CQRS 아키텍처를 구현하여 읽기 및 쓰기 관심사를 분리하고 읽기를 쓰기에서 독립적으로 확장하며 이벤트 소싱 시스템 및 고성능 보고 요구 사항을 사용하여 복잡한 쿼리 시나리오를 최적화하는 것을 가능하게 함","es":"Habilita a los agentes a implementar arquitecturas CQRS, lo que permite la separación de las preocupaciones de lectura y escritura, escalando las lecturas de forma independiente a las escrituras y optimizando escenarios de consultas complejas mediante sistemas con origen de eventos y requisitos de informes de alto rendimiento","fr":"Permet aux agents de mettre en œuvre des architectures CQRS, permettant la séparation des préoccupations de lecture et d''écriture, la mise à l''échelle des lectures de manière indépendante des écritures et l''optimisation des scénarios de requêtes complexes en utilisant des systèmes à source d''événements et des exigences de rapports à haute performance","de":"Ermöglicht es Agenten, CQRS-Architekturen zu implementieren, wodurch die Trennung von Lese- und Schreibbelangen ermöglicht wird, Lesevorgänge unabhängig von Schreibvorgängen skaliert werden und komplexe Abfrageszenarien unter Verwendung von ereignisquellengesteuerten Systemen und Hochleistungsberichterstellungsanforderungen optimiert werden","pt":"Habilita os agentes a implementar arquiteturas CQRS, permitindo a separação de preocupações de leitura e escrita, escalonando leituras de forma independente das escritas e otimizando cenários de consulta complexos usando sistemas originados por eventos e requisitos de relatórios de alto desempenho","ru":"Наделяет агентов возможностью реализовывать архитектуру CQRS, позволяя разделять проблемы чтения и записи, масштабировать чтение независимо от записи и оптимизировать сложные сценарии запросов с использованием систем, основанных на событиях, и требований к отчетам с высокими производительными характеристиками","ar":"تمكّن الوكيل من تنفيذ هندسة CQRS، وتمكينه من فصل اهتمامات القراءة والكتابة، وتمكينه من تسريع القراءات بشكل مستقل عن الكتابة، وتمكينه من تحسين سيناريوهات الاستفسار المعقدة باستخدام أنظمة مبنية على الأحداث ومتطلبات الإبلاغ الأداء العالي"},"useCases":{"en":["Implementing event-sourced systems","Scaling reads independently from writes","Optimizing complex query scenarios","Building high-performance reporting systems"],"zh":["实现事件源系统","独立于写入来扩展读取","优化复杂的查询场景","构建高性能报告系统"],"ja":["イベントソーシングシステムの実装","読み取りを書き込みから独立してスケール","複雑なクエリシナリオの最適化","ハイパフォーマンスのレポートシステムの構築"],"ko":["이벤트 소싱 시스템 구현","읽기를 쓰기에서 독립적으로 확장","복잡한 쿼리 시나리오 최적화","고성능 보고 시스템 구축"],"es":["Implementación de sistemas con origen de eventos","Escalado de lecturas de forma independiente a las escrituras","Optimización de escenarios de consultas complejas","Creación de sistemas de informes de alto rendimiento"],"fr":["Mise en œuvre de systèmes à source d''événements","Mise à l''échelle des lectures de manière indépendante des écritures","Optimisation des scénarios de requêtes complexes","Création de systèmes de rapports à haute performance"],"de":["Implementierung von ereignisquellengesteuerten Systemen","Skalieren von Lesevorgängen unabhängig von Schreibvorgängen","Optimierung komplexer Abfrageszenarien","Erstellung von Hochleistungsberichterstellungssystemen"],"pt":["Implementação de sistemas originados por eventos","Escalonamento de leituras de forma independente das escritas","Otimização de cenários de consulta complexos","Construção de sistemas de relatórios de alto desempenho"],"ru":["Реализация систем, основанных на событиях","Масштабирование чтения независимо от записи","Оптимизация сложных сценариев запросов","Создание систем отчетов с высокими производительными характеристиками"],"ar":["تنفيذ أنظمة مبنية على الأحداث","تسريع القراءات بشكل مستقل عن الكتابة","تحسين سيناريوهات الاستفسار المعقدة","بناء أنظمة إبلاغ الأداء العالي"]},"limitations":{"en":["Requires understanding of event-driven architecture","Limited to applications with separate read and write concerns"],"zh":["需要了解事件驱动架构","仅限于具有独立读写关注点的应用程序"],"ja":["イベント駆動型アーキテクチャの理解が必要","読み取りと書き込みの関心事が独立しているアプリケーションに限定"],"ko":["이벤트 驅動 아키텍처에 대한 이해가 필요","읽기 및 쓰기 관심사가 독립적인 응용 프로그램에만 한정"],"es":["Requiere comprensión de la arquitectura orientada a eventos","Limitado a aplicaciones con preocupaciones de lectura y escritura separadas"],"fr":["Nécessite une compréhension de l''architecture orientée aux événements","Limité aux applications avec des préoccupations de lecture et d''écriture séparées"],"de":["Erfordert Verständnis von ereignisgesteuerten Architekturen","Begrenzt auf Anwendungen mit getrennten Lese- und Schreibbelangen"],"pt":["Exige compreensão de arquitetura orientada a eventos","Limitado a aplicações com preocupações de leitura e escrita separadas"],"ru":["Требует понимания архитектуры, ориентированной на события","Ограничен для приложений с отдельными проблемами чтения и записи"],"ar":["يتطلب فهم هندسة معمارية مدفوعة بالأحداث","محدود للتطبيقات التي لديها اهتمامات قراءة وكتابة منفصلة"]},"version":4},"contentHash":"884c5d29fcc20fae096e703e7e30ed7f16ccf6f0071af9b62f58f10094865696","qualityScore":54}');
