INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agusruiz11/posicionarte-2026/cqrs-implementation', 'cqrs-implementation', 'agusruiz11', 'posicionarte-2026', 'community', 'cqrs-implementation agusruiz11 posicionarte-2026 community The cqrs-implementation skill provides a comprehensive guide to implementing Command Query Responsibility Segregation patterns, ideal for developers building event-sourced systems or optimizing complex query scenarios. CQRS实现是将读写责任分离的设计模式，适用于大规模系统和复杂查询场景 CQRS実装は、読み書きの責任を分離する設計パターンで、大規模なシステムや複雑なクエリシナリオに適しています CQRS 구현은 읽기 및 쓰기 책임을 분리하는 설계 패턴으로 대규모 시스템 및 복잡한 쿼리 시나리오에 적합합니다 La implementación de CQRS permite separar las preocupaciones de lectura y escritura, mejorar el rendimiento y optimizar consultas complejas. Aprende a implementar este patrón con nuestra guía La mise en œuvre de CQRS permet de séparer les préoccupations de lecture et d''écriture, d''améliorer les performances et d''optimiser les requêtes complexes. Découvrez comment avec notre guide Die Implementierung von CQRS ermöglicht die Trennung von Lese- und Schreibbelangen, die Verbesserung der Leistung und die Optimierung komplexer Abfragen. Erfahren Sie, wie Sie dieses Muster implementieren O padrão CQRS é uma abordagem arquitetônica que separa as preocupações de leitura e escrita, permitindo escalonar leituras independentemente de escritas. Шаблон CQRS — это архитектурный подход, который разделяет задачи чтения и записи, позволяя масштабировать чтение независимо от записи. نمط سيQRS هو نهج معماري يفصل بين اهتمامات القراءة والكتابة، مما يسمح بتوسيع نطاق القراءات بشكل مستقل عن الكتابات how to implement cqrs-implementation cqrs-implementation vs event sourcing cqrs-implementation setup guide what is cqrs-implementation pattern cqrs-implementation alternative to monolithic architecture cqrs-implementation install for high-performance reporting CQRS实现 读写分离 事件源系统 高性能报告 复杂查询优化 CQRS架构 大规模系统设计 AI工具 Separates read and write concerns for scalable architecture Supports building event-sourced systems with optimized query scenarios Enables different read/write data models for high-performance reporting Allows scaling reads independently from writes for improved performance Optimizes complex query scenarios for better data retrieval Provides a comprehensive guide to CQRS architecture implementation cqrs-implementation is a software design pattern that segregates an application into separate responsibilities for handling commands and queries');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('naj2r/claude-econ-paper-template/review-r', 'community', 'naj2r', 'claude-econ-paper-template', 'naj2r/claude-econ-paper-template', 'review-r', 0, 0, 54, '2026-03-05T22:23:00Z', '2026-03-07T13:14:40.976Z', '8daa70636e681ad973e73c4d84c3c44cae8d245526507b268692249300049bf9', '{"id":"naj2r/claude-econ-paper-template/review-r","name":"review-r","description":{"en":"The review-r skill runs a code review protocol on R scripts or QMD chapters, ensuring reproducibility and correctness. It benefits developers and researchers working with empirical economics research papers.","zh":"Review R 是一个代码审查协议，用于检查 R 脚本或 QMD 章节是否符合经验经济研究论文的标准。它检查代码的可复现性和正确性","ja":"Review R は、R スクリプトや QMD 章節が経験経済研究論文の基準を満たしているかどうかをチェックするコードレビュープロトコルです。コードの再現性と正確性をチェックします","ko":"Review R은 R 스크립트 또는 QMD 장이 경험 경제 연구 논문의 표준을 충족하는지 확인하는 코드 리뷰 프로토콜입니다. 코드의 재현성 및 정확성을 확인합니다","es":"Review-r es una plantilla de infraestructura de código para investigaciones económicas que ejecuta un protocolo de revisión de código en scripts R o capítulos QMD.","fr":"Review-r est un modèle d''infrastructure de code pour les recherches économiques qui exécute un protocole de révision de code sur les scripts R ou les chapitres QMD.","de":"Review-r ist eine Code-Infrastrukturvorlage für Wirtschaftsforschung, die ein Code-Review-Protokoll auf R-Skripten oder QMD-Kapiteln ausführt.","pt":"O Review-R é uma ferramenta de código aberto que executa um protocolo de revisão de código em scripts R ou capítulos QMD para pesquisas econômicas.","ru":"Review-R - это открытый инструмент, который запускает протокол проверки кода для скриптов R или глав QMD для экономических исследований.","ar":"Review-R هو أداة مفتوحة المصدر تقوم بتشغيل بروتوكول مراجعة الشفرة في سكريبتات R أو فصول QMD للبحوث الاقتصادية."},"seo":{"title":{"en":"review-r: Code Review Protocol for R Scripts | AI Agent S...","zh":"Review R 代码审查指南 - Claude Code 基础设施模板","ja":"Review R コードレビュープロトコル - Claude Code インフラストラクチャテンプレート","ko":"Review R 코드 리뷰 가이드 - Claude Code 인프라스트럭처 템플릿","es":"Guía de configuración de review-r para investigación econ...","fr":"Guide de mise en place de review-r pour la recherche écon...","de":"Einrichtungsleitfaden für review-r in der Wirtschaftsfors...","pt":"Guia de Configuração do Review-R para Pesquisas Econômicas","ru":"Настройка Review-R: ИИ Агент для Эмпирических Экономическ...","ar":"دليل إعداد Review-R لتقنيات البحث الاقتصادي"},"description":{"en":"Unlock reproducible and correct R code with review-r. Discover how to set up and utilize this AI agent skill for empirical economics research papers.","zh":"使用 Review R 代码审查协议，确保您的 R 脚本或 QMD 章节符合经验经济研究论文的标准","ja":"Review R コードレビュープロトコルを使用して、R スクリプトや QMD 章节が経験経済研究論文の基準を満たしていることを確認する","ko":"Review R 코드 리뷰 프로토콜을 사용하여 R 스크립트 또는 QMD 장이 경험 경제 연구 논문의 표준을 충족하는지 확인합니다","es":"Optimice sus investigaciones con review-r, un agente de IA para revisar código R y QMD. Aprenda a configurarlo","fr":"Optimisez vos recherches avec review-r, un outil d''IA pour réviser le code R et QMD. Découvrez comment le configurer","de":"Optimieren Sie Ihre Forschung mit review-r, einem KI-Tool zur Überprüfung von R- und QMD-Code. Erfahren Sie, wie Sie es einrichten","pt":"Aprenda a configurar o Review-R, uma ferramenta de código aberto para revisão de protocolos de pesquisa em R e QMD","ru":"Узнайте, как настроить Review-R, инструмент для проверки протоколов исследований на R и QMD с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Review-R، أداة مراجعة بروتوكولات البحث في R و QMD باستخدام تقنيات الإعلام الاصطناعي"},"definition":{"en":"review-r is a Claude Code infrastructure template for conducting thorough code reviews on R scripts and QMD chapters, focusing on reproducibility and correctness.","zh":"Review R 是一个用于经验经济研究论文的代码审查协议，检查 R 脚本或 QMD 章节的可复现性和正确性","ja":"Review R は、経験経済研究論文用のコードレビュープロトコルで、R スクリプトや QMD 章節の再現性と正確性をチェックする","ko":"Review R은 경험 경제 연구 논문용 코드 리뷰 프로토콜로 R 스크립트 또는 QMD 장의 재현성 및 정확성을 확인합니다","es":"Review-r es un agente de IA que revisa código R y QMD para investigaciones económicas","fr":"Review-r est un outil d''IA qui révise le code R et QMD pour la recherche économique","de":"Review-r ist ein KI-Tool, das R- und QMD-Code für Wirtschaftsforschung überprüft","pt":"O que é Review-R? É uma ferramenta de revisão de código para pesquisas econômicas que verifica a reprodutibilidade e correção de scripts R e QMD.","ru":"Что такое Review-R? Это инструмент для проверки кода для экономических исследований, который проверяет воспроизводимость и правильность скриптов R и QMD.","ar":"ما هو Review-R؟ هو أداة مراجعة الشفرة للبحوث الاقتصادية التي تقوم بفحص إمكانية إعادة الإنتاج ودقة سكريبتات R و QMD."},"features":{"en":["Checks for `set.seed()` presence in R scripts to ensure reproducibility","Verifies absolute paths or defined root variables for consistent file access","Enforces `library()` calls at the top of R scripts for organizational clarity","Detects hardcoded values that should be variables for improved maintainability","Ensures deterministic data loading without web scraping or caching issues"],"zh":["检查代码的可复现性，包括 set.seed() 的使用和绝对路径","检查代码的正确性，包括回归模型的指定","支持 R 脚本和 QMD 章节的代码审查","检查代码中是否存在硬编码值和非确定性数据加载","检查 library() 调用的位置和使用"],"ja":["コードの再現性をチェックする、set.seed() の使用と絶対パスの使用を含む","コードの正確性をチェックする、回帰モデルを指定することを含む","R スクリプトと QMD 章節のコードレビューをサポートする","コード内にハードコードされた値と非決定的なデータロードがあるかどうかをチェックする","library() 呼び出しの位置と使用をチェックする"],"ko":["코드의 재현성을 확인하는 기능, set.seed() 사용 및 절대 경로 포함","코드의 정확성을 확인하는 기능, 회귀 모델 지정 포함","R 스크립트 및 QMD 장의 코드 리뷰를 지원하는 기능","코드 내에 하드코딩된 값 및 비결정적 데이터 로딩이 있는지 확인하는 기능","library() 호출의 위치 및 사용을 확인하는 기능"],"es":["Revisión de reproducibilidad con comprobación de `set.seed()`","Verificación de corrección con análisis de regresión","Comprobación de rutas absolutas y variables raíz definidas","Análisis de carga de datos determinista","Revisión de llamadas a bibliotecas en la parte superior del código"],"fr":["Révision de la reproductibilité avec vérification de `set.seed()`","Vérification de la correction avec analyse de régression","Vérification des chemins absolus et des variables racine définies","Analyse de chargement de données déterministe","Révision des appels de bibliothèques en haut du code"],"de":["Überprüfung der Reproduzierbarkeit mit `set.seed()`-Prüfung","Korrekturprüfung mit Regressionsanalyse","Überprüfung absoluter Pfade und definierter Root-Variablen","Analyse deterministischer Datenladung","Überprüfung von Bibliotheksaufrufen am Anfang des Codes"],"pt":["Verificação de reprodutibilidade com `set.seed()`","Uso de caminhos absolutos ou variáveis de raiz definidas","Chamadas de biblioteca no início do script","Verificação de valores hardcoded","Carregamento de dados determinístico"],"ru":["Проверка воспроизводимости с `set.seed()`","Использование абсолютных путей или определенных корневых переменных","Вызовы библиотек в начале скрипта","Проверка жестко закодированных значений","Определенный загрузка данных"],"ar":["فحص قابلية إعادة الإنتاج باستخدام `set.seed()`","استخدام مسارات مطلقة أو متغيرات جذر محددة","استدعاءات المكتبات في بداية السكريبت","فحص القيم المحددة","تحميل البيانات التحديد"]},"keywords":{"en":["how to use review-r","review-r setup guide","review-r alternative","review-r for empirical economics research","R script code review","QMD chapter validation","reproducible R code","correct R scripting practices","review-r install","review-r vs other code review tools"],"zh":["Review R","代码审查","经验经济研究","R 脚本","QMD 章节","代码可复现性","代码正确性","AI 代码审查工具","AIエージェント"],"ja":["Review R","コードレビュー","経験経済研究","R スクリプト","QMD 章節","コードの再現性","コードの正確性","AI コードレビューツール","AIエージェント"],"ko":["Review R","코드 리뷰","경험 경제 연구","R 스크립트","QMD 장","코드의 재현성","코드의 정확성","AI 코드 리뷰 툴","인공지능 에이전트"],"es":["review-r","investigación económica","agente de IA","código R","QMD","revisión de código","reproducibilidad","corrección","regresión"],"fr":["review-r","recherche économique","outil d''IA","code R","QMD","révision de code","reproductibilité","correction","régression"],"de":["review-r","Wirtschaftsforschung","KI-Tool","R-Code","QMD","Code-Überprüfung","Reproduzierbarkeit","Korrektur","Regression"],"pt":["Review-R","revisão de código","pesquisas econômicas","R","QMD","reprodutibilidade","correção","bibliotecas R","script R"],"ru":["Review-R","проверка кода","экономические исследования","R","QMD","воспроизводимость","правильность","библиотеки R","скрипт R","ИИ Агенты"],"ar":["Review-R","مراجعة الشفرة","بحوث اقتصادية","R","QMD","إمكانية إعادة الإنتاج","دقة","مكتبات R","سكريبت R","تقنيات الإعلام الاصطناعي"]}},"owner":"naj2r","repo":"claude-econ-paper-template","repoPath":"naj2r/claude-econ-paper-template","stars":0,"forks":0,"updatedAt":"2026-03-05T22:23:00Z","topics":[],"category":"community","skillMd":{"name":"review-r","description":"Code review for R scripts checking reproducibility, correctness, and conventions","bodyPreview":"# Review R Code\n\nRun a code review protocol on an R script or QMD chapter.\n\n**Input:** `$ARGUMENTS` — path to `.R` or `.qmd` file.\n\n## Review Dimensions\n\n### 1. Reproducibility\n- [ ] `set.seed()` present if any randomness used\n- [ ] All paths are absolute or use defined root variable\n- [ ] `library()` calls at top (not scattered)\n- [ ] No hardcoded values that should be variables\n- [ ] Data loading is deterministic (no web scraping without caching)\n\n### 2. Correctness\n- [ ] Regression specificat","body":"# Review R Code\n\nRun a code review protocol on an R script or QMD chapter.\n\n**Input:** `$ARGUMENTS` — path to `.R` or `.qmd` file.\n\n## Review Dimensions\n\n### 1. Reproducibility\n- [ ] `set.seed()` present if any randomness used\n- [ ] All paths are absolute or use defined root variable\n- [ ] `library()` calls at top (not scattered)\n- [ ] No hardcoded values that should be variables\n- [ ] Data loading is deterministic (no web scraping without caching)\n\n### 2. Correctness\n- [ ] Regression specification matches paper ({{unit_fe}}+{{time_fe}} FE, clustered SEs)\n- [ ] Missing value handling is explicit (`na.rm=TRUE` where needed)\n- [ ] Joins preserve expected row counts (check for accidental duplication)\n- [ ] Factor/character conversions are intentional\n- [ ] Variable names match Stata equivalents for cross-verification\n\n### 3. Conventions (from `.claude/rules/stata-r-conventions.md`)\n- [ ] `library()` not `require()`\n- [ ] `|>` preferred over `%>%`\n- [ ] `fixest::feols()` for TWFE\n- [ ] `modelsummary` for tables\n- [ ] `haven::read_dta()` for Stata files\n- [ ] `snake_case` naming\n- [ ] Comments explain non-obvious logic\n\n### 4. Quarto-Specific (if .qmd)\n- [ ] Every code chunk has a unique `label:`\n- [ ] `echo:` and `eval:` set appropriately\n- [ ] Table/figure chunks have captions (`tbl-cap:`, `fig-cap:`)\n- [ ] Cross-references use `@sec-`, `@tbl-`, `@fig-` syntax\n- [ ] No orphaned code chunks (every chunk has surrounding narrative)\n\n## Output\n\nReport by severity (do NOT edit files, report only):\n- **Error**: Will produce wrong results or fail to run\n- **Warning**: May produce unexpected behavior\n- **Style**: Convention violation, should fix for consistency\n- **Note**: Suggestion for improvement\n\nFormat:\n```\n[SEVERITY] Line [N]: [Description]\n  Found:    [what''s there]\n  Expected: [what should be there]\n```\n"},"lastSynced":"2026-03-07T13:14:40.976Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Science Agents focused on empirical economics research needing automated R script validation.","zh":"适用于专注于经验经济学研究的数据科学代理，需要自动验证R脚本。","ja":"経験的経済学研究に焦点を当てたデータサイエンスエージェントに最適で、自動的なRスクリプトの検証が必要です。","ko":"경험 경제학 연구에 중점을 둔 데이터 과학 에이전트에게 적합하며 자동 R 스크립트 유효성을 필요로 합니다.","es":"Ideal para agentes de Ciencia de Datos centrados en investigación de economía empírica que necesitan una validación automática de scripts R.","fr":"Idéal pour les agents de science des données axés sur la recherche en économie empirique nécessitant une validation automatique de scripts R.","de":"Ideal für Data Science-Agents, die sich auf empirische Wirtschaftsforschung konzentrieren und eine automatisierte Validierung von R-Skripten benötigen.","pt":"Ideal para Agentes de Ciência de Dados focados em pesquisa de economia empírica que necessitam de validação automática de scripts R.","ru":"Идеально для агентов данных, ориентированных на эмпирические экономические исследования, требующих автоматической проверки скриптов R.","ar":"مثالي للوكلاء المعنيين بالعلوم البيانية المتخصصة في أبحاث الاقتصاد التجريبي التي تحتاج إلى التحقق التلقائي من البرامج النصية R."},"recommendation":{"en":"Empowers agents to ensure reproducibility and correctness in R scripts or QMD chapters by checking for set.seed() presence, absolute paths, and deterministic data loading, leveraging libraries and protocols like library() calls and caching for web scraping.","zh":"赋予代理人通过检查set.seed()存在、绝对路径和确定性数据加载来确保R脚本或QMD章节的可复现性和正确性，利用诸如library()调用和缓存的库和协议进行网络爬虫。","ja":"エージェントがset.seed()の存在、絶対パス、決定論的データロードをチェックすることで、RスクリプトやQMD章の再現性と正確性を確保することができ、library()呼び出しやキャッシングなどのライブラリやプロトコルを使用してWebスクレイピングを行う。","ko":"에이전트가 set.seed() 존재, 절대 경로 및 결정적 데이터 로드를 확인하여 R 스크립트 또는 QMD 장의 재현 가능성 및 정확성을 보장 할 수 있으며, 라이브러리 호출 및 캐싱과 같은 라이브러리 및 프로토콜을 사용하여 웹 스크레이핑을 수행 할 수 있습니다.","es":"Habilita a los agentes a garantizar la reproducibilidad y la corrección en scripts R o capítulos QMD comprobando la presencia de set.seed(), rutas absolutas y carga de datos determinista, aprovechando bibliotecas y protocolos como llamadas a library() y almacenamiento en caché para scraping web.","fr":"Permet aux agents de garantir la reproductibilité et la correction dans les scripts R ou les chapitres QMD en vérifiant la présence de set.seed(), les chemins absolus et le chargement de données déterministe, en exploitant les bibliothèques et les protocoles tels que les appels à library() et la mise en cache pour le scraping web.","de":"Ermächtigt die Agents, die Reproduzierbarkeit und Richtigkeit in R-Skripten oder QMD-Kapiteln sicherzustellen, indem sie die Anwesenheit von set.seed(), absoluten Pfaden und deterministischer Datenladung überprüfen, unter Ausnutzung von Bibliotheken und Protokollen wie library()-Aufrufen und Caching für Web-Scraping.","pt":"Habilita os agentes a garantir a reprodutibilidade e a correção nos scripts R ou capítulos QMD, verificando a presença de set.seed(), caminhos absolutos e carregamento de dados determinístico, utilizando bibliotecas e protocolos como chamadas de library() e cache para raspagem de web.","ru":"Наделяет агентов возможностью обеспечивать воспроизводимость и правильность скриптов R или глав QMD, проверяя наличие set.seed(), абсолютных путей и детерминированной загрузки данных, используя библиотеки и протоколы, такие как вызовы library() и кэширование для веб-скрейпинга.","ar":"تمكّن الوكلاء من ضمان إعادة الإنتاج ودقة البرامج النصية R أو الفصول QMD عن طريق التحقق من وجود set.seed()، والمسارات المطلقة، وتحميل البيانات الت quyếtيري، واستخدام المكتبات والبروتوكولات مثل مكالمات library() وذاكرة التخزين المؤقت للتصفح الويب."},"useCases":{"en":["Validating R script reproducibility for research papers","Debugging QMD chapters for empirical economics studies","Automating code reviews for data loading and library calls"],"zh":["验证研究论文的R脚本可复现性","调试经验经济学研究的QMD章节","自动化代码审查以进行数据加载和库调用"],"ja":["研究論文のRスクリプトの再現性を検証する","経験的経済学研究のQMD章をデバッグする","データロードとライブラリ呼び出しのコードレビューを自動化する"],"ko":["연구 논문의 R 스크립트 재현 가능성을 확인하는 것","경험 경제학 연구를 위한 QMD 장의 디버깅","데이터 로딩 및 라이브러리 호출에 대한 코드 리뷰를 자동화하는 것"],"es":["Validar la reproducibilidad de scripts R para artículos de investigación","Depurar capítulos QMD para estudios de economía empírica","Automatizar revisiones de código para carga de datos y llamadas a bibliotecas"],"fr":["Valider la reproductibilité de scripts R pour les articles de recherche","Déboguer les chapitres QMD pour les études d''économie empirique","Automatiser les révisions de code pour le chargement de données et les appels à des bibliothèques"],"de":["Überprüfen der Reproduzierbarkeit von R-Skripten für Forschungsarbeiten","Fehlerbehebung in QMD-Kapiteln für empirische Wirtschaftsstudien","Automatisieren von Code-Reviews für Datenladung und Bibliotheksaufrufe"],"pt":["Validar a reprodutibilidade de scripts R para artigos de pesquisa","Depurar capítulos QMD para estudos de economia empírica","Automatizar revisões de código para carregamento de dados e chamadas de biblioteca"],"ru":["Проверка воспроизводимости скриптов R для исследовательских статей","Отладка глав QMD для эмпирических экономических исследований","Автоматизация проверки кода для загрузки данных и вызовов библиотек"],"ar":["التحقق من إعادة إنتاج البرامج النصية R للأبحاث العلمية","تصحيح الأخطاء في الفصول QMD لدراسات الاقتصاد التجريبي","تأهيل مراجعة الشفرة التلقائية لتحميل البيانات ومكالمات المكتبة"]},"limitations":{"en":["Requires access to .R or .qmd files","Limited to R scripts and QMD chapters","Does not support web scraping without caching"],"zh":[".R或.qmd文件的访问要求","仅限R脚本和QMD章节","不支持缓存的Web爬虫"],"ja":[".Rまたは.qmdファイルへのアクセス要求","RスクリプトとQMD章のみのサポート","キャッシングのないWebスクレイピングのサポートなし"],"ko":[".R 또는 .qmd 파일에 대한 액세스 요구 사항","R 스크립트 및 QMD 장의 지원만","캐싱되지 않은 웹 스크레이핑을 지원하지 않음"],"es":["Requiere acceso a archivos .R o .qmd","Limitado a scripts R y capítulos QMD","No admite scraping web sin almacenamiento en caché"],"fr":["Nécessite l''accès à des fichiers .R ou .qmd","Limité aux scripts R et chapitres QMD","Ne prend pas en charge le scraping web sans mise en cache"],"de":["Benötigt Zugriff auf .R- oder .qmd-Dateien","Begrenzt auf R-Skripte und QMD-Kapitel","Unterstützt kein Web-Scraping ohne Caching"],"pt":["Exige acesso a arquivos .R ou .qmd","Limitado a scripts R e capítulos QMD","Não suporta raspagem de web sem cache"],"ru":["Требует доступа к файлам .R или .qmd","Ограничен скриптами R и главами QMD","Не поддерживает веб-скрейпинг без кэширования"],"ar":["يتطلب الوصول إلى الملفات .R أو .qmd","محدود بالبرامج النصية R والفصول QMD","لا يدعم التصفح الويب بدون ذاكرة التخزين المؤقت"]},"version":4},"contentHash":"8daa70636e681ad973e73c4d84c3c44cae8d245526507b268692249300049bf9","qualityScore":54}');
