INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('naj2r/claude-econ-paper-template/review-r', 'review-r', 'naj2r', 'claude-econ-paper-template', 'community', 'review-r naj2r claude-econ-paper-template community The review-r skill runs a code review protocol on R scripts or QMD chapters, ensuring reproducibility and correctness. It benefits developers and researchers working with empirical economics research papers. Review R 是一个代码审查协议，用于检查 R 脚本或 QMD 章节是否符合经验经济研究论文的标准。它检查代码的可复现性和正确性 Review R は、R スクリプトや QMD 章節が経験経済研究論文の基準を満たしているかどうかをチェックするコードレビュープロトコルです。コードの再現性と正確性をチェックします Review R은 R 스크립트 또는 QMD 장이 경험 경제 연구 논문의 표준을 충족하는지 확인하는 코드 리뷰 프로토콜입니다. 코드의 재현성 및 정확성을 확인합니다 Review-r es una plantilla de infraestructura de código para investigaciones económicas que ejecuta un protocolo de revisión de código en scripts R o capítulos QMD. Review-r est un modèle d''infrastructure de code pour les recherches économiques qui exécute un protocole de révision de code sur les scripts R ou les chapitres QMD. Review-r ist eine Code-Infrastrukturvorlage für Wirtschaftsforschung, die ein Code-Review-Protokoll auf R-Skripten oder QMD-Kapiteln ausführt. O Review-R é uma ferramenta de código aberto que executa um protocolo de revisão de código em scripts R ou capítulos QMD para pesquisas econômicas. Review-R - это открытый инструмент, который запускает протокол проверки кода для скриптов R или глав QMD для экономических исследований. Review-R هو أداة مفتوحة المصدر تقوم بتشغيل بروتوكول مراجعة الشفرة في سكريبتات R أو فصول QMD للبحوث الاقتصادية. how to use review-r review-r setup guide review-r alternative review-r for empirical economics research R script code review QMD chapter validation reproducible R code correct R scripting practices review-r install review-r vs other code review tools Review R 代码审查 经验经济研究 R 脚本 QMD 章节 代码可复现性 代码正确性 AI 代码审查工具 AIエージェント Checks for `set.seed()` presence in R scripts to ensure reproducibility Verifies absolute paths or defined root variables for consistent file access Enforces `library()` calls at the top of R scripts for organizational clarity Detects hardcoded values that should be variables for improved maintainability Ensures deterministic data loading without web scraping or caching issues review-r is a Claude Code infrastructure template for conducting thorough code reviews on R scripts and QMD chapters, focusing on reproducibility and correctness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pratyushdeosingh/mdp/semgrep-rule-creator', 'community', 'pratyushdeosingh', 'mdp', 'pratyushdeosingh/mdp', 'semgrep-rule-creator', 0, 0, 54, '2026-03-07T06:46:51Z', '2026-03-07T13:14:57.969Z', '9006fc329992b066dd10f0c90390fb95f42268fa735eabb0042d6cb2d3473ef7', '{"id":"pratyushdeosingh/mdp/semgrep-rule-creator","name":"semgrep-rule-creator","description":{"en":"The semgrep-rule-creator skill helps developers create custom Semgrep rules for specific bug patterns, security vulnerabilities, and coding standards. It enables writing rules with proper testing and validation.","zh":"Semgrep规则创建工具用于创建和测试Semgrep规则，以检测代码中的安全漏洞和错误","ja":"Semgrepルール作成ツールは、コードのセキュリティ脆弱性とエラーを検出するためのSemgrepルールを作成してテストするために使用されます","ko":"Semgrep 규칙 생성기는 코드의 보안 취약점과 오류를 탐지하는 Semgrep 규칙을 생성하고 테스트하는 데 사용됩니다","es":"Crea reglas Semgrep de producción con pruebas y validación adecuadas para detectar vulnerabilidades de seguridad y patrones de errores en tu código","fr":"Créez des règles Semgrep de production avec des tests et une validation appropriés pour détecter les vulnérabilités de sécurité et les modèles d''erreurs dans votre code","de":"Erstellen Sie Produktionsregeln für Semgrep mit ordnungsgemäßen Tests und Validierung, um Sicherheitslücken und Fehlermuster in Ihrem Code zu erkennen","pt":"Crie regras Semgrep personalizadas para detectar vulnerabilidades de segurança e padrões de bugs em seu código","ru":"Создайте индивидуальные правила Semgrep для обнаружения уязвимостей безопасности и шаблонов ошибок в вашем коде","ar":"انشئ قواعد Semgrep مخصصة لاكتشاف الثغرات الأمنية وأنماط الأخطاء في كودك"},"seo":{"title":{"en":"semgrep-rule-creator: Custom Rule Setup Guide | AI Agent ...","zh":"Semgrep规则创建工具：最佳实践指南","ja":"Semgrepルール作成ツール：セキュリティ脆弱性検出のためのガイド","ko":"Semgrep 규칙 생성기: 보안 취약점 탐지 설정 가이드","es":"Guía de creación de reglas Semgrep con AI Herra