INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pratyushdeosingh/mdp/semgrep-rule-creator', 'semgrep-rule-creator', 'pratyushdeosingh', 'mdp', 'community', 'semgrep-rule-creator pratyushdeosingh mdp community The semgrep-rule-creator skill helps developers create custom Semgrep rules for specific bug patterns, security vulnerabilities, and coding standards. It enables writing rules with proper testing and validation. Semgrep规则创建工具用于创建和测试Semgrep规则，以检测代码中的安全漏洞和错误 Semgrepルール作成ツールは、コードのセキュリティ脆弱性とエラーを検出するためのSemgrepルールを作成してテストするために使用されます Semgrep 규칙 생성기는 코드의 보안 취약점과 오류를 탐지하는 Semgrep 규칙을 생성하고 테스트하는 데 사용됩니다 Crea reglas Semgrep de producción con pruebas y validación adecuadas para detectar vulnerabilidades de seguridad y patrones de errores en tu código Créez des règles Semgrep de production avec des tests et une validation appropriés pour détecter les vulnérabilités de sécurité et les modèles d''erreurs dans votre code Erstellen Sie Produktionsregeln für Semgrep mit ordnungsgemäßen Tests und Validierung, um Sicherheitslücken und Fehlermuster in Ihrem Code zu erkennen Crie regras Semgrep personalizadas para detectar vulnerabilidades de segurança e padrões de bugs em seu código Создайте индивидуальные правила Semgrep для обнаружения уязвимостей безопасности и шаблонов ошибок в вашем коде انشئ قواعد Semgrep مخصصة لاكتشاف الثغرات الأمنية وأنماط الأخطاء في كودك how to use semgrep-rule-creator semgrep-rule-creator setup guide semgrep-rule-creator alternative semgrep-rule-creator vs static analysis creating custom Semgrep rules semgrep-rule-creator install Semgrep规则创建 安全漏洞检测 数据流漏洞检测 编码标准执行 规则测试和验证 AI工具 代码安全 Creates custom Semgrep rules for specific bug patterns Writes rules to detect security vulnerabilities in codebases Supports writing taint mode rules for data flow vulnerabilities Enforces coding standards with custom rules Validates rules with proper testing semgrep-rule-creator is a skill that enables developers to create production-quality Semgrep rules with proper testing and validation for detecting security vulnerabilities and enforcing coding standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jellydn/my-ai-tools/prd', 'community', 'jellydn', 'my-ai-tools', 'jellydn/my-ai-tools', 'prd', 0, 0, 54, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:12.830Z', '791920d6ef8bfbc08d6163b187edcba1cd632221feba0422970affc66e29b857', '{"id":"jellydn/my-ai-tools/prd","name":"prd","description":{"en":"The prd skill provides comprehensive configuration management for AI coding tools, generating detailed Product Requirements Documents for implementation. It benefits developers working with Claude Code, OpenCode, Amp, Codex, and Claude Code Switch.","zh":"PRD配置管理设置指南，用于AI编码工具的综合配置管理，包括Claude Code、OpenCode、Amp、Codex和Claude Code Switch","ja":"AIエージェントのためのPRD設定ガイド：Claude Code、OpenCode、Amp、Codexなどのツールを管理","ko":"PRD 설정 가이드: AI 에이전트를 위한 도구, Claude Code, OpenCode, Amp, Codex 등의 관리","es":"PRD es una herramienta de gestión de configuración para entornos de codificación de IA, que permite replicar configuraciones personalizadas para herramientas como Claude Code y OpenCode","fr":"PRD est un outil de gestion de configuration pour les environnements de codage de l''IA, qui permet de répliquer des configurations personnalisées pour des outils tels que Claude Code et OpenCode","de":"PRD ist ein Tool für die Konfigurationsverwaltung von KI-Coding-Umgebungen, das die Replikation von benutzerdefinierten Konfigurationen für Tools wie Claude Code und OpenCode ermöglicht","pt":"O PRD é uma ferramenta de gerenciamento de configuração para ferramentas de codificação AI, permitindo a replicação de configurações personalizadas para Claude Code, OpenCode, Amp e outros.","ru":"PRD - это инструмент управления конфигурацией для инструментов кодирования ИИ Агентов, позволяющий реплицировать настраиваемые конфигурации для Claude Code, OpenCode, Amp и других.","ar":"PRD هو أداة لإدارة التكوين لأدوات البرمجة الذكية، مما يسمح بتقليд التكوينات المخصصة لبرامج مثل Claude Code و OpenCode و Amp"},"seo":{"title":{"en":"prd: Comprehensive Configuration Management Setup Guide |...","zh":"PRD配置管理设置指南","ja":"PRD設定ガイド：AIエージェントのためのツール","ko":"PRD 설정 가이드: AI 에이전트를 위한 도구","es":"Guía de configuración de PRD para herramientas de codific...","fr":"Guide de configuration de PRD pour les outils de codage d...","de":"PRD-Konfigurationsleitfaden für KI-Coding-Tools","pt":"Guia de Configuração PRD para Ferramentas de Codificação AI","ru":"Руководство по настройке PRD для инструментов кодирования...","ar":"دليل إعداد PRD لأدوات البرمجة الذكية"},"description":{"en":"Discover how to replicate AI coding tool setups with prd. Learn to generate PRDs and manage configurations for Claude Code, OpenCode, and more. Get started now!","zh":"使用PRD生成器创建详细的产品需求文档，实现AI编码工具的综合配置管理","ja":"AIエージェントのためのPRD設定ガイド：Claude Code、OpenCode、Amp、Codexなどのツールを管理","ko":"PRD 생성기를 사용하여 AI 에이전트를 위한 세부적인 제품 요구 사항 문서를 생성하고, Claude Code, OpenCode, Amp, Codex 등의 도구를 관리","es":"Aprende a configurar tu entorno de codificación de IA con PRD, incluyendo Claude Code, OpenCode, Amp, Codex y Claude Code Switch","fr":"Découvrez comment configurer votre environnement de codage de l''IA avec PRD, y compris Claude Code, OpenCode, Amp, Codex et Claude Code Switch","de":"Erfahren Sie, wie Sie Ihre KI-Coding-Umgebung mit PRD konfigurieren, einschließlich Claude Code, OpenCode, Amp, Codex und Claude Code Switch","pt":"Aprenda a configurar o PRD para ferramentas de codificação AI como Claude Code, OpenCode e Amp, com servidores MCP e plugins personalizados","ru":"Узнайте, как настроить PRD для инструментов кодирования ИИ Агентов, таких как Claude Code, OpenCode и Amp, с серверами MCP и плагинами","ar":"تعرف على كيفية إعداد PRD لأدوات البرمجة الذكية مثل Claude Code و OpenCode و Amp، مع خادم MCP وملحقات مخصصة"},"definition":{"en":"prd is a comprehensive configuration management tool for AI coding tools, creating detailed Product Requirements Documents and replicating custom setups.","zh":"PRD是产品需求文档的缩写，用于描述产品的功能和特性","ja":"PRDはProduct Requirements Documentの略称で、製品の機能と特性を記述する文書","ko":"PRD는 제품 요구 사항 문서의 약자로, 제품의 기능과 특성을 설명하는 문서","es":"PRD es una herramienta de gestión de configuración que crea documentos de requisitos de producto detallados para la implementación de entornos de codificación de IA","fr":"PRD est un outil de gestion de configuration qui crée des documents de spécifications de produit détaillés pour la mise en œuvre d''environnements de codage de l''IA","de":"PRD ist ein Tool für die Konfigurationsverwaltung, das detaillierte Produktanforderungsdokumente für die Implementierung von KI-Coding-Umgebungen erstellt","pt":"O que é PRD? É uma ferramenta de gerenciamento de configuração para ferramentas de codificação AI","ru":"Что такое PRD? Это инструмент управления конфигурацией для инструментов кодирования ИИ Агентов","ar":"ما هو PRD؟ هو أداة لإدارة التكوين لأدوات البرمجة الذكية"},"features":{"en":["Generates structured PRDs based on user input and clarifying questions","Supports custom configurations for Claude Code, OpenCode, Amp, Codex, and Claude Code Switch","Creates PRDs in Markdown format, saved to tasks/prd-[feature-name].md","Asks essential clarifying questions to ensure accurate PRD generation","Replicates complete setups, including MCP servers, plugins, and commands"],"zh":["支持Claude Code、OpenCode、Amp、Codex和Claude Code Switch的自定义配置","提供MCP服务器、插件和命令的管理","生成详细的产品需求文档","支持任务管理，保存到tasks/prd-[feature-name].md","提供3-5个关键的澄清问题"],"ja":["Claude Code、OpenCode、Amp、Codex、Claude Code Switchのカスタム設定をサポート","MCPサーバー、プラグイン、コマンドの管理を提供","詳細な製品要件文書を生成","タスク管理をサポート、tasks/prd-[feature-name].mdに保存","3-5つの重要な質問を提供"],"ko":["Claude Code, OpenCode, Amp, Codex, Claude Code Switch의 사용자 정의 설정 지원","MCP 서버, 플러그인, 명령어 관리 제공","세부적인 제품 요구 사항 문서 생성","작업 관리 지원, tasks/prd-[feature-name].md에 저장","3-5개의 중요한 질문 제공"],"es":["Configuración personalizada para Claude Code, OpenCode, Amp, Codex y Claude Code Switch","Replicación de configuraciones con servidores MCP, plugins y comandos","Creación de documentos de requisitos de producto detallados","Compatibilidad con entornos de codificación de IA","Gestión de configuración para herramientas de codificación de IA"],"fr":["Configuration personnalisée pour Claude Code, OpenCode, Amp, Codex et Claude Code Switch","Réplication de configurations avec des serveurs MCP, des plugins et des commandes","Création de documents de spécifications de produit détaillés","Compatibilité avec les environnements de codage de l''IA","Gestion de configuration pour les outils de codage de l''IA"],"de":["Benutzerdefinierte Konfiguration für Claude Code, OpenCode, Amp, Codex und Claude Code Switch","Replikation von Konfigurationen mit MCP-Servern, Plugins und Befehlen","Erstellung detaillierter Produktanforderungsdokumente","Kompatibilität mit KI-Coding-Umgebungen","Konfigurationsverwaltung für KI-Coding-Tools"],"pt":["Suporte a ferramentas de codificação AI como Claude Code, OpenCode e Amp","Configuração personalizada de servidores MCP e plugins","Replicação de configurações para várias ferramentas de codificação","Geração de Documentos de Requisitos de Produto (PRD) detalhados","Suporte a comandos personalizados"],"ru":["Поддержка инструментов кодирования ИИ Агентов, таких как Claude Code, OpenCode и Amp","Настройка серверов MCP и плагинов","Репликация настраиваемых конфигураций для нескольких инструментов кодирования","Генерация подробных документов требований продукта (PRD)","Поддержка настраиваемых команд"],"ar":["دعم أدوات البرمجة الذكية مثل Claude Code و OpenCode و Amp","تكوين خادم MCP وملحقات مخصصة","تقليд التكوينات المخصصة لأدوات برمجة متعددة","إنشاء وثائق متطلبات المنتج (PRD) مفصلة","دعم أوامر مخصصة"]},"keywords":{"en":["how to use prd","prd setup guide","prd alternative","prd vs configuration management tools","prd install","what is prd","prd for AI coding tools","prd for Claude Code","prd configuration management"],"zh":["PRD配置管理","AI编码工具","Claude Code","OpenCode","Amp","Codex","产品需求文档","任务管理","MCP服务器","插件","命令"],"ja":["PRD設定","AIエージェント","Claude Code","OpenCode","Amp","Codex","製品要件文書","タスク管理","MCPサーバー","プラグイン","コマンド"],"ko":["PRD 설정","AI 에이전트","Claude Code","OpenCode","Amp","Codex","제품 요구 사항 문서","작업 관리","MCP 서버","플러그인","명령어"],"es":["PRD para IA","Configuración de herramientas de codificación de IA","Gestión de configuración para entornos de codificación de IA","Herramientas de codificación de IA"," Claude Code","OpenCode","Amp","Codex","Claude Code Switch"],"fr":["PRD pour l''IA","Configuration des outils de codage de l''IA","Gestion de configuration pour les environnements de codage de l''IA","Outils de codage de l''IA","Claude Code","OpenCode","Amp","Codex","Claude Code Switch"],"de":["PRD für KI","Konfiguration von KI-Coding-Tools","Konfigurationsverwaltung für KI-Coding-Umgebungen","KI-Coding-Tools","Claude Code","OpenCode","Amp","Codex","Claude Code Switch"],"pt":["PRD","ferramentas de codificação AI","Claude Code","OpenCode","Amp","servidores MCP","plugins personalizados","gerenciamento de configuração"],"ru":["PRD","инструменты кодирования ИИ Агентов","Claude Code","OpenCode","Amp","серверы MCP","плагины","управление конфигурацией"],"ar":["PRD","أدوات البرمجة الذكية","Claude Code","OpenCode","Amp","خادم MCP","ملحقات مخصصة","إدارة التكوين"]}},"owner":"jellydn","repo":"my-ai-tools","repoPath":"jellydn/my-ai-tools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.270Z","topics":[],"category":"community","skillMd":{"name":"prd","description":"Generate a Product Requirements Document (PRD) for a new feature. Use when planning a feature, starting a new project, or when asked to create a PRD. Triggers on: create a prd, write prd for, plan this feature, requirements for, spec out.","bodyPreview":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `tasks/prd-[feature-name].md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt i","body":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `tasks/prd-[feature-name].md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Focus on:\n\n- **Problem/Goal:** What problem does this solve?\n- **Core Functionality:** What are the key actions?\n- **Scope/Boundaries:** What should it NOT do?\n- **Success Criteria:** How do we know it''s done?\n\n### Format Questions Like This:\n\n```\n1. What is the primary goal of this feature?\n   A. Improve user onboarding experience\n   B. Increase user retention\n   C. Reduce support burden\n   D. Other: [please specify]\n\n2. Who is the target user?\n   A. New users only\n   B. Existing users only\n   C. All users\n   D. Admin users only\n\n3. What is the scope?\n   A. Minimal viable version\n   B. Full-featured implementation\n   C. Just the backend/API\n   D. Just the UI\n```\n\nThis lets users respond with \"1A, 2C, 3B\" for quick iteration.\n\n---\n\n## Step 2: PRD Structure\n\nGenerate the PRD with these sections:\n\n### 1. Introduction/Overview\nBrief description of the feature and the problem it solves.\n\n### 2. Goals\nSpecific, measurable objectives (bullet list).\n\n### 3. User Stories\nEach story needs:\n- **Title:** Short descriptive name\n- **Description:** \"As a [user], I want [feature] so that [benefit]\"\n- **Acceptance Criteria:** Verifiable checklist of what \"done\" means\n\nEach story should be small enough to implement in one focused session.\n\n**Format:**\n```markdown\n### US-001: [Title]\n**Description:** As a [user], I want [feature] so that [benefit].\n\n**Acceptance Criteria:**\n- [ ] Specific verifiable criterion\n- [ ] Another criterion\n- [ ] Typecheck/lint passes\n- [ ] **[UI stories only]** Verify in browser using dev-browser skill\n```\n\n**Important:** \n- Acceptance criteria must be verifiable, not vague. \"Works correctly\" is bad. \"Button shows confirmation dialog before deleting\" is good.\n- **For any story with UI changes:** Always include \"Verify in browser using dev-browser skill\" as acceptance criteria. This ensures visual verification of frontend work.\n\n### 4. Functional Requirements\nNumbered list of specific functionalities:\n- \"FR-1: The system must allow users to...\"\n- \"FR-2: When a user clicks X, the system must...\"\n\nBe explicit and unambiguous.\n\n### 5. Non-Goals (Out of Scope)\nWhat this feature will NOT include. Critical for managing scope.\n\n### 6. Design Considerations (Optional)\n- UI/UX requirements\n- Link to mockups if available\n- Relevant existing components to reuse\n\n### 7. Technical Considerations (Optional)\n- Known constraints or dependencies\n- Integration points with existing systems\n- Performance requirements\n\n### 8. Success Metrics\nHow will success be measured?\n- \"Reduce time to complete X by 50%\"\n- \"Increase conversion rate by 10%\"\n\n### 9. Open Questions\nRemaining questions or areas needing clarification.\n\n---\n\n## Writing for Junior Developers\n\nThe PRD reader may be a junior developer or AI agent. Therefore:\n\n- Be explicit and unambiguous\n- Avoid jargon or explain it\n- Provide enough detail to understand purpose and core logic\n- Number requirements for easy reference\n- Use concrete examples where helpful\n\n---\n\n## Output\n\n- **Format:** Markdown (`.md`)\n- **Location:** `tasks/`\n- **Filename:** `prd-[feature-name].md` (kebab-case)\n\n---\n\n## Example PRD\n\n```markdown\n# PRD: Task Priority System\n\n## Introduction\n\nAdd priority levels to tasks so users can focus on what matters most. Tasks can be marked as high, medium, or low priority, with visual indicators and filtering to help users manage their workload effectively.\n\n## Goals\n\n- Allow assigning priority (high/medium/low) to any task\n- Provide clear visual differentiation between priority levels\n- Enable filtering and sorting by priority\n- Default new tasks to medium priority\n\n## User Stories\n\n### US-001: Add priority field to database\n**Description:** As a developer, I need to store task priority so it persists across sessions.\n\n**Acceptance Criteria:**\n- [ ] Add priority column to tasks table: ''high'' | ''medium'' | ''low'' (default ''medium'')\n- [ ] Generate and run migration successfully\n- [ ] Typecheck passes\n\n### US-002: Display priority indicator on task cards\n**Description:** As a user, I want to see task priority at a glance so I know what needs attention first.\n\n**Acceptance Criteria:**\n- [ ] Each task card shows colored priority badge (red=high, yellow=medium, gray=low)\n- [ ] Priority visible without hovering or clicking\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-003: Add priority selector to task edit\n**Description:** As a user, I want to change a task''s priority when editing it.\n\n**Acceptance Criteria:**\n- [ ] Priority dropdown in task edit modal\n- [ ] Shows current priority as selected\n- [ ] Saves immediately on selection change\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-004: Filter tasks by priority\n**Description:** As a user, I want to filter the task list to see only high-priority items when I''m focused.\n\n**Acceptance Criteria:**\n- [ ] Filter dropdown with options: All | High | Medium | Low\n- [ ] Filter persists in URL params\n- [ ] Empty state message when no tasks match filter\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n## Functional Requirements\n\n- FR-1: Add `priority` field to tasks table (''high'' | ''medium'' | ''low'', default ''medium'')\n- FR-2: Display colored priority badge on each task card\n- FR-3: Include priority selector in task edit modal\n- FR-4: Add priority filter dropdown to task list header\n- FR-5: Sort by priority within each status column (high to medium to low)\n\n## Non-Goals\n\n- No priority-based notifications or reminders\n- No automatic priority assignment based on due date\n- No priority inheritance for subtasks\n\n## Technical Considerations\n\n- Reuse existing badge component with color variants\n- Filter state managed via URL search params\n- Priority stored in database, not computed\n\n## Success Metrics\n\n- Users can change priority in under 2 clicks\n- High-priority tasks immediately visible at top of lists\n- No regression in task list performance\n\n## Open Questions\n\n- Should priority affect task ordering within a column?\n- Should we add keyboard shortcuts for priority changes?\n```\n\n---\n\n## Checklist\n\nBefore saving the PRD:\n\n- [ ] Asked clarifying questions with lettered options\n- [ ] Incorporated user''s answers\n- [ ] User stories are small and specific\n- [ ] Functional requirements are numbered and unambiguous\n- [ ] Non-goals section defines clear boundaries\n- [ ] Saved to `tasks/prd-[feature-name].md`\n"},"lastSynced":"2026-03-08T02:00:12.830Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing comprehensive Product Requirements Document generation for AI coding tools.","zh":"适合需要为AI编码工具生成全面产品需求文档的开发者代理。","ja":"AIコーディングツールの包括的な製品要件文書の生成を必要とする開発者エージェントに適しています。","ko":"AI 코딩 도구를 위한 포괄적인 제품 요구 사항 문서 생성이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una generación completa de Documentos de Requisitos de Producto para herramientas de codificación de inteligencia artificial.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une génération complète de Documents de Spécifications de Produit pour les outils de codage d''intelligence artificielle.","de":"Perfekt für Entwickleragenten, die eine umfassende Generierung von Produktanforderungsdokumenten für KI-Codierungstools benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de geração abrangente de Documentos de Requisitos de Produto para ferramentas de codificação de IA.","ru":"Идеально для агентов-разработчиков, которым требуется всесторонняя генерация документов требований к продукту для инструментов кодирования ИИ.","ar":"مثالي لعميل التطوير الذي يحتاج إلى توليد شامل لوثائق متطلبات المنتج لأدوات برمجة الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to create detailed Product Requirements Documents in markdown format, utilizing essential clarifying questions and structured PRD generation, compatible with tools like Claude Code, OpenCode, and Amp.","zh":"赋予代理创建详细的产品需求文档，以markdown格式呈现，利用基本的澄清问题和结构化的PRD生成，兼容诸如Claude Code、OpenCode和Amp等工具。","ja":"エージェントが詳細な製品要件文書を作成できるようにし、Markdown形式で基本的な明確化の質問と構造化されたPRD生成を利用し、Claude Code、OpenCode、Ampなどのツールと互換性がある。","ko":"에이전트가 자세한 제품 요구 사항 문서를 만들 수 있도록 하며, 마크다운 형식으로 기본적인澄명 질문과 구조화된 PRD 생성을 활용하며, Claude Code, OpenCode, Amp 등의 도구와 호환됩니다.","es":"Habilita a los agentes a crear documentos de requisitos de producto detallados en formato markdown, utilizando preguntas esenciales de aclaración y generación de PRD estructurada, compatible con herramientas como Claude Code, OpenCode y Amp.","fr":"Permet aux agents de créer des documents de spécifications de produit détaillés au format markdown, en utilisant des questions essentielles de clarification et une génération de PRD structurée, compatible avec des outils tels que Claude Code, OpenCode et Amp.","de":"Ermächtigt Agenten, detaillierte Produktanforderungsdokumente im Markdown-Format zu erstellen, indem sie wesentliche Klarstellungsfragen und strukturierte PRD-Generierung verwenden, kompatibel mit Tools wie Claude Code, OpenCode und Amp.","pt":"Habilita os agentes a criar Documentos de Requisitos de Produto detalhados no formato markdown, utilizando perguntas essenciais de esclarecimento e geração estruturada de PRD, compatível com ferramentas como Claude Code, OpenCode e Amp.","ru":"Позволяет агентам создавать подробные документы требований к продукту в формате markdown, используя основные вопросы разъяснения и структурированную генерацию PRD, совместимую с инструментами seperti Claude Code, OpenCode и Amp.","ar":"تمكّن الوكيل من إنشاء وثائق متطلبات المنتج مفصلة بالتنسيق markdown، باستخدام أسئلة توضيحية أساسية وتوليد بنية.PRД، متوافقة مع أدوات مثل Claude Code و OpenCode و Amp."},"useCases":{"en":["Generating PRDs for new feature implementations","Creating structured documentation for development teams","Clarifying project requirements through essential questions"],"zh":["为新功能实现生成PRD","为开发团队创建结构化文档","通过基本问题澄清项目需求"],"ja":["新機能実装のPRDを生成する","開発チームの構造化ドキュメントを作成する","基本的な質問を通じてプロジェクトの要件を明確化する"],"ko":["새 기능 구현을 위한 PRD 생성","개발 팀을 위한 구조화된 문서 생성","기본적인 질문을 통해 프로젝트 요구 사항澄명"],"es":["Generación de PRD para nuevas implementaciones de funciones","Creación de documentación estructurada para equipos de desarrollo","Aclaración de los requisitos del proyecto a través de preguntas esenciales"],"fr":["Génération de PRD pour de nouvelles mises en œuvre de fonctionnalités","Création d''une documentation structurée pour les équipes de développement","Clarification des exigences du projet à l''aide de questions essentielles"],"de":["Generierung von PRD für neue Funktionsimplementierungen","Erstellung strukturierter Dokumentation für Entwicklungsteams","Klärung der Projektanforderungen durch wesentliche Fragen"],"pt":["Geração de PRDs para implementações de recursos novos","Criação de documentação estruturada para equipes de desenvolvimento","Esclarecimento de requisitos de projeto por meio de perguntas essenciais"],"ru":["Генерация PRD для реализации новых функций","Создание структурированной документации для команд разработки","Разъяснение требований проекта с помощью основных вопросов"],"ar":["توليد وثائق PRD لتنفيذ ميزات جديدة","إنشاء توثيق منظم للفرق التطويرية","توضيح متطلبات المشروع من خلال أسئلة أساسية"]},"limitations":{"en":["Requires user input for feature description","Limited to generating PRDs, does not implement features"],"zh":["需要用户输入功能描述","仅限于生成PRD，不实施功能"],"ja":["機能の説明をユーザーが入力する必要がある","PRDの生成のみで、機能の実装は行わない"],"ko":["기능 설명에 대한 사용자 입력이 필요","PRD 생성만 가능하며, 기능 구현은 하지 않음"],"es":["Requiere entrada de usuario para la descripción de la función","Limitado a la generación de PRD, no implementa funciones"],"fr":["Nécessite une saisie utilisateur pour la description de la fonction","Limité à la génération de PRD, n''implémente pas les fonctionnalités"],"de":["Benutzereingabe für die Funktionsbeschreibung ist erforderlich","Begrenzt auf die Generierung von PRD, implementiert keine Funktionen"],"pt":["Requer entrada do usuário para descrição de recurso","Limitado à geração de PRDs, não implementa recursos"],"ru":["Требует ввода пользователя для описания функции","Ограничен генерацией PRD, не реализует функции"],"ar":["يتطلب إدخال المستخدم لوصف الميزة","محدود بتوليد وثائق PRD، ولا يطبق الميزات"]},"version":4},"contentHash":"791920d6ef8bfbc08d6163b187edcba1cd632221feba0422970affc66e29b857","qualityScore":54}');
