INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jellydn/my-ai-tools/prd', 'prd', 'jellydn', 'my-ai-tools', 'community', 'prd jellydn my-ai-tools community The prd skill provides comprehensive configuration management for AI coding tools, generating detailed Product Requirements Documents for implementation. It benefits developers working with Claude Code, OpenCode, Amp, Codex, and Claude Code Switch. PRD配置管理设置指南，用于AI编码工具的综合配置管理，包括Claude Code、OpenCode、Amp、Codex和Claude Code Switch AIエージェントのためのPRD設定ガイド：Claude Code、OpenCode、Amp、Codexなどのツールを管理 PRD 설정 가이드: AI 에이전트를 위한 도구, Claude Code, OpenCode, Amp, Codex 등의 관리 PRD es una herramienta de gestión de configuración para entornos de codificación de IA, que permite replicar configuraciones personalizadas para herramientas como Claude Code y OpenCode PRD est un outil de gestion de configuration pour les environnements de codage de l''IA, qui permet de répliquer des configurations personnalisées pour des outils tels que Claude Code et OpenCode PRD ist ein Tool für die Konfigurationsverwaltung von KI-Coding-Umgebungen, das die Replikation von benutzerdefinierten Konfigurationen für Tools wie Claude Code und OpenCode ermöglicht O PRD é uma ferramenta de gerenciamento de configuração para ferramentas de codificação AI, permitindo a replicação de configurações personalizadas para Claude Code, OpenCode, Amp e outros. PRD - это инструмент управления конфигурацией для инструментов кодирования ИИ Агентов, позволяющий реплицировать настраиваемые конфигурации для Claude Code, OpenCode, Amp и других. PRD هو أداة لإدارة التكوين لأدوات البرمجة الذكية، مما يسمح بتقليд التكوينات المخصصة لبرامج مثل Claude Code و OpenCode و Amp how to use prd prd setup guide prd alternative prd vs configuration management tools prd install what is prd prd for AI coding tools prd for Claude Code prd configuration management PRD配置管理 AI编码工具 Claude Code OpenCode Amp Codex 产品需求文档 任务管理 MCP服务器 插件 命令 Generates structured PRDs based on user input and clarifying questions Supports custom configurations for Claude Code, OpenCode, Amp, Codex, and Claude Code Switch Creates PRDs in Markdown format, saved to tasks/prd-[feature-name].md Asks essential clarifying questions to ensure accurate PRD generation Replicates complete setups, including MCP servers, plugins, and commands prd is a comprehensive configuration management tool for AI coding tools, creating detailed Product Requirements Documents and replicating custom setups.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('untitled-data-company/data-skills/uv', 'community', 'untitled-data-company', 'data-skills', 'untitled-data-company/data-skills', 'uv', 0, 0, 54, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:14.799Z', '46108fd7a09f0c2238a5bd17b1912da9623cedffa6a6285512257c1efd229286', '{"id":"untitled-data-company/data-skills/uv","name":"uv","description":{"en":"The uv skill provides Python dependency and project management, offering an alternative to pip and poetry. It benefits developers by streamlining workflow and project setup.","zh":"uv包管理器是Python依赖管理的优质选择，提供简单易用的工作流程。使用uv可以优化项目依赖管理","ja":"uvパッケージマネージャーはPython依存性管理の優れた選択肢であり、シンプルで使いやすいワークフローを提供します。uvを使用するとプロジェクトの依存性管理を最適化できます","ko":"uv 패키지 매니저는 Python 의존성 관리의 우수한 선택입니다. 간단하고 사용하기 쉬운 워크플로우를 제공하여 프로젝트 의존성 관리를 최적화할 수 있습니다","es":"uv es un administrador de dependencias de Python que ofrece una alternativa a pip y poetry. Utilice uv para simplificar su flujo de trabajo y gestionar sus proyectos de manera más eficiente","fr":"uv est un gestionnaire de dépendances Python qui offre une alternative à pip et poetry. Utilisez uv pour simplifier votre workflow et gérer vos projets de manière plus efficace","de":"uv ist ein Python-Abhängigkeitsmanager, der eine Alternative zu pip und poetry bietet. Verwenden Sie uv, um Ihren Workflow zu vereinfachen und Ihre Projekte effizienter zu verwalten","pt":"O uv é um gerenciador de dependências Python que ajuda a melhorar a produtividade e a facilidade de uso. Ele oferece uma alternativa ao pip/poetry.","ru":"uv - менеджер зависимостей Python, который помогает повысить производительность и облегчить использование. Это альтернатива pip/poetry с помощью ИИ Агентов","ar":"uv هو أداة لإدارة التبعيات بايثون التي تساعد على تحسين الإنتاجية وسهولة الاستخدام. وهو بديل ل pip/poetry باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"uv: Python Dependency Management Setup Guide | AI Agent S...","zh":"uv 包管理器设置指南 - 优于pip/poetry的Python依赖管理","ja":"uvパッケージマネージャー設定ガイド - pip/poetryよりも優れたPython依存性管理","ko":"uv 패키지 매니저 설정 가이드 - pip/poetry보다 우수한 Python 의존성 관리","es":"Configuración de uv: Guía de administración de dependenci...","fr":"Configurer uv: Meilleures pratiques pour la gestion de dé...","de":"uv Einrichten: Leitfaden für Python-Abhängigkeitsmanagement","pt":"Guia de Configuração do uv: Gerenciamento de Dependências...","ru":"Настройка uv: Руководство по управлению зависимостями Pyt...","ar":"دليل إعداد uv: إدارة التبعيات بايثون باستخدام أدوات الذكا..."},"description":{"en":"Discover how to migrate from pip/poetry to uv and optimize your Python projects with the uv package manager - get started now!","zh":"使用uv包管理器优化Python项目依赖管理，提高开发效率。了解uv的工作原理和最佳实践","ja":"uvパッケージマネージャーを使用してPythonプロジェクトの依存性管理を最適化し、開発効率を向上させます。uvの仕組みとベストプラクティスについて学びましょう","ko":"uv 패키지 매니저를 사용하여 Python 프로젝트 의존성 관리를 최적화하고 개발 효율성을 높이세요. uv의 작동 원리와 최선의 관행에 대해 알아보세요","es":"Aprenda a configurar uv para administrar dependencias de Python de manera efectiva y mejore su flujo de trabajo con nuestra guía paso a paso","fr":"Découvrez comment configurer uv pour gérer les dépendances Python de manière efficace et améliorer votre workflow avec notre guide étape par étape","de":"Erfahren Sie, wie Sie uv für effektives Python-Abhängigkeitsmanagement einrichten und Ihren Workflow mit unserer Schritt-für-Schritt-Anleitung verbessern können","pt":"Aprenda a usar o uv como gerenciador de dependências Python, migrando de pip/poetry com facilidade e melhorando a produtividade","ru":"Узнайте, как использовать uv в качестве менеджера зависимостей Python, мигрируя с pip/poetry и повышая производительность с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام uv كاداة لإدارة التبعيات بايثون، وانتقل بسهولة من pip/poetry وتحسين الإنتاجية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"uv is a package manager that prefers a workflow over pip/poetry for Python dependency and project management, utilizing tools like uvx migrate-to-uv.","zh":"uv包管理器是一种优于pip/poetry的Python依赖管理工具","ja":"uvパッケージマネージャーはpip/poetryよりも優れたPython依存性管理ツールです","ko":"uv 패키지 매니저는 pip/poetry보다 우수한 Python 의존성 관리 도구입니다","es":"uv es un administrador de dependencias de Python que permite a los desarrolladores gestionar sus proyectos y dependencias de manera efectiva","fr":"uv est un outil de gestion de dépendances Python qui permet aux développeurs de gérer leurs projets et dépendances de manière efficace","de":"uv ist ein Python-Abhängigkeitsmanager, der es Entwicklern ermöglicht, ihre Projekte und Abhängigkeiten effektiv zu verwalten","pt":"O uv é um pacote de gerenciamento de dependências Python que visa substituir o pip/poetry","ru":"uv - пакет управления зависимостями Python, предназначенный для замены pip/poetry с помощью ИИ Агентов","ar":"uv هو حزمة لإدارة التبعيات بايثون تهدف إلى استبدال pip/poetry باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Migrates metadata and lockfiles from poetry/pipenv/conda using uvx migrate-to-uv","Supports project, script, and tool modes for flexible dependency management","Utilizes the uv sync command for efficient project synchronization","Converts lockfiles from poetry.lock, Pipfile, and environment.yml formats","Provides a workflow for managing Python dependencies and projects","Enables switching from existing package managers like pip and poetry"],"zh":["优于pip/poetry的Python依赖管理","支持项目、脚本和工具三种工作模式","提供migrate-to-uv工具用于转换元数据和锁文件","支持uv sync用于同步依赖项","简化项目依赖管理","提高开发效率"],"ja":["pip/poetryよりも優れたPython依存性管理","プロジェクト、スクリプト、ツールの3つのワークモードをサポート","migrate-to-uvツールを使用してメタデータとロックファイルを転換","uv syncを使用して依存関係を同期","プロジェクトの依存性管理を簡素化","開発効率を向上"],"ko":["pip/poetry보다 우수한 Python 의존성 관리","프로젝트, 스크립트, 툴의 3가지 워크플로우 모드를 지원","migrate-to-uv 툴을 사용하여 메타데이터와 잠금 파일을 전환","uv sync를 사용하여 의존 항목을 동기화","프로젝트 의존성 관리를 간소화","개발 효율성을 향상"],"es":["Administración de dependencias de Python","Alternativa a pip y poetry","Herramienta de migración para convertir proyectos de poetry a uv","Compatibilidad con proyectos de Python","Gestión de metadatos y lockfiles","Integración con herramientas de desarrollo de Python"],"fr":["Gestion de dépendances Python","Alternative à pip et poetry","Outil de migration pour convertir des projets poetry en uv","Compatibilité avec les projets Python","Gestion de métadonnées et de lockfiles","Intégration avec les outils de développement Python"],"de":["Verwaltung von Python-Abhängigkeiten","Alternative zu pip und poetry","Migrationswerkzeug zum Umwandeln von poetry-Projekten in uv","Kompatibilität mit Python-Projekten","Verwaltung von Metadaten und Lockfiles","Integration mit Python-Entwicklungstools"],"pt":["Migração fácil de pip/poetry para uv","Gerenciamento de dependências Python com uv","Melhoria da produtividade com uv","Compatibilidade com projetos Python existentes","Ferramenta de migração migrate-to-uv para uvx"],"ru":["Легкая миграция с pip/poetry на uv","Управление зависимостями Python с помощью uv","Повышение производительности с uv","Совместимость с существующими проектами Python","Инструмент миграции migrate-to-uv для uvx с помощью ИИ Агентов"],"ar":["هجرة سهلة من pip/poetry إلى uv","إدارة التبعيات بايثون باستخدام uv","تحسين الإنتاجية مع uv","توافق مع مشاريع بايثون الحالية","أداة هجرة migrate-to-uv ل uvx باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use uv","uv vs pip","uv alternative to poetry","uv install guide","what is uv package manager","uv setup for Python projects","uvx migrate-to-uv tool","uv sync command","uv for AI agents"],"zh":["uv包管理器","Python依赖管理","pip/poetry替代","项目依赖管理","开发效率优化","uv sync","migrate-to-uv","Python开发工具","依存性管理"],"ja":["uvパッケージマネージャー","Python依存性管理","pip/poetry代替","プロジェクト依存性管理","開発効率最適化","uv sync","migrate-to-uv","Python開発ツール","依存関係管理"],"ko":["uv 패키지 매니저","Python 의존성 관리","pip/poetry 대체","프로젝트 의존성 관리","개발 효율성 최적화","uv sync","migrate-to-uv","Python 개발 도구","의존 항목 관리"],"es":["uv python","administración de dependencias python","alternativa a pip","alternativa a poetry","herramienta de migración python","gestión de proyectos python","desarrollo de python","herramientas de desarrollo python","uv vs pip","uv vs poetry"],"fr":["uv python","gestion de dépendances python","alternative à pip","alternative à poetry","outil de migration python","gestion de projets python","développement python","outils de développement python","uv vs pip","uv vs poetry"],"de":["uv python","verwaltung von python-abhängigkeiten","alternative zu pip","alternative zu poetry","migrationswerkzeug python","verwaltung von python-projekten","python-entwicklung","python-entwicklungstools","uv vs pip","uv vs poetry"],"pt":["uv python","gerenciamento de dependências python","migração de pip para uv","alternativa ao pip","ferramenta de migração python","produtividade python","desenvolvimento python"],"ru":["uv python","управление зависимостями python","миграция с pip на uv","альтернатива pip","инструмент миграции python","производительность python","разработка python с помощью ИИ Агентов"],"ar":["uv python","إدارة التبعيات بايثون","هجرة من pip إلى uv","بديل ل pip","أداة هجرة بايثون","إنتاجية بايثون","تطوير بايثون باستخدام أدوات الذكاء الاصطناعي"]}},"owner":"untitled-data-company","repo":"data-skills","repoPath":"untitled-data-company/data-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"uv","description":">","bodyPreview":"# uv Package Manager\n\nPrefer **uv** over pip/poetry for Python dependency and project management. Use the workflow below and choose the right mode (project, script, or tool).\n\n## Mode Decision\n\n```\nUser needs to...\n│\n├─ Repo uses poetry / pipenv / conda (poetry.lock, Pipfile, environment.yml)\n│  → Ask: \"This repo uses [poetry/pipenv/conda]. Do you want to switch to uv?\"\n│  → If yes: prefer the migrate-to-uv tool (uvx migrate-to-uv in project root) to convert metadata and lockfile; then uv sync.","body":"# uv Package Manager\n\nPrefer **uv** over pip/poetry for Python dependency and project management. Use the workflow below and choose the right mode (project, script, or tool).\n\n## Mode Decision\n\n```\nUser needs to...\n│\n├─ Repo uses poetry / pipenv / conda (poetry.lock, Pipfile, environment.yml)\n│  → Ask: \"This repo uses [poetry/pipenv/conda]. Do you want to switch to uv?\"\n│  → If yes: prefer the migrate-to-uv tool (uvx migrate-to-uv in project root) to convert metadata and lockfile; then uv sync. Remove legacy files only after user confirms.\n│  → If no: do not use uv for project management; use the existing tool or uv pip only if appropriate.\n│\n├─ Repo has requirements.txt (no pyproject.toml)\n│  → Ask: \"This repo uses requirements.txt. Do you want to convert to uv (pyproject.toml + uv.lock)?\"\n│  → If yes: guide conversion (uv init, uv add from requirements, then uv sync)\n│  → If no: use Pip-Compatible workflow (uv pip)\n│\n├─ Manage a project (pyproject.toml, lockfile, team repo)\n│  → Use PROJECT workflow (uv init, uv add, uv sync, uv run)\n│\n├─ Run a single script with dependencies\n│  → Use SCRIPT workflow (uv add --script, uv run <script>)\n│\n├─ Run a one-off CLI tool (no project)\n│  → Use uvx: uvx <package> [args] or uv tool install <package>\n│\n└─ User declined conversion; existing pip/requirements workflow\n   → Use uv pip (uv venv, uv pip sync, uv pip compile)\n```\n\n## Project Workflow\n\nUse for apps, libraries, or any repo with `pyproject.toml`.\n\n### New project\n\n```bash\nuv init [project-name]\ncd [project-name]\nuv add <package> [package2...]\nuv sync\nuv run python main.py\n# or: uv run <any command>\n```\n\n### Existing project (already has pyproject.toml)\n\n```bash\nuv sync                    # install from lockfile (or resolve and lock)\nuv add <package>           # add dependency, update lockfile and env\nuv remove <package>       # remove dependency\nuv run <command>          # run in project venv (creates .venv if needed)\nuv lock                   # refresh lockfile only\n```\n\n### Pin Python version (optional)\n\n```bash\nuv python pin 3.11        # writes .python-version\nuv python install 3.11    # ensure that version is available\n```\n\n**Rules:**\n\n- Use `uv add` for project dependencies; avoid editing `pyproject.toml` by hand for deps when uv can do it.\n- After changing dependencies, run `uv sync` (or rely on `uv add`/`uv remove` which update the env).\n- Run project commands via `uv run` so the correct venv and env are used; do not assume `pip install` or manual activate.\n- When creating a new project, ensure `.venv` is in `.gitignore` (uv init usually adds it; add it if missing).\n- Treat `uv.lock` as a mandatory source-controlled artifact: commit it so all environments and CI use the same dependency versions; the lockfile is universal (one file for Windows, macOS, Linux).\n\n## Script Workflow\n\nFor a single Python file that needs packages (no full project).\n\n1. Add inline script metadata (or use `uv add --script` to add deps to the file):\n\n```python\n# /// script\n# requires-python = \">=3.10\"\n# dependencies = [\"requests\"]\n# ///\nimport requests\nprint(requests.get(\"https://example.com\"))\n```\n\n2. Add deps from CLI (updates the script file):\n\n```bash\nuv add --script example.py requests\n```\n\n3. Run with uv (creates an ephemeral env if needed):\n\n```bash\nuv run example.py\n```\n\nFor executable scripts that run without typing `uv run`, use a shebang (PEP 723):\n\n```python\n#!/usr/bin/env -S uv run --script\n# /// script\n# requires-python = \">=3.10\"\n# dependencies = [\"requests\"]\n# ///\n```\n\n**Rules:**\n\n- Use `uv add --script <file>` to declare dependencies for that script.\n- Use `uv run <script>.py` to run it; do not tell the user to `pip install` first.\n- For portability, scripts can use shebang `#!/usr/bin/env -S uv run --script`.\n\n## Tools (one-off CLI from PyPI)\n\nRun without installing globally:\n\n```bash\nuvx <package> [args]\n# e.g. uvx ruff check .\n# e.g. uvx pycowsay \"hello\"\n```\n\nInstall the tool for repeated use:\n\n```bash\nuv tool install <package>\n# e.g. uv tool install ruff\n```\n\n**Rules:**\n\n- Prefer `uvx` for one-off runs; use `uv tool install` when the user will call the tool often.\n\n## Repos Using requirements.txt\n\nWhen the repo has **requirements.txt** (and no `pyproject.toml`):\n\n1. **Ask the user:** \"This repo uses requirements.txt. Do you want to convert to uv (pyproject.toml + uv.lock)?\"\n2. **If yes:** Guide conversion: `uv init`, then `uv add -r requirements.txt` (or, if you have requirements.in and locked requirements.txt, `uv add -r requirements.in -c requirements.txt` to preserve versions), then `uv sync`. Optionally remove or keep requirements.txt per user preference.\n3. **If no:** Use the Pip-Compatible workflow below (no conversion).\n\nDo not convert to uv without asking when the repo currently uses only requirements.txt.\n\n## Pip-Compatible Workflow\n\nFor repos that still use `requirements.txt` or `pip` (and user did not want conversion):\n\n```bash\nuv venv                           # create .venv\nuv pip sync requirements.txt      # install from locked requirements\nuv pip compile requirements.in -o requirements.txt  # compile/lock\n```\n\nUse `uv pip` instead of `pip` for the same commands when you want speed and better resolution.\n\n## CI and Docker\n\nWhen the user asks about **uv in CI** (e.g. GitHub Actions) or **uv in Docker**, advise using the patterns below and point to [references/docker-and-ci.md](references/docker-and-ci.md) for full detail.\n\n**CI (e.g. GitHub Actions):**\n- Install uv with the official `astral-sh/setup-uv` action; use cache keyed by `uv.lock` and `pyproject.toml`.\n- Run `uv sync --locked` so the job fails if the lockfile is out of sync (no silent deploy of untested deps).\n- Optionally run `uv cache prune --ci` at end of job to keep cache lean.\n\n**Docker:**\n- Use a multi-stage build: builder stage with `ghcr.io/astral-sh/uv`, copy only `uv.lock` and `pyproject.toml` first, run `uv sync` (or equivalent), then copy `.venv` and app code into a slim runtime image (no uv/Rust in final image).\n- Set `UV_COMPILE_BYTECODE=1` and `UV_LINK_MODE=copy` in the build stage; use `--no-editable` when syncing so the final image doesn’t depend on source.\n- Run the container as a non-root user when possible.\n\nFor step-by-step Dockerfiles and CI workflow examples, see [references/docker-and-ci.md](references/docker-and-ci.md).\n\n## IDE Setup (Use uv .venv)\n\nAfter uv creates or uses a project `.venv`, **automatically try** to configure the IDE to use that interpreter so run/debug and IntelliSense use the same environment.\n\n1. **Target:** Workspace settings (project-scoped, shareable): `.vscode/settings.json`\n2. **Setting:** `python.defaultInterpreterPath` pointing at the project’s `.venv`:\n   - Linux/macOS: `\"${workspaceFolder}/.venv/bin/python\"`\n   - Windows: `\"${workspaceFolder}/.venv/Scripts/python.exe\"`\n3. **Behavior:** If `.vscode/settings.json` exists, read it, add or update only `python.defaultInterpreterPath`, then write back. If it doesn’t exist, create `.vscode/` and the file with this setting. Preserve all other keys.\n4. **When:** After `uv init`, `uv sync`, or conversion from requirements.txt that creates/updates `.venv`.\n\n**Rules:**\n\n- Use workspace settings (`.vscode/settings.json`), not user settings, so the choice is per-project and can be committed.\n- Do not overwrite or remove other settings in the file.\n- If the workspace already has a Python interpreter selected, still add/update this key so the project’s `.venv` is the default.\n\n## Automation and Agent Behavior\n\n1. **New Python project:** Run `uv init` (or `uv init <name>`), then `uv add` for initial deps, then `uv sync`. Suggest `uv run` for run/test commands.\n2. **Add dependency:** Use `uv add <package>`. For dev/optional: `uv add --dev <package>`.\n3. **Run something:** Use `uv run <command>` in a project; `uv run script.py` for scripts; `uvx <tool>` for one-off tools.\n4. **No manual venv activate:** Prefer `uv run` so the agent and user don’t depend on `source .venv/bin/activate`.\n5. **Lockfile:** Commit `uv.lock`; treat it as mandatory for parity. After pull or after editing deps, run `uv sync`. In CI, use `uv sync --locked` so the job fails if the lockfile is out of sync with `pyproject.toml`.\n6. **Detecting uv:** If `pyproject.toml` exists and there is no poetry/pipenv/conda (no poetry.lock, Pipfile, environment.yml), assume uv is allowed and suggest uv commands. If the user said \"use uv\", always prefer uv over pip/poetry. If poetry/pipenv/conda is present, ask before switching to uv (see Mode Decision).\n7. **requirements.txt only:** If the repo has requirements.txt but no pyproject.toml, ask whether the user wants to convert to uv before converting or using uv pip.\n8. **IDE interpreter:** After uv creates or syncs `.venv`, try to set the workspace Python interpreter by adding or updating `python.defaultInterpreterPath` in `.vscode/settings.json` (see IDE Setup above).\n\n## Common Commands Reference\n\n| Task              | Command                    |\n|-------------------|----------------------------|\n| New project       | `uv init [name]`           |\n| Add dependency    | `uv add <pkg>`             |\n| Add dev dependency| `uv add --dev <pkg>`       |\n| Remove dependency | `uv remove <pkg>`          |\n| Install from lock | `uv sync`                  |\n| Update lockfile   | `uv lock`                  |\n| Run in project    | `uv run <cmd>`             |\n| Run script        | `uv run script.py`        |\n| Run CLI tool once | `uvx <pkg> [args]`         |\n| Install tool      | `uv tool install <pkg>`    |\n| Create venv       | `uv venv`                  |\n| Pin Python        | `uv python pin 3.11`       |\n| Install Python    | `uv python install 3.11`   |\n\n## Additional Resources\n\n- Full CLI and options: [references/cli-and-commands.md](references/cli-and-commands.md)\n- Example flows: [references/examples.md](references/examples.md)\n- Common issues and fixes: [references/troubleshooting.md](references/troubleshooting.md)\n- Docker and CI: [references/docker-and-ci.md](references/docker-and-ci.md)\n- Workspaces (monorepos) and resolution: [references/workspaces-and-resolution.md](references/workspaces-and-resolution.md)\n"},"lastSynced":"2026-03-08T02:00:14.799Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing streamlined dependency and project management.","zh":"非常适合需要简化依赖和项目管理的Python开发代理。","ja":"Python開発エージェントが依存関係とプロジェクト管理をストリームライン化する必要がある場合に最適です。","ko":"의존성 및 프로젝트 관리를 단순화해야 하는 Python 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Python que necesitan una gestión de dependencias y proyectos optimizada.","fr":"Parfait pour les Agents de Développement Python ayant besoin d''une gestion de dépendances et de projets rationalisée.","de":"Perfekt für Python-Entwicklungsagenten, die eine optimierte Abhängigkeits- und Projektverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de gerenciamento de dependência e projeto otimizado.","ru":"Идеально подходит для агентов разработки Python, которым требуются оптимизированное управление зависимостями и проектами.","ar":"مثالي للوكلاء في تطوير بايثون الذين يحتاجون إلى إدارة تبعية ومشروع محسّنة."},"recommendation":{"en":"Empowers agents to manage Python dependencies and projects using uv, providing an alternative to pip and poetry with features like migration tools and lockfile management, supporting protocols such as uvx migrate-to-uv and file formats like poetry.lock.","zh":"赋予代理管理Python依存关系和项目的能力，使用uv，提供了pip和poetry的替代方案，具有迁移工具和锁定文件管理等功能，支持诸如uvx migrate-to-uv的协议和poetry.lock等文件格式。","ja":"エージェントがuvを使用してPythonの依存関係とプロジェクトを管理できるようにし、pipとpoetryの代替として、移行ツールやロックファイル管理などの機能を提供し、uvx migrate-to-uvなどのプロトコルやpoetry.lockなどのファイル形式をサポートします。","ko":"에이전트가 uv를 사용하여 Python 의존성 및 프로젝트를 관리할 수 있도록 하여 pip 및 poetry의 대안으로, 마이그레이션 도구 및 잠금 파일 관리와 같은 기능을 제공하며 uvx migrate-to-uv와 같은 프로토콜 및 poetry.lock와 같은 파일 형식을 지원합니다.","es":"Habilita a los agentes a gestionar dependencias y proyectos de Python utilizando uv, proporcionando una alternativa a pip y poetry con características como herramientas de migración y gestión de lockfile, compatibles con protocolos como uvx migrate-to-uv y formatos de archivo como poetry.lock.","fr":"Permet aux agents de gérer les dépendances et les projets Python à l''aide de uv, offrant une alternative à pip et poetry avec des fonctionnalités telles que des outils de migration et une gestion de lockfile, prenant en charge des protocoles tels que uvx migrate-to-uv et des formats de fichiers tels que poetry.lock.","de":"Ermächtigt die Agenten, Python-Abhängigkeiten und -Projekte mithilfe von uv zu verwalten, was eine Alternative zu pip und poetry mit Funktionen wie Migrationswerkzeugen und Lockfile-Verwaltung bietet, die Protokolle wie uvx migrate-to-uv und Dateiformate wie poetry.lock unterstützt.","pt":"Habilita os agentes a gerenciar dependências e projetos Python usando uv, fornecendo uma alternativa a pip e poetry com recursos como ferramentas de migração e gerenciamento de lockfile, suportando protocolos como uvx migrate-to-uv e formatos de arquivo como poetry.lock.","ru":"Наделяет агентов возможностью управлять зависимостями и проектами Python с помощью uv, предоставляя альтернативу pip и poetry с функциями như инструменты миграции и управление lockfile, поддерживая протоколы như uvx migrate-to-uv и форматы файлов như poetry.lock.","ar":"تمكن الوكلاء من إدارة التبعيات والمشاريع بايثون باستخدام uv، مما يوفر بديلاً عن pip وpoetry مع ميزات مثل أدوات الهجرة وإدارة lockfile، ودعم بروتوكولات مثل uvx migrate-to-uv وتنسيقات الملفات مثل poetry.lock."},"useCases":{"en":["Migrating existing projects from pip or poetry to uv","Streamlining workflow with uv sync","Converting metadata and lockfiles with uvx migrate-to-uv"],"zh":["从pip或poetry迁移到uv的现有项目","使用uv sync简化工作流程","使用uvx migrate-to-uv转换元数据和锁定文件"],"ja":["pipまたはpoetryからuvへの既存のプロジェクトの移行","uv syncを使用してワークフローを簡素化する","uvx migrate-to-uvを使用してメタデータとロックファイルを変換する"],"ko":["pip 또는 poetry에서 uv로의 기존 프로젝트 마이그레이션","uv sync를 사용하여 워크플로우를 단순화","uvx migrate-to-uv를 사용하여 메타데이터 및 잠금 파일을 변환"],"es":["Migrar proyectos existentes de pip o poetry a uv","Optimizar el flujo de trabajo con uv sync","Convertir metadatos y lockfiles con uvx migrate-to-uv"],"fr":["Migration de projets existants de pip ou poetry vers uv","Optimisation du flux de travail avec uv sync","Conversion de métadonnées et de lockfiles avec uvx migrate-to-uv"],"de":["Migrieren bestehender Projekte von pip oder poetry zu uv","Optimieren des Arbeitsablaufs mit uv sync","Umwandeln von Metadaten und Lockfiles mit uvx migrate-to-uv"],"pt":["Migrar projetos existentes de pip ou poetry para uv","Otimizar fluxo de trabalho com uv sync","Converter metadados e lockfiles com uvx migrate-to-uv"],"ru":["Мигрировать существующие проекты из pip или poetry в uv","Оптимизировать рабочий процесс с uv sync","Преобразовать метаданные и lockfiles с uvx migrate-to-uv"],"ar":["هجرة المشاريع الحالية من pip أو poetry إلى uv","تحسين تدفق العمل مع uv sync","تحويل البيانات الوصفية وlockfiles مع uvx migrate-to-uv"]},"limitations":{"en":["Requires Python environment","Limited to Python dependency and project management"],"zh":["需要Python环境","仅限Python依赖关系和项目管理"],"ja":["Python環境が必要","Pythonの依存関係とプロジェクト管理のみ"],"ko":["Python 환경이 필요","Python 의존성 및 프로젝트 관리만"],"es":["Requiere entorno de Python","Limitado a la gestión de dependencias y proyectos de Python"],"fr":["Nécessite un environnement Python","Limité à la gestion des dépendances et des projets Python"],"de":["Benötigt Python-Umgebung","Begrenzt auf die Verwaltung von Python-Abhängigkeiten und -Projekten"],"pt":["Requer ambiente Python","Limitado ao gerenciamento de dependência e projeto Python"],"ru":["Требуется среда Python","Ограничен управлением зависимостями и проектами Python"],"ar":["يتطلب بيئة Python","محدود بإدارة التبعية والمشروع Python"]},"version":4},"contentHash":"46108fd7a09f0c2238a5bd17b1912da9623cedffa6a6285512257c1efd229286","qualityScore":54}');
