INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('untitled-data-company/data-skills/uv', 'uv', 'untitled-data-company', 'data-skills', 'community', 'uv untitled-data-company data-skills community The uv skill provides Python dependency and project management, offering an alternative to pip and poetry. It benefits developers by streamlining workflow and project setup. uv包管理器是Python依赖管理的优质选择，提供简单易用的工作流程。使用uv可以优化项目依赖管理 uvパッケージマネージャーはPython依存性管理の優れた選択肢であり、シンプルで使いやすいワークフローを提供します。uvを使用するとプロジェクトの依存性管理を最適化できます uv 패키지 매니저는 Python 의존성 관리의 우수한 선택입니다. 간단하고 사용하기 쉬운 워크플로우를 제공하여 프로젝트 의존성 관리를 최적화할 수 있습니다 uv es un administrador de dependencias de Python que ofrece una alternativa a pip y poetry. Utilice uv para simplificar su flujo de trabajo y gestionar sus proyectos de manera más eficiente uv est un gestionnaire de dépendances Python qui offre une alternative à pip et poetry. Utilisez uv pour simplifier votre workflow et gérer vos projets de manière plus efficace uv ist ein Python-Abhängigkeitsmanager, der eine Alternative zu pip und poetry bietet. Verwenden Sie uv, um Ihren Workflow zu vereinfachen und Ihre Projekte effizienter zu verwalten O uv é um gerenciador de dependências Python que ajuda a melhorar a produtividade e a facilidade de uso. Ele oferece uma alternativa ao pip/poetry. uv - менеджер зависимостей Python, который помогает повысить производительность и облегчить использование. Это альтернатива pip/poetry с помощью ИИ Агентов uv هو أداة لإدارة التبعيات بايثون التي تساعد على تحسين الإنتاجية وسهولة الاستخدام. وهو بديل ل pip/poetry باستخدام أدوات الذكاء الاصطناعي how to use uv uv vs pip uv alternative to poetry uv install guide what is uv package manager uv setup for Python projects uvx migrate-to-uv tool uv sync command uv for AI agents uv包管理器 Python依赖管理 pip/poetry替代 项目依赖管理 开发效率优化 uv sync migrate-to-uv Python开发工具 依存性管理 Migrates metadata and lockfiles from poetry/pipenv/conda using uvx migrate-to-uv Supports project, script, and tool modes for flexible dependency management Utilizes the uv sync command for efficient project synchronization Converts lockfiles from poetry.lock, Pipfile, and environment.yml formats Provides a workflow for managing Python dependencies and projects Enables switching from existing package managers like pip and poetry uv is a package manager that prefers a workflow over pip/poetry for Python dependency and project management, utilizing tools like uvx migrate-to-uv.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('antoniocascais/claude-code-toolkit/c7', 'community', 'antoniocascais', 'claude-code-toolkit', 'antoniocascais/claude-code-toolkit', 'c7', 0, 0, 54, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:21.394Z', 'ad9992db459e0167d0e178dba459979e0acb058a2911b957575b737f8780b9a7', '{"id":"antoniocascais/claude-code-toolkit/c7","name":"c7","description":{"en":"The c7 skill is a fetch-only toolkit that provides documentation fetching capabilities for developers, allowing them to easily manage library documentation using the c7.sh script.","zh":"c7是AIエージェント文档抓取工具，支持缓存和强制刷新","ja":"c7はAIエージェントによるドキュメントフェッチツールで、キャッシュと強制リフレッシュをサポート","ko":"c7는 AI 에이전트 문서 가져오기 도구로서 캐시와 강제 새로고침을 지원","es":"c7 es una herramienta de recuperación de documentación que permite a los desarrolladores recuperar documentación de bibliotecas como NextJS con comandos de CLI personalizados","fr":"c7 est un outil de récupération de documentation qui permet aux développeurs de récupérer la documentation de bibliothèques comme NextJS avec des commandes CLI personnalisées","de":"c7 ist ein Dokumentenabruf-Tool, das es Entwicklern ermöglicht, Dokumentationen von Bibliotheken wie NextJS mit benutzerdefinierten CLI-Befehlen abzurufen","pt":"O c7 é uma ferramenta de fetch de documentação que permite aos desenvolvedores buscar e armazenar documentação de bibliotecas.","ru":"c7 - это ИИ Агент для FetchType документации, который позволяет разработчикам искать и хранить документацию библиотек.","ar":"c7 هو أداة استرجاع الوثائق التي تمكن المطورين من البحث وتخزين الوثائق للمكتبات."},"seo":{"title":{"en":"c7: Context7 Documentation Fetcher Setup Guide | AI Agent...","zh":"c7 Setup Guide: AIエージェント文档抓取工具","ja":"c7 Best Practices: AIエージェントによるドキュメントフェッチ","ko":"c7 Tutorial: AI 에이전트 문서 가져오기","es":"Guía de configuración de c7: Herramienta de recuperación ...","fr":"Guide de configuration de c7 : Outil de récupération de d...","de":"Einrichtungsleitfaden für c7: Dokumentenabruf-Tool","pt":"Guia de Configuração do c7 - Ferramenta de Fetch de Docum...","ru":"Настройка c7 - ИИ Агент для FetchType Документации","ar":"دليل إعداد c7 - أداة استرجاع الوثائق"},"description":{"en":"Unlock efficient documentation fetching with c7! Learn how to use the c7.sh script to fetch and manage library documentation, and discover its workflow capab...","zh":"了解c7 AIエージェント的功能和用法，包括文档抓取、缓存和强制刷新","ja":"c7 AIエージェントの使い方を学ぶ：ドキュメントのフェッチ、キャッシュ、強制リフレッシュ","ko":"c7 AI 에이전트의 기능과 사용 방법을 알아보세요: 문서 가져오기, 캐시, 강제 새로고침","es":"Aprende a utilizar c7 para recuperar documentación de bibliotecas como NextJS con comandos de CLI personalizados","fr":"Découvrez comment utiliser c7 pour récupérer la documentation de bibliothèques comme NextJS avec des commandes CLI personnalisées","de":"Erfahren Sie, wie Sie c7 verwenden können, um Dokumentationen von Bibliotheken wie NextJS mit benutzerdefinierten CLI-Befehlen abzurufen","pt":"Aprenda a configurar o c7, uma ferramenta de fetch de documentação para desenvolvedores, e melhore sua produtividade","ru":"Узнайте, как настроить c7, ИИ Агент для FetchType документации, и повысьте свою производительность","ar":"تعرف على كيفية إعداد c7، أداة استرجاع الوثائق للמطورين، وزيادة إنتاجيتك"},"definition":{"en":"c7 is a Context7 Documentation Fetcher, a fetch-only skill that provides a command-line interface for fetching and managing library documentation.","zh":"c7是AIエージェント的一种，用于抓取和管理文档","ja":"c7はAIエージェントの一種で、ドキュメントのフェッチと管理に使用","ko":"c7는 AI 에이전트의 일종으로 문서를 가져오고 관리하는 데 사용","es":"c7 es un agente de inteligencia artificial que recupera documentación de bibliotecas de software","fr":"c7 est un agent d''intelligence artificielle qui récupère la documentation de bibliothèques de logiciels","de":"c7 ist ein KI-Agent, der Dokumentationen von Softwarebibliotheken abruft","pt":"O c7 é uma ferramenta de linha de comando que executa comandos de fetch de documentação","ru":"c7 - это командная строка工具, который выполняет команды FetchType документации","ar":"c7 هو أداة سطر أوامر تقوم بتنفيذ أوامر استرجاع الوثائق"},"features":{"en":["Fetches documentation using the c7.sh script with library-name and query parameters","Lists cached documentation using the --list flag","Force re-fetches documentation using the --force flag, bypassing cache","Handles output with cached document paths and ages","Supports workflow automation using the scripts/c7.sh command"],"zh":["支持文档抓取","缓存功能","强制刷新","命令行接口（CLI）","支持多种库和查询","输出缓存路径和时间"],"ja":["ドキュメントのフェッチ","キャッシュ機能","強制リフレッシュ","コマンドラインインターフェース（CLI）","複数のライブラリとクエリをサポート","キャッシュパスと時間の出力"],"ko":["문서 가져오기","캐시 기능","강제 새로고침","명령줄 인터페이스（CLI）","여러 라이브러리와 쿼리 지원","캐시 경로와 시간 출력"],"es":["Recuperación de documentación de bibliotecas como NextJS","Uso de comandos de CLI personalizados","Opción de lista de documentos en caché","Opción de re recuperación forzada de documentos","Compatibilidad con bibliotecas de software populares"],"fr":["Récupération de la documentation de bibliothèques comme NextJS","Utilisation de commandes CLI personnalisées","Option de liste de documents en cache","Option de re-récupération forcée de documents","Compatibilité avec des bibliothèques de logiciels populaires"],"de":["Abruf von Dokumentationen von Bibliotheken wie NextJS","Verwendung von benutzerdefinierten CLI-Befehlen","Option zur Auflistung von Dokumenten im Cache","Option zur erzwungenen Neuerfassung von Dokumenten","Kompatibilität mit beliebten Softwarebibliotheken"],"pt":["Executa comandos de fetch de documentação com o script c7.sh","Permite buscar documentação de bibliotecas específicas","Armazena documentação em cache para acesso rápido","Fornece opção para forçar a re-fecth de documentação","Lista documentação em cache com a opção --list"],"ru":["Выполняет команды FetchType документации с помощью скрипта c7.sh","Позволяет искать документацию конкретных библиотек","Хранит документацию в кэше для быстрого доступа","Предоставляет возможность принудительно перерисовать документацию","Отображает документацию в кэше с помощью опции --list"],"ar":["تنفذ أوامر استرجاع الوثائق مع سكريبت c7.sh","تمكن من البحث عن وثائق المكتبات النوعية","تخزين الوثائق في ذاكرة التخزين المؤقت للوصول السريع","توفر خيار لإعادة استرجاع الوثائق","قائمة الوثائق في ذاكرة التخزين المؤقت مع خيار --list"]},"keywords":{"en":["how to use c7","c7 setup guide","c7 alternative","c7 vs documentation managers","c7 install","what is c7","c7 workflow automation","c7 documentation fetcher","c7.sh script usage"],"zh":["c7 AIエージェント","文档抓取工具","缓存","强制刷新","命令行接口","AI工具","开发者工具","文档管理"],"ja":["c7 AIエージェント","ドキュメントフェッチツール","キャッシュ","強制リフレッシュ","コマンドラインインターフェース","AIエージェント","開発者ツール","ドキュメント管理"],"ko":["c7 AI 에이전트","문서 가져오기 도구","캐시","강제 새로고침","명령줄 인터페이스","AI 에이전트","개발자 도구","문서 관리"],"es":["c7","agente de inteligencia artificial","herramienta de recuperación de documentación","NextJS","CLI","desarrollo de software","documentación de bibliotecas","herramientas de desarrollo"],"fr":["c7","agent d''intelligence artificielle","outil de récupération de documentation","NextJS","CLI","développement de logiciels","documentation de bibliothèques","outils de développement"],"de":["c7","KI-Agent","Dokumentenabruf-Tool","NextJS","CLI","Softwareentwicklung","Dokumentation von Bibliotheken","Entwicklungstools"],"pt":["c7","ferramenta de fetch de documentação","desenvolvimento de software","linha de comando","documentação de bibliotecas","cache de documentação","script c7.sh"],"ru":["c7","ИИ Агент","Ферумента для FetchType документации","Разработка программного обеспечения","Командная строка","Документация библиотек","Кэш документации","Скрипт c7.sh"],"ar":["c7","أداة استرجاع الوثائق","تطوير البرمجيات","سطر الأوامر","وثائق المكتبات","ذاكرة التخزين المؤقت للوثائق","سكريبت c7.sh","أدوات المطورين"]}},"owner":"antoniocascais","repo":"claude-code-toolkit","repoPath":"antoniocascais/claude-code-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"c7","description":"Fetches up-to-date library documentation from Context7 and saves to /tmp/context7/. Use when needing current API docs, code examples, library references, SDK documentation, or checking latest library versions. Triggers: context7, c7, library docs, fetch docs, current documentation, api reference.","bodyPreview":"# c7 - Context7 Documentation Fetcher\n\nFetch-only skill. Does NOT read docs into context.\n\n## Usage\n\n### Fetch documentation\n\n```bash\nscripts/c7.sh <library-name> \"<query>\"\n```\n\nExample:\n```bash\nscripts/c7.sh nextjs \"app router middleware\"\n```\n\n### List cached docs\n\n```bash\nscripts/c7.sh --list\n```\n\n### Force re-fetch (bypass cache)\n\n```bash\nscripts/c7.sh --force <library-name> \"<query>\"\n```\n\n## Workflow\n\n1. Run `scripts/c7.sh <library> \"<query>\"`\n2. Handle output:\n   - `CACHED: <path> (Xh old)`","body":"# c7 - Context7 Documentation Fetcher\n\nFetch-only skill. Does NOT read docs into context.\n\n## Usage\n\n### Fetch documentation\n\n```bash\nscripts/c7.sh <library-name> \"<query>\"\n```\n\nExample:\n```bash\nscripts/c7.sh nextjs \"app router middleware\"\n```\n\n### List cached docs\n\n```bash\nscripts/c7.sh --list\n```\n\n### Force re-fetch (bypass cache)\n\n```bash\nscripts/c7.sh --force <library-name> \"<query>\"\n```\n\n## Workflow\n\n1. Run `scripts/c7.sh <library> \"<query>\"`\n2. Handle output:\n   - `CACHED: <path> (Xh old)` → Use AskUserQuestion: \"Documentation for X is already cached (Y hours old). Use cached version or fetch fresh?\"\n     - If re-fetch → run with `--force`\n     - If use cached → inform user of location, done\n   - Success (path printed) → inform user: \"Documentation saved to <path>\"\n   - `NOT_FOUND:` → Use AskUserQuestion: \"Library not found in Context7. How should I proceed?\" with options like retry with different name, skip, etc.\n   - `RATE_LIMITED:` → inform user rate limit hit, stop\n   - `API_ERROR:` → inform user of error, stop\n\n3. Done. Do NOT read the file into context.\n\n## Exit Codes\n\n| Code | Output | Action |\n|------|--------|--------|\n| 0 | filepath | Success - report location |\n| 0 | CACHED: path | Ask user: use cache or re-fetch? |\n| 1 | NOT_FOUND: | Ask user for alternatives |\n| 2 | RATE_LIMITED: | Inform user, stop |\n| 3 | API_ERROR: | Inform user, stop |\n| 4 | FUZZY_MATCH: | Ask user: \"Context7 matched X instead of Y. Use this or try different name?\" |\n"},"lastSynced":"2026-03-08T02:00:21.394Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient library documentation management and retrieval capabilities.","zh":"适合需要高效的库文档管理和检索能力的开发人员代理。","ja":"開発者エージェントが効率的なライブラリドキュメントの管理と取得機能を必要とする場合に最適です。","ko":"개발자 에이전트가 효율적인 라이브러리 문서 관리 및 검색 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una gestión y recuperación eficientes de la documentación de bibliotecas.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une gestion et d''une récupération efficaces de la documentation de bibliothèques.","de":"Perfekt für Developer-Agents, die eine effiziente Bibliotheks-Dokumentationsverwaltung und -abrufmöglichkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de gerenciamento eficiente de documentação de biblioteca e capacidades de recuperação.","ru":"Идеально подходит для агентов-разработчиков, которым необходим эффективный менеджмент документации библиотек и возможностей поиска.","ar":"مثالي لعميل المطور الذي يحتاج إلى إدارة مستندات المكتبة وفعالية استرجاعها."},"recommendation":{"en":"Empowers agents to fetch and manage library documentation using the c7.sh script, providing easy access to documentation for various libraries and handling cache management through protocols like fetch-only and force re-fetch, supporting queries and library names.","zh":"赋予代理使用 c7.sh 脚本来获取和管理库文档的能力，提供对各种库文档的轻松访问，并通过诸如 fetch-only 和强制重新获取等协议来处理缓存管理，支持查询和库名称。","ja":"c7.sh スクリプトを使用してライブラリドキュメントを取得して管理するエージェントの能力を可能にし、さまざまなライブラリのドキュメントへのアクセスを容易にし、fetch-only や強制再取得などのプロトコルを介してキャッシュ管理を行い、クエリやライブラリ名をサポートします。","ko":"c7.sh 스크립트를 사용하여 라이브러리 문서를 가져오고 관리하는 에이전트의 능력을 가능하게 하며, 다양한 라이브러리의 문서에 쉽게 접근할 수 있고, fetch-only 또는 강제 다시 가져오기와 같은 프로토콜을 통해 캐시 관리를 처리하며, 쿼리 및 라이브러리 이름을 지원합니다.","es":"Habilita a los agentes a recuperar y gestionar la documentación de bibliotecas utilizando el script c7.sh, proporcionando un acceso fácil a la documentación para varias bibliotecas y gestionando la gestión de caché a través de protocolos como fetch-only y fuerza re-cargar, soportando consultas y nombres de bibliotecas.","fr":"Permet aux agents de récupérer et de gérer la documentation de bibliothèques en utilisant le script c7.sh, offrant un accès facile à la documentation pour diverses bibliothèques et gérant la gestion du cache via des protocoles tels que fetch-only et force re-charger, en prenant en charge les requêtes et les noms de bibliothèques.","de":"Ermöglicht es den Agenten, die Bibliotheks-Dokumentation mithilfe des Skripts c7.sh abzurufen und zu verwalten, indem es einen einfachen Zugriff auf die Dokumentation für verschiedene Bibliotheken bietet und die Cache-Verwaltung durch Protokolle wie fetch-only und erzwungenes Neuladen unterstützt, wobei Abfragen und Bibliotheksnamen unterstützt werden.","pt":"Habilita os agentes a buscar e gerenciar documentação de biblioteca usando o script c7.sh, fornecendo acesso fácil à documentação de várias bibliotecas e lidando com gerenciamento de cache por meio de protocolos como fetch-only e force re-fetch, suportando consultas e nomes de bibliotecas.","ru":"Наделяет агентов возможностью получать и управлять документацией библиотек с помощью скрипта c7.sh, обеспечивая легкий доступ к документации различных библиотек и обрабатывая управление кэшем посредством протоколов типа fetch-only и force re-fetch, поддерживая запросы и имена библиотек.","ar":"يمنح الوكلاء khảية البحث وإدارة مستندات المكتبة باستخدام سكريبت c7.sh، مما يوفر وصولاً سهلاً إلى مستندات المكتبات المختلفة ومعالجة إدارة الذاكرة المؤقتة من خلال بروتوكولات مثل fetch-only و force re-fetch، ودعم الاستفسارات وأسماء المكتبات."},"useCases":{"en":["Fetching documentation for specific libraries","Managing cached documentation for frequent queries","Force re-fetching documentation to bypass cache and ensure up-to-date information"],"zh":["获取特定库的文档","管理缓存文档以进行频繁的查询","强制重新获取文档以绕过缓存并确保最新信息"],"ja":["特定ライブラリのドキュメントを取得する","頻繁なクエリのためにキャッシュされたドキュメントを管理する","キャッシュをバイパスして最新情報を確保するためにドキュメントを強制的に再取得する"],"ko":["특정 라이브러리의 문서를 가져오는 것","빈번한 쿼리를 위해 캐시된 문서를 관리하는 것","캐시를 우회하여 최신 정보를 보장하기 위해 문서를 강제로 다시 가져오는 것"],"es":["Recuperar la documentación para bibliotecas específicas","Gestionar la documentación en caché para consultas frecuentes","Forzar la recarga de la documentación para omitir la caché y asegurar información actualizada"],"fr":["Récupérer la documentation pour des bibliothèques spécifiques","Gérer la documentation en cache pour des requêtes fréquentes","Forcer la re-chargement de la documentation pour contourner le cache et assurer des informations à jour"],"de":["Abrufen der Dokumentation für spezifische Bibliotheken","Verwalten der zwischengespeicherten Dokumentation für häufige Abfragen","Erzwingen des Neuladens der Dokumentation, um den Cache zu umgehen und aktuelle Informationen sicherzustellen"],"pt":["Buscar documentação para bibliotecas específicas","Gerenciar documentação em cache para consultas frequentes","Force re-fetching documentação para bypassar cache e garantir informações atualizadas"],"ru":["Получение документации для конкретных библиотек","Управление документацией в кэше для частых запросов","Принудительное получение документации для обхода кэша и обеспечения актуальной информации"],"ar":["استرجاع مستندات المكتبة المحددة","إدارة مستندات الذاكرة المؤقتة للاستفسارات المتكررة","إعادة استرجاع المستندات بالقوة لتجاوز الذاكرة المؤقتة وضمان الحصول على معلومات محدثة"]},"limitations":{"en":["Fetch-only capability, does not read docs into context","Requires script execution through bash","Cache management required for optimal performance"],"zh":["仅获取能力，不读取文档到上下文","需要通过 bash 执行脚本","需要缓存管理以实现最佳性能"],"ja":["fetch-only 機能であり、ドキュメントをコンテキストに読み込まない","スクリプトの実行には bash が必要","最適なパフォーマンスを実現するにはキャッシュ管理が必要"],"ko":["fetch-only 기능이며, 문서를 컨텍스트에 읽어들이지 않음","스크립트 실행에는 bash가 필요함","최적의 성능을 달성하기 위해 캐시 관리가 필요함"],"es":["Capacidad fetch-only, no lee los documentos en el contexto","Requiere la ejecución del script a través de bash","Se requiere gestión de caché para un rendimiento óptimo"],"fr":["Capacité fetch-only, ne lit pas les documents dans le contexte","Nécessite l''exécution du script via bash","Gestion du cache requise pour des performances optimales"],"de":["Fetch-only-Fähigkeit, liest keine Dokumente im Kontext","Benötigt die Ausführung des Skripts über bash","Cache-Verwaltung erforderlich für optimale Leistung"],"pt":["Capacidade fetch-only, não lê documentos no contexto","Requer execução de script por meio do bash","Gerenciamento de cache necessário para desempenho ótimo"],"ru":["Возможность fetch-only, не читает документы в контексте","Требует выполнения скрипта через bash","Управление кэшем необходимо для оптимальной производительности"],"ar":["القدرة على fetch-only، ولا تقرأ المستندات في السياق","تتطلب تنفيذ السكريبت من خلال bash","إدارة الذاكرة المؤقتة ضرورية لأداء مثالي"]},"version":4},"contentHash":"ad9992db459e0167d0e178dba459979e0acb058a2911b957575b737f8780b9a7","qualityScore":54}');
