INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('antoniocascais/claude-code-toolkit/c7', 'c7', 'antoniocascais', 'claude-code-toolkit', 'community', 'c7 antoniocascais claude-code-toolkit community The c7 skill is a fetch-only toolkit that provides documentation fetching capabilities for developers, allowing them to easily manage library documentation using the c7.sh script. c7是AIエージェント文档抓取工具，支持缓存和强制刷新 c7はAIエージェントによるドキュメントフェッチツールで、キャッシュと強制リフレッシュをサポート c7는 AI 에이전트 문서 가져오기 도구로서 캐시와 강제 새로고침을 지원 c7 es una herramienta de recuperación de documentación que permite a los desarrolladores recuperar documentación de bibliotecas como NextJS con comandos de CLI personalizados c7 est un outil de récupération de documentation qui permet aux développeurs de récupérer la documentation de bibliothèques comme NextJS avec des commandes CLI personnalisées c7 ist ein Dokumentenabruf-Tool, das es Entwicklern ermöglicht, Dokumentationen von Bibliotheken wie NextJS mit benutzerdefinierten CLI-Befehlen abzurufen O c7 é uma ferramenta de fetch de documentação que permite aos desenvolvedores buscar e armazenar documentação de bibliotecas. c7 - это ИИ Агент для FetchType документации, который позволяет разработчикам искать и хранить документацию библиотек. c7 هو أداة استرجاع الوثائق التي تمكن المطورين من البحث وتخزين الوثائق للمكتبات. how to use c7 c7 setup guide c7 alternative c7 vs documentation managers c7 install what is c7 c7 workflow automation c7 documentation fetcher c7.sh script usage c7 AIエージェント 文档抓取工具 缓存 强制刷新 命令行接口 AI工具 开发者工具 文档管理 Fetches documentation using the c7.sh script with library-name and query parameters Lists cached documentation using the --list flag Force re-fetches documentation using the --force flag, bypassing cache Handles output with cached document paths and ages Supports workflow automation using the scripts/c7.sh command c7 is a Context7 Documentation Fetcher, a fetch-only skill that provides a command-line interface for fetching and managing library documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('skillcreatorai/Ai-Agent-Skills/jira-issues', 'community', 'skillcreatorai', 'Ai-Agent-Skills', 'skillcreatorai/Ai-Agent-Skills', 'jira-issues', 0, 0, 54, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:33.515Z', '649a1012fe6ddb0e7e86e83e267dd23b27dad0ac22195311205d5d4e7b0632fc', '{"id":"skillcreatorai/Ai-Agent-Skills/jira-issues","name":"jira-issues","description":{"en":"The jira-issues skill enables developers to create and manage Jira issues using the Jira REST API or MCP. It benefits AI agent developers and Jira users.","zh":"使用 Jira REST API 或 MCP 创建和管理 Jira 问题","ja":"Jira REST API または MCP を使用して Jira の課題を创建および管理する","ko":"Jira REST API 또는 MCP를 사용하여 Jira 이슈를 생성하고 관리합니다","es":"Configura y gestiona problemas de Jira con la API de Jira o MCP. Utiliza npx @anthropic/create-mcp-server jira para una integración sin problemas.","fr":"Configurez et gérez les problèmes Jira avec l''API Jira ou MCP. Utilisez npx @anthropic/create-mcp-server jira pour une intégration sans problème.","de":"Konfigurieren und verwalten Sie Jira-Probleme mit der Jira-API oder MCP. Verwenden Sie npx @anthropic/create-mcp-server jira für eine reibungslose Integration.","pt":"O skill de jira-issues permite criar e gerenciar problemas do Jira usando o Jira REST API ou MCP. Configure facilmente com o servidor MCP do Jira ou variáveis de ambiente","ru":"Навык jira-issues позволяет создавать и управлять проблемами Jira с помощью Jira REST API или MCP. Настройте легко с сервером MCP Jira или переменными среды","ar":"يسمح لك مهارة jira-issues بإنشاء وإدارة قضايا جيرا باستخدام واجهة برمجة تطبيقات جيرا أو MCP. قم بتكوينها بسهولة مع خادم MCP من جيرا أو متغيرات البيئة"},"seo":{"title":{"en":"jira-issues: Jira REST API Integration Setup Guide | AI A...","zh":"Jira 问题管理集成指南","ja":"Jira Issue 管理のための AI エージェント設定ガイド","ko":"Jira 이슈 관리를 위한 AI 에이전트 설정 가이드","