INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skillcreatorai/Ai-Agent-Skills/jira-issues', 'jira-issues', 'skillcreatorai', 'Ai-Agent-Skills', 'community', 'jira-issues skillcreatorai Ai-Agent-Skills community The jira-issues skill enables developers to create and manage Jira issues using the Jira REST API or MCP. It benefits AI agent developers and Jira users. 使用 Jira REST API 或 MCP 创建和管理 Jira 问题 Jira REST API または MCP を使用して Jira の課題を创建および管理する Jira REST API 또는 MCP를 사용하여 Jira 이슈를 생성하고 관리합니다 Configura y gestiona problemas de Jira con la API de Jira o MCP. Utiliza npx @anthropic/create-mcp-server jira para una integración sin problemas. Configurez et gérez les problèmes Jira avec l''API Jira ou MCP. Utilisez npx @anthropic/create-mcp-server jira pour une intégration sans problème. Konfigurieren und verwalten Sie Jira-Probleme mit der Jira-API oder MCP. Verwenden Sie npx @anthropic/create-mcp-server jira für eine reibungslose Integration. O skill de jira-issues permite criar e gerenciar problemas do Jira usando o Jira REST API ou MCP. Configure facilmente com o servidor MCP do Jira ou variáveis de ambiente Навык jira-issues позволяет создавать и управлять проблемами Jira с помощью Jira REST API или MCP. Настройте легко с сервером MCP Jira или переменными среды يسمح لك مهارة jira-issues بإنشاء وإدارة قضايا جيرا باستخدام واجهة برمجة تطبيقات جيرا أو MCP. قم بتكوينها بسهولة مع خادم MCP من جيرا أو متغيرات البيئة jira-issues setup guide jira rest api integration jira mcp server install how to use jira-issues with ai agents jira-issues alternative jira-issues vs trello jira api token management jira issue management for ai agents npx @anthropic/create-mcp-server jira Jira 问题管理 Jira REST API MCP 环境变量设置 API 令牌获取 CLI 命令 Jira 问题创建 Jira 问题管理工具 AI 에이전트 Installs Jira MCP server using npx @anthropic/create-mcp-server jira command Sets environment variables for Jira REST API integration, including JIRA_BASE_URL, JIRA_EMAIL, and JIRA_API_TOKEN Supports direct API setup with API token management Utilizes bash commands for setup and configuration Integrates with Jira REST API for seamless issue management Manages Jira issues using MCP server for AI agents jira-issues is a skill that integrates Jira issue management with AI agents using the Jira REST API or MCP server.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aaronontheweb/dotnet-skills/serialization', 'community', 'Aaronontheweb', 'dotnet-skills', 'Aaronontheweb/dotnet-skills', 'serialization', 0, 0, 54, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:36.646Z', '0f1f254521079e26f086132d639c959b4ac7be6ad2ec8fe64be61724d9021779', '{"id":"Aaronontheweb/dotnet-skills/serialization","name":"serialization","description":{"en":"The serialization skill provides .NET developers with expertise in choosing serialization formats, migrating from Newtonsoft.Json to System.Text.Json, and optimizing performance. It benefits developers working on APIs, messaging, or persistence.","zh":"Serialization是.NET开发中的一个重要概念，涉及数据的序列化和反序列化，AIエージェント工具","ja":"シリアライゼーションは、.NET開発でデータを効率的に処理するための重要な概念です、AIエージェント","ko":"Serialization은 .NET 개발에서 데이터를 효율적으로 처리하는 데 중요한 개념입니다, AI 도구","es":"La serialización en .NET es crucial para el intercambio de datos. Aprende a implementarla de manera efectiva.","fr":"La sérialisation en .NET est essentielle pour l''échange de données. Découvrez comment l''implémenter de manière efficace.","de":"Die Serialisierung in .NET ist für den Datenaustausch entscheidend. Erfahren Sie, wie Sie sie effektiv implementieren.","pt":"Serialização é um processo fundamental para desenvolvedores .NET, permitindo a conversão de objetos em formatos que podem ser armazenados ou transmitidos.","ru":"Сериализация является фундаментальным процессом для разработчиков .NET, позволяющим преобразовывать объекты в форматы, которые могут быть хранены или переданы, ИИ Агенты.","ar":"التسلسل هو عملية أساسية للمطورين .NET، مما يسمح بالتحويل الكائنات إلى تنسيقات يمكن تخزينها أو نقلها، أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"Serialization: Setup Guide for .NET Developers | AI Agent...","zh":"Serialization_SETUP GUIDE: .NET开发者最佳实践","ja":"シリアライゼーション_BEST PRACTICES: .NET開発者向け","ko":"Serialization_가이드: .NET 개발자를 위한 최적화 방법","es":"Guía de configuración de serialización para .NET Developers","fr":"Meilleures pratiques de sérialisation pour les développeu...","de":"Leitfaden für die Serialisierung in .NET: Optimierung und...","pt":"Guia de Configuração de Serialização para Desenvolvedores...","ru":"Руководство по настройке сериализации для разработчиков ....","ar":"دليل إعداد التسلسل لل開発 .NET، أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to optimize serialization in .NET with expert guidance on choosing formats, migrating from Newtonsoft.Json, and implementing AOT-compatible solu...","zh":"了解Serialization在.NET中的应用，包括API、消息传递和持久性，AIエージェント工具","ja":"シリアライゼーションを使用して.NETアプリケーションのパフォーマンスを最適化する方法を学ぶ、AIエージェント","ko":"Serialization을 사용하여 .NET 애플리케이션의 성능을 최적화하는 방법을 알아보세요, AI 도구","es":"Descubre cómo implementar la serialización en .NET de manera efectiva, incluyendo consejos para optimizar el rendimiento y elegir el formato adecuado","fr":"Découvrez les meilleures pratiques pour la sérialisation en .NET, y compris l''optimisation des performances et le choix du format approprié","de":"Erfahren Sie, wie Sie die Serialisierung in .NET effektiv implementieren, einschließlich Tipps zur Leistungsoptimierung und zur Auswahl des richtigen Formats","pt":"Aprenda a escolher o formato de serialização correto para APIs, mensagens ou persistência, migre do Newtonsoft.Json para System.Text.Json e otimize o desempe...","ru":"Узнайте, как выбрать правильный формат сериализации для API, сообщений или хранения, перенести с Newtonsoft.Json на System.Text.Json и оптимизировать произво...","ar":"تعلم كيفية اختيار تنسيق التسلسل الصحيح للواجهات البرمجية، الرسائل أو التخزين، وحول من Newtonsoft.Json إلى System.Text.Json واضبط أداء التسلسل، أدوات الذكاء ا..."},"definition":{"en":"Serialization is the process of converting data into a format that can be stored or transmitted, with schema-based and reflection-based approaches available, such as Protobuf and MessagePack.","zh":"Serialization是指将数据转换为可存储或传输的格式的过程","ja":"シリアライゼーションは、データをストレージまたは転送可能な形式に変換するプロセスです","ko":"Serialization은 데이터를 저장 또는 전송 가능한 형식으로 변환하는 프로세스입니다","es":"La serialización es el proceso de convertir datos en un formato que puede ser almacenado o transmitido","fr":"La sérialisation est le processus de conversion de données en un format qui peut être stocké ou transmis","de":"Die Serialisierung ist der Prozess der Umwandlung von Daten in ein Format, das gespeichert oder übertragen werden kann","pt":"Serialização é o processo de converter objetos em formatos que podem ser armazenados ou transmitidos.","ru":"Сериализация - это процесс преобразования объектов в форматы, которые могут быть хранены или переданы.","ar":"التسلسل هو عملية تحويل الكائنات إلى تنسيقات يمكن تخزينها أو نقلها."},"features":{"en":["Choosing a serialization format for APIs, messaging, or persistence","Migrating from Newtonsoft.Json to System.Text.Json","Implementing AOT-compatible serialization","Designing wire formats for distributed systems","Optimizing serialization performance"],"zh":["支持Schema-Based和Reflection-Based序列化","可用于API、消息传递和持久性","支持Protobuf、MessagePack等序列化格式","可用于实现AOT兼容的序列化","可用于优化序列化性能"],"ja":["Schema-BasedとReflection-Basedのシリアライゼーションをサポート","API、メッセージング、永続性に使用可能","Protobuf、MessagePackなどのシリアライゼーション形式をサポート","AOT互換のシリアライゼーションを実装可能","シリアライゼーション性能を最適化可能"],"ko":["Schema-Based와 Reflection-Based serialization을 지원","API, 메시징, 영속성에 사용 가능","Protobuf, MessagePack 등의 serialization 형식을 지원","AOT 호환 serialization을 구현 가능","Serialization 성능을 최적화 가능"],"es":["Compatibilidad con System.Text.Json y Newtonsoft.Json","Implementación de serialización AOT (Ahead-Of-Time)","Diseño de formatos de cable para sistemas distribuidos","Optimización del rendimiento de serialización","Soporte para Protobuf y MessagePack"],"fr":["Compatibilité avec System.Text.Json et Newtonsoft.Json","Implémentation de la sérialisation AOT (Ahead-Of-Time)","Conception de formats de fil pour les systèmes distribués","Optimisation des performances de sérialisation","Prise en charge de Protobuf et MessagePack"],"de":["Kompatibilität mit System.Text.Json und Newtonsoft.Json","Implementierung der Serialisierung AOT (Ahead-Of-Time)","Entwurf von Drahtformaten für verteilte Systeme","Leistungsoptimierung der Serialisierung","Unterstützung für Protobuf und MessagePack"],"pt":["Escolha do formato de serialização correto para APIs, mensagens ou persistência","Migração do Newtonsoft.Json para System.Text.Json","Implementação de serialização compatível com AOT","Desenvolvimento de formatos de fio para sistemas distribuídos","Otimização do desempenho da serialização"],"ru":["Выбор правильного формата сериализации для API, сообщений или хранения","Перенос с Newtonsoft.Json на System.Text.Json","Реализация сериализации, совместимой с AOT","Разработка форматов передачи для распределенных систем","Оптимизация производительности сериализации"],"ar":["اختيار تنسيق التسلسل الصحيح للواجهات البرمجية، الرسائل أو التخزين","تحويل من Newtonsoft.Json إلى System.Text.Json","تنفيذ التسلسل المتوافق مع AOT","تصميم تنسيقات الكابل للنظم الموزعة","تحسين أداء التسلسل"]},"keywords":{"en":["how to use serialization in .NET","what is serialization format","serialization vs Newtonsoft.Json","serialization setup guide for .NET","System.Text.Json serialization example","optimizing serialization performance in .NET"],"zh":["Serialization",".NET开发","AIエージェント工具","Schema-Based序列化","Reflection-Based序列化","Protobuf","MessagePack","AOT兼容","序列化性能优化"],"ja":["シリアライゼーション",".NET開発","AIエージェント","Schema-Basedシリアライゼーション","Reflection-Basedシリアライゼーション","Protobuf","MessagePack","AOT互換","シリアライゼーション性能最適化"],"ko":["Serialization",".NET 개발","AI 도구","Schema-Based serialization","Reflection-Based serialization","Protobuf","MessagePack","AOT 호환","Serialization 성능 최적화"],"es":["serialización en .NET","System.Text.Json","Newtonsoft.Json","serialización AOT","formatos de cable","optimización de rendimiento","Protobuf","MessagePack","desarrollo de aplicaciones .NET","herramientas de desarrollo .NET"],"fr":["sérialisation en .NET","System.Text.Json","Newtonsoft.Json","sérialisation AOT","formats de fil","optimisation des performances","Protobuf","MessagePack","développement d''applications .NET","outils de développement .NET"],"de":["Serialisierung in .NET","System.Text.Json","Newtonsoft.Json","Serialisierung AOT","Drahtformate","Leistungsoptimierung","Protobuf","MessagePack",".NET-Anwendungsentwicklung",".NET-Entwicklungstools","Künstliche Intelligenz Tools"],"pt":["serialização .NET","System.Text.Json","Newtonsoft.Json","AOT","desenvolvimento de sistemas distribuídos","otimização de desempenho","formatos de serialização","APIs","mensagens","persistência"],"ru":["сериализация .NET","System.Text.Json","Newtonsoft.Json","AOT","разработка распределенных систем","оптимизация производительности","форматы сериализации","API","сообщения","хранение","ИИ Агенты"],"ar":["التسلسل .NET","System.Text.Json","Newtonsoft.Json","AOT","تطوير النظم الموزعة","تحسين الأداء","تنسيقات التسلسل","الواجهات البرمجية","الرسائل","التخزين","أدوات الذكاء الاصطناعي"]}},"owner":"Aaronontheweb","repo":"dotnet-skills","repoPath":"Aaronontheweb/dotnet-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"serialization","description":"Choose the right serialization format for .NET applications. Prefer schema-based formats (Protobuf, MessagePack) over reflection-based (Newtonsoft.Json). Use System.Text.Json with AOT source generators for JSON scenarios.","bodyPreview":"# Serialization in .NET\n\n## When to Use This Skill\n\nUse this skill when:\n- Choosing a serialization format for APIs, messaging, or persistence\n- Migrating from Newtonsoft.Json to System.Text.Json\n- Implementing AOT-compatible serialization\n- Designing wire formats for distributed systems\n- Optimizing serialization performance\n\n---\n\n## Schema-Based vs Reflection-Based\n\n| Aspect | Schema-Based | Reflection-Based |\n|--------|--------------|------------------|\n| **Examples** | Protobuf, MessagePack,","body":"# Serialization in .NET\n\n## When to Use This Skill\n\nUse this skill when:\n- Choosing a serialization format for APIs, messaging, or persistence\n- Migrating from Newtonsoft.Json to System.Text.Json\n- Implementing AOT-compatible serialization\n- Designing wire formats for distributed systems\n- Optimizing serialization performance\n\n---\n\n## Schema-Based vs Reflection-Based\n\n| Aspect | Schema-Based | Reflection-Based |\n|--------|--------------|------------------|\n| **Examples** | Protobuf, MessagePack, System.Text.Json (source gen) | Newtonsoft.Json, BinaryFormatter |\n| **Type info in payload** | No (external schema) | Yes (type names embedded) |\n| **Versioning** | Explicit field numbers/names | Implicit (type structure) |\n| **Performance** | Fast (no reflection) | Slower (runtime reflection) |\n| **AOT compatible** | Yes | No |\n| **Wire compatibility** | Excellent | Poor |\n\n**Recommendation**: Use schema-based serialization for anything that crosses process boundaries.\n\n---\n\n## Format Recommendations\n\n| Use Case | Recommended Format | Why |\n|----------|-------------------|-----|\n| **REST APIs** | System.Text.Json (source gen) | Standard, AOT-compatible |\n| **gRPC** | Protocol Buffers | Native format, excellent versioning |\n| **Actor messaging** | MessagePack or Protobuf | Compact, fast, version-safe |\n| **Event sourcing** | Protobuf or MessagePack | Must handle old events forever |\n| **Caching** | MessagePack | Compact, fast |\n| **Configuration** | JSON (System.Text.Json) | Human-readable |\n| **Logging** | JSON (System.Text.Json) | Structured, parseable |\n\n### Formats to Avoid\n\n| Format | Problem |\n|--------|---------|\n| **BinaryFormatter** | Security vulnerabilities, deprecated, never use |\n| **Newtonsoft.Json default** | Type names in payload break on rename |\n| **DataContractSerializer** | Complex, poor versioning |\n| **XML** | Verbose, slow, complex |\n\n---\n\n## System.Text.Json with Source Generators\n\nFor JSON serialization, use System.Text.Json with source generators for AOT compatibility and performance.\n\n### Setup\n\n```csharp\n// Define a JsonSerializerContext with all your types\n[JsonSerializable(typeof(Order))]\n[JsonSerializable(typeof(OrderItem))]\n[JsonSerializable(typeof(Customer))]\n[JsonSerializable(typeof(List<Order>))]\n[JsonSourceGenerationOptions(\n    PropertyNamingPolicy = JsonKnownNamingPolicy.CamelCase,\n    DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull)]\npublic partial class AppJsonContext : JsonSerializerContext { }\n```\n\n### Usage\n\n```csharp\n// Serialize with context\nvar json = JsonSerializer.Serialize(order, AppJsonContext.Default.Order);\n\n// Deserialize with context\nvar order = JsonSerializer.Deserialize(json, AppJsonContext.Default.Order);\n\n// Configure in ASP.NET Core\nbuilder.Services.ConfigureHttpJsonOptions(options =>\n{\n    options.SerializerOptions.TypeInfoResolverChain.Insert(0, AppJsonContext.Default);\n});\n```\n\n### Benefits\n\n- **No reflection at runtime** - All type info generated at compile time\n- **AOT compatible** - Works with Native AOT publishing\n- **Faster** - No runtime type analysis\n- **Trim-safe** - Linker knows exactly what''s needed\n\n---\n\n## Protocol Buffers (Protobuf)\n\nBest for: Actor systems, gRPC, event sourcing, any long-lived wire format.\n\n### Setup\n\n```bash\ndotnet add package Google.Protobuf\ndotnet add package Grpc.Tools\n```\n\n### Define Schema\n\n```protobuf\n// orders.proto\nsyntax = \"proto3\";\n\nmessage Order {\n    string id = 1;\n    string customer_id = 2;\n    repeated OrderItem items = 3;\n    int64 created_at_ticks = 4;\n\n    // Adding new fields is always safe\n    string notes = 5;  // Added in v2 - old readers ignore it\n}\n\nmessage OrderItem {\n    string product_id = 1;\n    int32 quantity = 2;\n    int64 price_cents = 3;\n}\n```\n\n### Versioning Rules\n\n```protobuf\n// SAFE: Add new fields with new numbers\nmessage Order {\n    string id = 1;\n    string customer_id = 2;\n    string shipping_address = 5;  // NEW - safe\n}\n\n// SAFE: Remove fields (old readers ignore unknown, new readers use default)\n// Just stop using the field, keep the number reserved\nmessage Order {\n    string id = 1;\n    // customer_id removed, but field 2 is reserved\n    reserved 2;\n}\n\n// UNSAFE: Change field types\nmessage Order {\n    int32 id = 1;  // Was: string - BREAKS!\n}\n\n// UNSAFE: Reuse field numbers\nmessage Order {\n    reserved 2;\n    string new_field = 2;  // Reusing 2 - BREAKS!\n}\n```\n\n---\n\n## MessagePack\n\nBest for: High-performance scenarios, compact payloads, actor messaging.\n\n### Setup\n\n```bash\ndotnet add package MessagePack\ndotnet add package MessagePack.Annotations\n```\n\n### Usage with Contracts\n\n```csharp\n[MessagePackObject]\npublic sealed class Order\n{\n    [Key(0)]\n    public required string Id { get; init; }\n\n    [Key(1)]\n    public required string CustomerId { get; init; }\n\n    [Key(2)]\n    public required IReadOnlyList<OrderItem> Items { get; init; }\n\n    [Key(3)]\n    public required DateTimeOffset CreatedAt { get; init; }\n\n    // New field - old readers skip unknown keys\n    [Key(4)]\n    public string? Notes { get; init; }\n}\n\n// Serialize\nvar bytes = MessagePackSerializer.Serialize(order);\n\n// Deserialize\nvar order = MessagePackSerializer.Deserialize<Order>(bytes);\n```\n\n### AOT-Compatible Setup\n\n```csharp\n// Use source generator for AOT\n[MessagePackObject]\npublic partial class Order { }  // partial enables source gen\n\n// Configure resolver\nvar options = MessagePackSerializerOptions.Standard\n    .WithResolver(CompositeResolver.Create(\n        GeneratedResolver.Instance,  // Generated\n        StandardResolver.Instance));\n```\n\n---\n\n## Migrating from Newtonsoft.Json\n\n### Common Issues\n\n| Newtonsoft | System.Text.Json | Fix |\n|------------|------------------|-----|\n| `$type` in JSON | Not supported by default | Use discriminators or custom converters |\n| `JsonProperty` | `JsonPropertyName` | Different attribute |\n| `DefaultValueHandling` | `DefaultIgnoreCondition` | Different API |\n| `NullValueHandling` | `DefaultIgnoreCondition` | Different API |\n| Private setters | Requires `[JsonInclude]` | Explicit opt-in |\n| Polymorphism | `[JsonDerivedType]` (.NET 7+) | Explicit discriminators |\n\n### Migration Pattern\n\n```csharp\n// Newtonsoft (reflection-based)\npublic class Order\n{\n    [JsonProperty(\"order_id\")]\n    public string Id { get; set; }\n\n    [JsonProperty(NullValueHandling = NullValueHandling.Ignore)]\n    public string? Notes { get; set; }\n}\n\n// System.Text.Json (source-gen compatible)\npublic sealed record Order(\n    [property: JsonPropertyName(\"order_id\")]\n    string Id,\n\n    string? Notes  // Null handling via JsonSerializerOptions\n);\n\n[JsonSerializable(typeof(Order))]\n[JsonSourceGenerationOptions(\n    PropertyNamingPolicy = JsonKnownNamingPolicy.SnakeCaseLower,\n    DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull)]\npublic partial class OrderJsonContext : JsonSerializerContext { }\n```\n\n### Polymorphism with Discriminators\n\n```csharp\n// .NET 7+ polymorphism\n[JsonDerivedType(typeof(CreditCardPayment), \"credit_card\")]\n[JsonDerivedType(typeof(BankTransferPayment), \"bank_transfer\")]\npublic abstract record Payment(decimal Amount);\n\npublic sealed record CreditCardPayment(decimal Amount, string Last4) : Payment(Amount);\npublic sealed record BankTransferPayment(decimal Amount, string AccountNumber) : Payment(Amount);\n\n// Serializes as:\n// { \"$type\": \"credit_card\", \"amount\": 100, \"last4\": \"1234\" }\n```\n\n---\n\n## Wire Compatibility Patterns\n\n### Tolerant Reader\n\nOld code must safely ignore unknown fields:\n\n```csharp\n// Protobuf/MessagePack: Automatic - unknown fields skipped\n// System.Text.Json: Configure to allow\nvar options = new JsonSerializerOptions\n{\n    UnmappedMemberHandling = JsonUnmappedMemberHandling.Skip\n};\n```\n\n### Introduce Read Before Write\n\nDeploy deserializers before serializers for new formats:\n\n```csharp\n// Phase 1: Add deserializer (deployed everywhere)\npublic Order Deserialize(byte[] data, string manifest) => manifest switch\n{\n    \"Order.V1\" => DeserializeV1(data),\n    \"Order.V2\" => DeserializeV2(data),  // NEW - can read V2\n    _ => throw new NotSupportedException()\n};\n\n// Phase 2: Enable serializer (next release, after V1 deployed everywhere)\npublic (byte[] data, string manifest) Serialize(Order order) =>\n    _useV2Format\n        ? (SerializeV2(order), \"Order.V2\")\n        : (SerializeV1(order), \"Order.V1\");\n```\n\n### Never Embed Type Names\n\n```csharp\n// BAD: Type name in payload - renaming class breaks wire format\n{\n    \"$type\": \"MyApp.Order, MyApp.Core\",\n    \"id\": \"123\"\n}\n\n// GOOD: Explicit discriminator - refactoring safe\n{\n    \"type\": \"order\",\n    \"id\": \"123\"\n}\n```\n\n---\n\n## Performance Comparison\n\nApproximate throughput (higher is better):\n\n| Format | Serialize | Deserialize | Size |\n|--------|-----------|-------------|------|\n| MessagePack | ★★★★★ | ★★★★★ | ★★★★★ |\n| Protobuf | ★★★★★ | ★★★★★ | ★★★★★ |\n| System.Text.Json (source gen) | ★★★★☆ | ★★★★☆ | ★★★☆☆ |\n| System.Text.Json (reflection) | ★★★☆☆ | ★★★☆☆ | ★★★☆☆ |\n| Newtonsoft.Json | ★★☆☆☆ | ★★☆☆☆ | ★★★☆☆ |\n\nFor hot paths, prefer MessagePack or Protobuf.\n\n---\n\n## Akka.NET Serialization\n\nFor Akka.NET actor systems, use schema-based serialization:\n\n```hocon\nakka {\n  actor {\n    serializers {\n      messagepack = \"Akka.Serialization.MessagePackSerializer, Akka.Serialization.MessagePack\"\n    }\n    serialization-bindings {\n      \"MyApp.Messages.IMessage, MyApp\" = messagepack\n    }\n  }\n}\n```\n\nSee [Akka.NET Serialization Docs](https://getakka.net/articles/networking/serialization.html).\n\n---\n\n## Best Practices\n\n### DO\n\n```csharp\n// Use source generators for System.Text.Json\n[JsonSerializable(typeof(Order))]\npublic partial class AppJsonContext : JsonSerializerContext { }\n\n// Use explicit field numbers/keys\n[MessagePackObject]\npublic class Order\n{\n    [Key(0)] public string Id { get; init; }\n}\n\n// Use records for immutable message types\npublic sealed record OrderCreated(OrderId Id, CustomerId CustomerId);\n```\n\n### DON''T\n\n```csharp\n// Don''t use BinaryFormatter (ever)\nvar formatter = new BinaryFormatter();  // Security risk!\n\n// Don''t embed type names in wire format\nsettings.TypeNameHandling = TypeNameHandling.All;  // Breaks on rename!\n\n// Don''t use reflection serialization for hot paths\nJsonConvert.SerializeObject(order);  // Slow, not AOT-compatible\n```\n\n---\n\n## Resources\n\n- **System.Text.Json Source Generation**: https://learn.microsoft.com/en-us/dotnet/standard/serialization/system-text-json/source-generation\n- **Protocol Buffers**: https://protobuf.dev/\n- **MessagePack-CSharp**: https://github.com/MessagePack-CSharp/MessagePack-CSharp\n- **Akka.NET Serialization**: https://getakka.net/articles/networking/serialization.html\n- **Wire Compatibility**: https://getakka.net/community/contributing/wire-compatibility.html\n"},"lastSynced":"2026-03-08T02:00:36.646Z","agentAnalysis":{"suitability":{"en":"Perfect for .NET Agents needing efficient data serialization and migration capabilities.","zh":"非常适合需要高效数据序列化和迁移能力的 .NET Agent。","ja":".NET Agent に高效なデータシリアル化と移行機能が必要な場合に最適です。","ko":".NET 에이전트가 효율적인 데이터 직렬화 및 마이그레이션 기능을 필요로 하는 경우에 완벽합니다.","es":"Perfecto para agentes .NET que necesitan capacidades de serialización de datos eficientes y de migración.","fr":"Parfait pour les agents .NET nécessitant des capacités de sérialisation de données efficaces et de migration.","de":"Perfekt für .NET-Agents, die effiziente Daten-Serialisierungs- und Migrationsfunktionen benötigen.","pt":"Perfeito para agentes .NET que necessitam de capacidades de serialização de dados eficientes e de migração.","ru":"Идеально подходит для агентов .NET, требующих эффективных возможностей сериализации данных и миграции.","ar":"مثالي لعمليات .NET التي تحتاج إلى قدرات تسلسلة بيانات وكفاءة هجرة."},"recommendation":{"en":"Empowers agents to optimize performance by choosing the right serialization formats, such as System.Text.Json, and migrating from Newtonsoft.Json, while also implementing AOT-compatible serialization and designing wire formats for distributed systems using Protobuf and MessagePack.","zh":"赋予代理优化性能的能力，通过选择合适的序列化格式（如 System.Text.Json），从 Newtonsoft.Json 迁移，同时实施 AOT 兼容的序列化，并使用 Protobuf 和 MessagePack 为分布式系统设计线协议。","ja":"エージェントに、適切なシリアル化形式（たとえば System.Text.Json）を選択してパフォーマンスを最適化し、Newtonsoft.Json から移行し、AOT 互換シリアル化を実装し、Protobuf および MessagePack を使用して分散システムのワイヤーフォーマットを設計する能力を付与します。","ko":"에이전트가 성능을 최적화 할 수 있는 능력을 부여함으로써, 적절한 직렬화 형식 (예 : System.Text.Json)을 선택하고 Newtonsoft.Json에서 마이그레이션 하며 AOT 호환 직렬화를 구현하고 Protobuf 및 MessagePack를 사용하여 분산 시스템을 위한 와이어 형식을 설계한다.","es":"Habilita a los agentes a optimizar el rendimiento al elegir los formatos de serialización adecuados, como System.Text.Json, y migrar de Newtonsoft.Json, además de implementar una serialización compatible con AOT y diseñar formatos de cable para sistemas distribuidos utilizando Protobuf y MessagePack.","fr":"Permet aux agents d''optimiser les performances en choisissant les formats de sérialisation appropriés, tels que System.Text.Json, et en migrant de Newtonsoft.Json, tout en implementant une sérialisation compatible AOT et en concevant des formats de fil pour les systèmes distribués à l''aide de Protobuf et MessagePack.","de":"Ermöglicht es den Agents, die Leistung zu optimieren, indem sie die richtigen Serialisierungsformate wie System.Text.Json wählen und von Newtonsoft.Json migrieren, während sie auch eine AOT-kompatible Serialisierung implementieren und Drahtformate für verteilte Systeme mit Protobuf und MessagePack entwerfen.","pt":"Habilita os agentes a otimizar o desempenho, escolhendo os formatos de serialização certos, como System.Text.Json, e migrando de Newtonsoft.Json, além de implementar serialização compatível com AOT e projetar formatos de fio para sistemas distribuídos usando Protobuf e MessagePack.","ru":"Позволяет агентам оптимизировать производительность, выбирая правильные форматы сериализации, такие как System.Text.Json, и мигрируя из Newtonsoft.Json, а также реализуя сериализацию, совместимую с AOT, и проектируя форматы проводки для распределенных систем с использованием Protobuf и MessagePack.","ar":"تمكين الوكيل من تحسين الأداء عن طريق اختيار صيغ التسلسلة الصحيحة مثل System.Text.Json والهجرة من Newtonsoft.Json، بالإضافة إلى تنفيذ تسلسلة متوافقة مع AOT وتصميم صيغ سلكية لأنظمة موزعة باستخدام Protobuf وMessagePack."},"useCases":{"en":["Migrating APIs from Newtonsoft.Json to System.Text.Json","Optimizing serialization performance for distributed systems","Implementing schema-based serialization with Protobuf","Designing efficient wire formats for messaging"],"zh":["从 Newtonsoft.Json 迁移到 System.Text.Json 的 API","优化分布式系统的序列化性能","使用 Protobuf 实现基于模式的序列化","为消息传递设计高效的线协议"],"ja":["Newtonsoft.Json から System.Text.Json への API の移行","分散システムのシリアル化パフォーマンスの最適化","Protobuf を使用したスキーマベースのシリアル化の実装","メッセージングのための効率的なワイヤーフォーマットの設計"],"ko":["Newtonsoft.Json에서 System.Text.Json으로의 API 마이그레이션","분산 시스템을 위한 직렬화 성능 최적화","Protobuf를 사용한 스키마 기반 직렬화 구현","메시징을 위한 효율적인 와이어 형식 설계"],"es":["Migrar APIs de Newtonsoft.Json a System.Text.Json","Optimizar el rendimiento de serialización para sistemas distribuidos","Implementar una serialización basada en esquemas con Protobuf","Diseñar formatos de cable eficientes para mensajería"],"fr":["Migrer des API de Newtonsoft.Json à System.Text.Json","Optimiser les performances de sérialisation pour les systèmes distribués","Mettre en œuvre une sérialisation basée sur des schémas avec Protobuf","Concevoir des formats de fil efficaces pour la messagerie"],"de":["APIs von Newtonsoft.Json auf System.Text.Json migrieren","Serialisierungsleistung für verteilte Systeme optimieren","Eine schemabasierte Serialisierung mit Protobuf implementieren","Effiziente Drahtformate für Messaging entwerfen"],"pt":["Migrar APIs de Newtonsoft.Json para System.Text.Json","Otimizar o desempenho da serialização para sistemas distribuídos","Implementar serialização baseada em esquema com Protobuf","Projetar formatos de fio eficientes para mensagens"],"ru":["Мигрировать API из Newtonsoft.Json в System.Text.Json","Оптимизировать производительность сериализации для распределенных систем","Реализовать сериализацию на основе схемы с Protobuf","Проектировать эффективные форматы проводки для обмена сообщениями"],"ar":["هجرة واجهات برمجة التطبيقات من Newtonsoft.Json إلى System.Text.Json","تحسين أداء التسلسلة لأنظمة موزعة","تنفيذ تسلسلة قائمة على مخطط مع Protobuf","تصميم صيغ سلكية فعالة للرسائل"]},"limitations":{"en":["Requires .NET environment","Limited to serialization formats compatible with .NET"],"zh":[".NET 环境が必要","仅限于与 .NET 兼容的序列化格式"],"ja":[".NET 環境が必要",".NET と互換性のあるシリアル化形式のみ"],"ko":[".NET 환경이 필요",".NET과 호환되는 직렬화 형식만"],"es":["Requiere un entorno .NET","Limitado a formatos de serialización compatibles con .NET"],"fr":["Nécessite un environnement .NET","Limité aux formats de sérialisation compatibles avec .NET"],"de":["Benötigt eine .NET-Umgebung","Begrenzt auf mit .NET kompatible Serialisierungsformate"],"pt":["Requer ambiente .NET","Limitado a formatos de serialização compatíveis com .NET"],"ru":["Требуется среда .NET","Ограничен форматами сериализации, совместимыми с .NET"],"ar":["يتطلب بيئة .NET","محدود بالصيغ المتوافقة مع .NET لتسلسلة البيانات"]},"version":4},"contentHash":"0f1f254521079e26f086132d639c959b4ac7be6ad2ec8fe64be61724d9021779","qualityScore":54}');
