INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aaronontheweb/dotnet-skills/serialization', 'serialization', 'Aaronontheweb', 'dotnet-skills', 'community', 'serialization Aaronontheweb dotnet-skills community The serialization skill provides .NET developers with expertise in choosing serialization formats, migrating from Newtonsoft.Json to System.Text.Json, and optimizing performance. It benefits developers working on APIs, messaging, or persistence. Serialization是.NET开发中的一个重要概念，涉及数据的序列化和反序列化，AIエージェント工具 シリアライゼーションは、.NET開発でデータを効率的に処理するための重要な概念です、AIエージェント Serialization은 .NET 개발에서 데이터를 효율적으로 처리하는 데 중요한 개념입니다, AI 도구 La serialización en .NET es crucial para el intercambio de datos. Aprende a implementarla de manera efectiva. La sérialisation en .NET est essentielle pour l''échange de données. Découvrez comment l''implémenter de manière efficace. Die Serialisierung in .NET ist für den Datenaustausch entscheidend. Erfahren Sie, wie Sie sie effektiv implementieren. Serialização é um processo fundamental para desenvolvedores .NET, permitindo a conversão de objetos em formatos que podem ser armazenados ou transmitidos. Сериализация является фундаментальным процессом для разработчиков .NET, позволяющим преобразовывать объекты в форматы, которые могут быть хранены или переданы, ИИ Агенты. التسلسل هو عملية أساسية للمطورين .NET، مما يسمح بالتحويل الكائنات إلى تنسيقات يمكن تخزينها أو نقلها، أدوات الذكاء الاصطناعي. how to use serialization in .NET what is serialization format serialization vs Newtonsoft.Json serialization setup guide for .NET System.Text.Json serialization example optimizing serialization performance in .NET Serialization .NET开发 AIエージェント工具 Schema-Based序列化 Reflection-Based序列化 Protobuf MessagePack AOT兼容 序列化性能优化 Choosing a serialization format for APIs, messaging, or persistence Migrating from Newtonsoft.Json to System.Text.Json Implementing AOT-compatible serialization Designing wire formats for distributed systems Optimizing serialization performance Serialization is the process of converting data into a format that can be stored or transmitted, with schema-based and reflection-based approaches available, such as Protobuf and MessagePack.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('onmax/nuxt-skills/motion', 'community', 'onmax', 'nuxt-skills', 'onmax/nuxt-skills', 'motion', 0, 0, 54, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.488Z', 'f0e7a7749a2eed534f115c551b6ff27c17c9f38c25689302b7032fe583e41a60', '{"id":"onmax/nuxt-skills/motion","name":"motion","description":{"en":"Motion is a Vue, Nuxt, and NuxtHub skill for AI coding assistants, providing hardware-accelerated animations with minimal bundle size. It benefits developers working with Vue 3 and Nuxt.","zh":"Motion是Vue和Nuxt的动画库，提供生产就绪的硬件加速动画","ja":"MotionはVueとNuxtのアニメーションライブラリで、制作就緒のハードウェアアクセラレーションアニメーションを提供します","ko":"Motion은 Vue와 Nuxt의 애니메이션 라이브러리로, 생산 준비가 된 하드웨어 가속 애니메이션을 제공합니다","es":"Motion Vue es una biblioteca de animación para Vue 3 y Nuxt que ofrece animaciones aceleradas por hardware con un tamaño de paquete mínimo.","fr":"Motion Vue est une bibliothèque d''animation pour Vue 3 et Nuxt qui propose des animations accélérées par matériel avec une taille de paquet minimal.","de":"Motion Vue ist eine Animationsbibliothek für Vue 3 und Nuxt, die hardwarebeschleunigte Animationen mit minimalem Paketgröße bietet.","pt":"O Motion Vue é uma biblioteca de animação para Vue 3 e Nuxt, oferecendo animações aceleradas por hardware com tamanho de bundle mínimo","ru":"Motion Vue — это библиотека анимаций для Vue 3 и Nuxt, обеспечивающая аппаратно ускоренные анимации с минимальным размером пакета","ar":"Motion Vue هو مكتبة رسوم متحركة ل Vue 3 و Nuxt، يوفر رسومًا متحركة تعمل بمساعدة الأجهزة مع حجم حزمة صغير"},"seo":{"title":{"en":"Motion: Hardware-Accelerated Animation Setup Guide | AI A...","zh":"Motion AI工具集成指南 - Vue和Nuxt动画库","ja":"Motion AIエージェントのセットアップガイド - VueとNuxtのアニメーションライブラリ","ko":"Motion AI 에이전트 통합 가이드 - Vue와 Nuxt 애니메이션 라이브러리","es":"Guía de configuración de Motion Vue para AI Agents","fr":"Guide de démarrage de Motion Vue pour les outils d''IA","de":"Einrichtungsleitfaden für Motion Vue bei KI-Tools","pt":"Guia de Configuração do Motion Vue para Animações","ru":"Настройка Motion Vue для анимаций: ИИ Агенты","ar":"دليل إعداد Motion Vue للرسوم المتحركة"},"description":{"en":"Unlock seamless animations with Motion Vue! Learn how to integrate this library into your Vue 3 and Nuxt projects for production-ready results","zh":"了解Motion AI工具如何帮助您创建Vue和Nuxt动画，实现生产就绪的硬件加速动画","ja":"Motion AIエージェントを使用してVueとNuxtのアニメーションを作成する方法を学びましょう","ko":"Motion AI 에이전트를 사용하여 Vue와 Nuxt 애니메이션을 생성하는 방법을 알아보세요","es":"Aprende a utilizar Motion Vue para crear animaciones declarativas y gestos basados en interacciones con Vue 3 y Nuxt.","fr":"Découvrez comment utiliser Motion Vue pour créer des animations déclaratives et des interactions basées sur les gestes avec Vue 3 et Nuxt.","de":"Erfahren Sie, wie Sie Motion Vue verwenden, um deklarative Animationen und gestenbasierte Interaktionen mit Vue 3 und Nuxt zu erstellen.","pt":"Aprenda a usar o Motion Vue para criar animações declarativas e interações baseadas em gestos com Vue 3 e Nuxt","ru":"Узнайте, как использовать Motion Vue для создания декларативных анимаций и жестовых взаимодействий с Vue 3 и Nuxt","ar":"تعلم كيفية استخدام Motion Vue لإنشاء الرسوم المتحركة الإعلانية والتفاعلات المعتمدة على الإيماءات مع Vue 3 و Nuxt"},"definition":{"en":"Motion is an animation library for Vue 3 and Nuxt, offering progressive reference for Motion Vue animations with a minimal bundle size","zh":"Motion是Vue和Nuxt的动画库，提供简单的声明式动画和手势交互","ja":"MotionはVueとNuxtのアニメーションライブラリで、シンプルな宣言的アニメーションとジェスチャーインタラクションを提供します","ko":"Motion은 Vue와 Nuxt의 애니메이션 라이브러리로, 단순한 선언적 애니메이션과 제스처 상호작용을 제공합니다","es":"Motion Vue es una biblioteca de animación para Vue 3 y Nuxt que permite crear animaciones declarativas y gestos basados en interacciones.","fr":"Motion Vue est une bibliothèque d''animation pour Vue 3 et Nuxt qui permet de créer des animations déclaratives et des interactions basées sur les gestes.","de":"Motion Vue ist eine Animationsbibliothek für Vue 3 und Nuxt, die es ermöglicht, deklarative Animationen und gestenbasierte Interaktionen zu erstellen.","pt":"O Motion Vue é uma biblioteca de animação para Vue 3 e Nuxt que fornece animações aceleradas por hardware","ru":"Motion Vue — это библиотека анимаций для Vue 3 и Nuxt, обеспечивающая аппаратно ускоренные анимации","ar":"Motion Vue هو مكتبة رسوم متحركة ل Vue 3 و Nuxt التي توفر رسومًا متحركة تعمل بمساعدة الأجهزة"},"features":{"en":["Provides hardware-accelerated animations with minimal bundle size","Supports simple declarative animations like fade, slide, and scale","Enables gesture-based interactions such as hover and tap","Load only files relevant to the current task, reducing bundle size","Compatible with Vue 3 and Nuxt for seamless integration","Offers a progressive reference for Motion Vue animations"],"zh":["支持Vue 3和Nuxt","生产就绪的硬件加速动画","简单的声明式动画","手势交互支持","小巧的包大小"],"ja":["Vue 3とNuxtに対応","制作就緒のハードウェアアクセラレーションアニメーション","シンプルな宣言的アニメーション","ジェスチャーインタラクション対応","小さなパッケージサイズ"],"ko":["Vue 3와 Nuxt 지원","생산 준비가 된 하드웨어 가속 애니메이션","단순한 선언적 애니메이션","제스처 상호작용 지원","작은 패키지 크기"],"es":["Animaciones declarativas con Vue 3","Interacciones basadas en gestos con Nuxt","Animaciones aceleradas por hardware","Tamaño de paquete mínimo","Compatibilidad con NuxtHub"],"fr":["Animations déclaratives avec Vue 3","Interactions basées sur les gestes avec Nuxt","Animations accélérées par matériel","Taille de paquet minimal","Compatibilité avec NuxtHub"],"de":["Deklarative Animationen mit Vue 3","Gestenbasierte Interaktionen mit Nuxt","Hardwarebeschleunigte Animationen","Minimale Paketgröße","Kompatibilität mit NuxtHub"],"pt":["Animações declarativas simples (fade, slide, scale)","Interações baseadas em gestos (hover, tap)","Compatibilidade com Vue 3 e Nuxt","Tamanho de bundle mínimo","Animações aceleradas por hardware"],"ru":["Декларативные анимации (fade, slide, scale)","Жестовые взаимодействия (hover, tap)","Совместимость с Vue 3 и Nuxt","Минимальный размер пакета","Аппаратно ускоренные анимации"],"ar":["الرسوم المتحركة الإعلانية البسيطة (fade, slide, scale)","التفاعلات المعتمدة على الإيماءات (hover, tap)","التوافق مع Vue 3 و Nuxt","حجم الحزمة الصغير","الرسوم المتحركة التي تعمل بمساعدة الأجهزة"]},"keywords":{"en":["how to use motion vue","motion vue alternative","motion vue vs framer motion","motion vue install","motion vue setup guide","what is motion vue","motion vue tutorial","motion vue documentation","motion vue examples","motion vue nuxt integration"],"zh":["Motion AI工具","Vue动画库","Nuxt动画库","硬件加速动画","声明式动画","手势交互","Vue 3动画","Nuxt动画"],"ja":["Motion AIエージェント","Vueアニメーションライブラリ","Nuxtアニメーションライブラリ","ハードウェアアクセラレーションアニメーション","宣言的アニメーション","ジェスチャーインタラクション","Vue 3アニメーション","Nuxtアニメーション"],"ko":["Motion AI 에이전트","Vue 애니메이션 라이브러리","Nuxt 애니메이션 라이브러리","하드웨어 가속 애니메이션","선언적 애니메이션","제스처 상호작용","Vue 3 애니메이션","Nuxt 애니메이션"],"es":["Motion Vue","AI Agents","Vue 3","Nuxt","NuxtHub","animaciones declarativas","interacciones basadas en gestos","animaciones aceleradas por hardware"],"fr":["Motion Vue","outils d''IA","Vue 3","Nuxt","NuxtHub","animations déclaratives","interactions basées sur les gestes","animations accélérées par matériel"],"de":["Motion Vue","KI-Tools","Vue 3","Nuxt","NuxtHub","deklarative Animationen","gestenbasierte Interaktionen","hardwarebeschleunigte Animationen"],"pt":["Motion Vue","animações Vue 3","Nuxt animações","biblioteca de animação","animações aceleradas por hardware","tamanho de bundle mínimo","desenvolvimento web","Vue.js","Nuxt.js"],"ru":["Motion Vue","анимации Vue 3","Nuxt анимации","библиотека анимаций","аппаратно ускоренные анимации","минимальный размер пакета","веб-разработка","Vue.js","Nuxt.js","ИИ Агенты"],"ar":["Motion Vue","الرسوم المتحركة Vue 3","Nuxt الرسوم المتحركة","مكتبة الرسوم المتحركة","الرسوم المتحركة التي تعمل بمساعدة الأجهزة","حجم الحزمة الصغير","تطوير الويب","Vue.js","Nuxt.js","أدوات الذكاء الاصطناعي"]}},"owner":"onmax","repo":"nuxt-skills","repoPath":"onmax/nuxt-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"motion","description":"Use when adding animations with Motion Vue (motion-v) - provides motion component API, gesture animations, scroll-linked effects, layout transitions, and composables for Vue 3/Nuxt","bodyPreview":"# Motion Vue (motion-v)\n\nAnimation library for Vue 3 and Nuxt. Production-ready, hardware-accelerated animations with minimal bundle size.\n\n**Current stable:** motion-v 1.x - Vue port of Motion (formerly Framer Motion)\n\n## Overview\n\nProgressive reference for Motion Vue animations. Load only files relevant to current task (~200 tokens base, 500-1500 per sub-file).\n\n## When to Use\n\n**Use Motion Vue for:**\n\n- Simple declarative animations (fade, slide, scale)\n- Gesture-based interactions (hover, ta","body":"# Motion Vue (motion-v)\n\nAnimation library for Vue 3 and Nuxt. Production-ready, hardware-accelerated animations with minimal bundle size.\n\n**Current stable:** motion-v 1.x - Vue port of Motion (formerly Framer Motion)\n\n## Overview\n\nProgressive reference for Motion Vue animations. Load only files relevant to current task (~200 tokens base, 500-1500 per sub-file).\n\n## When to Use\n\n**Use Motion Vue for:**\n\n- Simple declarative animations (fade, slide, scale)\n- Gesture-based interactions (hover, tap, drag)\n- Scroll-linked animations\n- Layout animations and shared element transitions\n- Spring physics animations\n\n**Consider alternatives:**\n\n- **GSAP** - Complex timelines, SVG morphing, scroll-triggered sequences\n- **@vueuse/motion** - Simpler API, less features, smaller bundle\n- **CSS animations** - Simple transitions without JS\n\n## Installation\n\n```bash\n# Vue 3\npnpm add motion-v\n\n# Nuxt 3\npnpm add motion-v @vueuse/nuxt\n```\n\n```ts\n// nuxt.config.ts - Nuxt 3 setup\nexport default defineNuxtConfig({\n  modules: [''motion-v/nuxt''],\n})\n```\n\n## Quick Reference\n\n| Working on...                | Load file                 |\n| ---------------------------- | ------------------------- |\n| Motion component, gestures   | references/components.md  |\n| useMotionValue, useScroll    | references/composables.md |\n| Animation examples, patterns | references/examples.md    |\n\n## Loading Files\n\n**Consider loading these reference files based on your task:**\n\n- [ ] [references/components.md](references/components.md) - if using Motion component, gestures, or layout animations\n- [ ] [references/composables.md](references/composables.md) - if using useMotionValue, useScroll, useSpring, or animate()\n- [ ] [references/examples.md](references/examples.md) - if looking for animation patterns or inspiration\n\n**DO NOT load all files at once.** Load only what''s relevant to your current task.\n\n## Core Concepts\n\n### Motion Component\n\nRender any HTML/SVG element with animation capabilities:\n\n```vue\n<script setup lang=\"ts\">\nimport { motion } from ''motion-v''\n</script>\n\n<template>\n  <motion.div\n    :initial=\"{ opacity: 0, y: 20 }\"\n    :animate=\"{ opacity: 1, y: 0 }\"\n    :exit=\"{ opacity: 0, y: -20 }\"\n    :transition=\"{ duration: 0.3 }\"\n  >\n    Animated content\n  </motion.div>\n</template>\n```\n\n### Gesture Animations\n\n```vue\n<motion.button\n  :whileHover=\"{ scale: 1.05 }\"\n  :whilePress=\"{ scale: 0.95 }\"\n  :transition=\"{ type: ''spring'', stiffness: 400 }\"\n>\n  Click me\n</motion.button>\n```\n\n### Scroll Animations\n\n```vue\n<motion.div\n  :initial=\"{ opacity: 0 }\"\n  :whileInView=\"{ opacity: 1 }\"\n  :viewport=\"{ once: true, margin: ''-100px'' }\"\n>\n  Appears on scroll\n</motion.div>\n```\n\n## Available Guidance\n\n**[references/components.md](references/components.md)** - Motion component variants, animation props, gesture props, layout animations, transition configuration\n\n**[references/composables.md](references/composables.md)** - useMotionValue, useSpring, useTransform, useScroll, useInView, animate()\n\n**[references/examples.md](references/examples.md)** - External resources, component libraries, animation patterns and inspiration\n"},"lastSynced":"2026-03-08T02:00:38.488Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing hardware-accelerated animation capabilities in Vue and Nuxt environments.","zh":"适合需要在 Vue 和 Nuxt 环境中使用硬件加速动画功能的前端代理。","ja":"Vue および Nuxt 環境でハードウェア アクセラレーションされたアニメーション機能を必要とするフロントエンド エージェントに適しています。","ko":"Vue 및 Nuxt 환경에서 하드웨어 가속 애니메이션 기능을 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades de animación aceleradas por hardware en entornos Vue y Nuxt.","fr":"Parfait pour les agents Frontend qui ont besoin de capacités d''animation accélérées par matériel dans les environnements Vue et Nuxt.","de":"Perfekt für Frontend-Agents, die Hardware-beschleunigte Animationsfunktionen in Vue- und Nuxt-Umgebungen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de animação aceleradas por hardware em ambientes Vue e Nuxt.","ru":"Идеально подходит для агентов Frontend, которым необходимы аппаратно ускоренные анимационные возможности в средах Vue и Nuxt.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى قدرات_animation معززة بالأجهزة في بيئات Vue و Nuxt."},"recommendation":{"en":"Empowers agents to create production-ready, hardware-accelerated animations with minimal bundle size using Motion Vue, leveraging Vue 3 and Nuxt compatibility, and gesture-based interactions like hover and tap.","zh":"赋予代理创建生产就绪的硬件加速动画的能力，使用 Motion Vue，利用 Vue 3 和 Nuxt 兼容性，并使用诸如 hover 和 tap 之类的基于手势的交互，具有最小的包大小。","ja":"Motion Vue を使用して、Vue 3 および Nuxt との互換性を活用し、ホーバーおよびタップなどのジェスチャーベースのインタラクションを使用して、最小のバンドルサイズで生产就绪のハードウェア アクセラレーションされたアニメーションを作成するエージェントの能力を付与します。","ko":"Motion Vue를 사용하여 Vue 3 및 Nuxt와의 호환성을 활용하고 hover 및 tap과 같은 제스처 기반 상호 작용을 사용하여 최소한의 번들 크기로 생산 준비가 된 하드웨어 가속 애니메이션을 만들 수 있는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a crear animaciones de producción listas, aceleradas por hardware, con un tamaño de paquete mínimo utilizando Motion Vue, aprovechando la compatibilidad con Vue 3 y Nuxt, y las interacciones basadas en gestos como hover y tap.","fr":"Permet aux agents de créer des animations prêtes pour la production, accélérées par matériel, avec une taille de bundle minimale en utilisant Motion Vue, en exploitant la compatibilité avec Vue 3 et Nuxt, et les interactions basées sur les gestes comme hover et tap.","de":"Ermöglicht es den Agents, produktionsbereite, hardwarebeschleunigte Animationen mit minimalem Bundlegewicht zu erstellen, indem es Motion Vue nutzt, die Kompatibilität mit Vue 3 und Nuxt ausnutzt und gestenbasierte Interaktionen wie Hover und Tap.","pt":"Habilita os agentes a criar animações de produção prontas, aceleradas por hardware, com tamanho de pacote mínimo usando Motion Vue, aproveitando a compatibilidade com Vue 3 e Nuxt e interações baseadas em gestos, como hover e toque.","ru":"Наделяет агентов возможностью создавать готовые к производству, аппаратно ускоренные анимации с минимальным размером пакета, используя Motion Vue, используя совместимость с Vue 3 и Nuxt, и жестовые взаимодействия, такие как наведение и касание.","ar":"يمكّن الوكلاء من إنشاء رسوم متحركة جاهزة للإنتاج معززة بالأجهزة مع حجم حزمة صغير باستخدام Motion Vue، واستغلال التوافق مع Vue 3 و Nuxt والتفاعلات القائمة على الإشارات مثل الحوفر والتاب."},"useCases":{"en":["Implementing simple declarative animations such as fade, slide, and scale","Developing gesture-based interactions for enhanced user experience","Optimizing animation performance with minimal bundle size"],"zh":["实现简单的声明式动画，例如淡入、淡出、滑动和缩放","开发基于手势的交互以增强用户体验","使用最小的包大小优化动画性能"],"ja":["フェード、スライド、スケールなどのシンプルな宣言型アニメーションの実装","拡張されたユーザー エクスペリエンスのためのジェスチャーベースのインタラクションの開発","最小のバンドル サイズでアニメーション パフォーマンスの最適化"],"ko":["페이드, 슬라이드, 스케일 등과 같은 단순한 선언적 애니메이션 구현","향상된 사용자 경험을 위한 제스처 기반 상호 작용 개발","최소한의 번들 크기로 애니메이션 성능 최적화"],"es":["Implementar animaciones declarativas simples como fade, slide y scale","Desarrollar interacciones basadas en gestos para una experiencia de usuario mejorada","Optimizar el rendimiento de la animación con un tamaño de paquete mínimo"],"fr":["Mettre en œuvre des animations déclaratives simples telles que fade, slide et scale","Développer des interactions basées sur les gestes pour une expérience utilisateur améliorée","Optimiser les performances d''animation avec une taille de bundle minimale"],"de":["Einfache deklarative Animationen wie Fade, Slide und Scale implementieren","Gestenbasierte Interaktionen für eine verbesserte Benutzererfahrung entwickeln","Animationsleistung mit minimalem Bundlegewicht optimieren"],"pt":["Implementar animações declarativas simples, como fade, slide e scale","Desenvolver interações baseadas em gestos para experiência do usuário aprimorada","Otimizar o desempenho da animação com tamanho de pacote mínimo"],"ru":["Реализация простых декларативных анимаций, таких как затухание, скольжение и масштабирование","Разработка жестовых взаимодействий для улучшения пользовательского опыта","Оптимизация производительности анимации с минимальным размером пакета"],"ar":["تطبيق رسوم متحركة إعلانية بسيطة مثل التلاشي والانزلاق والتكبير","تطوير تفاعلات قائمة على الإشارات لتحسين تجربة المستخدم","تحسين أداء الرسوم المتحركة مع حجم حزمة صغير"]},"limitations":{"en":["Specific to Vue 3 and Nuxt environments","Requires Motion Vue library integration"],"zh":["仅限于 Vue 3 和 Nuxt 环境","需要 Motion Vue 库集成"],"ja":["Vue 3 および Nuxt 環境に限定","Motion Vue ライブラリの統合が必要"],"ko":["Vue 3 및 Nuxt 환경에만 국한","Motion Vue 라이브러리 통합이 필요"],"es":["Específico para entornos Vue 3 y Nuxt","Requiere integración de la biblioteca Motion Vue"],"fr":["Spécifique aux environnements Vue 3 et Nuxt","Nécessite l''intégration de la bibliothèque Motion Vue"],"de":["Spezifisch für Vue 3- und Nuxt-Umgebungen","Benötigt die Integration der Motion Vue-Bibliothek"],"pt":["Específico para ambientes Vue 3 e Nuxt","Requer integração da biblioteca Motion Vue"],"ru":["Конкретно для сред Vue 3 и Nuxt","Требует интеграции библиотеки Motion Vue"],"ar":["محدد لبيئات Vue 3 و Nuxt","يتطلب تكامل مكتبة Motion Vue"]},"version":4},"contentHash":"f0e7a7749a2eed534f115c551b6ff27c17c9f38c25689302b7032fe583e41a60","qualityScore":54}');
