INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kasperjunge/agent-resources/create-plan', 'create-plan', 'kasperjunge', 'agent-resources', 'community', 'create-plan kasperjunge agent-resources community The create-plan skill allows AI agents to create a comprehensive implementation plan and enter plan mode for execution, benefiting developers in the development workflow. create-plan技能是AI工具的包管理器，允许开发者从GitHub安装技能并创建全面实施计划 create-planスキルはAIエージェントのパッケージマネージャーで、GitHubからスキルをインストールし、計画を作成する create-plan 스킬은 AI 에이전트의 패키지 매니저로, GitHub에서 스킬을 설치하고 계획을 생성합니다 Create Plan es un administrador de paquetes para agentes de AI que permite crear un plan de implementación integral desde GitHub. Create Plan est un gestionnaire de paquets pour les outils d''IA qui permet de créer un plan d''implémentation complet à partir de GitHub. Create Plan ist ein Paketmanager für AI-Agents, der die Erstellung eines umfassenden Implementierungsplans aus GitHub ermöglicht. Create-Plan é uma ferramenta de gerenciamento de habilidades para agentes de IA que permite criar planos de implementação eficazes Create-Plan - это менеджер навыков для ИИ Агентов, который позволяет создавать комплексные планы реализации Create-Plan هو أداة إدارة المهارات للوكلاء الذكية التي تمكنك من إنشاء خطط تنفيذ فعالة how to use create-plan create-plan setup guide create-plan alternative create-plan vs package managers install create-plan what is create-plan create-plan for AI agents create-plan development workflow create-plan GitHub integration AI工具 create-plan技能 包管理器 GitHub 实施计划 开发流程 第一原则 Installs agent skills from GitHub with a single command Enables creation of a comprehensive implementation plan Enters plan mode for execution as part of a 5-step development workflow Supports resistance to bias toward finishing quickly Follows core principles of first principles and simplicity Positions itself as Step 4 in the development workflow create-plan is a package manager for AI agents that enables the installation of skills from GitHub with a single command, facilitating a streamlined development workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('axiomhq/cli/explore-dataset', 'community', 'axiomhq', 'cli', 'axiomhq/cli', 'explore-dataset', 0, 0, 54, '2026-03-08T01:57:15.284Z', '2026-03-08T02:00:56.197Z', '4eb974798cc51093529b441a992fc5bdc1bca12cd733a850ca899afe76d040e8', '{"id":"axiomhq/cli/explore-dataset","name":"explore-dataset","description":{"en":"The explore-dataset skill enables developers to systematically explore Axiom datasets, understanding their structure, content, and potential use cases. It benefits AI agent developers and data analysts.","zh":"Axiom 命令行工具用于探索数据集，了解其结构和内容。使用 `/explore-dataset` 命令来发现数据集的模式和结构。","ja":"Axiom コマンドラインツールはデータセットを探索し、その構造とコンテンツを理解するために使用されます。`/explore-dataset` コマンドを使用してデータセットのパターンと構造を発見します。","ko":"Axiom 명령줄 도구는 데이터셋을 탐색하여 구조와 내용을 이해하는 데 사용됩니다. `/explore-dataset` 명령을 사용하여 데이터셋의 패턴과 구조를 발견합니다.","es":"Explore-dataset es un sistema de exploración de datos que permite a los desarrolladores comprender la estructura y el contenido de un conjunto de datos Axiom","fr":"Explore-dataset est un système d''exploration de données qui permet aux développeurs de comprendre la structure et le contenu d''un jeu de données Axiom","de":"Explore-Dataset ist ein Datenerkundungssystem, das es Entwicklern ermöglicht, die Struktur und den Inhalt eines Axiom-Datensatzes zu verstehen","pt":"O explore-dataset é uma ferramenta de linha de comando do Axiom que permite explorar conjuntos de dados de forma sistemática.","ru":"Explore-dataset - это инструмент командной строки Axiom, который позволяет систематически исследовать наборы данных.","ar":"explore-dataset هو أداة سطر الأوامر في Axiom التي تمكنك من استكشاف مجموعات البيانات بطريقة منهجية"},"seo":{"title":{"en":"explore-dataset: Dataset Exploration Setup Guide | AI Age...","zh":"探索数据集：Axiom 命令行工具 Setup Guide","ja":"データセットの探索：Axiom コマンドラインツールのベストプラクティス","ko":"데이터セット 탐색: Axiom 명령줄 도구 설정 가이드","es":"Guía de configuración de explore-dataset para desarrollad...","fr":"Configurer explore-dataset : Guide de démarrage pour les ...","de":"Explore-Dataset-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do explore-dataset: Explorando Conju...","ru":"Настройка ИИ Агентов: explore-dataset для исследования на...","ar":"دليل إعداد explore-dataset: استكشاف مجموعات البيانات باست..."},"description":{"en":"Unlock the full potential of Axiom datasets with explore-dataset. Discover how to systematically explore and understand your data with our expert guide.","zh":"了解 Axiom 命令行工具的强大功能，探索数据集，发现模式和结构，AIエージェント","ja":"Axiom コマンドラインツールの Potential を解き放ち、データセットを探索し、構造とコンテンツを理解する、AIエージェント","ko":"Axiom 명령줄 도구의 기능을 살펴보고 데이터셋을 탐색하여 구조와 내용을 이해하는 방법, AI 도구","es":"Aprende a utilizar explore-dataset para explorar sistemáticamente un conjunto de datos Axiom y descubrir su estructura y contenido","fr":"Découvrez comment utiliser explore-dataset pour explorer systématiquement un jeu de données Axiom et en découvrir la structure et le contenu","de":"Erfahren Sie, wie Sie explore-dataset verwenden, um ein Axiom-Datenset systematisch zu erkunden und dessen Struktur und Inhalt zu entdecken","pt":"Aprenda a explorar conjuntos de dados com o explore-dataset, uma ferramenta de linha de comando do Axiom. Descubra esquemas, liste conjuntos de dados disponí...","ru":"Узнайте, как исследовать наборы данных с помощью explore-dataset, инструмента командной строки Axiom. Откройте для себя схемы, список доступных наборов данны...","ar":"تعرف على كيفية استكشاف مجموعات البيانات باستخدام explore-dataset، أداة سطر الأوامر في Axiom. اكتشف مخططات البيانات، قوائم مجموعات البيانات المتاحة وأكثر من ذلك"},"definition":{"en":"explore-dataset is a command-line tool for systematically exploring Axiom datasets to understand their structure, content, and potential use cases.","zh":"Axiom 命令行工具的 `explore-dataset` 功能是用于探索数据集的结构和内容的工具","ja":"Axiom コマンドラインツールの `explore-dataset` 機能は、データセットの構造とコンテンツを理解するためのツールです","ko":"Axiom 명령줄 도구의 `explore-dataset` 기능은 데이터셋의 구조와 내용을 이해하는 데 사용되는 도구입니다","es":"Explore-dataset es una herramienta de línea de comandos que permite explorar sistemáticamente un conjunto de datos Axiom","fr":"Explore-dataset est un outil de ligne de commande qui permet d''explorer systématiquement un jeu de données Axiom","de":"Explore-Dataset ist ein Kommandozeilen-Tool, das die systematische Erkundung eines Axiom-Datensatzes ermöglicht","pt":"O explore-dataset é uma ferramenta que permite explorar conjuntos de dados para entender sua estrutura e conteúdo.","ru":"Explore-dataset - это инструмент, который позволяет исследовать наборы данных для понимания их структуры и содержания.","ar":"explore-dataset هو أداة تستخدم لاستكشاف مجموعات البيانات لفهم هيكلها ومحتواها"},"features":{"en":["Lists available datasets using the `axiom dataset list -f json` command","Discovers actual field names and types using the `axiom query` command","Supports dataset exploration protocol with a systematic approach","Provides a command-line interface for exploring Axiom datasets","Enables discovery of dataset schema and content"],"zh":["支持使用 `/explore-dataset` 命令来探索数据集","可以使用 `axiom dataset list -f json` 命令来列出可用的数据集","可以使用 `axiom query` 命令来发现数据集的模式和结构","支持使用 `$ARGUMENTS` 变量来获取数据集名称","支持使用 CLI 命令来探索数据集","支持 JSON 格式的数据集列表"],"ja":[" `/explore-dataset` コマンドを使用してデータセットを探索する機能"," `axiom dataset list -f json` コマンドを使用して利用可能なデータセットをリストする機能"," `axiom query` コマンドを使用してデータセットのパターンと構造を発見する機能"," `$ARGUMENTS` 変数を使用してデータセット名を取得する機能"," CLI コマンドを使用してデータセットを探索する機能"," JSON 形式のデータセットリストをサポートする機能"],"ko":[" `/explore-dataset` 명령을 사용하여 데이터셋을 탐색하는 기능"," `axiom dataset list -f json` 명령을 사용하여 사용 가능한 데이터셋을 목록으로 표시하는 기능"," `axiom query` 명령을 사용하여 데이터셋의 패턴과 구조를 발견하는 기능"," `$ARGUMENTS` 변수를 사용하여 데이터셋 이름을 가져오는 기능"," CLI 명령을 사용하여 데이터셋을 탐색하는 기능"," JSON 형식의 데이터셋 목록을 지원하는 기능"],"es":["Lista de conjuntos de datos disponibles con `axiom dataset list -f json`","Descubrimiento de esquemas con `axiom query`","Exploración de campos y tipos de datos","Compatibilidad con la línea de comandos","Integración con Axiom"],"fr":["Liste des jeux de données disponibles avec `axiom dataset list -f json`","Découverte de schémas avec `axiom query`","Exploration de champs et de types de données","Compatibilité avec la ligne de commande","Intégration avec Axiom"],"de":["Liste der verfügbaren Datensätze mit `axiom dataset list -f json`","Schema-Erkennung mit `axiom query`","Felder- und Datentypen-Erkundung","Kompatibilität mit der Kommandozeile","Integration mit Axiom"],"pt":["Lista conjuntos de dados disponíveis com `axiom dataset list -f json`","Descobre esquemas de conjuntos de dados com `axiom query`","Explora conjuntos de dados de forma sistemática","Suporta linha de comando para automação","Permite entender a estrutura e o conteúdo dos conjuntos de dados"],"ru":["Список доступных наборов данных с помощью `axiom dataset list -f json`","Открывает схемы наборов данных с помощью `axiom query`","Систематически исследует наборы данных","Поддерживает командную строку для автоматизации","Позволяет понять структуру и содержание наборов данных"],"ar":["قائمة مجموعات البيانات المتاحة باستخدام `axiom dataset list -f json`","اكتشف مخططات مجموعات البيانات باستخدام `axiom query`","استكشاف مجموعات البيانات بطريقة منهجية","دعم سطر الأوامر للتحكم الآلي","تمكنك من فهم هيكل ومحتويات مجموعات البيانات"]},"keywords":{"en":["how to use explore-dataset","explore-dataset alternative","explore-dataset setup guide","what is explore-dataset","explore-dataset vs axiom query","install explore-dataset","explore-dataset documentation","axiom dataset exploration","dataset exploration protocol"],"zh":["Axiom 命令行工具","explore-dataset","数据集探索","AIエージェント","命令行工具","数据集结构","数据集内容","CLI 命令","JSON 格式"],"ja":["Axiom コマンドラインツール","explore-dataset","データセットの探索","AIエージェント","コマンドラインツール","データセットの構造","データセットのコンテンツ","CLI コマンド","JSON 形式"],"ko":["Axiom 명령줄 도구","explore-dataset","데이터셋 탐색","AI 도구","명령줄 도구","데이터셋 구조","데이터셋 내용","CLI 명령","JSON 형식"],"es":["herramientas de AI","exploración de datos","Axiom","línea de comandos","desarrollo de software","conjuntos de datos","esquemas de datos","tipos de datos"],"fr":["outils d''IA","exploration de données","Axiom","ligne de commande","développement de logiciels","jeux de données","schémas de données","types de données"],"de":["KI-Tools","Datenerkundung","Axiom","Kommandozeile","Software-Entwicklung","Datensätze","Daten-Schemata","Daten-Typen"],"pt":["explore-dataset","Axiom","conjuntos de dados","linha de comando","esquemas de dados","automatização de dados","análise de dados","ferramentas de dados","desenvolvimento de dados"],"ru":["explore-dataset","Axiom","наборы данных","командная строка","схемы данных","автоматизация данных","анализ данных","инструменты данных","разработка данных","ИИ Агенты"],"ar":["explore-dataset","Axiom","مجموعات البيانات","سطر الأوامر","مخططات البيانات","تحكم آلي بالبيانات","تحليل البيانات","أدوات البيانات","تطوير البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"axiomhq","repo":"cli","repoPath":"axiomhq/cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.284Z","topics":[],"category":"community","skillMd":{"name":"explore-dataset","description":"Explore an Axiom dataset to understand its schema, fields, volume, and patterns. Use when discovering a new dataset, investigating data structure, or understanding what data is available.","bodyPreview":"# Dataset Exploration\n\nSystematically explore an Axiom dataset to understand its structure, content, and potential use cases.\n\n## Arguments\n\nWhen invoked with a dataset name (e.g., `/explore-dataset logs`), the name is available as `$ARGUMENTS`.\n\n## Exploration Protocol\n\n### 1. List Available Datasets\n\nIf no dataset specified, list what''s available:\n\n```bash\naxiom dataset list -f json\n```\n\n### 2. Schema Discovery\n\n**Always start here.** Discover actual field names and types:\n\n```bash\naxiom query","body":"# Dataset Exploration\n\nSystematically explore an Axiom dataset to understand its structure, content, and potential use cases.\n\n## Arguments\n\nWhen invoked with a dataset name (e.g., `/explore-dataset logs`), the name is available as `$ARGUMENTS`.\n\n## Exploration Protocol\n\n### 1. List Available Datasets\n\nIf no dataset specified, list what''s available:\n\n```bash\naxiom dataset list -f json\n```\n\n### 2. Schema Discovery\n\n**Always start here.** Discover actual field names and types:\n\n```bash\naxiom query \"[''<dataset>''] | getschema\" --start-time -1h\n```\n\nIdentify:\n- Field names and types\n- Dotted fields requiring bracket notation\n- Timestamp fields\n- Key dimensions (service, status, level)\n\n**OTel trace data:** If schema contains `trace_id`, `span_id`, `attributes.*`, note that:\n- Service fields are promoted: use `[''service.name'']` not `[''resource.service.name'']`\n- Custom attributes: `[''attributes.custom''][''field'']` with `tostring()` for aggregations\n- See `axiom-apl` skill''s [OTel reference](../axiom-apl/references/otel.md) for field mappings\n\n### 3. Sample Data\n\nExamine actual values:\n\n```bash\naxiom query \"[''<dataset>''] | limit 10\" --start-time -1h -f json\n```\n\nLook for:\n- Data structure and relationships\n- Field value formats\n- Data quality issues\n\n### 4. Volume Analysis\n\nUnderstand data volume patterns:\n\n```bash\naxiom query \"[''<dataset>''] | summarize count() by bin(_time, 1h) | sort by _time asc\" --start-time -24h\n```\n\nAnalyze:\n- Event volume over time\n- Data freshness\n- Collection gaps\n\n### 5. Categorical Field Analysis\n\nFor each key categorical field (status, level, service):\n\n```bash\naxiom query \"[''<dataset>''] | summarize count() by <field> | top 20 by count_\" --start-time -1h\n```\n\nIdentify:\n- Value distributions\n- Cardinality\n- Key dimensions for filtering\n\n### 6. Numerical Field Statistics\n\nFor numeric fields (duration, bytes, count):\n\n```bash\naxiom query \"[''<dataset>''] | summarize count(), min(<field>), max(<field>), avg(<field>), percentiles(<field>, 50, 95, 99)\" --start-time -1h\n```\n\n### 7. Error Pattern Detection\n\nSearch for error indicators:\n\n```bash\naxiom query \"search in ([''<dataset>'']) ''error'' or ''fail'' or ''exception'' | limit 20\" --start-time -1h\n```\n\n## Output Format\n\nProvide a summary including:\n\n```markdown\n## Dataset Summary: <name>\n\n### Purpose\n<What system generated this data, what it represents>\n\n### Key Fields\n| Field | Type | Description |\n|-------|------|-------------|\n| ... | ... | ... |\n\n### Volume\n- Events per hour: ~X\n- Data freshness: last event at X\n\n### Key Dimensions\n- `status`: 200, 400, 500, ...\n- `service.name`: api, web, worker, ...\n\n### Recommended Queries\n<Common queries for this dataset>\n\n### Monitoring Opportunities\n<What could be alerted on>\n```\n\n## When NOT to Use\n\n- **Known datasets**: If you already understand the schema, skip exploration and query directly\n- **Quick field check**: Use `getschema` directly for single field lookups\n- **Production queries**: Exploration uses expensive operations (`search`); extract patterns then optimize\n- **Repeated analysis**: Once explored, document findings and reuse—don''t re-explore\n\n## APL Reference\n\nFor query syntax, invoke the `axiom-apl` skill which provides comprehensive documentation on operators, functions, and patterns.\n"},"lastSynced":"2026-03-08T02:00:56.197Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing systematic exploration of Axiom datasets for structure, content, and potential use cases.","zh":"非常适合需要对 Axiom 数据集进行系统化探索以获取结构、内容和潜在用例的数据分析代理。","ja":"Axiom データセットの構造、コンテンツ、潜在的な使用例の体系的な探索が必要なデータ分析エージェントに最適です。","ko":"Axiom 데이터셋의 구조, 내용 및 잠재적 사용 사례에 대한 체계적인 탐색이 필요한 데이터 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan una exploración sistemática de los conjuntos de datos de Axiom para estructura, contenido y casos de uso potenciales.","fr":"Parfait pour les Agents d''Analyse de Données nécessitant une exploration systématique des jeux de données Axiom pour structure, contenu et cas d''utilisation potentiels.","de":"Perfekt für Data Analysis Agents, die eine systematische Erforschung von Axiom-Datensätzen für Struktur, Inhalt und potenzielle Anwendungsfälle benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de exploração sistemática de conjuntos de dados Axiom para estrutura, conteúdo e casos de uso potenciais.","ru":"Идеально для агентов анализа данных, которым требуется систематическое исследование наборов данных Axiom для структуры, содержания и потенциальных случаев использования.","ar":"مثالي للوكلاء تحليل البيانات الذين يحتاجون إلى استكشاف منهجي لمجموعات بيانات Axiom لهياكلها ومحتوىاها والحالات استخدامها المحتملة."},"recommendation":{"en":"Empowers agents to systematically discover dataset schemas, list available datasets, and analyze field names and types using Axiom query and JSON-formatted output, facilitating advanced data visualization and analysis capabilities.","zh":"赋予代理系统地发现数据集模式、列出可用的数据集，并使用 Axiom 查询和 JSON 格式输出分析字段名称和类型，从而实现高级数据可视化和分析功能。","ja":"エージェントに、Axiom クエリと JSON 形式の出力を使用して、データセットのスキーマを体系的に発見し、利用可能なデータセットをリストし、フィールド名とタイプを分析する機能を提供し、高度なデータ可視化と分析機能を実現します。","ko":"에이전트가 Axiom 쿼리 및 JSON 형식의 출력을 사용하여 데이터셋 스키마를 체계적으로 발견하고 사용 가능한 데이터셋을 나열하며 필드 이름 및 유형을 분석하여 고급 데이터 시각화 및 분석 기능을 제공합니다.","es":"Habilita a los agentes a descubrir sistemáticamente esquemas de conjunto de datos, listar conjuntos de datos disponibles y analizar nombres y tipos de campo utilizando la consulta de Axiom y la salida en formato JSON, lo que facilita capacidades avanzadas de visualización y análisis de datos.","fr":"Permet aux agents de découvrir systématiquement les schémas de jeu de données, de lister les jeux de données disponibles et d''analyser les noms et les types de champ en utilisant la requête Axiom et la sortie au format JSON, ce qui facilite les capacités avancées de visualisation et d''analyse de données.","de":"Ermächtigt Agents, Datensatzschemata systematisch zu entdecken, verfügbare Datensätze aufzulisten und Feldnamen und -typen unter Verwendung von Axiom-Abfragen und JSON-formatierter Ausgabe zu analysieren, wodurch erweiterte Datenvisualisierungs- und Analysefunktionen ermöglicht werden.","pt":"Habilita os agentes a descobrirem sistematicamente esquemas de conjunto de dados, listarem conjuntos de dados disponíveis e analisarem nomes de campo e tipos usando consulta Axiom e saída formatada em JSON, facilitando capacidades avançadas de visualização e análise de dados.","ru":"Наделяет агентов возможностью систематически обнаруживать схемы наборов данных, перечислять доступные наборы данных и анализировать имена полей и типы с помощью запроса Axiom и вывода в формате JSON, что облегчает расширенные возможности визуализации и анализа данных.","ar":"تمكّن الوكلاء من اكتشاف مخططات مجموعات البيانات بشكل منهجي وlisting مجموعات البيانات المتاحة وتحليل أسماء الحقول وأنواعها باستخدام استعلام Axiom ومخرجات JSON، مما يسهل إمكانيات متقدمة لتصور البيانات وتحليلها."},"useCases":{"en":["Discovering dataset schemas for informed model training","Listing available datasets for data-driven decision making","Analyzing field names and types for efficient data processing"],"zh":["发现数据集模式以进行知情的模型训练","列出可用的数据集以进行数据驱动的决策","分析字段名称和类型以进行高效的数据处理"],"ja":["情報に基づいたモデル訓練のためのデータセットスキーマの発見","データ駆動の意思決定のための利用可能なデータセットのリスト","効率的なデータ処理のためのフィールド名とタイプの分析"],"ko":["정보에 기반한 모델 트레이닝을 위한 데이터셋 스키마의 발견","데이터 주도적인 의사 결정의ための 사용 가능한 데이터셋의 목록","효율적인 데이터 처리를 위한 필드 이름 및 유형의 분석"],"es":["Descubrir esquemas de conjunto de datos para un entrenamiento de modelo informado","Listar conjuntos de datos disponibles para la toma de decisiones basada en datos","Analizar nombres y tipos de campo para un procesamiento de datos eficiente"],"fr":["Découvrir les schémas de jeu de données pour un entraînement de modèle éclairé","Lister les jeux de données disponibles pour la prise de décision basée sur les données","Analyser les noms et les types de champ pour un traitement de données efficace"],"de":["Entdecken von Datensatzschemata für eine informierte Modellierung","Auflisten verfügbarer Datensätze für datengetriebene Entscheidungsfindung","Analysieren von Feldnamen und -typen für ein effizientes Datenverarbeiten"],"pt":["Descobrir esquemas de conjunto de dados para treinamento de modelo informado","Listar conjuntos de dados disponíveis para tomada de decisão baseada em dados","Analizar nomes de campo e tipos para processamento de dados eficiente"],"ru":["Обнаружение схем наборов данных для информированного обучения модели","Перечисление доступных наборов данных для принятия решений на основе данных","Анализ имен полей и типов для эффективной обработки данных"],"ar":["اكتشاف مخططات مجموعات البيانات لتدريب الموديلات على أساسها","الاستفادة من قائمة مجموعات البيانات المتاحة لاتخاذ قرارات مدعومة بالبيانات","تحليل أسماء الحقول وأنواعها من أجل معالجة البيانات بكفاءة"]},"limitations":{"en":["Requires Axiom dataset access","Dependent on axiom query and dataset list functionality"],"zh":["需要 Axiom 数据集访问","依赖于 Axiom 查询和数据集列表功能"],"ja":["Axiom データセットへのアクセスが必要","Axiom クエリとデータセットリスト機能に依存"],"ko":["Axiom 데이터셋에 대한 액세스가 필요함","Axiom 쿼리 및 데이터셋 목록 기능에 의존"],"es":["Requiere acceso al conjunto de datos de Axiom","Dependiente de la funcionalidad de consulta y lista de conjuntos de datos de axiom"],"fr":["Nécessite un accès au jeu de données Axiom","Dépend de la fonctionnalité de requête et de liste de jeux de données d''axiom"],"de":["Benötigt Zugriff auf den Axiom-Datensatz","Abhängig von der Axiom-Abfrage- und Datensatzlistenfunktion"],"pt":["Requer acesso ao conjunto de dados Axiom","Dependente da funcionalidade de consulta e lista de conjuntos de dados do Axiom"],"ru":["Требует доступа к набору данных Axiom","Зависит от функциональности запроса и списка наборов данных Axiom"],"ar":["يتطلب الوصول إلى مجموعة بيانات Axiom","يعتمد على وظيفة استعلام وقائمة مجموعات بيانات Axiom"]},"version":4},"contentHash":"4eb974798cc51093529b441a992fc5bdc1bca12cd733a850ca899afe76d040e8","qualityScore":54}');
