INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('axiomhq/cli/explore-dataset', 'explore-dataset', 'axiomhq', 'cli', 'community', 'explore-dataset axiomhq cli community The explore-dataset skill enables developers to systematically explore Axiom datasets, understanding their structure, content, and potential use cases. It benefits AI agent developers and data analysts. Axiom 命令行工具用于探索数据集，了解其结构和内容。使用 `/explore-dataset` 命令来发现数据集的模式和结构。 Axiom コマンドラインツールはデータセットを探索し、その構造とコンテンツを理解するために使用されます。`/explore-dataset` コマンドを使用してデータセットのパターンと構造を発見します。 Axiom 명령줄 도구는 데이터셋을 탐색하여 구조와 내용을 이해하는 데 사용됩니다. `/explore-dataset` 명령을 사용하여 데이터셋의 패턴과 구조를 발견합니다. Explore-dataset es un sistema de exploración de datos que permite a los desarrolladores comprender la estructura y el contenido de un conjunto de datos Axiom Explore-dataset est un système d''exploration de données qui permet aux développeurs de comprendre la structure et le contenu d''un jeu de données Axiom Explore-Dataset ist ein Datenerkundungssystem, das es Entwicklern ermöglicht, die Struktur und den Inhalt eines Axiom-Datensatzes zu verstehen O explore-dataset é uma ferramenta de linha de comando do Axiom que permite explorar conjuntos de dados de forma sistemática. Explore-dataset - это инструмент командной строки Axiom, который позволяет систематически исследовать наборы данных. explore-dataset هو أداة سطر الأوامر في Axiom التي تمكنك من استكشاف مجموعات البيانات بطريقة منهجية how to use explore-dataset explore-dataset alternative explore-dataset setup guide what is explore-dataset explore-dataset vs axiom query install explore-dataset explore-dataset documentation axiom dataset exploration dataset exploration protocol Axiom 命令行工具 explore-dataset 数据集探索 AIエージェント 命令行工具 数据集结构 数据集内容 CLI 命令 JSON 格式 Lists available datasets using the `axiom dataset list -f json` command Discovers actual field names and types using the `axiom query` command Supports dataset exploration protocol with a systematic approach Provides a command-line interface for exploring Axiom datasets Enables discovery of dataset schema and content explore-dataset is a command-line tool for systematically exploring Axiom datasets to understand their structure, content, and potential use cases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ooiyeefei/ccc/excalidraw', 'community', 'ooiyeefei', 'ccc', 'ooiyeefei/ccc', 'excalidraw', 0, 0, 54, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.597Z', 'a5e257e280fd877c31ce33c69c739ce40f11861c6008aa0a79f48652fbd622f5', '{"id":"ooiyeefei/ccc/excalidraw","name":"excalidraw","description":{"en":"Excalidraw generates architecture diagrams as .excalidraw files from codebase analysis, benefiting developers and architects. It identifies components, services, and databases, mapping relationships and dependencies.","zh":"Excalidraw是一种代码分析工具，可以生成架构图。支持多种语言和框架，能够识别组件、服务、数据库和API","ja":"Excalidrawはコード分析ツールであり、アーキテクチャ図を生成します。複数の言語とフレームワークをサポートし、コンポーネント、サービス、データベース、APIを識別します","ko":"Excalidraw는 코드 분석 도구로 아키텍처 다이어그램을 생성합니다. 여러 언어와 프레임워크를 지원하며 컴포넌트, 서비스, 데이터베이스 및 API를 식별할 수 있습니다","es":"Excalidraw es una herramienta para generar diagramas de arquitectura como archivos .excalidraw. Analiza el código y identifica componentes y servicios.","fr":"Excalidraw est un outil pour générer des diagrammes d''architecture au format .excalidraw. Il analyse le code et identifie les composants et les services.","de":"Excalidraw ist ein Tool zur Generierung von Architekturdiagrammen als .excalidraw-Dateien. Es analysiert den Code und identifiziert Komponenten und Dienste.","pt":"O Excalidraw é uma ferramenta de geração de diagramas de arquitetura que analisa o código e identifica componentes, serviços e bancos de dados","ru":"ИИ Агент Excalidraw - это инструмент для генерации диаграмм архитектуры, который анализирует код и идентифицирует компоненты, сервисы и базы данных","ar":"إكسكالي درو هو أداة لإنشاء رسومات بنية النظام التي تحلل الكود وتحدد المكونات والخدمات وقواعد البيانات"},"seo":{"title":{"en":"Excalidraw: Architecture Diagram Generator for AI Agents ...","zh":"Excalidraw_SETUP GUIDE：代码分析生成架构图","ja":"Excalidrawセットアップガイド：コード分析によるアーキテクチャ図生成","ko":"Excalidraw 설정 가이드: 코드 분석을 통한 아키텍처 다이어그램 생성","es":"Guía de configuración de Excalidraw para generación de di...","fr":"Guide d''installation d''Excalidraw pour la génération de d...","de":"Excalidraw-Setup-Anleitung für die Generierung von Archit...","pt":"Guia de Configuração do Excalidraw para Geração de Diagra...","ru":"ИИ Агент Excalidraw: Руководство по Настройке для Генерац...","ar":"دليل إعداد إكسكالي درو لإنشاء رسومات بنية النظام"},"description":{"en":"Unlock the power of Excalidraw and generate architecture diagrams from codebase analysis. Learn how to get started and visualize your system today!","zh":"使用Excalidraw自动生成代码分析报告，支持PNG和SVG导出。了解如何使用Claude Code自定义插件","ja":"Excalidrawを使用してコード分析レポートを自動生成します。PNGおよびSVGへのエクスポートもサポートします。Claude Codeのカスタムプラグインについてご覧ください","ko":"Excalidraw를 사용하여 코드 분석 보고서를 자동 생성하고 PNG 및 SVG로 내보내세요. Claude Code의 사용자 지정 플러그인에 대해 자세히 알아보세요","es":"Aprende a generar diagramas de arquitectura como archivos .excalidraw directamente desde el análisis del código, con exportación opcional a PNG y SVG","fr":"Découvrez comment générer des diagrammes d''architecture au format .excalidraw directement à partir de l''analyse du code, avec exportation facultative vers PN...","de":"Erfahren Sie, wie Sie Architekturdiagramme als .excalidraw-Dateien direkt aus der Codeanalyse generieren, mit optionaler Exportmöglichkeit nach PNG und SVG","pt":"Aprenda a usar o Excalidraw para gerar diagramas de arquitetura a partir da análise do código, com exportação para PNG e SVG","ru":"Изучите, как использовать ИИ Агент Excalidraw для генерации диаграмм архитектуры из анализа кода, с возможностью экспорта в PNG и SVG","ar":"تعلم كيفية استخدام إكسكالي درو لإنشاء رسومات بنية النظام من تحليل الكود، مع إمكانية تصدير إلى PNG وSVG"},"definition":{"en":"Excalidraw is a diagram generator that creates architecture diagrams as .excalidraw files directly from codebase analysis, with optional export to PNG and SVG.","zh":"Excalidraw是一种代码分析工具，能够生成架构图","ja":"Excalidrawはコード分析ツールであり、アーキテクチャ図を生成する","ko":"Excalidraw는 코드 분석 도구로 아키텍처 다이어그램을 생성하는 도구입니다","es":"Excalidraw es una herramienta de generación de diagramas de arquitectura que analiza el código y crea archivos .excalidraw","fr":"Excalidraw est un outil de génération de diagrammes d''architecture qui analyse le code et crée des fichiers .excalidraw","de":"Excalidraw ist ein Tool zur Generierung von Architekturdiagrammen, das den Code analysiert und .excalidraw-Dateien erstellt","pt":"Excalidraw é uma ferramenta de geração de diagramas de arquitetura que usa análise de código para criar diagramas","ru":"ИИ Агент Excalidraw - это инструмент для генерации диаграмм архитектуры на основе анализа кода","ar":"إكسكالي درو هو أداة لإنشاء رسومات بنية النظام باستخدام تحليل الكود"},"features":{"en":["Generates architecture diagrams as .excalidraw files from codebase analysis","Identifies components, services, databases, and APIs","Maps relationships and dependencies between system components","Exports diagrams to PNG and SVG formats","Analyzes codebases in any language or framework"],"zh":["代码分析报告自动生成","支持PNG和SVG导出","识别组件、服务、数据库和API","支持多种语言和框架","Claude Code自定义插件"],"ja":["コード分析レポートの自動生成","PNGおよびSVGへのエクスポート","コンポーネント、サービス、データベース、APIの識別","複数の言語とフレームワークのサポート","Claude Codeのカスタムプラグイン"],"ko":["코드 분석 보고서 자동 생성","PNG 및 SVG로 내보내기","컴포넌트, 서비스, 데이터베이스 및 API 식별","여러 언어 및 프레임워크 지원","Claude Code 사용자 지정 플러그인"],"es":["Generación de diagramas de arquitectura como archivos .excalidraw","Análisis de código para identificar componentes y servicios","Exportación opcional a PNG y SVG","Compatibilidad con cualquier lenguaje y framework de programación","Identificación de relaciones y dependencias entre componentes"],"fr":["Génération de diagrammes d''architecture au format .excalidraw","Analyse de code pour identifier les composants et les services","Exportation facultative vers PNG et SVG","Compatibilité avec n''importe quel langage et framework de programmation","Identification des relations et des dépendances entre les composants"],"de":["Generierung von Architekturdiagrammen als .excalidraw-Dateien","Code-Analyse zur Identifizierung von Komponenten und Diensten","Optionale Exportmöglichkeit nach PNG und SVG","Kompatibilität mit jedem Programmiersprache und Framework","Identifizierung von Beziehungen und Abhängigkeiten zwischen Komponenten"],"pt":["Geração de diagramas de arquitetura a partir da análise do código","Identificação de componentes, serviços e bancos de dados","Exportação para PNG e SVG","Análise de código em qualquer linguagem ou framework","Mapeamento de relacionamentos entre componentes"],"ru":["Генерация диаграмм архитектуры на основе анализа кода","Идентификация компонентов, сервисов и баз данных","Экспорт в PNG и SVG","Анализ кода на любом языке или фреймворке","Отображение связей между компонентами"],"ar":["إنشاء رسومات بنية النظام من تحليل الكود","تحديد المكونات والخدمات وقواعد البيانات","تصدير إلى PNG وSVG","تحليل الكود بلغة أو إطار عمل معين","خريطة العلاقات بين المكونات"]},"keywords":{"en":["how to use excalidraw","excalidraw setup guide","excalidraw alternative","excalidraw vs graphviz","excalidraw install","what is excalidraw","excalidraw tutorial","excalidraw architecture diagram"],"zh":["Excalidraw","代码分析","架构图","Claude Code","自定义插件","AIエージェント","代码分析工具","架构图生成"],"ja":["Excalidraw","コード分析","アーキテクチャ図","Claude Code","カスタムプラグイン","AIエージェント","コード分析ツール","アーキテクチャ図生成"],"ko":["Excalidraw","코드 분석","아키텍처 다이어그램","Claude Code","사용자 지정 플러그인","AI 에이전트","코드 분석 도구","아키텍처 다이어그램 생성"],"es":["excalidraw","diagramas de arquitectura","generación de diagramas","análisis de código","exportación a PNG y SVG","herramientas de desarrollo","desarrollo de software","ingeniería de software"],"fr":["excalidraw","diagrammes d''architecture","génération de diagrammes","analyse de code","exportation vers PNG et SVG","outils de développement","développement de logiciels","ingénierie de logiciels"],"de":["excalidraw","Architekturdiagramme","Generierung von Diagrammen","Code-Analyse","Export nach PNG und SVG","Entwicklungstools","Software-Entwicklung","Software-Engineering"],"pt":["excalidraw","diagramas de arquitetura","análise de código","geração de diagramas","exportação para PNG","exportação para SVG","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент Excalidraw","диаграммы архитектуры","анализ кода","генерация диаграмм","экспорт в PNG","экспорт в SVG","разработка программного обеспечения","инструменты разработки"],"ar":["إكسكالي درو","رسومات بنية النظام","تحليل الكود","إنشاء رسومات","تصدير إلى PNG","تصدير إلى SVG","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ooiyeefei","repo":"ccc","repoPath":"ooiyeefei/ccc","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.285Z","topics":[],"category":"community","skillMd":{"name":"excalidraw","description":"Generate architecture diagrams as .excalidraw files from codebase analysis, with optional PNG/SVG export. Use when the user asks to create architecture diagrams, system diagrams, visualize codebase structure, generate excalidraw files, export excalidraw diagrams to PNG or SVG, or convert .excalidraw files to image formats.","bodyPreview":"# Excalidraw Diagram Generator\n\nGenerate architecture diagrams as `.excalidraw` files directly from codebase analysis, with optional export to PNG and SVG.\n\n---\n\n## Quick Start\n\n**User just asks:**\n```\n\"Generate an architecture diagram for this project\"\n\"Create an excalidraw diagram of the system\"\n\"Visualize this codebase as an excalidraw file\"\n```\n\n**Claude Code will:**\n1. Analyze the codebase (any language/framework)\n2. Identify components, services, databases, APIs\n3. Map relationships and da","body":"# Excalidraw Diagram Generator\n\nGenerate architecture diagrams as `.excalidraw` files directly from codebase analysis, with optional export to PNG and SVG.\n\n---\n\n## Quick Start\n\n**User just asks:**\n```\n\"Generate an architecture diagram for this project\"\n\"Create an excalidraw diagram of the system\"\n\"Visualize this codebase as an excalidraw file\"\n```\n\n**Claude Code will:**\n1. Analyze the codebase (any language/framework)\n2. Identify components, services, databases, APIs\n3. Map relationships and data flows\n4. Generate valid `.excalidraw` JSON with dynamic IDs and labels\n5. Optionally export to PNG and/or SVG using Playwright\n\n**No prerequisites:** Works without existing diagrams, Terraform, or specific file types.\n\n---\n\n## Critical Rules\n\n### 1. NEVER Use Diamond Shapes\n\nDiamond arrow connections are broken in raw Excalidraw JSON. Use styled rectangles instead:\n\n| Semantic Meaning | Rectangle Style |\n|------------------|-----------------|\n| Orchestrator/Hub | Coral (`#ffa8a8`/`#c92a2a`) + strokeWidth: 3 |\n| Decision Point | Orange (`#ffd8a8`/`#e8590c`) + dashed stroke |\n\n### 2. Labels Require TWO Elements\n\nThe `label` property does NOT work in raw JSON. Every labeled shape needs:\n\n```json\n// 1. Shape with boundElements reference\n{\n  \"id\": \"my-box\",\n  \"type\": \"rectangle\",\n  \"boundElements\": [{ \"type\": \"text\", \"id\": \"my-box-text\" }]\n}\n\n// 2. Separate text element with containerId\n{\n  \"id\": \"my-box-text\",\n  \"type\": \"text\",\n  \"containerId\": \"my-box\",\n  \"text\": \"My Label\"\n}\n```\n\n### 3. Elbow Arrows Need Three Properties\n\nFor 90-degree corners (not curved):\n\n```json\n{\n  \"type\": \"arrow\",\n  \"roughness\": 0,        // Clean lines\n  \"roundness\": null,     // Sharp corners\n  \"elbowed\": true        // 90-degree mode\n}\n```\n\n### 4. Arrow Edge Calculations\n\nArrows must start/end at shape edges, not centers:\n\n| Edge | Formula |\n|------|---------|\n| Top | `(x + width/2, y)` |\n| Bottom | `(x + width/2, y + height)` |\n| Left | `(x, y + height/2)` |\n| Right | `(x + width, y + height/2)` |\n\n**Detailed arrow routing:** See `references/arrows.md`\n\n---\n\n## Element Types\n\n| Type | Use For |\n|------|---------|\n| `rectangle` | Services, databases, containers, orchestrators |\n| `ellipse` | Users, external systems, start/end points |\n| `text` | Labels inside shapes, titles, annotations |\n| `arrow` | Data flow, connections, dependencies |\n| `line` | Grouping boundaries, separators |\n\n**Full JSON format:** See `references/json-format.md`\n\n---\n\n## Workflow\n\n### Step 1: Analyze Codebase\n\nDiscover components by looking for:\n\n| Codebase Type | What to Look For |\n|---------------|------------------|\n| Monorepo | `packages/*/package.json`, workspace configs |\n| Microservices | `docker-compose.yml`, k8s manifests |\n| IaC | Terraform/Pulumi resource definitions |\n| Backend API | Route definitions, controllers, DB models |\n| Frontend | Component hierarchy, API calls |\n\n**Use tools:**\n- `Glob` → `**/package.json`, `**/Dockerfile`, `**/*.tf`\n- `Grep` → `app.get`, `@Controller`, `CREATE TABLE`\n- `Read` → README, config files, entry points\n\n### Step 2: Plan Layout\n\n**Vertical flow (most common):**\n```\nRow 1: Users/Entry points (y: 100)\nRow 2: Frontend/Gateway (y: 230)\nRow 3: Orchestration (y: 380)\nRow 4: Services (y: 530)\nRow 5: Data layer (y: 680)\n\nColumns: x = 100, 300, 500, 700, 900\nElement size: 160-200px x 80-90px\n```\n\n**Other patterns:** See `references/examples.md`\n\n### Step 3: Generate Elements\n\nFor each component:\n1. Create shape with unique `id`\n2. Add `boundElements` referencing text\n3. Create text with `containerId`\n4. Choose color based on type\n\n**Color palettes:** See `references/colors.md`\n\n### Step 4: Add Connections\n\nFor each relationship:\n1. Calculate source edge point\n2. Plan elbow route (avoid overlaps)\n3. Create arrow with `points` array\n4. Match stroke color to destination type\n\n**Arrow patterns:** See `references/arrows.md`\n\n### Step 5: Add Grouping (Optional)\n\nFor logical groupings:\n- Large transparent rectangle with `strokeStyle: \"dashed\"`\n- Standalone text label at top-left\n\n### Step 6: Validate and Write\n\nRun validation before writing. Save to `docs/` or user-specified path.\n\n**Validation checklist:** See `references/validation.md`\n\n### Step 7: Export to PNG/SVG (Optional)\n\nAfter writing the `.excalidraw` file, ask the user if they want PNG, SVG, or both exports.\n\nUses Playwright MCP tools and `@excalidraw/utils` to programmatically render the diagram — no manual upload to excalidraw.com needed.\n\n**Requires:** Playwright MCP tools (`browser_navigate`, `browser_run_code`, `browser_close`).\n\n**Full export procedure:** See `references/export.md`\n\n---\n\n## Quick Arrow Reference\n\n**Straight down:**\n```json\n{ \"points\": [[0, 0], [0, 110]], \"x\": 590, \"y\": 290 }\n```\n\n**L-shape (left then down):**\n```json\n{ \"points\": [[0, 0], [-325, 0], [-325, 125]], \"x\": 525, \"y\": 420 }\n```\n\n**U-turn (callback):**\n```json\n{ \"points\": [[0, 0], [50, 0], [50, -125], [20, -125]], \"x\": 710, \"y\": 440 }\n```\n\n**Arrow width/height** = bounding box of points:\n```\npoints [[0,0], [-440,0], [-440,70]] → width=440, height=70\n```\n\n**Multiple arrows from same edge** - stagger positions:\n```\n5 arrows: 20%, 35%, 50%, 65%, 80% across edge width\n```\n\n---\n\n## Default Color Palette\n\n| Component | Background | Stroke |\n|-----------|------------|--------|\n| Frontend | `#a5d8ff` | `#1971c2` |\n| Backend/API | `#d0bfff` | `#7048e8` |\n| Database | `#b2f2bb` | `#2f9e44` |\n| Storage | `#ffec99` | `#f08c00` |\n| AI/ML | `#e599f7` | `#9c36b5` |\n| External APIs | `#ffc9c9` | `#e03131` |\n| Orchestration | `#ffa8a8` | `#c92a2a` |\n| Message Queue | `#fff3bf` | `#fab005` |\n| Cache | `#ffe8cc` | `#fd7e14` |\n| Users | `#e7f5ff` | `#1971c2` |\n\n**Cloud-specific palettes:** See `references/colors.md`\n\n---\n\n## Quick Validation Checklist\n\nBefore writing file:\n- [ ] Every shape with label has boundElements + text element\n- [ ] Text elements have containerId matching shape\n- [ ] Multi-point arrows have `elbowed: true`, `roundness: null`\n- [ ] Arrow x,y = source shape edge point\n- [ ] Arrow final point offset reaches target edge\n- [ ] No diamond shapes\n- [ ] No duplicate IDs\n\n**Full validation algorithm:** See `references/validation.md`\n\n---\n\n## Common Issues\n\n| Issue | Fix |\n|-------|-----|\n| Labels don''t appear | Use TWO elements (shape + text), not `label` property |\n| Arrows curved | Add `elbowed: true`, `roundness: null`, `roughness: 0` |\n| Arrows floating | Calculate x,y from shape edge, not center |\n| Arrows overlapping | Stagger start positions across edge |\n\n**Detailed bug fixes:** See `references/validation.md`\n\n---\n\n## Reference Files\n\n| File | Contents |\n|------|----------|\n| `references/json-format.md` | Element types, required properties, text bindings |\n| `references/arrows.md` | Routing algorithm, patterns, bindings, staggering |\n| `references/colors.md` | Default, AWS, Azure, GCP, K8s palettes |\n| `references/examples.md` | Complete JSON examples, layout patterns |\n| `references/validation.md` | Checklists, validation algorithm, bug fixes |\n| `references/export.md` | PNG/SVG export procedure via Playwright |\n\n---\n\n## Output\n\n- **Location:** `docs/architecture/` or user-specified\n- **Filename:** Descriptive, e.g., `system-architecture.excalidraw`\n- **Exports (optional):** `system-architecture.svg` and/or `system-architecture.png` in same directory\n- **Testing:** Open `.excalidraw` in https://excalidraw.com or VS Code extension; `.svg` and `.png` can be viewed directly or embedded in documentation\n"},"lastSynced":"2026-03-08T02:00:56.597Z","agentAnalysis":{"suitability":{"en":"Perfect for Architecture Analysis Agents needing advanced diagram generation capabilities for codebase visualization.","zh":"非常适合需要高级图表生成功能以可视化代码库的架构分析代理。","ja":"コードベースの可視化のための高度なダイアグラム生成機能を必要とするアーキテクチャ分析エージェントに最適です。","ko":"코드베이스 시각화를 위한 고급 다이어그램 생성 기능이 필요한 아키텍처 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de arquitectura que necesitan capacidades avanzadas de generación de diagramas para la visualización del codebase.","fr":"Parfait pour les agents d''analyse d''architecture ayant besoin de capacités avancées de génération de diagrammes pour la visualisation du codebase.","de":"Perfekt für Architekturanalyse-Agents, die erweiterte Diagrammgenerierungsfunktionen für die Visualisierung des Codebase benötigen.","pt":"Perfeito para Agentes de Análise de Arquitetura que necessitam de capacidades avançadas de geração de diagramas para visualização de codebase.","ru":"Идеально подходит для агентов анализа архитектуры, которым требуются продвинутые возможности генерации диаграмм для визуализации кодовой базы.","ar":"مثالي للوكلاء تحليل الهيكل تحتاج إلى القدرات المتقدمة لتوليد الرسومات للرؤية код قاعدة."},"recommendation":{"en":"Empowers agents to generate architecture diagrams as .excalidraw files directly from codebase analysis, with optional export to PNG and SVG, mapping relationships and dependencies between components, services, and databases.","zh":"赋予代理直接从代码库分析生成架构图表作为 .excalidraw 文件的能力，并可选地导出为 PNG 和 SVG 文件，映射组件、服务和数据库之间的关系和依赖。","ja":"コードベース分析から直接アーキテクチャダイアグラムを .excalidraw ファイルとして生成するエージェントを可能にし、PNG および SVG へのオプションのエクスポートを提供し、コンポーネント、サービス、およびデータベース間の関係と依存関係をマッピングします。","ko":"에이전트가 코드베이스 분석에서 직접 아키텍처 다이어그램을 .excalidraw 파일로 생성할 수 있도록 하며, PNG 및 SVG로의 선택적 내보내기를 제공하여 구성 요소, 서비스 및 데이터베이스 간의 관계와 종속성을 매핑합니다.","es":"Habilita a los agentes a generar diagramas de arquitectura como archivos .excalidraw directamente desde el análisis del codebase, con exportación opcional a PNG y SVG, mapeando relaciones y dependencias entre componentes, servicios y bases de datos.","fr":"Permet aux agents de générer des diagrammes d''architecture sous forme de fichiers .excalidraw directement à partir de l''analyse du codebase, avec exportation facultative vers PNG et SVG, en cartographiant les relations et les dépendances entre les composants, les services et les bases de données.","de":"Ermöglicht es Agents, Architekturdiagramme als .excalidraw-Dateien direkt aus der Codebase-Analyse zu generieren, mit optionaler Exportmöglichkeit zu PNG und SVG, wobei Beziehungen und Abhängigkeiten zwischen Komponenten, Diensten und Datenbanken abgebildet werden.","pt":"Habilita os agentes a gerar diagramas de arquitetura como arquivos .excalidraw diretamente da análise da codebase, com exportação opcional para PNG e SVG, mapeando relacionamentos e dependências entre componentes, serviços e bancos de dados.","ru":"Наделяет агентов возможностью генерировать диаграммы архитектуры в виде файлов .excalidraw напрямую из анализа кодовой базы, с возможным экспортом в PNG и SVG, отображая отношения и зависимости между компонентами, сервисами и базами данных.","ar":"تمكين الوكلاء لتوليد رسومات الهيكل كما الملفات .excalidraw مباشرة من تحليل قاعدة الشفرة، مع الاستيراد الاختياري إلى PNG وSVG، وتحديد العلاقات والاعتماديات بين المكونات والخدمات وقواعد البيانات."},"useCases":{"en":["Generating architecture diagrams for codebase analysis","Visualizing system components and dependencies","Creating excalidraw files for project documentation"],"zh":["为代码库分析生成架构图表","可视化系统组件和依赖","为项目文档创建 excalidraw 文件"],"ja":["コードベース分析のためのアーキテクチャダイアグラムの生成","システムコンポーネントと依存関係の可視化","プロジェクトドキュメントのための excalidraw ファイルの作成"],"ko":["코드베이스 분석을 위한 아키텍처 다이어그램 생성","시스템 구성 요소 및 종속성 시각화","프로젝트 문서를 위한 excalidraw 파일 생성"],"es":["Generación de diagramas de arquitectura para el análisis del codebase","Visualización de componentes y dependencias del sistema","Creación de archivos excalidraw para la documentación de proyectos"],"fr":["Génération de diagrammes d''architecture pour l''analyse du codebase","Visualisation des composants et des dépendances du système","Création de fichiers excalidraw pour la documentation de projet"],"de":["Generierung von Architekturdiagrammen für die Codebase-Analyse","Visualisierung von Systemkomponenten und -abhängigkeiten","Erstellung von excalidraw-Dateien für die Projektdokumentation"],"pt":["Gerar diagramas de arquitetura para análise de codebase","Visualizar componentes do sistema e dependências","Criar arquivos excalidraw para documentação de projeto"],"ru":["Генерировать диаграммы архитектуры для анализа кодовой базы","Визуализировать компоненты системы и зависимости","Создавать файлы excalidraw для документации проекта"],"ar":["توليد رسومات الهيكل لتحليل قاعدة الشفرة","رؤية مكونات النظام والاعتماديات","إنشاء ملفات excalidraw لتوثيق المشروع"]},"limitations":{"en":["Requires codebase access for analysis","Limited to generating .excalidraw, PNG, and SVG files"],"zh":["需要代码库访问权限进行分析","仅限生成 .excalidraw、PNG 和 SVG 文件"],"ja":["分析のためにコードベースへのアクセスが必要",".excalidraw、PNG、SVG ファイルの生成のみ"],"ko":["분석을 위해 코드베이스 접근 권한이 필요",".excalidraw, PNG, SVG 파일 생성만 가능"],"es":["Requiere acceso al codebase para el análisis","Limitado a la generación de archivos .excalidraw, PNG y SVG"],"fr":["Nécessite un accès au codebase pour l''analyse","Limité à la génération de fichiers .excalidraw, PNG et SVG"],"de":["Benötigt Zugriff auf den Codebase für die Analyse","Begrenzt auf die Generierung von .excalidraw-, PNG- und SVG-Dateien"],"pt":["Requer acesso à codebase para análise","Limitado a gerar arquivos .excalidraw, PNG e SVG"],"ru":["Требует доступа к кодовой базе для анализа","Ограничен генерацией файлов .excalidraw, PNG и SVG"],"ar":["يتطلب الوصول إلى قاعدة الشفرة للتحليل","محدود بتوليد الملفات .excalidraw وPNG وSVG"]},"version":4},"contentHash":"a5e257e280fd877c31ce33c69c739ce40f11861c6008aa0a79f48652fbd622f5","qualityScore":54}');
