INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ooiyeefei/ccc/excalidraw', 'excalidraw', 'ooiyeefei', 'ccc', 'community', 'excalidraw ooiyeefei ccc community Excalidraw generates architecture diagrams as .excalidraw files from codebase analysis, benefiting developers and architects. It identifies components, services, and databases, mapping relationships and dependencies. Excalidraw是一种代码分析工具，可以生成架构图。支持多种语言和框架，能够识别组件、服务、数据库和API Excalidrawはコード分析ツールであり、アーキテクチャ図を生成します。複数の言語とフレームワークをサポートし、コンポーネント、サービス、データベース、APIを識別します Excalidraw는 코드 분석 도구로 아키텍처 다이어그램을 생성합니다. 여러 언어와 프레임워크를 지원하며 컴포넌트, 서비스, 데이터베이스 및 API를 식별할 수 있습니다 Excalidraw es una herramienta para generar diagramas de arquitectura como archivos .excalidraw. Analiza el código y identifica componentes y servicios. Excalidraw est un outil pour générer des diagrammes d''architecture au format .excalidraw. Il analyse le code et identifie les composants et les services. Excalidraw ist ein Tool zur Generierung von Architekturdiagrammen als .excalidraw-Dateien. Es analysiert den Code und identifiziert Komponenten und Dienste. O Excalidraw é uma ferramenta de geração de diagramas de arquitetura que analisa o código e identifica componentes, serviços e bancos de dados ИИ Агент Excalidraw - это инструмент для генерации диаграмм архитектуры, который анализирует код и идентифицирует компоненты, сервисы и базы данных إكسكالي درو هو أداة لإنشاء رسومات بنية النظام التي تحلل الكود وتحدد المكونات والخدمات وقواعد البيانات how to use excalidraw excalidraw setup guide excalidraw alternative excalidraw vs graphviz excalidraw install what is excalidraw excalidraw tutorial excalidraw architecture diagram Excalidraw 代码分析 架构图 Claude Code 自定义插件 AIエージェント 代码分析工具 架构图生成 Generates architecture diagrams as .excalidraw files from codebase analysis Identifies components, services, databases, and APIs Maps relationships and dependencies between system components Exports diagrams to PNG and SVG formats Analyzes codebases in any language or framework Excalidraw is a diagram generator that creates architecture diagrams as .excalidraw files directly from codebase analysis, with optional export to PNG and SVG.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lee-to/ai-factory/ai-factory.review', 'community', 'lee-to', 'ai-factory', 'lee-to/ai-factory', 'ai-factory.review', 0, 0, 54, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:58.426Z', '572f2fa2d2de7dbf264e1261641ef2d694da44e16e33414e8ad764c72365d871', '{"id":"lee-to/ai-factory/ai-factory.review","name":"ai-factory.review","description":{"en":"ai-factory.review is a code review assistant that analyzes staged and unstaged changes using git diff, focusing on correctness, security, and performance, benefiting developers and teams.","zh":"ai-factory.review 是一个代码审查助手，能够自动检查代码的正确性、安全性、性能和可维护性","ja":"ai-factory.review はコードレビューを支援するツールで、正確性、セキュリティ、パフォーマンス、メンテナンス性をチェック","ko":"ai-factory.review는 코드 리뷰를 지원하는 도구로, 코드의 정확성, 보안, 성능, 유지 보수성을 확인합니다","es":"ai-factory.review es una herramienta de revisión de código que analiza la corrección, seguridad, rendimiento y mantenibilidad del código","fr":"ai-factory.review est un outil de revue de code qui analyse la correction, la sécurité, les performances et la maintenabilité du code","de":"ai-factory.review ist ein Code-Review-Tool, das die Korrektheit, Sicherheit, Leistung und Wartbarkeit des Codes analysiert","pt":"O ai-factory.review é uma ferramenta de revisão de código que analisa alterações de código para garantir correção, segurança e desempenho","ru":"ai-factory.review - это инструмент для ревью кода, анализирующий изменения кода для обеспечения корректности, безопасности и производительности","ar":"ai-factory.review هو أداة مراجعة الكود التي تحلل التعديلات على الكود لضمان الدقة والأمان والأداء"},"seo":{"title":{"en":"ai-factory.review: Automated Code Review Setup Guide | AI...","zh":"AI工厂代码审查助手 Setup Guide","ja":"AIエージェントのコードレビュー ベストプラクティス","ko":"AI 팩토리 코드 리뷰 가이드","es":"Guía de configuración de ai-factory.review para revisión ...","fr":"Guide de configuration d''ai-factory.review pour la revue ...","de":"Konfigurationsleitfaden für ai-factory.review zur Code-Üb...","pt":"Guia de Configuração do ai-factory.review: Ferramenta de ...","ru":"Настройка ai-factory.review: Инструмент для ревью кода","ar":"دليل إعداد ai-factory.review: أداة مراجعة الكود"},"description":{"en":"Discover how ai-factory.review simplifies code review with git diff and GitHub PR analysis - try it now and streamline your development workflow!","zh":"使用AI工厂代码审查助手来提高代码质量，确保安全性、性能和可维护性","ja":"AIエージェントを使用してコードをレビューし、品質を向上させる","ko":"AI 팩토리 코드 리뷰를 통해 코드 품질을 높이고 보안, 성능, 유지 보수성을 개선하세요","es":"Aprende a utilizar ai-factory.review para revisar tu código de manera efectiva y mejorar la calidad de tus proyectos","fr":"Découvrez comment utiliser ai-factory.review pour examiner votre code de manière efficace et améliorer la qualité de vos projets","de":"Erfahren Sie, wie Sie ai-factory.review verwenden, um Ihren Code effektiv zu überprüfen und die Qualität Ihrer Projekte zu verbessern","pt":"Aprenda a configurar o ai-factory.review para revisar código com foco em correção, segurança e desempenho","ru":"Узнайте, как настроить ai-factory.review для ревью кода с фокусом на корректности, безопасности и производительности","ar":"تعلم كيفية إعداد ai-factory.review لمراجعة الكود مع التركيز على الدقة والأمان والأداء"},"definition":{"en":"ai-factory.review is a code review tool that performs thorough analysis of Git changes, including staged and unstaged changes, using commands like git diff --cached and gh pr view.","zh":"ai-factory.review 是一种AI驱动的代码审查工具","ja":"ai-factory.review はAI駆動のコードレビューツール","ko":"ai-factory.review는 AI 기반 코드 리뷰 도구입니다","es":"ai-factory.review es un agente de IA para la revisión de código que utiliza Git y GitHub para analizar cambios","fr":"ai-factory.review est un agent IA pour la revue de code qui utilise Git et GitHub pour analyser les modifications","de":"ai-factory.review ist ein AI-Agent für die Code-Überprüfung, der Git und GitHub verwendet, um Änderungen zu analysieren","pt":"O que é ai-factory.review? É uma ferramenta de revisão de código automatizada","ru":"Что такое ai-factory.review? Это автоматизированный инструмент для ревью кода","ar":"ما هو ai-factory.review؟ هو أداة مراجعة الكود الآلية"},"features":{"en":["Runs git diff --cached to analyze staged changes","Uses gh pr view to retrieve PR details and gh pr diff for PR changes","Analyzes each file''s changes for correctness, security, and performance","Reviews all changes in a GitHub PR","Performs thorough code reviews focusing on maintainability"],"zh":["支持git diff和git diff --cached命令","能够分析代码变更并提供审查报告","支持PR号/URL审查","使用gh pr view和gh pr diff命令获取PR详细信息","能够检查代码的正确性、安全性、性能和可维护性"],"ja":["git diffおよびgit diff --cachedコマンドをサポート","コードの変更を分析し、レビューレポートを提供","PR番号/URLのレビューをサポート","gh pr viewおよびgh pr diffコマンドを使用してPRの詳細情報を取得","コードの正確性、セキュリティ、パフォーマンス、メンテナンス性をチェック"],"ko":["git diff 및 git diff --cached 명령어 지원","코드 변경 사항 분석 및 리뷰 보고서 제공","PR 번호/URL 리뷰 지원","gh pr view 및 gh pr diff 명령어를 사용하여 PR 상세 정보 가져오기","코드의 정확성, 보안, 성능, 유지 보수성을 확인"],"es":["Análisis de cambios con git diff","Revisión de solicitudes de extracción con gh pr view","Análisis de seguridad y rendimiento del código","Comprobación de la corrección y mantenibilidad del código","Integración con GitHub para la revisión de código","Soporte para la revisión de código en línea y fuera de línea"],"fr":["Analyse des modifications avec git diff","Examen des demandes d''extraction avec gh pr view","Analyse de la sécurité et des performances du code","Vérification de la correction et de la maintenabilité du code","Intégration avec GitHub pour la revue de code","Prise en charge de la revue de code en ligne et hors ligne"],"de":["Analyse von Änderungen mit git diff","Überprüfung von Pull-Request mit gh pr view","Analyse der Sicherheit und Leistung des Codes","Überprüfung der Korrektheit und Wartbarkeit des Codes","Integration mit GitHub für die Code-Überprüfung","Unterstützung für die Code-Überprüfung online und offline"],"pt":["Análise de alterações de código com git diff","Revisão de código com foco em correção, segurança e desempenho","Integração com GitHub para revisar pull requests","Suporte a revisão de código em diferentes linguagens","Análise de código com checklist de revisão"],"ru":["Анализ изменений кода с помощью git diff","Ревью кода с фокусом на корректности, безопасности и производительности","Интеграция с GitHub для ревью pull requests","Поддержка ревью кода на разных языках","Анализ кода с помощью чек-листа ревью"],"ar":["تحليل التعديلات على الكود مع git diff","مراجعة الكود مع التركيز على الدقة والأمان والأداء","التكامل مع GitHub لمراجعة طلبات السحب","دعم مراجعة الكود في لغات مختلفة","تحليل الكود مع قائمة مراجعة"]},"keywords":{"en":["how to use ai-factory.review","ai-factory.review alternative","ai-factory.review setup guide","what is ai-factory.review","ai-factory.review vs code review tools","git diff code review","GitHub PR analysis tool","automated code review with ai-factory.review","ai-factory.review install"],"zh":["AI代码审查","代码审查工具","git diff","代码质量","代码安全","代码性能","代码维护性","AI工厂代码审查助手"],"ja":["AIコードレビュー","コードレビューツール","git diff","コード品質","コードセキュリティ","コードパフォーマンス","コードメンテナンス性","AIエージェントのコードレビュー"],"ko":["AI 코드 리뷰","코드 리뷰 도구","git diff","코드 품질","코드 보안","코드 성능","코드 유지 보수성","AI 팩토리 코드 리뷰 가이드"],"es":["ai-factory.review","revisión de código","agente de IA","Git","GitHub","seguridad del código","rendimiento del código","mantenimiento del código","desarrollo de software","herramientas de desarrollo"],"fr":["ai-factory.review","revue de code","agent IA","Git","GitHub","sécurité du code","performances du code","maintenabilité du code","développement de logiciels","outils de développement"],"de":["ai-factory.review","Code-Überprüfung","AI-Agent","Git","GitHub","Sicherheit des Codes","Leistung des Codes","Wartbarkeit des Codes","Software-Entwicklung","Entwicklungstools"],"pt":["revisão de código","ferramenta de revisão de código","ai-factory.review","git diff","revisão de código automatizada","desenvolvimento de software","segurança de código","produção de código"],"ru":["ревью кода","инструмент для ревью кода","ai-factory.review","git diff","автоматизированное ревью кода","разработка программного обеспечения","безопасность кода","производительность кода"],"ar":["مراجعة الكود","أداة مراجعة الكود","ai-factory.review","git diff","مراجعة الكود الآلية","تطوير البرمجيات","أمان الكود","إنتاجية الكود"]}},"owner":"lee-to","repo":"ai-factory","repoPath":"lee-to/ai-factory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"ai-factory.review","description":"Perform code review on staged changes or a pull request. Checks for bugs, security issues, performance problems, and best practices. Use when user says review code, check my code, review PR, or is this code okay.","bodyPreview":"# Code Review Assistant\n\nPerform thorough code reviews focusing on correctness, security, performance, and maintainability.\n\n## Behavior\n\n### Without Arguments (Review Staged Changes)\n\n1. Run `git diff --cached` to get staged changes\n2. If nothing staged, run `git diff` for unstaged changes\n3. Analyze each file''s changes\n\n### With PR Number/URL\n\n1. Use `gh pr view <number> --json` to get PR details\n2. Use `gh pr diff <number>` to get the diff\n3. Review all changes in the PR\n\n## Review Checklist","body":"# Code Review Assistant\n\nPerform thorough code reviews focusing on correctness, security, performance, and maintainability.\n\n## Behavior\n\n### Without Arguments (Review Staged Changes)\n\n1. Run `git diff --cached` to get staged changes\n2. If nothing staged, run `git diff` for unstaged changes\n3. Analyze each file''s changes\n\n### With PR Number/URL\n\n1. Use `gh pr view <number> --json` to get PR details\n2. Use `gh pr diff <number>` to get the diff\n3. Review all changes in the PR\n\n## Review Checklist\n\n### Correctness\n- [ ] Logic errors or bugs\n- [ ] Edge cases handling\n- [ ] Null/undefined checks\n- [ ] Error handling completeness\n- [ ] Type safety (if applicable)\n\n### Security\n- [ ] SQL injection vulnerabilities\n- [ ] XSS vulnerabilities\n- [ ] Command injection\n- [ ] Sensitive data exposure\n- [ ] Authentication/authorization issues\n- [ ] CSRF protection\n- [ ] Input validation\n\n### Performance\n- [ ] N+1 query problems\n- [ ] Unnecessary re-renders (React)\n- [ ] Memory leaks\n- [ ] Inefficient algorithms\n- [ ] Missing indexes (database)\n- [ ] Large payload sizes\n\n### Best Practices\n- [ ] Code duplication\n- [ ] Dead code\n- [ ] Magic numbers/strings\n- [ ] Proper naming conventions\n- [ ] SOLID principles\n- [ ] DRY principle\n\n### Testing\n- [ ] Test coverage for new code\n- [ ] Edge cases tested\n- [ ] Mocking appropriateness\n\n## Output Format\n\n```markdown\n## Code Review Summary\n\n**Files Reviewed:** [count]\n**Risk Level:** 🟢 Low / 🟡 Medium / 🔴 High\n\n### Critical Issues\n[Must be fixed before merge]\n\n### Suggestions\n[Nice to have improvements]\n\n### Questions\n[Clarifications needed]\n\n### Positive Notes\n[Good patterns observed]\n```\n\n## Review Style\n\n- Be constructive, not critical\n- Explain the \"why\" behind suggestions\n- Provide code examples when helpful\n- Acknowledge good code\n- Prioritize feedback by importance\n- Ask questions instead of making assumptions\n\n## Examples\n\n**User:** `/ai-factory.review`\nReview staged changes in current repository.\n\n**User:** `/ai-factory.review 123`\nReview PR #123 using GitHub CLI.\n\n**User:** `/ai-factory.review https://github.com/org/repo/pull/123`\nReview PR from URL.\n\n## Integration\n\nIf GitHub MCP is configured, can:\n- Post review comments directly to PR\n- Request changes or approve\n- Add labels based on review outcome\n\n> **Tip:** Context is heavy after code review. Consider `/clear` or `/compact` before continuing with other tasks.\n"},"lastSynced":"2026-03-08T02:00:58.426Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced git diff analysis and comprehensive content review capabilities.","zh":"非常适合需要高级git diff分析和全面内容审查功能的代码审查代理。","ja":"コードレビューエージェントが高度なgit diff分析と包括的なコンテンツレビューキャパビリティを必要とする場合に最適です。","ko":"고급 git diff 분석 및 종합적인 콘텐츠 리뷰 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan un análisis avanzado de git diff y capacidades de revisión de contenido comprehensivas.","fr":"Parfait pour les agents de révision de code nécessitant une analyse avancée de git diff et des capacités de révision de contenu complètes.","de":"Perfekt für Code-Review-Agenten, die eine erweiterte git diff-Analyse und umfassende Inhaltsüberprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise avançada de git diff e capacidades de revisão de conteúdo abrangentes.","ru":"Идеально подходит для агентов проверки кода, которым требуются расширенный анализ git diff и всесторонние возможности проверки контента.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى تحليل متقدم ل-git diff وقدرات مراجعة المحتوى الشاملة."},"recommendation":{"en":"Empowers agents to analyze staged and unstaged changes using git diff, focusing on correctness, security, and performance, while utilizing GitHub PR APIs for thorough code reviews, providing maintainability and security benefits.","zh":"赋予代理分析暂存和未暂存的更改，使用git diff，注重正确性、安全性和性能，同时利用GitHub PR API进行彻底的代码审查，提供可维护性和安全性优势。","ja":"エージェントがステージ済みおよびステージされていない変更を分析し、git diffを使用して正確性、セキュリティ、パフォーマンスに焦点を当て、GitHub PR APIを使用して包括的なコードレビューを実施し、保守性およびセキュリティの利点を提供します。","ko":"에이전트가 스테이징된 변경과 스테이징되지 않은 변경을 분석하고 git diff를 사용하여 정확성, 보안, 성능에 초점을 맞추고 GitHub PR API를 사용하여 철저한 코드 리뷰를 제공하여 유지 보수성 및 보안 이점을 제공합니다.","es":"Habilita a los agentes a analizar cambios preparados y no preparados utilizando git diff, centrándose en la corrección, la seguridad y el rendimiento, mientras utiliza las API de GitHub PR para revisiones de código exhaustivas, proporcionando beneficios de mantenibilidad y seguridad.","fr":"Permet aux agents d''analyser les modifications préparées et non préparées à l''aide de git diff, en se concentrant sur la correction, la sécurité et les performances, tout en utilisant les API GitHub PR pour des révisions de code exhaustives, offrant des avantages en termes de maintenabilité et de sécurité.","de":"Ermächtigt Agenten, vorgemerkte und nicht vorgemerkte Änderungen mit git diff zu analysieren, wobei der Schwerpunkt auf Korrektheit, Sicherheit und Leistung liegt, während die GitHub-PR-APIs für umfassende Code-Reviews verwendet werden, um Wartbarkeits- und Sicherheitsvorteile zu bieten.","pt":"Permite que os agentes analisem alterações em estágio e não em estágio usando git diff, com foco em correção, segurança e desempenho, ao mesmo tempo em que utilizam as GitHub PR APIs para revisões de código abrangentes, proporcionando benefícios de manutenção e segurança.","ru":"Позволяет агентам анализировать зафиксированные и незафиксированные изменения с помощью git diff, сосредотачиваясь на правильности, безопасности и производительности, а также используя GitHub PR API для тщательных проверок кода, обеспечивая преимущества поддержки и безопасности.","ar":"يمكن للعميل تحليل التغييرات المرحلة وغير المرحلة باستخدام git diff ، مع التركيز على الدقة والأمان والأداء ، وفي الوقت نفسه استخدام GitHub PR APIs للتحقق الشامل من الكود ، وتوفير الفوائد من صيانة والأمان."},"useCases":{"en":["Automating code reviews for staged changes","Analyzing pull requests for security vulnerabilities","Debugging performance issues in unstaged code changes"],"zh":["为暂存的更改自动执行代码审查","分析拉取请求中的安全漏洞","调试未暂存的代码更改中的性能问题"],"ja":["ステージ済みの変更のコードレビューを自動化する","プルリクエストのセキュリティ脆弱性を分析する","ステージされていないコード変更のパフォーマンスの問題をデバッグする"],"ko":["스테이징된 변경에 대한 코드 리뷰 자동화","풀 리퀘스트의 보안 취약점 분석","스테이징되지 않은 코드 변경의 성능 문제 디버깅"],"es":["Automatizar revisiones de código para cambios preparados","Analizar solicitudes de extracción para vulnerabilidades de seguridad","Depurar problemas de rendimiento en cambios de código no preparados"],"fr":["Automatiser les révisions de code pour les modifications préparées","Analyser les demandes d''extraction pour les vulnérabilités de sécurité","Déboguer les problèmes de performances dans les modifications de code non préparées"],"de":["Automatisieren von Code-Reviews für vorgemerkte Änderungen","Analyse von Pull-Requests auf Sicherheitsverletzungen","Fehlerbehebung bei Leistungsproblemen in nicht vorgemerkten Codeänderungen"],"pt":["Automatizar revisões de código para alterações em estágio","Analisar solicitações de pull para vulnerabilidades de segurança","Depurar problemas de desempenho em alterações de código não em estágio"],"ru":["Автоматизировать проверку кода для зафиксированных изменений","Анализировать запросы на включение для уязвимостей безопасности","Отлаживать проблемы производительности в незафиксированных изменениях кода"],"ar":["توسيع مراجعة الكود الآلي للتغييرات المرحلة","تحليل طلبات السحب للثغرات الأمنية","تصحيح مشاكل الأداء في تغييرات الكود غير المرحلة"]},"limitations":{"en":["Requires git installation and configuration","Limited to GitHub PRs for external review","Needs access to git repository for analysis"],"zh":["需要git安装和配置","仅限于GitHub PRs进行外部审查","需要访问git存储库进行分析"],"ja":["gitのインストールと設定が必要","外部レビューはGitHub PRsに限定される","分析にはgitリポジトリへのアクセスが必要"],"ko":["git 설치 및 구성이 필요","외부 리뷰는 GitHub PRs로 제한","분석을 위해 git 저장소への 액세스가 필요"],"es":["Requiere instalación y configuración de git","Limitado a GitHub PR para revisión externa","Necesita acceso al repositorio de git para análisis"],"fr":["Nécessite l''installation et la configuration de git","Limité aux GitHub PR pour la révision externe","Nécessite l''accès au référentiel git pour l''analyse"],"de":["Benötigt git-Installation und -Konfiguration","Begrenzt auf GitHub-PR für externe Überprüfung","Benötigt Zugriff auf das git-Repository für die Analyse"],"pt":["Exige instalação e configuração do git","Limitado a PRs do GitHub para revisão externa","Necessita de acesso ao repositório git para análise"],"ru":["Требует установки и настройки git","Ограничен GitHub PR для внешней проверки","Требует доступа к репозиторию git для анализа"],"ar":["يتطلب تثبيت وتكوين git","محدود ل-PRs GitHub لمراجعة خارجية","يحتاج إلى الوصول إلى مستودع git للتحليل"]},"version":4},"contentHash":"572f2fa2d2de7dbf264e1261641ef2d694da44e16e33414e8ad764c72365d871","qualityScore":54}');
