INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lee-to/ai-factory/ai-factory.review', 'ai-factory.review', 'lee-to', 'ai-factory', 'community', 'ai-factory.review lee-to ai-factory community ai-factory.review is a code review assistant that analyzes staged and unstaged changes using git diff, focusing on correctness, security, and performance, benefiting developers and teams. ai-factory.review 是一个代码审查助手，能够自动检查代码的正确性、安全性、性能和可维护性 ai-factory.review はコードレビューを支援するツールで、正確性、セキュリティ、パフォーマンス、メンテナンス性をチェック ai-factory.review는 코드 리뷰를 지원하는 도구로, 코드의 정확성, 보안, 성능, 유지 보수성을 확인합니다 ai-factory.review es una herramienta de revisión de código que analiza la corrección, seguridad, rendimiento y mantenibilidad del código ai-factory.review est un outil de revue de code qui analyse la correction, la sécurité, les performances et la maintenabilité du code ai-factory.review ist ein Code-Review-Tool, das die Korrektheit, Sicherheit, Leistung und Wartbarkeit des Codes analysiert O ai-factory.review é uma ferramenta de revisão de código que analisa alterações de código para garantir correção, segurança e desempenho ai-factory.review - это инструмент для ревью кода, анализирующий изменения кода для обеспечения корректности, безопасности и производительности ai-factory.review هو أداة مراجعة الكود التي تحلل التعديلات على الكود لضمان الدقة والأمان والأداء how to use ai-factory.review ai-factory.review alternative ai-factory.review setup guide what is ai-factory.review ai-factory.review vs code review tools git diff code review GitHub PR analysis tool automated code review with ai-factory.review ai-factory.review install AI代码审查 代码审查工具 git diff 代码质量 代码安全 代码性能 代码维护性 AI工厂代码审查助手 Runs git diff --cached to analyze staged changes Uses gh pr view to retrieve PR details and gh pr diff for PR changes Analyzes each file''s changes for correctness, security, and performance Reviews all changes in a GitHub PR Performs thorough code reviews focusing on maintainability ai-factory.review is a code review tool that performs thorough analysis of Git changes, including staged and unstaged changes, using commands like git diff --cached and gh pr view.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flowglad/flowglad/pm', 'community', 'flowglad', 'flowglad', 'flowglad/flowglad', 'pm', 0, 0, 54, '2026-03-08T01:57:15.291Z', '2026-03-08T02:01:02.604Z', 'c7e7fe7d141d659a1e626ad3daa593f2596f30f4e2b2b4768ea4e6b96fdac745', '{"id":"flowglad/flowglad/pm","name":"pm","description":{"en":"The pm skill is an open-source, zero webhooks payment provider that enables seamless payment processing. It benefits developers and businesses looking for a straightforward payment solution.","zh":"pm 是一个开源的零 webhook 支付提供者，能够简化支付流程","ja":"pm はオープンソースのウェブフック不要の決済プロバイダーであり、決済プロセスを簡素化する","ko":"pm은 오픈소스의 웹후크 없는 결제 제공자로 결제 과정을 단순화합니다","es":"pm es un proveedor de pagos de código abierto y sin webhooks. Ofrece una solución de pago flexible y personalizable","fr":"pm est un fournisseur de paiement open source et sans webhooks. Il propose une solution de paiement flexible et personnalisable","de":"pm ist ein Open-Source-Zahlungsanbieter ohne Webhooks. Es bietet eine flexible und anpassbare Zahlungslösung","pt":"O pm é um provedor de pagamento de código aberto e sem webhooks, permitindo pagamentos mais seguros e eficientes","ru":"pm - это открытый поставщик платежей без вебхуков, обеспечивающий более безопасные и эффективные платежи","ar":"pm هو مزود للدفع مفتوح المصدر بدون ويب هوك، مما يسمح بالدفع أكثر أمانًا وفعالية"},"seo":{"title":{"en":"pm: Zero Webhooks Payment Provider Setup Guide | AI Agent...","zh":"pm Setup Guide: 零 webhook 支付提供者","ja":"pm セットアップガイド: ウェブフック不要のオープンソース決済プロバイダー","ko":"pm 설정 가이드: 웹후크 없는 오픈소스 결제 제공자","es":"Guía de configuración de pm: Proveedor de pagos de código...","fr":"Guide de configuration de pm: Fournisseur de paiement ope...","de":"pm-Konfigurationsleitfaden: Open-Source-Zahlungsanbieter","pt":"Configuração do pm: Guia de Pagamento sem Webhooks","ru":"Настройка pm: Руководство по оплате без вебхуков","ar":"إعداد pm: دليل الدفع بدون ويب هوك"},"description":{"en":"Discover how pm simplifies payment processing without webhooks. Learn how to integrate pm into your workflow and start accepting payments today!","zh":"了解如何使用 pm 实现零 webhook 支付，提高开发效率和安全性","ja":"pm を使用してウェブフック不要の決済を実現し、開発効率とセキュリティを高める方法を学ぶ","ko":"pm을 사용하여 웹후크 없는 결제를 구현하고 개발 효율 및 보안을 높이는 방법에 대해 알아보세요","es":"Aprende a configurar pm, un proveedor de pagos de código abierto y sin webhooks, para mejorar tus procesos de pago","fr":"Découvrez comment configurer pm, un fournisseur de paiement open source et sans webhooks, pour améliorer vos processus de paiement","de":"Erfahren Sie, wie Sie pm, einen Open-Source-Zahlungsanbieter ohne Webhooks, konfigurieren können, um Ihre Zahlungsprozesse zu verbessern","pt":"Descubra como configurar o pm, um provedor de pagamento de código aberto e sem webhooks, para melhorar suas operações de pagamento","ru":"Узнайте, как настроить pm, открытого поставщика платежей без вебхуков, чтобы улучшить ваши платежные операции","ar":"تعرف على كيفية إعداد pm، وهو مزود للدفع مفتوح المصدر بدون ويب هوك، لتحسين عمليات الدفع الخاصة بك"},"definition":{"en":"pm is an open-source payment provider that eliminates the need for webhooks, streamlining payment processing for developers and businesses.","zh":"pm 是一个开源的 Payments Manager，提供零 webhook 支付解决方案","ja":"pm はオープンソースの Payments Manager であり、ウェブフック不要の決済ソリューションを提供する","ko":"pm은 오픈소스의 Payments Manager로 웹후크 없는 결제 솔루션을 제공합니다","es":"pm es un proveedor de pagos de código abierto que permite pagos sin webhooks","fr":"pm est un fournisseur de paiement open source qui permet des paiements sans webhooks","de":"pm ist ein Open-Source-Zahlungsanbieter, der Zahlungen ohne Webhooks ermöglicht","pt":"O que é pm? Um provedor de pagamento de código aberto e sem webhooks para operações de pagamento mais seguras","ru":"Что такое pm? Открытый поставщик платежей без вебхуков для более безопасных платежных операций","ar":"ما هو pm؟ مزود للدفع مفتوح المصدر بدون ويب هوك للعمليات المالية أكثر أمانًا"},"features":{"en":["Integrates with Slack MCP for reading incident channel history","Generates comprehensive incident postmortem documents","Stores structured postmortems in Notion","Creates action items from incident discussions","Requires Slack MCP and Notion configuration"],"zh":["开源的零 webhook 支付解决方案","支持多种支付方式","简化支付流程","提高开发效率","增强安全性"],"ja":["オープンソースのウェブフック不要の決済ソリューション","複数の決済方法をサポート","決済プロセスを簡素化","開発効率を高める","セキュリティを強化"],"ko":["오픈소스의 웹후크 없는 결제 솔루션","다양한 결제 방법 지원","결제 과정을 단순화","개발 효율을 높임","보안성을 강화"],"es":["Proveedor de pagos de código abierto","Sin webhooks","Solución de pago flexible y personalizable","Integración con Slack para incidentes","Almacenamiento de postmortems estructurados en Notion"],"fr":["Fournisseur de paiement open source","Sans webhooks","Solution de paiement flexible et personnalisable","Intégration avec Slack pour les incidents","Stockage de postmortems structurés dans Notion"],"de":["Open-Source-Zahlungsanbieter","Ohne Webhooks","Flexible und anpassbare Zahlungslösung","Integration mit Slack für Incidents","Speicherung von strukturierten Postmortems in Notion"],"pt":["Pagamento sem webhooks","Código aberto para personalização","Integração com sistemas de pagamento existentes","Segurança de pagamento avançada","Facilidade de implementação"],"ru":["Платежи без вебхуков","Открытый код для кастомизации","Интеграция с существующими системами платежей","Продвинутая безопасность платежей","Легкость реализации"],"ar":["دفع بدون ويب هوك","كود مفتوح للتحويل","التكامل مع أنظمة الدفع الحالية","أمان الدفع المتقدم","سهولة التنفيذ"]},"keywords":{"en":["how to use pm payment provider","pm alternative to traditional payment gateways","pm vs stripe","pm install guide","pm setup for zero webhooks payment","what is pm payment provider","pm payment processing for developers","pm open-source payment solution"],"zh":["pm payments","零 webhook 支付","开源支付提供者","开发效率","安全性","支付解决方案","AIエージェント","Payments Manager"],"ja":["pm payments","ウェブフック不要の決済","オープンソース決済プロバイダー","開発効率","セキュリティ","決済ソリューション","AIエージェント","Payments Manager"],"ko":["pm payments","웹후크 없는 결제","오픈소스 결제 제공자","개발 효율","보안성","결제 솔루션","AI 에이전트","Payments Manager"],"es":["proveedores de pagos de código abierto","pagos sin webhooks","soluciones de pago personalizables","integración con Slack","Notion para postmortems","herramientas de pago para desarrolladores","pm proveedor de pagos","configuración de pm"],"fr":["fournisseurs de paiement open source","paiements sans webhooks","solutions de paiement personnalisables","intégration avec Slack","Notion pour les postmortems","outils de paiement pour les développeurs","pm fournisseur de paiement","configuration de pm"],"de":["Open-Source-Zahlungsanbieter","Zahlungen ohne Webhooks","flexible und anpassbare Zahlungslösungen","Integration mit Slack","Notion für Postmortems","Zahlungstools für Entwickler","pm-Zahlungsanbieter","Konfiguration von pm"],"pt":["pm pagamento","provedor de pagamento","código aberto","sem webhooks","pagamento seguro","integração de pagamento","personalização de pagamento","soluções de pagamento"],"ru":["pm платежи","поставщик платежей","открытый код","без вебхуков","безопасные платежи","интеграция платежей","кастомизация платежей","решения для платежей"],"ar":["pm دفع","مزود للدفع","كود مفتوح","دون ويب هوك","دفع آمن","تكامل الدفع","تحويل الدفع","حلول الدفع"]}},"owner":"flowglad","repo":"flowglad","repoPath":"flowglad/flowglad","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.291Z","topics":[],"category":"community","skillMd":{"name":"pm","description":"Create incident postmortems by reading Slack incident channels and creating structured postmortem documents in Notion. Use when conducting postmortem reviews or documenting incident responses.","bodyPreview":"# Incident Postmortem Generator\n\nCreate comprehensive incident postmortem documents by reading Slack incident channels and storing structured postmortems in Notion.\n\n## When to Use\n\n- After resolving a production incident\n- When conducting postmortem reviews\n- When documenting incident responses for team learning\n- To generate action items from incident discussions\n\n## Prerequisites\n\nThis skill requires the following MCP servers to be configured:\n- **Slack MCP** - For reading incident channel hi","body":"# Incident Postmortem Generator\n\nCreate comprehensive incident postmortem documents by reading Slack incident channels and storing structured postmortems in Notion.\n\n## When to Use\n\n- After resolving a production incident\n- When conducting postmortem reviews\n- When documenting incident responses for team learning\n- To generate action items from incident discussions\n\n## Prerequisites\n\nThis skill requires the following MCP servers to be configured:\n- **Slack MCP** - For reading incident channel history\n- **Notion MCP** - For creating postmortem documents in the Notes database\n\nOptional:\n- **Betterstack MCP** - For including telemetry and uptime links\n\n## Process\n\n### 1. Identify the Incident Channel\n\nAsk the user for the Slack channel name or ID. The channel should be the dedicated incident channel (typically named like `#incident-<name>` or `#inc-<date>-<description>`).\n\n### 2. Read Slack Channel History\n\nUse the Slack MCP to fetch the channel''s message history:\n\n```\nmcp__slack__slack_list_channels\n```\n\nFind the channel ID, then fetch history:\n\n```\nmcp__slack__slack_get_channel_history with channel_id\n```\n\nFor threaded discussions, also fetch thread replies:\n\n```\nmcp__slack__slack_get_thread_replies with channel_id and thread_ts\n```\n\nGet user information to resolve mentions:\n\n```\nmcp__slack__slack_get_users\n```\n\n### 3. Analyze the Incident\n\nFrom the Slack messages, extract:\n\n1. **Timeline**: Key events in chronological order\n   - When was the incident first detected?\n   - When was it acknowledged?\n   - What investigation steps were taken?\n   - When was it mitigated/resolved?\n\n2. **Root Cause**: The underlying technical issue\n   - What broke?\n   - Why did it break?\n   - What dependencies were involved?\n\n3. **Impact**: The effect on users/systems\n   - What services were affected?\n   - How many users impacted?\n   - What was the duration?\n\n4. **Open Questions**: Unresolved items from discussion\n   - Unclear technical details\n   - Areas needing further investigation\n   - Decisions that need to be made\n\n5. **Action Items**: Follow-up tasks with assignees\n   - Preventive measures\n   - Monitoring improvements\n   - Documentation updates\n   - Process changes\n\n### 4. Generate Postmortem Document\n\nCreate a markdown document following this structure:\n\n```markdown\n# Incident Postmortem: [Brief Title]\n\n**Date:** [Incident Date]\n**Severity:** [P0/P1/P2/P3]\n**Duration:** [Total incident duration]\n**Author:** [Person creating postmortem]\n\n## Summary\n\n[2-3 sentence summary of what happened and the impact]\n\n## Timeline\n\n| Time (UTC) | Event |\n|------------|-------|\n| HH:MM | Incident detected via [source] |\n| HH:MM | Team alerted |\n| HH:MM | Investigation began |\n| HH:MM | Root cause identified |\n| HH:MM | Mitigation deployed |\n| HH:MM | Incident resolved |\n\n## Impact\n\n- **Services Affected:** [List of affected services]\n- **Users Impacted:** [Number or percentage]\n- **Duration:** [How long users were affected]\n- **Data Loss:** [Yes/No, details if applicable]\n\n## Root Cause Analysis\n\n### What Happened\n\n[Detailed technical explanation of the failure]\n\n### Why It Happened\n\n[Contributing factors, systemic issues]\n\n### Detection\n\n[How was the incident discovered? Could we have detected it sooner?]\n\n## Telemetry & Monitoring\n\n[If Betterstack MCP is available, include relevant links]\n\n- **Uptime Dashboard:** [Link]\n- **Error Metrics:** [Link]\n- **Relevant Alerts:** [Link]\n\n## Open Questions\n\n- [ ] [Unresolved question 1]\n- [ ] [Unresolved question 2]\n\n## Action Items\n\n| Action | Assignee | Priority | Status |\n|--------|----------|----------|--------|\n| [Action description] | @[username] | High/Medium/Low | Open |\n| [Action description] | @[username] | High/Medium/Low | Open |\n\n## Lessons Learned\n\n### What Went Well\n\n- [Positive aspects of incident response]\n\n### What Could Be Improved\n\n- [Areas for improvement]\n\n## References\n\n- **Incident Channel:** #[channel-name]\n- **Related PRs:** [Links to fix PRs]\n- **Related Docs:** [Links to relevant documentation]\n```\n\n### 5. Create Notion Page\n\nUse the Notion MCP to create the postmortem in the Notes database:\n\nFirst, search for the Notes database:\n\n```\nmcp__claude_ai_Notion__notion-search with query: \"Notes\"\n```\n\nOr use the Notion skill:\n\n```\nSkill: notion-search with \"Notes database\"\n```\n\nThen create the page with the postmortem content:\n\n```\nmcp__claude_ai_Notion__notion-create-pages with:\n- parent: Notes database ID\n- title: \"Incident Postmortem: [Brief Title]\"\n- content: [Generated markdown content]\n```\n\n**Important:** Add the required tags to the page:\n- `eng`\n- `postmortem`\n\nIf the Notion MCP supports tags/properties, set them during creation. Otherwise, use the update page tool:\n\n```\nmcp__claude_ai_Notion__notion-update-page with:\n- page_id: [created page ID]\n- properties: { tags: [\"eng\", \"postmortem\"] }\n```\n\n### 6. Share Results\n\nAfter creating the postmortem:\n\n1. Provide the Notion page link to the user\n2. Optionally post a summary back to the Slack channel:\n\n```\nmcp__slack__slack_post_message with:\n- channel: [incident channel ID]\n- text: \"Postmortem document created: [Notion link]\"\n```\n\n## Tips for Quality Postmortems\n\n### Blameless Culture\n\n- Focus on systems and processes, not individuals\n- Use \"the system failed to...\" rather than \"person X failed to...\"\n- Treat failures as learning opportunities\n\n### Be Specific\n\n- Include exact timestamps when available\n- Reference specific commits, PRs, or deployments\n- Quantify impact with numbers when possible\n\n### Actionable Items\n\n- Each action item should be specific and achievable\n- Assign clear owners\n- Set priorities to help with planning\n\n### Capture Context\n\n- Include relevant Slack threads and discussions\n- Link to monitoring dashboards and alerts\n- Reference any related incidents\n\n## Output\n\nProvide to the user:\n\n1. **Summary** of what was extracted from Slack\n2. **Notion link** to the created postmortem\n3. **List of action items** for easy reference\n4. **Any gaps** that need manual filling (if information was missing from Slack)\n"},"lastSynced":"2026-03-08T02:01:02.604Z","agentAnalysis":{"suitability":{"en":"Perfect for Payment Processing Agents needing seamless payment integration via open-source, zero webhooks solutions.","zh":"非常适合需要通过开源、零Webhooks解决方案实现无缝支付集成的支付处理代理。","ja":"オープンソース、ゼロWebhooksソリューションを介して無縫な支払い統合を必要とする支払い処理エージェントに最適です。","ko":"오픈소스, 웹훅이 없는 솔루션을 통해 무결점 支払い 統合을 필요로 하는 支払い 처리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Procesamiento de Pagos que necesitan una integración de pago sin problemas a través de soluciones de código abierto y zero webhooks.","fr":"Parfait pour les Agents de Traitement de Paiement ayant besoin d''une intégration de paiement transparente via des solutions open-source et zero webhooks.","de":"Perfekt für Zahlungsverarbeitungsagenten, die eine nahtlose Zahlungsintegration über Open-Source-Lösungen und Zero-Webhooks-Lösungen benötigen.","pt":"Perfeito para Agentes de Processamento de Pagamento que necessitam de integração de pagamento sem interrupção via soluções de código aberto, sem webhooks.","ru":"Идеально подходит для агентов обработки платежей, которым необходима бесшовная интеграция платежей через открытые решения, не требующие веб-хуков.","ar":"مثالي لعمليات معالجة الدفع التي تحتاج إلى دمج الدفع بدون انقطاع عبر حلول مفتوحة المصدر ، بدون هوك ويب."},"recommendation":{"en":"Empowers agents to facilitate straightforward payment processing using Slack MCP for incident channel reading and Notion for storing structured postmortems, leveraging protocols like webhooks for efficient payment handling.","zh":"赋予代理商使用Slack MCP进行事件频道读取和使用Notion存储结构化事后总结的能力，利用像Webhooks这样的协议来高效处理支付，从而实现直接的支付处理。","ja":"Slack MCPを使用してインシデントチャンネルを読み取り、Notionを使用して構造化された事後分析を保存することで、エージェントが直接的な支払い処理を容易に行えるようにし、Webhooksなどのプロトコルを利用して効率的に支払いを処理します。","ko":"Slack MCP를 사용하여 인시던트 채널을 읽고 Notion을 사용하여 구조화된 사고 분석을 저장하여 에이전트가 직접적인 支払い 처리를 쉽게 수행할 수 있도록하며, Webhooksなどの 프로토콜을 사용하여 효율적으로 支払い 를 처리합니다.","es":"Habilita a los agentes a facilitar un procesamiento de pagos sencillo utilizando Slack MCP para la lectura del canal de incidentes y Notion para almacenar postmortems estructurados, aprovechando protocolos como webhooks para un manejo de pagos eficiente.","fr":"Permet aux agents de faciliter un traitement de paiement straightforward en utilisant Slack MCP pour la lecture du canal d''incident et Notion pour stocker des postmortems structurés, en exploitant des protocoles comme les webhooks pour un traitement de paiement efficace.","de":"Ermächtigt Agenten, ein einfaches Zahlungsverarbeitungssystem zu ermöglichen, indem Slack MCP für das Lesen des Vorfallkanals und Notion für das Speichern strukturierter Postmortems verwendet wird, wobei Protokolle wie Webhooks für eine effiziente Zahlungsabwicklung genutzt werden.","pt":"Permite que os agentes facilitem o processamento de pagamentos diretos usando Slack MCP para leitura de canais de incidentes e Notion para armazenar postmortems estruturados, aproveitando protocolos como webhooks para manipulação de pagamentos eficiente.","ru":"Наделяет агентов возможностью облегчить обработку платежей, используя Slack MCP для чтения каналов инцидентов и Notion для хранения структурированных постмортемов, используя протоколы, такие как веб-хуки, для эффективного xử lý платежей.","ar":"يمنح الوكلاء تسهيل معالجة الدفع المباشر باستخدام Slack MCP لقراءة قنوات الحوادث و Notion لتخزين ما بعد الحوادث الهيكلية ، واستخدام بروتوكولات مثل الويب هوك للتعامل الفعال مع الدفع."},"useCases":{"en":["Automating incident postmortem document creation","Generating action items from incident discussions in Slack","Documenting incident responses for team learning in Notion"],"zh":["自动创建事件事后总结文档","从Slack中的事件讨论中生成操作项","在Notion中记录事件响应以供团队学习"],"ja":["インシデント事後分析文書の自動作成","Slackでのインシデント議論からアクションアイテムを生成する","Notionにインシデント対応を記録してチームの学習に役立てる"],"ko":["인시던트 사고 분석 문서의 자동 생성","Slack의 인시던트 토론에서 액션 항목 생성","Notion에 인시던트 대응을 기록하여 팀의 학습에 활용"],"es":["Automatización de la creación de documentos de postmortem de incidentes","Generación de elementos de acción a partir de discusiones de incidentes en Slack","Documentación de respuestas a incidentes para el aprendizaje del equipo en Notion"],"fr":["Automatisation de la création de documents postmortem d''incident","Génération d''éléments d''action à partir de discussions d''incident sur Slack","Documentation des réponses aux incidents pour l''apprentissage de l''équipe sur Notion"],"de":["Automatisierung der Erstellung von Postmortem-Dokumenten für Vorfälle","Erzeugung von Aktionselementen aus Vorfallsdiskussionen in Slack","Dokumentation von Vorfallsantworten für das Teamlernen in Notion"],"pt":["Criação automática de documentos de postmortem de incidentes","Geração de itens de ação a partir de discussões de incidentes no Slack","Documentação de respostas de incidentes para aprendizado da equipe no Notion"],"ru":["Автоматическое создание документов постмортема инцидентов","Генерация элементов действий из обсуждений инцидентов в Slack","Документирование ответов на инциденты для обучения команды в Notion"],"ar":["إنشاء تلقائي لوثائق ما بعد الحوادث","توليد عناصر إجراء من المناقشات المتعلقة بالحوادث في Slack","توثيق استجابات الحوادث لتعلّم الفريق في Notion"]},"limitations":{"en":["Requires Slack MCP server configuration","Needs Notion for storing postmortems"],"zh":["需要Slack MCP服务器配置","需要Notion来存储事后总结"],"ja":["Slack MCPサーバーの設定が必要","事後分析を保存するためにNotionが必要"],"ko":["Slack MCP 서버 구성이 필요","사고 분석을 저장하기 위해 Notion이 필요"],"es":["Requiere configuración del servidor Slack MCP","Necesita Notion para almacenar postmortems"],"fr":["Nécessite une configuration du serveur Slack MCP","A besoin de Notion pour stocker des postmortems"],"de":["Benötigt Slack-MCP-Server-Konfiguration","Benötigt Notion zum Speichern von Postmortems"],"pt":["Requer configuração do servidor Slack MCP","Necessita Notion para armazenar postmortems"],"ru":["Требует настройки сервера Slack MCP","Требует Notion для хранения постмортемов"],"ar":["يتطلب تكوين خادم Slack MCP","يحتاج إلى Notion لتخزين ما بعد الحوادث"]},"version":4},"contentHash":"c7e7fe7d141d659a1e626ad3daa593f2596f30f4e2b2b4768ea4e6b96fdac745","qualityScore":54}');
