INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flowglad/flowglad/pm', 'pm', 'flowglad', 'flowglad', 'community', 'pm flowglad flowglad community The pm skill is an open-source, zero webhooks payment provider that enables seamless payment processing. It benefits developers and businesses looking for a straightforward payment solution. pm 是一个开源的零 webhook 支付提供者，能够简化支付流程 pm はオープンソースのウェブフック不要の決済プロバイダーであり、決済プロセスを簡素化する pm은 오픈소스의 웹후크 없는 결제 제공자로 결제 과정을 단순화합니다 pm es un proveedor de pagos de código abierto y sin webhooks. Ofrece una solución de pago flexible y personalizable pm est un fournisseur de paiement open source et sans webhooks. Il propose une solution de paiement flexible et personnalisable pm ist ein Open-Source-Zahlungsanbieter ohne Webhooks. Es bietet eine flexible und anpassbare Zahlungslösung O pm é um provedor de pagamento de código aberto e sem webhooks, permitindo pagamentos mais seguros e eficientes pm - это открытый поставщик платежей без вебхуков, обеспечивающий более безопасные и эффективные платежи pm هو مزود للدفع مفتوح المصدر بدون ويب هوك، مما يسمح بالدفع أكثر أمانًا وفعالية how to use pm payment provider pm alternative to traditional payment gateways pm vs stripe pm install guide pm setup for zero webhooks payment what is pm payment provider pm payment processing for developers pm open-source payment solution pm payments 零 webhook 支付 开源支付提供者 开发效率 安全性 支付解决方案 AIエージェント Payments Manager Integrates with Slack MCP for reading incident channel history Generates comprehensive incident postmortem documents Stores structured postmortems in Notion Creates action items from incident discussions Requires Slack MCP and Notion configuration pm is an open-source payment provider that eliminates the need for webhooks, streamlining payment processing for developers and businesses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rubys/showcase/compare-erb-js', 'community', 'rubys', 'showcase', 'rubys/showcase', 'compare-erb-js', 0, 0, 54, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:11.483Z', 'c19b9eebb9f8e3dd2b1d7a23e404d1f7c4cdc0939c71b68961722c3ce0b940ce', '{"id":"rubys/showcase/compare-erb-js","name":"compare-erb-js","description":{"en":"The compare-erb-js skill enables developers to compare ERB templates and their JavaScript-converted equivalents, ensuring matching output for offline scoring SPAs. It benefits developers working with auto-converted ERB templates.","zh":"compare-erb-js是用于比较ERB模板和JavaScript转换后的模板输出的工具，确保离线评分SPA的准确性","ja":"compare-erb-jsはERBテンプレートとJavaScriptに変換されたテンプレートの出力を比較するツールで、オフラインスコアリングSPAの精度を確保する","ko":"compare-erb-js는 ERB 템플릿과 JavaScript로 변환된 템플릿의 출력을 비교하여 오프라인 평가 SPA의 정확성을 보장하는 도구입니다","es":"Compare-erb-js es una herramienta para comparar la salida de plantillas ERB y JavaScript. Utiliza scripts/render_erb_and_js.rb para verificar la compatibilidad","fr":"Compare-erb-js est un outil pour comparer la sortie de modèles ERB et JavaScript. Utilisez scripts/render_erb_and_js.rb pour vérifier la compatibilité","de":"Compare-erb-js ist ein Tool zum Vergleich der Ausgabe von ERB- und JavaScript-Vorlagen. Verwenden Sie scripts/render_erb_and_js.rb, um die Kompatibilität zu überprüfen","pt":"O compare-erb-js é uma ferramenta para comparar saídas de templates ERB e JavaScript, usada em SPAs de pontuação offline","ru":"Compare-erb-js - это инструмент для сравнения вывода шаблонов ERB и JavaScript, используемый в автономных SPA","ar":"compare-erb-js هو أداة لمقارنة مخرجات قوالب ERB و JavaScript، تستخدم في تطبيقات الويب الحديثة"},"seo":{"title":{"en":"compare-erb-js: Template Comparison Setup Guide | AI Agen...","zh":"compare-erb-js 模板输出比较工具","ja":"compare-erb-js: ERBとJavaScriptテンプレートの出力比較","ko":"compare-erb-js: ERB와 JavaScript 템플릿 출력 비교 도구","es":"Guía de configuración de compare-erb-js para agentes de IA","fr":"Guide de mise en place de compare-erb-js pour les outils ...","de":"Einrichtungsleitfaden für compare-erb-js in KI-Agenten","pt":"Guia de Configuração do compare-erb-js para Desenvolvedores","ru":"Настройка сравнения ERB и JavaScript с помощью ИИ Агентов","ar":"دليل إعداد compare-erb-js لتقنيات الويب"},"description":{"en":"Unlock seamless template rendering with compare-erb-js. Learn how to verify ERB and JavaScript template output with our expert guide and optimize your workfl...","zh":"使用compare-erb-js工具比较ERB模板和JavaScript转换后的模板输出，确保离线评分SPA的准确性","ja":"compare-erb-jsを使用してERBテンプレートとJavaScriptに変換されたテンプレートの出力を比較し、オフラインスコアリングSPAの精度を確保する","ko":"compare-erb-js를 사용하여 ERB 템플릿과 JavaScript로 변환된 템플릿의 출력을 비교하여 오프라인 평가 SPA의 정확성을 보장합니다","es":"Aprenda a comparar plantillas ERB y JavaScript con compare-erb-js. Verifique la salida de las plantillas para una aplicación web de puntuación offline","fr":"Découvrez comment comparer des modèles ERB et JavaScript avec compare-erb-js. Vérifiez la sortie des modèles pour une application web de notation hors ligne","de":"Erfahren Sie, wie Sie ERB- und JavaScript-Vorlagen mit compare-erb-js vergleichen. Überprüfen Sie die Ausgabe der Vorlagen für eine Offline-Scoring-Webanwendung","pt":"Aprenda a usar o compare-erb-js para comparar saídas de templates ERB e JavaScript, essencial para SPAs de pontuação offline","ru":"Используйте compare-erb-js для сравнения вывода шаблонов ERB и JavaScript, необходимых для автономных SPA","ar":"تعرف على كيفية استخدام compare-erb-js لمقارنة مخرجات قوالب ERB و JavaScript، مما هو ضروري لتقنيات الويب الحديثة"},"definition":{"en":"compare-erb-js is a technical skill that compares ERB templates with their JavaScript-converted equivalents, verifying matching output for accurate rendering.","zh":"compare-erb-js是一种用于比较ERB模板和JavaScript转换后的模板输出的工具","ja":"compare-erb-jsはERBテンプレートとJavaScriptに変換されたテンプレートの出力を比較するツール","ko":"compare-erb-js는 ERB 템플릿과 JavaScript로 변환된 템플릿의 출력을 비교하는 도구","es":"Compare-erb-js es una herramienta de desarrollo que compara la salida de plantillas ERB y JavaScript","fr":"Compare-erb-js est un outil de développement qui compare la sortie de modèles ERB et JavaScript","de":"Compare-erb-js ist ein Entwicklungstool, das die Ausgabe von ERB- und JavaScript-Vorlagen vergleicht","pt":"O compare-erb-js é uma ferramenta de desenvolvimento que compara saídas de templates ERB e JavaScript","ru":"Compare-erb-js - это инструмент разработки, сравнивающий вывод шаблонов ERB и JavaScript","ar":"compare-erb-js هو أداة تطوير تقنيات الويب لمقارنة مخرجات قوالب ERB و JavaScript"},"features":{"en":["Compares ERB templates with JavaScript-converted equivalents using scripts/render_erb_and_js.rb","Verifies matching output for offline scoring SPAs","Supports rendering of heat lists and individual heats","Utilizes Ruby scripts for template comparison","Works with SQLite3 databases, such as db/2025-barcelona-november.sqlite3","Enables verification of template output using bundle exec ruby commands"],"zh":["支持ERB模板和JavaScript转换后的模板输出比较","使用Ruby脚本执行比较","支持离线评分SPA的准确性","提供命令行接口(CLI)执行比较","支持多个数据库文件比较"],"ja":["ERBテンプレートとJavaScriptに変換されたテンプレートの出力を比較する","Rubyスクリプトを使用して比較を実行する","オフラインスコアリングSPAの精度を確保する","コマンドラインインターフェース(CLI)を使用して比較を実行する","複数のデータベースファイルの比較をサポートする"],"ko":["ERB 템플릿과 JavaScript로 변환된 템플릿의 출력을 비교","Ruby 스크립트를 사용하여 비교를 수행","오프라인 평가 SPA의 정확성을 보장","명령줄 인터페이스(CLI)를 사용하여 비교를 수행","다중 데이터베이스 파일 비교를 지원"],"es":["Comparación de plantillas ERB y JavaScript","Uso de scripts/render_erb_and_js.rb para verificar la compatibilidad","Compatibilidad con aplicaciones web de puntuación offline","Soporte para bases de datos SQLite","Ejecución de comandos de Ruby para renderizar plantillas"],"fr":["Comparaison de modèles ERB et JavaScript","Utilisation de scripts/render_erb_and_js.rb pour vérifier la compatibilité","Compatibilité avec des applications web de notation hors ligne","Prise en charge des bases de données SQLite","Exécution de commandes Ruby pour renderiser des modèles"],"de":["Vergleich von ERB- und JavaScript-Vorlagen","Verwendung von scripts/render_erb_and_js.rb zur Überprüfung der Kompatibilität","Kompatibilität mit Offline-Scoring-Webanwendungen","Unterstützung für SQLite-Datenbanken","Ausführung von Ruby-Befehlen zum Rendern von Vorlagen"],"pt":["Compara saídas de templates ERB e JavaScript","Usa o script render_erb_and_js.rb para verificar a saída","Suporta comparação de listas de calor e calor individual","Executa em ambiente de desenvolvimento com Ruby","Integração com banco de dados SQLite"],"ru":["Сравнивает вывод шаблонов ERB и JavaScript","Использует скрипт render_erb_and_js.rb для проверки вывода","Поддерживает сравнение списков тепла и отдельных теплов","Выполняется в среде разработки с Ruby","Интегрируется с базой данных SQLite"],"ar":["مقارنة مخرجات قوالب ERB و JavaScript","استخدام سكريبت render_erb_and_js.rb لتحقق من المخرجات","دعم لمقارنة قوائم الحرارة والحرارة الفردية","التشغيل في بيئة تطوير باستخدام Ruby","التكامل مع قاعدة بيانات SQLite"]},"keywords":{"en":["how to use compare-erb-js","compare-erb-js setup guide","erb vs javascript template comparison","compare-erb-js alternative","compare-erb-js install","what is compare-erb-js","compare-erb-js template rendering","erb template comparison tool","javascript template verification"],"zh":["compare-erb-js","ERB模板","JavaScript模板","离线评分SPA","Ruby脚本","命令行接口","模板输出比较","AI工具","AIエージェント"],"ja":["compare-erb-js","ERBテンプレート","JavaScriptテンプレート","オフラインスコアリングSPA","Rubyスクリプト","コマンドラインインターフェース","テンプレート出力比較","AIツール","AIエージェント"],"ko":["compare-erb-js","ERB 템플릿","JavaScript 템플릿","오프라인 평가 SPA","Ruby 스크립트","명령줄 인터페이스","템플릿 출력 비교","AI 도구","AI 에이전트"],"es":["compare-erb-js","plantillas ERB","JavaScript","desarrollo web","aplicaciones web de puntuación offline","SQLite","Ruby","herramientas de desarrollo","agentes de IA"],"fr":["compare-erb-js","modèles ERB","JavaScript","développement web","applications web de notation hors ligne","SQLite","Ruby","outils de développement","outils d''IA"],"de":["compare-erb-js","ERB-Vorlagen","JavaScript","Webentwicklung","Offline-Scoring-Webanwendungen","SQLite","Ruby","Entwicklungstools","KI-Agenten"],"pt":["compare-erb-js","ERB templates","JavaScript templates","SPA de pontuação offline","desenvolvimento web","ferramentas de desenvolvimento","Ruby","SQLite","templates de marcação"],"ru":["compare-erb-js","шаблоны ERB","шаблоны JavaScript","автономные SPA","разработка веб-приложений","инструменты разработки","Ruby","SQLite","шаблоны разметки"],"ar":["compare-erb-js","قوالب ERB","قوالب JavaScript","تطبيقات الويب الحديثة","تطوير ويب","أدوات التطوير","Ruby","SQLite","قوالب ترميز"]}},"owner":"rubys","repo":"showcase","repoPath":"rubys/showcase","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"compare-erb-js","description":"Compare ERB and JavaScript template outputs for the offline scoring SPA. Use when working on ERB-to-JS conversion, debugging template parity issues, or verifying that changes to scoring views work correctly in both ERB and SPA modes.","bodyPreview":"# Compare ERB vs JavaScript Template Output\n\nUse `scripts/render_erb_and_js.rb` to verify that ERB templates and their JavaScript-converted equivalents produce matching output. This is essential for the offline scoring SPA which uses auto-converted ERB templates.\n\n## Basic Usage\n\n```bash\n# Compare heat list\nbundle exec ruby scripts/render_erb_and_js.rb db/2025-barcelona-november.sqlite3 83\n\n# Compare individual heat\nbundle exec ruby scripts/render_erb_and_js.rb db/2025-barcelona-november.sqlite3","body":"# Compare ERB vs JavaScript Template Output\n\nUse `scripts/render_erb_and_js.rb` to verify that ERB templates and their JavaScript-converted equivalents produce matching output. This is essential for the offline scoring SPA which uses auto-converted ERB templates.\n\n## Basic Usage\n\n```bash\n# Compare heat list\nbundle exec ruby scripts/render_erb_and_js.rb db/2025-barcelona-november.sqlite3 83\n\n# Compare individual heat\nbundle exec ruby scripts/render_erb_and_js.rb db/2025-barcelona-november.sqlite3 83 1\n\n# With style parameter\nbundle exec ruby scripts/render_erb_and_js.rb db/2025-barcelona-november.sqlite3 83 1 radio\n```\n\nOr using environment variable:\n```bash\nRAILS_APP_DB=2025-barcelona-november bundle exec ruby scripts/render_erb_and_js.rb 83 1\n```\n\n## What It Does\n\n1. Renders the ERB template via Rails routing (extracts `<main>` content)\n2. Fetches converted JavaScript templates from `/templates/scoring.js`\n3. Fetches normalized data from `/scores/:judge/heats/data`\n4. Hydrates the data using `heat_hydrator.js` (for individual heats)\n5. Renders using the JavaScript template\n6. Compares row counts and saves both outputs for diff analysis\n\n## Output Files\n\nAll files are saved to `/tmp/` for analysis:\n\n- `/tmp/erb_rendered.html` - ERB template output (main content only)\n- `/tmp/js_rendered.html` - JavaScript template output\n- `/tmp/scoring_templates.js` - Converted templates from `/templates/scoring.js`\n- `/tmp/heats_data.json` - Raw normalized data from server\n- `/tmp/js_template_data.json` - Hydrated data passed to JS template\n\n## Analyzing Differences\n\n```bash\n# Quick diff\ndiff /tmp/erb_rendered.html /tmp/js_rendered.html\n\n# Side-by-side comparison\ndiff -y /tmp/erb_rendered.html /tmp/js_rendered.html | less\n\n# Compare specific attributes\ndiff <(grep -o ''href=\"[^\"]*\"'' /tmp/erb_rendered.html | sort) \\\n     <(grep -o ''href=\"[^\"]*\"'' /tmp/js_rendered.html | sort)\n```\n\n## Common Differences\n\nSome differences are expected due to ERB-to-JS conversion limitations:\n\n- **HTML entity encoding**: ERB uses `&quot;` while JS uses `\"`\n- **link_to blocks**: Block form of `link_to` may render differently\n- **Whitespace**: Minor whitespace differences are normal\n\n## Architecture\n\nThis tool supports the \"Server computes, hydration joins, templates filter\" principle:\n\n- **Server**: Computes derived values and paths (respects RAILS_APP_SCOPE)\n- **Hydration**: `heat_hydrator.js` joins normalized data by resolving IDs\n- **Templates**: ERB and JS templates filter/format data identically\n\n## Key Source Files\n\n### Server-side (Rails)\n\n- `app/controllers/scores_controller.rb`\n  - `heats_data` action: Returns normalized JSON data for SPA\n  - `heat` action: Sets instance variables for ERB templates\n  - Computes `paths:` hash with server-computed URLs\n\n- `app/controllers/templates_controller.rb`\n  - `scoring` action: Converts ERB templates to JavaScript on-the-fly\n  - Defines path helper stubs for JS templates\n  - Uses `ErbPrismConverter` for conversion\n\n- `lib/erb_prism_converter.rb`\n  - Converts ERB templates to JavaScript functions using Ruby''s Prism parser\n  - Handles Ruby-to-JS translation (loops, conditionals, method calls)\n\n### Client-side (JavaScript)\n\n- `app/javascript/lib/heat_hydrator.js`\n  - `buildLookupTables()`: Creates Maps for O(1) entity lookup\n  - `hydrateHeat()`: Resolves IDs to full objects\n  - `buildHeatTemplateData()`: Prepares complete data for templates\n\n- `app/javascript/controllers/heat_app_controller.js`\n  - Main Stimulus controller for the offline scoring SPA\n  - Loads templates and data, handles navigation\n  - Manages offline/online state transitions\n\n### ERB Templates (source of truth)\n\n- `app/views/scores/heat.html.erb` - Main heat view\n- `app/views/scores/heatlist.html.erb` - Heat list view\n- `app/views/scores/_heat_header.html.erb` - Heat header partial\n- `app/views/scores/_info_box.html.erb` - Info box with feedback errors\n- `app/views/scores/_navigation_footer.html.erb` - Prev/next navigation\n- `app/views/scores/_table_heat.html.erb` - Standard heat table\n- `app/views/scores/_rank_heat.html.erb` - Finals ranking view\n- `app/views/scores/_solo_heat.html.erb` - Solo heat view\n- `app/views/scores/_cards_heat.html.erb` - Card-based scoring view\n\n### Scripts\n\n- `scripts/render_erb_and_js.rb` - This comparison tool\n- `scripts/hydrate_heats.mjs` - Node.js script for hydrating data (used by comparison tool)\n"},"lastSynced":"2026-03-08T02:01:11.483Z","agentAnalysis":{"suitability":{"en":"Perfect for Ruby-based AI Agents needing ERB template comparison and validation for offline scoring SPAs.","zh":"适合于需要ERB模板比较和验证的离线评分单页应用的Ruby-based AI Agents。","ja":"オフラインスコアリングSPAのERBテンプレートの比較と検証が必要なRubyベースのAIエージェントに最適です。","ko":"오프라인 스코어링 SPA의 ERB 템플릿 비교 및 검증이 필요한 Ruby 기반 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial basados en Ruby que necesitan comparación y validación de plantillas ERB para puntuación de SPAs sin conexión.","fr":"Parfait pour les agents d''intelligence artificielle basés sur Ruby nécessitant une comparaison et une validation de modèles ERB pour le scoring de SPAs hors ligne.","de":"Perfekt für Ruby-basierte KI-Agents, die ERB-Vorlagenvergleich und -validierung für Offline-Scoring von SPAs benötigen.","pt":"Perfeito para Agentes de IA baseados em Ruby que precisam de comparação e validação de modelos de template ERB para pontuação offline de SPAs.","ru":"Идеально подходит для агентов ИИ на основе Ruby, которым необходима сравнение и проверка шаблонов ERB для автономной оценки SPAs.","ar":"مثالي للوكلاء الذكيين قائم على روبي الذين يحتاجون إلى مقارنة وตรวจ صحة قوالب ERB للتصنيف بدون اتصال SPAs."},"recommendation":{"en":"Empowers agents to verify matching output between ERB templates and their JavaScript-converted equivalents using Ruby scripts like render_erb_and_js.rb, ensuring data consistency for auto-converted ERB templates in SQLite3 databases.","zh":"赋予代理人使用Ruby脚本（如render_erb_and_js.rb）验证ERB模板和其JavaScript转换等效物之间的匹配输出，确保自动转换的ERB模板在SQLite3数据库中的数据一致性。","ja":"エージェントがRubyスクリプト（例：render_erb_and_js.rb）を使用して、ERBテンプレートとそのJavaScriptへの変換の等価物間の出力の一致を検証できるようにし、SQLite3データベース内の自動変換されたERBテンプレートのデータ一貫性を確保します。","ko":"에이전트가 Ruby 스크립트(예: render_erb_and_js.rb)를 사용하여 ERB 템플릿과 해당 JavaScript로 변환된 등価物 간의 출력 일치를 검증할 수 있도록 하여, SQLite3 데이터베이스 내의 자동 변환된 ERB 템플릿의 데이터 일관성을 보장합니다.","es":"Habilita a los agentes a verificar la coincidencia de la salida entre plantillas ERB y sus equivalentes convertidos a JavaScript utilizando scripts de Ruby como render_erb_and_js.rb, garantizando la consistencia de los datos para plantillas ERB autoconvertidas en bases de datos SQLite3.","fr":"Permet aux agents de vérifier la correspondance de la sortie entre les modèles ERB et leurs équivalents convertis en JavaScript en utilisant des scripts Ruby tels que render_erb_and_js.rb, assurant ainsi la cohérence des données pour les modèles ERB auto-convertis dans les bases de données SQLite3.","de":"Ermöglicht es Agents, die Übereinstimmung der Ausgabe zwischen ERB-Vorlagen und ihren in JavaScript umgewandelten Äquivalenten zu überprüfen, indem Ruby-Skripte wie render_erb_and_js.rb verwendet werden, um somit die Datenkonsistenz für auto-umgewandelte ERB-Vorlagen in SQLite3-Datenbanken sicherzustellen.","pt":"Habilita os agentes a verificar a saída correspondente entre os modelos de template ERB e seus equivalentes convertidos para JavaScript usando scripts Ruby como render_erb_and_js.rb, garantindo a consistência dos dados para os modelos de template ERB convertidos automaticamente em bancos de dados SQLite3.","ru":"Наделяет агентов возможностью проверить соответствующую выходную информацию между шаблонами ERB и их эквивалентами, преобразованными в JavaScript, используя скрипты Ruby, такие как render_erb_and_js.rb, обеспечивая согласованность данных для автоматически преобразованных шаблонов ERB в базах данных SQLite3.","ar":"تمكّن الوكلاء من التحقق من الإخراج المطابق بين قوالب ERB ومقابلاتها المحوّلة إلى JavaScript باستخدام سكريبتات Ruby مثل render_erb_and_js.rb، مما يضمن συνέافة البيانات لقوالب ERB المحوّلة تلقائيًا في قواعد بيانات SQLite3."},"useCases":{"en":["Comparing heat list outputs","Validating individual heat renderings","Debugging ERB to JavaScript conversions"],"zh":["比较热度列表输出","验证单个热度渲染","调试ERB到JavaScript转换"],"ja":["ヒートリスト出力の比較","個々のヒートレンダリングの検証","ERBからJavaScriptへの変換のデバッグ"],"ko":["열 목록 출력 비교","개별 열 렌더링 검증","ERB에서 JavaScript로의 변환 디버깅"],"es":["Comparación de salidas de listas de calor","Validación de representaciones de calor individuales","Depuración de conversiones de ERB a JavaScript"],"fr":["Comparaison des sorties de listes de chaleur","Validation des rendus de chaleur individuels","Débogage des conversions de ERB en JavaScript"],"de":["Vergleich von Ausgaben von Hitzlisten","Validierung von einzelnen Hitzrendern","Fehlerbehebung bei Umwandlungen von ERB in JavaScript"],"pt":["Comparação de saídas de lista de calor","Validação de renderizações de calor individuais","Depuração de conversões de ERB para JavaScript"],"ru":["Сравнение выходных данных списка тепла","Проверка отдельных рендерингов тепла","Отладка преобразований ERB в JavaScript"],"ar":["مقارنة مخرجات قائمة الحرارة","تحقق من عروض الحرارة الفردية","تصحيح أخطاء تحويلات ERB إلى JavaScript"]},"limitations":{"en":["Requires Ruby environment","SQLite3 database access needed","Limited to ERB and JavaScript template comparisons"],"zh":["需要Ruby环境","需要SQLite3数据库访问","仅限ERB和JavaScript模板比较"],"ja":["Ruby環境が必要","SQLite3データベースへのアクセスが必要","ERBとJavaScriptテンプレートの比較のみ"],"ko":["Ruby 환경 필요","SQLite3 데이터베이스 액세스 필요","ERB 및 JavaScript 템플릿 비교만 가능"],"es":["Requiere entorno de Ruby","Se necesita acceso a la base de datos SQLite3","Limitado a comparaciones de plantillas ERB y JavaScript"],"fr":["Nécessite un environnement Ruby","L''accès à la base de données SQLite3 est nécessaire","Limité aux comparaisons de modèles ERB et JavaScript"],"de":["Benötigt Ruby-Umgebung","Zugriff auf SQLite3-Datenbank erforderlich","Begrenzt auf Vergleiche von ERB- und JavaScript-Vorlagen"],"pt":["Requer ambiente Ruby","Acesso ao banco de dados SQLite3 necessário","Limitado a comparações de modelos de template ERB e JavaScript"],"ru":["Требуется среда Ruby","Необходим доступ к базе данных SQLite3","Ограничен сравнением шаблонов ERB и JavaScript"],"ar":["يتطلب بيئة روبي","يتطلب وصولًا إلى قاعدة بيانات SQLite3","محدود بمقارنة قوالب ERB والجافاسكريبت"]},"version":4},"contentHash":"c19b9eebb9f8e3dd2b1d7a23e404d1f7c4cdc0939c71b68961722c3ce0b940ce","qualityScore":54}');
