INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rubys/showcase/compare-erb-js', 'compare-erb-js', 'rubys', 'showcase', 'community', 'compare-erb-js rubys showcase community The compare-erb-js skill enables developers to compare ERB templates and their JavaScript-converted equivalents, ensuring matching output for offline scoring SPAs. It benefits developers working with auto-converted ERB templates. compare-erb-js是用于比较ERB模板和JavaScript转换后的模板输出的工具，确保离线评分SPA的准确性 compare-erb-jsはERBテンプレートとJavaScriptに変換されたテンプレートの出力を比較するツールで、オフラインスコアリングSPAの精度を確保する compare-erb-js는 ERB 템플릿과 JavaScript로 변환된 템플릿의 출력을 비교하여 오프라인 평가 SPA의 정확성을 보장하는 도구입니다 Compare-erb-js es una herramienta para comparar la salida de plantillas ERB y JavaScript. Utiliza scripts/render_erb_and_js.rb para verificar la compatibilidad Compare-erb-js est un outil pour comparer la sortie de modèles ERB et JavaScript. Utilisez scripts/render_erb_and_js.rb pour vérifier la compatibilité Compare-erb-js ist ein Tool zum Vergleich der Ausgabe von ERB- und JavaScript-Vorlagen. Verwenden Sie scripts/render_erb_and_js.rb, um die Kompatibilität zu überprüfen O compare-erb-js é uma ferramenta para comparar saídas de templates ERB e JavaScript, usada em SPAs de pontuação offline Compare-erb-js - это инструмент для сравнения вывода шаблонов ERB и JavaScript, используемый в автономных SPA compare-erb-js هو أداة لمقارنة مخرجات قوالب ERB و JavaScript، تستخدم في تطبيقات الويب الحديثة how to use compare-erb-js compare-erb-js setup guide erb vs javascript template comparison compare-erb-js alternative compare-erb-js install what is compare-erb-js compare-erb-js template rendering erb template comparison tool javascript template verification compare-erb-js ERB模板 JavaScript模板 离线评分SPA Ruby脚本 命令行接口 模板输出比较 AI工具 AIエージェント Compares ERB templates with JavaScript-converted equivalents using scripts/render_erb_and_js.rb Verifies matching output for offline scoring SPAs Supports rendering of heat lists and individual heats Utilizes Ruby scripts for template comparison Works with SQLite3 databases, such as db/2025-barcelona-november.sqlite3 Enables verification of template output using bundle exec ruby commands compare-erb-js is a technical skill that compares ERB templates with their JavaScript-converted equivalents, verifying matching output for accurate rendering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kagenti/kagenti/kagenti:deploy', 'community', 'kagenti', 'kagenti', 'kagenti/kagenti', 'kagenti:deploy', 0, 0, 54, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:12.417Z', '23820e668229c7f84c366b7e47868bada2fa96ce199bb31fff66e17e30d62dc4', '{"id":"kagenti/kagenti/kagenti:deploy","name":"kagenti:deploy","description":{"en":"The kagenti:deploy skill guides developers through deploying or redeploying the Kagenti Kind cluster using the Python installer, providing a comprehensive setup process for AI agents.","zh":"Kagenti:Deploy技能指导您通过Python安装器部署或重新部署Kagenti Kind集群，确保Context-Safe Execution","ja":"Kagenti:Deploy スキルは、Python インストーラーを使用して Kagenti Kind クラスターをデプロイまたは再デプロイする方法を説明します","ko":"Kagenti:Deploy 스킬은 Python 설치 프로그램을 사용하여 Kagenti Kind 클러스터를 배포 또는 재배포하는 방법을 안내합니다","es":"El skill kagenti:deploy te guía a través del proceso de despliegue o redepliegue del cluster Kind de Kagenti utilizando el instalador de Python","fr":"Le skill kagenti:deploy vous guide à travers le processus de déploiement ou de redeplloiement du cluster Kind de Kagenti en utilisant l''installeur Python","de":"Das Skill kagenti:deploy führt Sie durch den Prozess des Bereitstellens oder erneuten Bereitstellens des Kagenti-Kind-Clusters mithilfe des Python-Installers","pt":"O kagenti:deploy é um skill que fornece uma guia passo-a-passo para deployar ou redeployar o cluster Kagenti Kind usando o instalador Python","ru":"kagenti:deploy - это навык, который предоставляет пошаговое руководство по развертыванию или переустановке кластера Kagenti Kind с помощью инсталлятора Python","ar":"kagenti:deploy هو مهارة توفر دليل خطوة بخطوة لتثبيت أو إعادة تثبيت مجموعة الخوادم Kagenti Kind باستخدام مثبت بايثون"},"seo":{"title":{"en":"kagenti:deploy: Cluster Deployment Setup Guide | AI Agent...","zh":"Kagenti部署指南：使用Python安装器设置集群","ja":"Kagenti:Deploy セットアップガイド - Python インストーラーを使用したクラスタ設定","ko":"Kagenti 배포 설정 가이드: 파이썬 설치 프로그램을 사용하여 클러스터 설정","es":"Guía de configuración de kagenti:deploy para clusters Kind","fr":"Guide de déploiement de kagenti:deploy pour les clusters ...","de":"Einrichtungsleitfaden für kagenti:deploy-Cluster","pt":"Guia de Configuração kagenti:deploy - Instalação de Cluster","ru":"Настройка kagenti:deploy - Руководство по развертыванию к...","ar":"دليل إعداد kagenti:deploy - تثبيت مجموعة الخوادم"},"description":{"en":"Discover how to deploy or redeploy the Kagenti Kind cluster using the Python installer with kagenti:deploy - get started with our technical guide today!","zh":"使用Kagenti:Deploy技能，通过Python安装器轻松设置和重新部署Kagenti Kind集群，实现Context-Safe Execution","ja":"Kagenti:Deploy スキルを使用して、Python インストーラーで Kagenti Kind クラスターを簡単に設定して再配置します","ko":"Kagenti:Deploy 스킬을 사용하여 Python 설치 프로그램으로 Kagenti Kind 클러스터를 쉽게 설정하고 재배포합니다","es":"Aprende a desplegar o volver a desplegar el cluster Kind de Kagenti utilizando el instalador de Python y sigue las mejores prácticas para la ejecución segura","fr":"Découvrez comment déployer ou redeployer le cluster Kind de Kagenti en utilisant l''installeur Python et suivez les meilleures pratiques pour l''exécution sécu...","de":"Erfahren Sie, wie Sie den Kagenti-Kind-Cluster mithilfe des Python-Installers bereitstellen oder neu bereitstellen und folgen Sie den bewährten Verfahren für...","pt":"Aprenda a configurar o kagenti:deploy para instalar e gerenciar clusters com o instalador Python e scripts de deploy","ru":"Узнайте, как настроить kagenti:deploy для развертывания и управления кластерами с помощью инсталлятора Python и скриптов развертывания","ar":"تعرف على كيفية تثبيت وتشغيل kagenti:deploy لتركيب وتدارة المجموعات الخوادم باستخدام مثبت بايثون وبرامج النشر"},"definition":{"en":"kagenti:deploy is a skill that enables the deployment or redeployment of the Kagenti Kind cluster using a Python installer, facilitating context-safe execution and logging.","zh":"Kagenti:Deploy是一种AI工具，用于通过Python安装器设置和重新部署Kagenti Kind集群","ja":"Kagenti:Deployは、Python インストーラーを使用して Kagenti Kind クラスターを設定して再配置するためのAIエージェントです","ko":"Kagenti:Deploy는 Python 설치 프로그램을 사용하여 Kagenti Kind 클러스터를 설정하고 재배포하는 AI 도구입니다","es":"kagenti:deploy es un skill que facilita el despliegue de clusters Kind de Kagenti mediante un instalador de Python","fr":"kagenti:deploy est un skill qui facilite le déploiement de clusters Kind de Kagenti via un installeur Python","de":"kagenti:deploy ist ein Skill, der die Bereitstellung von Kagenti-Kind-Clustern mithilfe eines Python-Installers erleichtert","pt":"O kagenti:deploy é um skill de deploy de cluster que utiliza o instalador Python e scripts de deploy para gerenciar a instalação de clusters","ru":"kagenti:deploy - это навык развертывания кластера, который использует инсталлятор Python и скрипты развертывания для управления установкой кластеров","ar":"kagenti:deploy هو مهارة نشر مجموعة الخوادم التي تستخدم مثبت بايثون وبرامج النشر لإدارة تركيب المجموعات الخوادم"},"features":{"en":["Utilizes a Python installer for deploying the Kagenti Kind cluster","Supports context-safe execution with redirectable log output","Employs bash scripts for automation, such as kind-full-test.sh","Generates detailed logs in files, including deploy.log","Facilitates logging with customizable LOG_DIR environment variable","Executes deploy scripts with output redirection for debugging"],"zh":["使用Python安装器设置Kagenti Kind集群","支持Context-Safe Execution","生成详细的部署日志","支持重定向输出到文件","集成到Kagenti主仓库中"],"ja":["Python インストーラーを使用して Kagenti Kind クラスターを設定","Context-Safe Executionをサポート","詳細なデプロイログを生成","出力をファイルにリダイレクトすることをサポート","Kagenti メインリポジトリに統合"],"ko":["Python 설치 프로그램을 사용하여 Kagenti Kind 클러스터를 설정","Context-Safe Execution을 지원","상세한 배포 로그를 생성","출력을 파일로 리ダイ렉트하는 것을 지원","Kagenti 메인 저장소에 통합"],"es":["Despliegue de clusters Kind de Kagenti","Instalador de Python para una configuración sencilla","Ejecución segura mediante la redirección de la salida a archivos","Compatibilidad con la ejecución de scripts de despliegue","Soporte para la gestión de registros de despliegue"],"fr":["Déploiement de clusters Kind de Kagenti","Installeur Python pour une configuration simple","Exécution sécurisée via la redirection de la sortie vers des fichiers","Compatibilité avec l''exécution de scripts de déploiement","Prise en charge de la gestion des journaux de déploiement"],"de":["Bereitstellung von Kagenti-Kind-Clustern","Python-Installer für eine einfache Konfiguration","Sichere Ausführung durch Umleitung der Ausgabe in Dateien","Kompatibilität mit der Ausführung von Deploy-Skripten","Unterstützung für die Verwaltung von Deploy-Protokollen"],"pt":["Instalador Python para deploy de cluster","Scripts de deploy para gerenciar a instalação","Suporte a execução de comandos em contexto seguro","Redirecionamento de saída para arquivos de log","Utilização de variáveis de ambiente para configuração"],"ru":["Инсталлятор Python для развертывания кластера","Скрипты развертывания для управления установкой","Поддержка безопасного выполнения команд","Перенаправление вывода в файлы журнала","Использование переменных окружения для конфигурации"],"ar":["مثبت بايثون لنشر المجموعات الخوادم","برامج النشر لإدارة التثبيت","دعم تنفيذ الأوامر في سياق آمن","تحويل الإخراج إلى ملفات سجل","استخدام متغيرات البيئة للتكوين"]},"keywords":{"en":["how to use kagenti:deploy","kagenti:deploy setup guide","kagenti:deploy vs kind cluster","kagenti:deploy install","what is kagenti:deploy","kagenti:deploy alternative","kagenti:deploy cluster deployment","kagenti:deploy python installer","kagenti:deploy logging","kagenti:deploy context-safe execution"],"zh":["Kagenti部署","Python安装器","Context-Safe Execution","Kagenti Kind集群","AI工具","集群设置","重新部署","部署日志","Python开发"],"ja":["Kagenti:Deploy","Python インストーラー","Context-Safe Execution","Kagenti Kind クラスター","AIエージェント","クラスター設定","再配置","デプロイログ","Python開発"],"ko":["Kagenti 배포","Python 설치 프로그램","Context-Safe Execution","Kagenti Kind 클러스터","AI 도구","클러스터 설정","재배포","배포 로그","Python 개발"],"es":["kagenti deploy","despliegue de clusters Kind","instalador de Python","ejecución segura","gestión de registros de despliegue","herramientas de AI","agentes de IA","desarrollo de software"],"fr":["kagenti deploy","déploiement de clusters Kind","installeur Python","exécution sécurisée","gestion des journaux de déploiement","outils d''IA","agents d''IA","développement de logiciels"],"de":["kagenti deploy","Bereitstellung von Kind-Clustern","Python-Installer","sichere Ausführung","Verwaltung von Deploy-Protokollen","AI-Tools","KI-Agenten","Software-Entwicklung"],"pt":["kagenti deploy","instalador python","scripts de deploy","cluster kind","execução de comandos em contexto seguro","redirecionamento de saída para arquivos de log","variáveis de ambiente para configuração"],"ru":["kagenti deploy","инсталлятор python","скрипты развертывания","кластер kind","безопасное выполнение команд","перенаправление вывода в файлы журнала","переменные окружения для конфигурации"],"ar":["kagenti deploy","مثبت بايثون","برامج النشر","مجموعة الخوادم kind","تنفيذ الأوامر في سياق آمن","تحويل الإخراج إلى ملفات سجل","متغيرات البيئة للتكوين"]}},"owner":"kagenti","repo":"kagenti","repoPath":"kagenti/kagenti","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"kagenti:deploy","description":"Deploy or redeploy the Kagenti Kind cluster using the Python installer - quick redeploy, manual steps, and troubleshooting","bodyPreview":"# Deploy Cluster Skill\n\nThis skill guides you through deploying or redeploying the Kagenti Kind cluster using the Python installer.\n\n## Context-Safe Execution (MANDATORY)\n\n**Deploy scripts produce hundreds of lines.** Always redirect to files:\n\n```bash\nexport LOG_DIR=/tmp/kagenti/deploy/$(basename $(git rev-parse --show-toplevel))\nmkdir -p $LOG_DIR\n\n# Pattern: redirect deploy output\n./.github/scripts/local-setup/kind-full-test.sh ... > $LOG_DIR/deploy.log 2>&1; echo \"EXIT:$?\"\n# On failure: Task(","body":"# Deploy Cluster Skill\n\nThis skill guides you through deploying or redeploying the Kagenti Kind cluster using the Python installer.\n\n## Context-Safe Execution (MANDATORY)\n\n**Deploy scripts produce hundreds of lines.** Always redirect to files:\n\n```bash\nexport LOG_DIR=/tmp/kagenti/deploy/$(basename $(git rev-parse --show-toplevel))\nmkdir -p $LOG_DIR\n\n# Pattern: redirect deploy output\n./.github/scripts/local-setup/kind-full-test.sh ... > $LOG_DIR/deploy.log 2>&1; echo \"EXIT:$?\"\n# On failure: Task(subagent_type=''Explore'') with Grep to find errors\n```\n\n## When to Use\n\n- Setting up new local development cluster\n- Full cluster redeploy after major changes\n- Cluster is corrupted or unstable\n- Testing clean deployment\n- Running E2E tests locally\n\n## Resource Requirements\n\n**Minimum** (from CLAUDE.md):\n- 12GB RAM\n- 4 CPU cores\n- Docker Desktop, Rancher Desktop, or Podman\n\n**Recommended for development**:\n- 16GB RAM\n- 6 CPU cores\n- 50GB free disk space\n\n## Multiple Clusters\n\nYou can run multiple Kind clusters:\n- **agent-platform** - Created by kagenti-installer (default)\n- **kagenti-demo** - Your existing cluster\n- Each cluster runs independently with its own name\n\nCheck existing clusters:\n```bash\nkind get clusters\n```\n\n## Quick Redeploy (Full Installation)\n\n```bash\n# 1. Setup environment (first time only)\ncp kagenti/installer/app/.env_template kagenti/installer/app/.env\n# Edit .env with:\n# - GITHUB_USER=<your-github-username>\n# - GITHUB_TOKEN=<ghcr.io-token>\n# - OPENAI_API_KEY=<openai-key>\n# - AGENT_NAMESPACES=team1,team2\n\n# 2. Full redeploy (creates new cluster + installs everything)\ncd kagenti/installer\nuv run kagenti-installer\n\n# What it does (15-25 minutes):\n# ✓ Creates Kind cluster \"agent-platform\"\n# ✓ Installs registry (optional)\n# ✓ Installs Tekton Pipelines\n# ✓ Installs Cert-Manager\n# ✓ Installs Platform Operator\n# ✓ Installs Istio Ambient\n# ✓ Installs Gateway API\n# ✓ Installs SPIRE\n# ✓ Installs MCP Gateway\n# ✓ Installs Keycloak + PostgreSQL\n# ✓ Installs Addons (Prometheus, Kiali, Phoenix)\n# ✓ Installs UI\n# ✓ Installs ToolHive\n# ✓ Creates agent namespaces (team1, team2)\n```\n\n## Use Existing Cluster\n\n```bash\n# Install on already running Kind cluster\ncd kagenti/installer\nuv run kagenti-installer --use-existing-cluster\n```\n\n## Cleanup and Fresh Install\n\n```bash\n# 1. Delete existing cluster\nkind delete cluster --name agent-platform\n\n# 2. Clean Docker images (optional)\ndocker system prune -a\n\n# 3. Fresh install\ncd kagenti/installer\nuv run kagenti-installer\n```\n\n## Selective Component Installation\n\nSkip components you don''t need for faster deployment:\n\n```bash\n# Minimal install (no UI, no observability, no auth)\ncd kagenti/installer\nuv run kagenti-installer \\\n  --skip-install ui \\\n  --skip-install addons \\\n  --skip-install keycloak \\\n  --skip-install spire\n\n# Skip specific components\nuv run kagenti-installer \\\n  --skip-install tekton \\\n  --skip-install operator \\\n  --skip-install gateway \\\n  --skip-install mcp_gateway\n\n# Install only core platform (for testing)\nuv run kagenti-installer \\\n  --skip-install addons \\\n  --skip-install ui \\\n  --skip-install keycloak \\\n  --skip-install agents\n```\n\n**Available components to skip**:\n- `registry` - Internal container registry\n- `tekton` - Tekton Pipelines (build system)\n- `cert_manager` - Certificate management\n- `operator` - Platform Operator (deprecated, being replaced by kagenti-operator)\n- `istio` - Service mesh\n- `gateway` - Kubernetes Gateway API\n- `spire` - Workload identity\n- `mcp_gateway` - MCP Gateway\n- `addons` - Observability (Prometheus, Kiali, Phoenix)\n- `ui` - Kagenti UI\n- `keycloak` - Authentication\n- `agents` - Demo agents\n- `metrics_server` - Metrics server\n- `inspector` - MCP inspector\n- `toolhive` - ToolHive operator\n\n## Deploy Weather Agents (Demo)\n\n```bash\n# After platform is installed\nkubectl apply -f kagenti/examples/components/\n```\n\nThis creates:\n- **weather-tool** in team1 namespace\n- **weather-service** in team1 namespace\n\n## Check Deployment Health\n\n### Quick Health Check\n\n```bash\n# Run the health check script (from CI)\nchmod +x .github/scripts/verify_deployment.sh\n.github/scripts/verify_deployment.sh\n\n# What it checks:\n# ✓ Resource usage (RAM, disk, CPU, containers)\n# ✓ Deployment status (weather-tool, weather-service, keycloak, operator)\n# ✓ Pod health summary (total, running, pending, failed, crashloop)\n# ✓ Failed pod details (events, error logs)\n```\n\n### Manual Health Checks\n\n```bash\n# All pods\nkubectl get pods -A\n\n# Failed pods only\nkubectl get pods -A --field-selector=status.phase!=Running,status.phase!=Succeeded\n\n# Specific namespace\nkubectl get pods -n team1\nkubectl get pods -n keycloak\nkubectl get pods -n kagenti-system\n\n# Deployments\nkubectl get deployments -A\n\n# Services\nkubectl get svc -A\n```\n\n## Run E2E Tests Locally\n\nAfter platform is deployed:\n\n```bash\ncd kagenti\n\n# Install test dependencies\nuv pip install -r tests/requirements.txt\n\n# Run all deployment health tests\nuv run pytest tests/e2e/test_deployment_health.py -v\n\n# Run only critical tests\nuv run pytest tests/e2e/test_deployment_health.py -v --only-critical\n\n# Run specific test\nuv run pytest tests/e2e/test_deployment_health.py::TestWeatherToolDeployment::test_weather_tool_deployment_ready -v\n\n# Exclude Keycloak tests\nuv run pytest tests/e2e/test_deployment_health.py -v --exclude-app=keycloak\n\n# Increase timeout\nuv run pytest tests/e2e/test_deployment_health.py -v --app-timeout=600\n```\n\n## Run Full CI Workflow Locally\n\nSimulate what runs in CI:\n\n```bash\n# 1. Install platform\ncd kagenti/installer\nuv run kagenti-installer --silent\n\n# 2. Deploy weather agents\ncd ../..\nkubectl apply -f kagenti/examples/components/\n\n# 3. Wait for deployments\nkubectl wait --for=condition=available --timeout=300s deployment/weather-tool -n team1\nkubectl wait --for=condition=available --timeout=300s deployment/weather-service -n team1\n\n# 4. Run health check\nchmod +x .github/scripts/verify_deployment.sh\n.github/scripts/verify_deployment.sh\n\n# 5. Run E2E tests\ncd kagenti\nuv pip install -r tests/requirements.txt\nuv run pytest tests/e2e/test_deployment_health.py -v \\\n  --timeout=300 \\\n  --tb=short\n```\n\n## Troubleshooting Deployment\n\n### Issue: Installer Timeout or Slow\n\n```bash\n# Check Docker resource allocation\ndocker info | grep -E \"CPUs|Total Memory\"\n\n# Increase timeout (images can be slow to pull)\n# The installer will retry - just re-run:\ncd kagenti/installer\nuv run kagenti-installer --use-existing-cluster\n```\n\n### Issue: \"Error loading config file\" or kubectl errors\n\n```bash\n# Check kubeconfig\nkubectl config current-context\n\n# Should show: kind-agent-platform\n\n# If not, set context\nkubectl config use-context kind-agent-platform\n```\n\n### Issue: Pods stuck in ImagePullBackOff\n\n```bash\n# Check if images are available in Kind\ndocker exec agent-platform-control-plane crictl images\n\n# Reload images (for custom builds)\nkind load docker-image <image-name> --name agent-platform\n\n# Check pod description for error\nkubectl describe pod <pod-name> -n <namespace>\n```\n\n### Issue: Keycloak Connection Issues\n\n```bash\n# Restart Keycloak\nkubectl delete -n keycloak -f kagenti/installer/app/resources/keycloak.yaml\nkubectl apply -n keycloak -f kagenti/installer/app/resources/keycloak.yaml\n\n# Restart Istio ztunnel\nkubectl rollout restart daemonset -n istio-system ztunnel\n\n# Restart Gateway\nkubectl rollout restart -n kagenti-system deployment http-istio\n```\n\n### Issue: Need to Update Secrets\n\n```bash\n# Update GitHub token\nkubectl -n <namespace> delete secret github-token-secret\n\n# Re-run installer to recreate secrets\ncd kagenti/installer\nuv run kagenti-installer --use-existing-cluster\n```\n\n### Issue: Blank UI on macOS\n\n```bash\n# Disable Screen Time Content & Privacy Restrictions\n# System Settings > Screen Time > Content & Privacy\n```\n\n### Issue: GitHub Token Errors\n\n```bash\n# Ensure token has correct scopes:\n# - repo:all\n# - write:packages\n# - read:packages\n\n# Clear cached credentials\ndocker logout ghcr.io\n```\n\n## Access Platform Services\n\nAfter deployment, access these services:\n\n```bash\n# Kagenti UI\nopen http://kagenti-ui.localtest.me:8080\n\n# Keycloak Admin Console\nopen http://keycloak.localtest.me:8080\n# Username: admin\n# Password: (from Keycloak secret)\nkubectl get secret -n keycloak keycloak-initial-admin -o jsonpath=''{.data.password}'' | base64 -d\n\n# Prometheus (if addons installed)\nkubectl port-forward -n observability svc/prometheus 9090:9090\nopen http://localhost:9090\n\n# Grafana (if addons installed)\nkubectl port-forward -n observability svc/grafana 3000:3000\nopen http://localhost:3000\n\n# Kiali (if addons installed)\nkubectl port-forward -n kiali svc/kiali 20001:20001\nopen http://localhost:20001\n```\n\n## Platform Configuration\n\n### Environment Variables (.env file)\n\nRequired in `kagenti/installer/app/.env`:\n\n```bash\n# GitHub access for ghcr.io\nGITHUB_USER=your-username\nGITHUB_TOKEN=ghp_xxx  # Classic token with repo:all, write:packages, read:packages\n\n# OpenAI API (for agents)\nOPENAI_API_KEY=sk-xxx\n\n# Agent namespaces\nAGENT_NAMESPACES=team1,team2\n\n# Optional: Slack (for Slack tool demo)\nSLACK_BOT_TOKEN=xoxb-xxx\n```\n\n### Cluster Configuration\n\nEdit `kagenti/installer/app/config.py`:\n\n```python\nCLUSTER_NAME = \"agent-platform\"  # Kind cluster name\nDOMAIN_NAME = \"localtest.me\"     # Domain for services\nCONTAINER_ENGINE = \"docker\"      # or \"podman\"\n```\n\n## Manual Step-by-Step Deployment (Advanced)\n\nFor debugging or understanding the installer:\n\n```bash\n# 1. Create Kind cluster manually\ncat <<EOF | kind create cluster --name agent-platform --config=-\nkind: Cluster\napiVersion: kind.x-k8s.io/v1alpha4\nnodes:\n- role: control-plane\n  extraPortMappings:\n  - containerPort: 30080\n    hostPort: 8080\n  - containerPort: 30443\n    hostPort: 9443\nEOF\n\n# 2. Set kubeconfig context\nkubectl config use-context kind-agent-platform\n\n# 3. Install components one by one\ncd kagenti/installer\n\n# Install Tekton\nkubectl apply -f https://storage.googleapis.com/tekton-releases/pipeline/previous/v0.66.0/release.yaml\n\n# Install Cert-Manager\nkubectl apply -f https://github.com/cert-manager/cert-manager/releases/download/v1.16.2/cert-manager.yaml\n\n# ... (see installer code for full sequence)\n```\n\n## Related Skills\n\n- **k8s:health**: Check comprehensive platform health\n- **k8s:logs**: Query logs for debugging\n- **k8s:pods**: Debug pod issues\n\n## Pro Tips\n\n1. **Use --use-existing-cluster**: Faster reinstalls without recreating cluster\n2. **Skip components**: Use --skip-install for faster iteration\n3. **Multiple clusters**: Use different cluster names for parallel testing\n4. **Resource allocation**: Ensure Docker/Podman has enough RAM (16GB recommended)\n5. **Cache images**: Pulled images are cached - subsequent installs are faster\n6. **Silent mode**: Use --silent to skip interactive prompts\n7. **Check logs**: If installer fails, check pod logs in kagenti-system namespace\n\n## Common Workflows\n\n### Daily Development\n```bash\n# Use existing cluster, skip slow components\ncd kagenti/installer\nuv run kagenti-installer --use-existing-cluster \\\n  --skip-install addons \\\n  --skip-install keycloak\n```\n\n### Full Test Before PR\n```bash\n# Fresh cluster, all components, run tests\nkind delete cluster --name agent-platform\ncd kagenti/installer\nuv run kagenti-installer --silent\nkubectl apply -f kagenti/examples/components/\n.github/scripts/verify_deployment.sh\ncd kagenti && uv run pytest tests/e2e/test_deployment_health.py -v\n```\n\n### Quick Agent Testing\n```bash\n# Minimal platform, just enough for agents\ncd kagenti/installer\nuv run kagenti-installer \\\n  --skip-install addons \\\n  --skip-install ui \\\n  --skip-install keycloak\nkubectl apply -f kagenti/examples/components/\n```\n"},"lastSynced":"2026-03-08T02:01:12.417Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated Kubernetes deployment and management using Kind clusters and Python installers.","zh":"非常适合需要使用 Kind 集群和 Python 安装程序进行自动化 Kubernetes 部署和管理的 AI 代理。","ja":"Kind クラスターと Python インストーラーを使用した自動化された Kubernetes の展開と管理が必要な AI エージェントに最適です。","ko":"Kind 클러스터와 Python 설치 프로그램을 사용하여 자동화된 Kubernetes 배포 및 관리가 필요한 AI 에이전트에게 완벽합니다.","es":"Perfecto para agentes de IA que necesitan despliegue y administración de Kubernetes automatizados utilizando clústeres Kind y instaladores de Python.","fr":"Parfait pour les agents IA ayant besoin d''un déploiement et d''une gestion de Kubernetes automatisés en utilisant des clusters Kind et des installateurs Python.","de":"Perfekt für KI-Agents, die ein automatisiertes Kubernetes-Deployment und -Management mit Kind-Clustern und Python-Installern benötigen.","pt":"Perfeito para Agentes de IA que precisam de implantação e gerenciamento automatizados do Kubernetes usando clusters Kind e instaladores Python.","ru":"Идеально для ИИ-агентов, которым требуется автоматизированная установка и управление Kubernetes с использованием кластеров Kind и установщиков Python.","ar":"مثالي لعمليات الوكيل الإصطناعي التي تحتاج إلى تثبيت وتحكم آليين لبرنامج Kubernetes باستخدام مجموعات Kind وبرامج تثبيت Python."},"recommendation":{"en":"Empowers agents to deploy or redeploy Kagenti Kind clusters using Python scripts, providing comprehensive setup processes and context-safe execution with redirectable log outputs, utilizing bash scripts and git repository analysis.","zh":"赋予代理使用 Python 脚本部署或重新部署 Kagenti Kind 集群的能力，提供全面性的设置流程和上下文安全的执行，具有可重定向的日志输出，利用 bash 脚本和 git 仓库分析。","ja":"Python スクリプトを使用して Kagenti Kind クラスターを展開または再展開する機能をエージェントに与え、包括的なセットアッププロセスとコンテキストセーフな実行、およびリダイレクタブルなログ出力を提供し、bash スクリプトと git リポジトリ分析を利用します。","ko":"Python 스크립트를 사용하여 Kagenti Kind 클러스터를 배포 또는 재배포하는 기능을 에이전트에게 부여하여, 포괄적인 설정 프로세스와 문맥 안전한 실행 및 리다이렉션 가능한 로그 출력을 제공하며, bash 스크립트 및 git 저장소 분석을 활용합니다.","es":"Habilita a los agentes a implementar o reimplementar clústeres Kind de Kagenti utilizando scripts de Python, proporcionando procesos de configuración integrales y ejecución segura del contexto con salidas de registros redirigibles, utilizando scripts de bash y análisis de repositorio de git.","fr":"Permet aux agents de déployer ou de redéployer des clusters Kind Kagenti en utilisant des scripts Python, fournissant des processus de configuration complets et une exécution sécurisée du contexte avec des sorties de journal redirigeables, en utilisant des scripts bash et une analyse de référentiel git.","de":"Ermächtigt Agents, Kagenti Kind-Cluster mithilfe von Python-Skripten zu deployen oder redeployen, indem umfassende Einrichtungsprozesse und kontextsichere Ausführung mit umleitbaren Log-Ausgaben bereitgestellt werden, unter Verwendung von Bash-Skripten und Git-Repository-Analyse.","pt":"Habilita os agentes a implantar ou reimplantar clusters Kagenti Kind usando scripts Python, fornecendo processos de configuração abrangentes e execução segura de contexto com saídas de log redirecionáveis, utilizando scripts bash e análise de repositório git.","ru":"Наделяет агентов возможностью развертывать или пере развертывать кластеры Kagenti Kind с использованием скриптов Python, обеспечивая полные процессы настройки и контекстно-безопасную работу с перенаправляемыми выводами журнала, используя скрипты bash и анализ репозитория git.","ar":"يسمح للوكلاء بتنفيذ أو إعادة تنفيذ مجموعات Kagenti Kind باستخدام سكريبتات Python، مما يوفر عمليات إعداد شاملة وتنفيذ آمن سياق مع مخرجات سجل قابلة لإعادة التوجيه، باستخدام سكريبتات bash وتحليل مستودع جيت."},"useCases":{"en":["Deploying Kagenti Kind clusters for AI agent development environments","Redeploying clusters for updated configurations or agent requirements","Debugging deployment issues using log outputs and error redirection"],"zh":["为 AI 代理开发环境部署 Kagenti Kind 集群","重新部署集群以更新配置或代理要求","使用日志输出和错误重定向调试部署问题"],"ja":["AI エージェント開発環境用の Kagenti Kind クラスターの展開","更新された構成またはエージェントの要件のためにクラスターを再展開","ログ出力とエラーのリダイレクトを使用して展開の問題をデバッグ"],"ko":["AI 에이전트 개발 환경을 위한 Kagenti Kind 클러스터 배포","업데이트된 구성 또는 에이전트 요구 사항을 위해 클러스터를 재배포","로그 출력 및 오류 리다이렉션을 사용하여 배포 문제를 디버깅"],"es":["Implementación de clústeres Kind de Kagenti para entornos de desarrollo de agentes de IA","Reimplementación de clústeres para configuraciones actualizadas o requisitos de agentes","Depuración de problemas de implementación utilizando salidas de registros y redirección de errores"],"fr":["Déploiement de clusters Kind Kagenti pour les environnements de développement d''agents IA","Redéploiement de clusters pour des configurations mises à jour ou des exigences d''agents","Débogage des problèmes de déploiement en utilisant les sorties de journal et la redirection des erreurs"],"de":["Bereitstellung von Kagenti Kind-Clustern für KI-Agent-Entwicklungsumgebungen","Neubereitstellung von Clustern für aktualisierte Konfigurationen oder Agentenanforderungen","Fehlerbehebung bei Bereitstellungsproblemen unter Verwendung von Log-Ausgaben und Fehlernachleitung"],"pt":["Implantação de clusters Kagenti Kind para ambientes de desenvolvimento de agentes de IA","Reimplantação de clusters para configurações atualizadas ou requisitos de agentes","Depuração de problemas de implantação usando saídas de log e redirecionamento de erros"],"ru":["Развертывание кластеров Kagenti Kind для сред разработки ИИ-агентов","Переразвертывание кластеров для обновленных конфигураций или требований агентов","Отладка проблем развертывания с использованием вывода журнала и перенаправления ошибок"],"ar":["تثبيت مجموعات Kagenti Kind لبيئات تطوير عمليات الوكيل الإصطناعي","إعادة تثبيت المجموعات للتكوينات المحدثة أو متطلبات الوكيل","تصحيح الأخطاء في التثبيت باستخدام مخرجات السجل وإعادة توجيه الأخطاء"]},"limitations":{"en":["Requires Python installer and compatible environment","Needs git repository access for revision parsing","Dependent on bash script execution for deployment"],"zh":["需要 Python 安装程序和兼容环境","需要 git 仓库访问以进行修订解析","依赖于 bash 脚本执行进行部署"],"ja":["Python インストーラーと互換性のある環境が必要","修正の解析のために git リポジトリへのアクセスが必要","展開のために bash スクリプトの実行に依存"],"ko":["Python 설치 프로그램 및 호환 환경이 필요","修订 파싱을 위해 git 저장소 액세스가 필요","배포를 위해 bash 스크립트 실행에 의존"],"es":["Requiere instalador de Python y entorno compatible","Necesita acceso al repositorio de git para el análisis de revisiones","Dependiente de la ejecución de scripts de bash para la implementación"],"fr":["Nécessite un installateur Python et un environnement compatible","A besoin d''un accès au référentiel git pour l''analyse des révisions","Dépend de l''exécution de scripts bash pour le déploiement"],"de":["Benötigt Python-Installateur und kompatibles Umfeld","Benötigt Zugriff auf Git-Repository für Revisionenanalyse","Abhängig von der Ausführung von Bash-Skripten für die Bereitstellung"],"pt":["Requer instalador Python e ambiente compatível","Necessita acesso ao repositório git para análise de revisão","Dependente da execução de scripts bash para implantação"],"ru":["Требуется установщик Python и совместимая среда","Требуется доступ к репозиторию git для анализа ревизий","Зависит от выполнения скриптов bash для развертывания"],"ar":["يتطلب تثبيت Python وبيئة متوافقة","يحتاج إلى الوصول إلى مستودع جيت لتحليل المراجعة","يعتمد على تنفيذ سكريبتات bash للتثبيت"]},"version":4},"contentHash":"23820e668229c7f84c366b7e47868bada2fa96ce199bb31fff66e17e30d62dc4","qualityScore":54}');
