INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kagenti/kagenti/kagenti:deploy', 'kagenti:deploy', 'kagenti', 'kagenti', 'community', 'kagenti:deploy kagenti kagenti community The kagenti:deploy skill guides developers through deploying or redeploying the Kagenti Kind cluster using the Python installer, providing a comprehensive setup process for AI agents. Kagenti:Deploy技能指导您通过Python安装器部署或重新部署Kagenti Kind集群，确保Context-Safe Execution Kagenti:Deploy スキルは、Python インストーラーを使用して Kagenti Kind クラスターをデプロイまたは再デプロイする方法を説明します Kagenti:Deploy 스킬은 Python 설치 프로그램을 사용하여 Kagenti Kind 클러스터를 배포 또는 재배포하는 방법을 안내합니다 El skill kagenti:deploy te guía a través del proceso de despliegue o redepliegue del cluster Kind de Kagenti utilizando el instalador de Python Le skill kagenti:deploy vous guide à travers le processus de déploiement ou de redeplloiement du cluster Kind de Kagenti en utilisant l''installeur Python Das Skill kagenti:deploy führt Sie durch den Prozess des Bereitstellens oder erneuten Bereitstellens des Kagenti-Kind-Clusters mithilfe des Python-Installers O kagenti:deploy é um skill que fornece uma guia passo-a-passo para deployar ou redeployar o cluster Kagenti Kind usando o instalador Python kagenti:deploy - это навык, который предоставляет пошаговое руководство по развертыванию или переустановке кластера Kagenti Kind с помощью инсталлятора Python kagenti:deploy هو مهارة توفر دليل خطوة بخطوة لتثبيت أو إعادة تثبيت مجموعة الخوادم Kagenti Kind باستخدام مثبت بايثون how to use kagenti:deploy kagenti:deploy setup guide kagenti:deploy vs kind cluster kagenti:deploy install what is kagenti:deploy kagenti:deploy alternative kagenti:deploy cluster deployment kagenti:deploy python installer kagenti:deploy logging kagenti:deploy context-safe execution Kagenti部署 Python安装器 Context-Safe Execution Kagenti Kind集群 AI工具 集群设置 重新部署 部署日志 Python开发 Utilizes a Python installer for deploying the Kagenti Kind cluster Supports context-safe execution with redirectable log output Employs bash scripts for automation, such as kind-full-test.sh Generates detailed logs in files, including deploy.log Facilitates logging with customizable LOG_DIR environment variable Executes deploy scripts with output redirection for debugging kagenti:deploy is a skill that enables the deployment or redeployment of the Kagenti Kind cluster using a Python installer, facilitating context-safe execution and logging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kungfuai/CVlization/remote-run-ssh', 'community', 'kungfuai', 'CVlization', 'kungfuai/CVlization', 'remote-run-ssh', 0, 0, 54, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:19.785Z', '9dccd67d06aca8901b403c73a1113d84e6d26029f91de4c52a6bf9a532c2c854', '{"id":"kungfuai/CVlization/remote-run-ssh","name":"remote-run-ssh","description":{"en":"remote-run-ssh enables developers to run CVlization examples on remote GPUs via SSH, ideal for heavy trainings or evaluations requiring CUDA.","zh":"远程SSH运行CVlization示例，依赖Docker和CUDA实现高效训练","ja":"CVlizationの例をリモートSSHで実行し、DockerとCUDAを使用して高速化","ko":"원격 SSH를 통해 CVlization 예제를 실행하고 Docker 및 CUDA를 사용하여 효율적인 훈련을实现","es":"El skill remote-run-ssh permite la ejecución de ejemplos de CVlization en un GPU remoto a través de SSH","fr":"Le skill remote-run-ssh permet d''exécuter des exemples de CVlization sur un GPU distant via SSH","de":"Der remote-run-ssh-Skill ermöglicht die Ausführung von CVlization-Beispielen auf einem Remote-GPU über SSH","pt":"O remote-run-ssh permite operar exemplos de cvlization em um GPU remoto com Docker, ideal para treinamentos pesados","ru":"Remote-run-ssh позволяет работать с примерами cvlization на удаленном GPU с помощью Docker, подходящий для тяжелых тренировок","ar":"يسمح remote-run-ssh بتشغيل أمثلة cvlization على جهاز كمبيوتر بعيد مع دッカー، مناسب للتدريبات الثقيلة"},"seo":{"title":{"en":"remote-run-ssh: Remote GPU Setup Guide | AI Agent Skill","zh":"远程SSH运行设置指南 - 运行CVlization示例","ja":"リモートSSH実行のベストプラクティス - CVlizationの例","ko":"원격 SSH 실행 가이드 - CVlization 예제 실행","es":"Guía de configuración de remote-run-ssh para agentes de i...","fr":"Guide de configuration de remote-run-ssh pour les outils ...","de":"Einrichtungsleitfaden für remote-run-ssh in KI-Agenten","pt":"Guia de Configuração do remote-run-ssh para Ferramentas d...","ru":"ИИ Агенты: Руководство по настройке remote-run-ssh","ar":"دليل إعداد remote-run-ssh لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock remote GPU power with remote-run-ssh. Learn how to operate CVlization examples over SSH and boost your AI model training","zh":"使用远程SSH运行CVlization示例，实现CUDA加速和高效训练","ja":"リモートSSHを使用してCVlizationの例を実行し、CUDAを活用して高速化","ko":"원격 SSH를 사용하여 CVlization 예제를 실행하고 CUDA 가속을 통해 효율적인 훈련을实现","es":"Aprende a utilizar remote-run-ssh para operar ejemplos de CVlization en un GPU remoto con Docker","fr":"Découvrez comment utiliser remote-run-ssh pour exécuter des exemples de CVlization sur un GPU distant avec Docker","de":"Erfahren Sie, wie Sie remote-run-ssh verwenden, um CVlization-Beispiele auf einem Remote-GPU mit Docker auszuführen","pt":"Aprenda a configurar o remote-run-ssh para operar exemplos de cvlization em um GPU remoto com Docker","ru":"Узнайте, как настроить remote-run-ssh для работы с примерами cvlization на удаленном GPU с помощью Docker","ar":"تعلم كيفية إعداد remote-run-ssh لتشغيل أمثلة cvlization على جهاز كمبيوتر بعيد مع دッカー"},"definition":{"en":"remote-run-ssh is a practical workflow for using and training vision and language models on remote GPUs reachable via SSH","zh":"远程SSH运行是指使用SSH协议在远程服务器上运行CVlization示例","ja":"リモートSSH実行とは、SSHプロトコルを使用してリモートサーバー上でCVlizationの例を実行すること","ko":"원격 SSH 실행은 SSH 프로토콜을 사용하여 원격 서버에서 CVlization 예제를 실행하는 것을 의미","es":"Remote-run-ssh es un skill que permite la ejecución remota de ejemplos de CVlization sobre un GPU","fr":"Remote-run-ssh est un skill qui permet l''exécution à distance d''exemples de CVlization sur un GPU","de":"Remote-run-ssh ist ein Skill, der die Remote-Ausführung von CVlization-Beispielen auf einem GPU ermöglicht","pt":"O que é remote-run-ssh? Uma ferramenta para operar exemplos de cvlization em um GPU remoto","ru":"Что такое remote-run-ssh? Инструмент для работы с примерами cvlization на удаленном GPU","ar":"ما هو remote-run-ssh؟ أداة لتشغيل أمثلة cvlization على جهاز كمبيوتر بعيد"},"features":{"en":["Operates CVlization examples on remote GPUs via SSH","Minimizes remote copy to just the target example folder and cvlization library","Utilizes example''s own build.sh and train.sh Docker helpers","Keeps user''s long-lived checkout on the remote untouched","Supports heavy trainings or evaluations requiring CUDA"],"zh":["使用SSH协议在远程服务器上运行CVlization示例","依赖Docker和CUDA实现高效训练","支持CUDA加速和多 GPU 训练","使用build.sh和train.sh脚本简化训练流程"],"ja":["SSHプロトコルを使用してリモートサーバー上でCVlizationの例を実行","DockerとCUDAを使用して高速化","CUDAアクセラレーションとマルチGPUトレーニングをサポート","build.shとtrain.shスクリプトを使用してトレーニングのワークフローを簡素化"],"ko":["SSH 프로토콜을 사용하여 원격 서버에서 CVlization 예제를 실행","Docker 및 CUDA를 사용하여 효율적인 훈련을实现","CUDA 가속과 멀티 GPU 훈련을 지원","build.sh와 train.sh 스크립트를 사용하여 훈련 워크플로우를 간소화"],"es":["Ejecución de ejemplos de CVlization en un GPU remoto","Uso de Docker para la ejecución de ejemplos","Conexión segura a través de SSH","Minimización de la copia remota","Uso de build.sh y train.sh para la ejecución de ejemplos"],"fr":["Exécution d''exemples de CVlization sur un GPU distant","Utilisation de Docker pour l''exécution d''exemples","Connexion sécurisée via SSH","Minimisation de la copie distante","Utilisation de build.sh et train.sh pour l''exécution d''exemples"],"de":["Ausführung von CVlization-Beispielen auf einem Remote-GPU","Verwendung von Docker für die Ausführung von Beispielen","Sichere Verbindung über SSH","Minimierung der Remote-Kopie","Verwendung von build.sh und train.sh für die Ausführung von Beispielen"],"pt":["Opera exemplos de cvlization em um GPU remoto","Utiliza Docker para treinamentos e avaliações","Mantém a cópia remota minimalista","Suporta treinamentos pesados com CUDA","Integração com o cvlization/"],"ru":["Работа с примерами cvlization на удаленном GPU","Использование Docker для тренировок и оценок","Минималистичная удаленная копия","Поддержка тяжелых тренировок с CUDA","Интеграция с cvlization/"],"ar":["تشغيل أمثلة cvlization على جهاز كمبيوتر بعيد","استخدام دッカー للتدريبات والتقويم","نسخة بعيدة محددة","دعم التدريبات الثقيلة مع CUDA","التكامل مع cvlization/"]},"keywords":{"en":["how to use remote-run-ssh","remote-run-ssh setup guide","remote-run-ssh vs docker","what is remote-run-ssh","remote-run-ssh alternative","remote-run-ssh install","ssh remote gpu","cvlization examples","cuda remote training"],"zh":["远程SSH运行","CVlization示例","CUDA加速","Docker","高效训练","AI工具","AIエージェント"],"ja":["リモートSSH実行","CVlizationの例","CUDAアクセラレーション","Docker","高速化","AIエージェント","AIツール"],"ko":["원격 SSH 실행","CVlization 예제","CUDA 가속","Docker","효율적인 훈련","AI 에이전트","AI 툴"],"es":["remote-run-ssh","CVlization","GPU remoto","Docker","SSH","agentes de inteligencia artificial","ejecución remota","build.sh","train.sh"],"fr":["remote-run-ssh","CVlization","GPU distant","Docker","SSH","outils d''intelligence artificielle","exécution à distance","build.sh","train.sh"],"de":["remote-run-ssh","CVlization","Remote-GPU","Docker","SSH","KI-Agenten","Remote-Ausführung","build.sh","train.sh"],"pt":["remote-run-ssh","ferramentas de ia","cvlization","gpu remoto","docker","treinamentos pesados","cuda","ia","desenvolvimento de ia"],"ru":["remote-run-ssh","ии агенты","cvlization","удаленный gpu","docker","тяжелые тренировки","cuda","искусственный интеллект","разработка ии"],"ar":["remote-run-ssh","أدوات الذكاء الاصطناعي","cvlization","جهاز كمبيوتر بعيد","دッカー","تدريبات ثقيلة","cuda","الذكاء الاصطناعي","تطوير الذكاء الاصطناعي"]}},"owner":"kungfuai","repo":"CVlization","repoPath":"kungfuai/CVlization","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"remote-run-ssh","description":"Run CVlization examples on the `ssh l1` GPU host by copying only the needed example directory plus the shared `cvlization/` package into `/tmp`, then launching the example’s Docker scripts.","bodyPreview":"# Remote Run over SSH\n\nOperate CVlization examples on the remote GPU reachable as `ssh l1`. This playbook keeps the remote copy minimal—just the target example folder (e.g., `examples/perception/multimodal_multitask/recipe_analysis_torch`) and the `cvlization/` library—then relies on the example’s own `build.sh` / `train.sh` Docker helpers. The user’s long-lived checkout on the remote stays untouched.\n\n## When to Use\n- Heavy trainings or evaluations that require CUDA (CIFAR10 speed runs, multimo","body":"# Remote Run over SSH\n\nOperate CVlization examples on the remote GPU reachable as `ssh l1`. This playbook keeps the remote copy minimal—just the target example folder (e.g., `examples/perception/multimodal_multitask/recipe_analysis_torch`) and the `cvlization/` library—then relies on the example’s own `build.sh` / `train.sh` Docker helpers. The user’s long-lived checkout on the remote stays untouched.\n\n## When to Use\n- Heavy trainings or evaluations that require CUDA (CIFAR10 speed runs, multimodal pipelines, etc.).\n- Performance or regression measurements on the remote GPU after local code changes.\n- Producing reproducible logs / artifacts for discussions or CI baselines without pushing a branch first.\n\n## Prerequisites\n- Local repo state ready to sync (uncommitted changes acceptable).\n- SSH config already maps the GPU machine to `l1`.\n- Remote host provides NVIDIA GPU (currently A10) and Docker with GPU runtime enabled.\n- At least ~15 GB free under `/tmp` for the slim workspace, Docker context, and caches.\n- Hugging Face tokens or other creds available locally if the example pulls hub assets.\n\n## Quick Reference\n1. Choose the example to run.\n2. `rsync` only the example folder, `cvlization/`, and any required helper dirs to `/tmp/cvlization_remote` on `l1`.\n3. On `l1`, run `./build.sh` inside the example folder to build the Docker image.\n4. Run `./train.sh` (or the example’s equivalent) to launch the job with GPU access.\n5. Collect logs / metrics and record the run in `var/skills/remote-run-ssh/runs/<timestamp>/log.md`.\n\n## Detailed Procedure\n\n### 1. Identify the example and supporting files\n- Note the example path relative to repo root (e.g., `examples/perception/multimodal_multitask/recipe_analysis_torch`).\n- List any extra assets the run needs (custom configs under `examples`, top-level scripts, environment files, etc.).\n- Confirm `cvlization/` includes all library modules the example imports.\n\n### 2. Sync minimal workspace to `/tmp`\n```bash\nREMOTE_ROOT=/tmp/cvlization_remote\nrsync -az --delete \\\n  --include=''cvlization/***'' \\\n  --include=''examples/***'' \\\n  --include=''scripts/***'' \\\n  --include=''pyproject.toml'' \\\n  --include=''setup.cfg'' \\\n  --include=''README.md'' \\\n  --exclude=''*'' \\\n  ./ l1:${REMOTE_ROOT}/\n```\nTips:\n- Adjust the include list if the example needs additional files (e.g., `docker-compose.yml`, `requirements.txt`). The blanket `--exclude=''*''` prevents unrelated directories from syncing.\n- Keep the remote path structure (`${REMOTE_ROOT}/examples/...`) aligned with the local repo so relative paths like `../../../..` used inside scripts still resolve to the repo root.\n- Avoid syncing `.git`, local datasets, `.venv`, or heavy cache directories.\n\n### 3. Build the example image\n```bash\nssh l1 ''cd /tmp/cvlization_remote/examples/perception/multimodal_multitask/recipe_analysis_torch && ./build.sh''\n```\n- The Docker build context is limited to the example folder, keeping builds quick.\n- Edit `build.sh` locally if you need custom base images or dependency tweaks before re-syncing.\n\n### 4. Confirm GPU availability\n```bash\nssh l1 ''nvidia-smi''\n```\nEnsure no conflicting jobs are consuming the GPU before starting a long run.\n\n### 5. Run the training script (Docker)\n```bash\nssh l1 ''cd /tmp/cvlization_remote/examples/perception/multimodal_multitask/recipe_analysis_torch && ./train.sh > run.log 2>&1''\n```\n- Tail logs while the job runs:\n```bash\nssh l1 ''tail -f /tmp/cvlization_remote/examples/perception/multimodal_multitask/recipe_analysis_torch/run.log''\n```\n- `train.sh` already mounts the example directory at `/workspace`, mounts the synced repo root read-only at `/cvlization_repo`, and sets `PYTHONPATH=/cvlization_repo`.\n- Customize environment variables or extra mounts by editing `train.sh` locally (e.g., injecting dataset paths, WANDB keys) then re-syncing.\n- If an example lacks Docker scripts, fall back to running its entrypoint directly (`python train.py`) inside the container or a temporary venv—but document the deviation in the run log.\n\n### 6. Capture metrics\nLog files should include per-epoch summaries and final metrics. Record:\n- Wall-clock time / throughput.\n- Accuracy, loss, or other task metrics.\n- Warnings or notable log lines (e.g., retry downloads, CUDA warnings).\n\n### 7. Retrieve artifacts (optional)\n```bash\nrsync -az l1:/tmp/cvlization_remote/examples/perception/multimodal_multitask/recipe_analysis_torch/run.log \\\n  ./remote_runs/$(date +%Y%m%dT%H%M%S)_multimodal.log\n```\nCopy checkpoints, TensorBoard logs, or generated samples in the same manner if needed.\n\n### 8. Document the run\n- Create `var/skills/remote-run-ssh/runs/<timestamp>/log.md` summarizing:\n  - Example path, git commit or diff basis.\n  - Commands executed (`build.sh`, `train.sh` args).\n  - Key metrics / observations.\n  - Location of logs or artifacts (local paths or remote references).\n\n### 9. Cleanup (optional)\n- Delete `/tmp/cvlization_remote` when finished if the disk budget is tight (`ssh l1 ''rm -rf /tmp/cvlization_remote''`).\n- Clear cached datasets (`rm -rf /root/.cache/...` inside Docker) only if future runs should start fresh.\n\n## Troubleshooting\n- **Missing module inside container**: Ensure `train.sh` mounts the repo root and sets `PYTHONPATH`. Re-run `rsync` if files were added after the initial sync.\n- **Docker build fails**: Inspect the output of `./build.sh`. Some examples assume base images with CUDA toolkits—update the Dockerfile accordingly.\n- **CUDA OOM**: Reduce batch sizes or precision, or run one job at a time on `l1`.\n- **No GPU detected**: Confirm `--gpus=all` is present in `train.sh` and check `nvidia-smi` on the host.\n- **Long sync times**: Tighten the rsync include rules to the specific example and library folders required.\n\n## Outputs\nEvery run should leave:\n- Remote workspace at `/tmp/cvlization_remote` containing the synced example + library.\n- Local or remote logs with the captured metrics.\n- A run log under `var/skills/remote-run-ssh/runs/<timestamp>/log.md` documenting the session.\n"},"lastSynced":"2026-03-08T02:01:19.785Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing remote GPU acceleration via SSH for heavy machine learning trainings or evaluations requiring CUDA.","zh":"适用于需要通过SSH进行远程GPU加速的AI代理，用于需要CUDA的重型机器学习训练或评估。","ja":"SSH経由でリモートGPUの加速が必要なAIエージェントに適しています。CUDAが必要な重い機械学習のトレーニングや評価に使用されます。","ko":"SSH를 통해 원격 GPU 가속이 필요한 AI 에이전트에 적합합니다. CUDA가 필요한 무거운 기계 학습 훈련 또는 평가에 사용됩니다.","es":"Perfecto para agentes de IA que necesitan aceleración de GPU remota a través de SSH para entrenamientos o evaluaciones de aprendizaje automático pesados que requieren CUDA.","fr":"Parfait pour les agents IA nécessitant une accélération GPU à distance via SSH pour des entraînements ou des évaluations d''apprentissage automatique lourds nécessitant CUDA.","de":"Perfekt für KI-Agenten, die eine Remote-GPU-Beschleunigung über SSH für schwere Machine-Learning-Trainings oder Bewertungen benötigen, die CUDA erfordern.","pt":"Perfeito para Agentes de IA que necessitam de aceleração de GPU remota via SSH para treinamentos ou avaliações de aprendizado de máquina pesados que requerem CUDA.","ru":"Идеально подходит для агентов ИИ, которым требуется удаленное ускорение GPU через SSH для тяжелых обучений или оценок, требующих CUDA.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تحتاج إلى تسريع وحدة معالجة الرسومات عن بعد عبر SSH لتدريبات أو تقييمات تعلم الآلة الثقيلة التي تتطلب CUDA."},"recommendation":{"en":"Empowers agents to operate CVlization examples on remote GPUs via SSH, leveraging CUDA for heavy trainings or evaluations, while keeping the remote copy minimal with just the target example folder and the cvlization library.","zh":"赋予代理在远程GPU上通过SSH操作CVlization示例的能力，利用CUDA进行重型训练或评估，同时保持远程副本最小化，只包括目标示例文件夹和CVlization库。","ja":"エージェントがSSH経由でリモートGPU上でCVlizationの例を操作できる機能を提供します。CUDAを使用して重いトレーニングや評価を行い、リモートコピーを最小限に抑え、ターゲットの例フォルダとCVlizationライブラリのみを保持します。","ko":"에이전트가 SSH를 통해 원격 GPU에서 CVlization 예제를操作할 수 있는 기능을 제공합니다. CUDA를 사용하여 무거운 훈련 또는 평가를 수행하며 원격 복사본을 최소화하여 대상 예제 폴더와 CVlization 라이브러리만 유지합니다.","es":"Habilita a los agentes a operar ejemplos de CVlization en GPUs remotas a través de SSH, aprovechando CUDA para entrenamientos o evaluaciones pesados, mientras mantiene la copia remota minimal con solo la carpeta de ejemplo de destino y la biblioteca cvlization.","fr":"Permet aux agents d''exploiter des exemples de CVlization sur des GPU distants via SSH, en exploitant CUDA pour des entraînements ou des évaluations lourds, tout en gardant la copie distante minimale avec seulement le dossier d''exemple cible et la bibliothèque cvlization.","de":"Ermöglicht es Agenten, CVlization-Beispiele auf Remote-GPUs über SSH zu betreiben, indem CUDA für schwere Trainings oder Bewertungen genutzt wird, während die Remote-Kopie minimal gehalten wird, mit nur dem Ziel-Beispiel-Ordner und der cvlization-Bibliothek.","pt":"Habilita os agentes a operar exemplos de CVlization em GPUs remotas via SSH, utilizando CUDA para treinamentos ou avaliações pesados, mantendo a cópia remota minimal com apenas a pasta do exemplo de destino e a biblioteca cvlization.","ru":"Позволяет агентам работать с примерами CVlization на удаленных GPU через SSH, используя CUDA для тяжелых обучений или оценок, при этом сохраняя удаленную копию минимальной с仅 папкой целевого примера и библиотекой cvlization.","ar":"تمكين الوكيل من تشغيل أمثلة CVlization على وحدات معالجة الرسومات عن بعد عبر SSH، باستخدام CUDA للتدريبات أو التقييمات الثقيلة، مع الحفاظ على نسخة متوافرة مع مجلد مثال الهدف ومكتبة cvlization فقط."},"useCases":{"en":["Automating heavy trainings on remote GPUs","Evaluating machine learning models on CIFAR10 datasets","Deploying CVlization examples on remote servers with SSH access"],"zh":["在远程GPU上自动化重型训练","在CIFAR10数据集上评估机器学习模型","将CVlization示例部署到具有SSH访问权限的远程服务器"],"ja":["リモートGPU上での重いトレーニングの自動化","CIFAR10データセット上での機械学習モデルの評価","SSHアクセスが可能なリモートサーバーへのCVlizationの例のデプロイ"],"ko":["원격 GPU에서 무거운 훈련을 자동화하는 것","CIFAR10 데이터셋에서 기계 학습 모델을 평가하는 것","SSH 액세스가 가능한 원격 서버에 CVlization 예제를 배포하는 것"],"es":["Automatizar entrenamientos pesados en GPUs remotas","Evaluar modelos de aprendizaje automático en conjuntos de datos CIFAR10","Implementar ejemplos de CVlization en servidores remotos con acceso SSH"],"fr":["Automatiser des entraînements lourds sur des GPU distants","Évaluer des modèles d''apprentissage automatique sur des ensembles de données CIFAR10","Déployer des exemples de CVlization sur des serveurs distants avec un accès SSH"],"de":["Schwere Trainings auf Remote-GPUs automatisieren","Machine-Learning-Modelle auf CIFAR10-Datensätzen bewerten","CVlization-Beispiele auf Remote-Servern mit SSH-Zugriff bereitstellen"],"pt":["Automatizar treinamentos pesados em GPUs remotas","Avaliar modelos de aprendizado de máquina em conjuntos de dados CIFAR10","Implantar exemplos de CVlization em servidores remotos com acesso SSH"],"ru":["Автоматизация тяжелых обучений на удаленных GPU","Оценка моделей машинного обучения на наборах данных CIFAR10","Развертывание примеров CVlization на удаленных серверах с доступом SSH"],"ar":["أتمتة التدريبات الثقيلة على وحدات معالجة الرسومات عن بعد","تقييم نماذج تعلم الآلة على مجموعات بيانات CIFAR10","نشر أمثلة CVlization على الخواديم عن بعد مع وصول SSH"]},"limitations":{"en":["Requires SSH access to remote GPU","CUDA dependency for GPU acceleration","Limited to CVlization examples with Docker helpers"],"zh":["需要远程GPU的SSH访问","CUDA依赖项用于GPU加速","仅限于具有Docker助手的CVlization示例"],"ja":["リモートGPUへのSSHアクセスが必要","GPU加速にはCUDA依存関係が必要","Dockerヘルパーを使用したCVlizationの例に限定"],"ko":["원격 GPU에 대한 SSH 액세스가 필요합니다.","GPU 가속에는 CUDA 종속성이 필요합니다.","Docker 헬퍼를 사용하는 CVlization 예제에만 제한됩니다."],"es":["Requiere acceso SSH a la GPU remota","Dependencia de CUDA para la aceleración de GPU","Limitado a ejemplos de CVlization con ayuda de Docker"],"fr":["Nécessite un accès SSH à la GPU distante","Dépendance de CUDA pour l''accélération GPU","Limité aux exemples de CVlization avec des aides Docker"],"de":["Benötigt SSH-Zugriff auf die Remote-GPU","CUDA-Abhängigkeit für die GPU-Beschleunigung","Begrenzt auf CVlization-Beispiele mit Docker-Hilfe"],"pt":["Requer acesso SSH ao GPU remoto","Dependência do CUDA para aceleração de GPU","Limitado a exemplos de CVlization com helpers do Docker"],"ru":["Требуется доступ SSH к удаленному GPU","Зависимость от CUDA для ускорения GPU","Ограниченность примерами CVlization с помощью Docker"],"ar":["يتطلب وصول SSH إلى وحدة معالجة الرسومات عن بعد","اعتماد CUDA لتسريع وحدة معالجة الرسومات","محدود بأمثلة CVlization مع مساعدات Docker"]},"version":4},"contentHash":"9dccd67d06aca8901b403c73a1113d84e6d26029f91de4c52a6bf9a532c2c854","qualityScore":54}');
