INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kungfuai/CVlization/remote-run-ssh', 'remote-run-ssh', 'kungfuai', 'CVlization', 'community', 'remote-run-ssh kungfuai CVlization community remote-run-ssh enables developers to run CVlization examples on remote GPUs via SSH, ideal for heavy trainings or evaluations requiring CUDA. 远程SSH运行CVlization示例，依赖Docker和CUDA实现高效训练 CVlizationの例をリモートSSHで実行し、DockerとCUDAを使用して高速化 원격 SSH를 통해 CVlization 예제를 실행하고 Docker 및 CUDA를 사용하여 효율적인 훈련을实现 El skill remote-run-ssh permite la ejecución de ejemplos de CVlization en un GPU remoto a través de SSH Le skill remote-run-ssh permet d''exécuter des exemples de CVlization sur un GPU distant via SSH Der remote-run-ssh-Skill ermöglicht die Ausführung von CVlization-Beispielen auf einem Remote-GPU über SSH O remote-run-ssh permite operar exemplos de cvlization em um GPU remoto com Docker, ideal para treinamentos pesados Remote-run-ssh позволяет работать с примерами cvlization на удаленном GPU с помощью Docker, подходящий для тяжелых тренировок يسمح remote-run-ssh بتشغيل أمثلة cvlization على جهاز كمبيوتر بعيد مع دッカー، مناسب للتدريبات الثقيلة how to use remote-run-ssh remote-run-ssh setup guide remote-run-ssh vs docker what is remote-run-ssh remote-run-ssh alternative remote-run-ssh install ssh remote gpu cvlization examples cuda remote training 远程SSH运行 CVlization示例 CUDA加速 Docker 高效训练 AI工具 AIエージェント Operates CVlization examples on remote GPUs via SSH Minimizes remote copy to just the target example folder and cvlization library Utilizes example''s own build.sh and train.sh Docker helpers Keeps user''s long-lived checkout on the remote untouched Supports heavy trainings or evaluations requiring CUDA remote-run-ssh is a practical workflow for using and training vision and language models on remote GPUs reachable via SSH');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vercel/ai-elements/ai-elements', 'community', 'vercel', 'ai-elements', 'vercel/ai-elements', 'ai-elements', 0, 0, 54, '2026-03-08T01:57:15.277Z', '2026-03-08T02:01:19.794Z', '6e1697f6728f131cfbbb6b53543438921ce11faafcc4d5e0cc361b1643324e71', '{"id":"vercel/ai-elements/ai-elements","name":"ai-elements","description":{"en":"ai-elements is a component library and custom registry built on shadcn/ui, helping developers build AI-native applications faster with pre-built components.","zh":"ai-elements是shadcn/ui的组件库和自定义注册表，提供预建组件，如会话和消息等","ja":"ai-elementsはshadcn/uiのコンポーネントライブラリとカスタムレジストリで、会話やメッセージなどの事前構築コンポーネントを提供","ko":"ai-elements는 shadcn/ui 기반의 컴포넌트 라이브러리 및 사용자 정의 레지스트리로서 대화 및 메시지 등의 사전 구축 컴포넌트를 제공","es":"AI Elements es una biblioteca de componentes y registro personalizado construida sobre shadcn/ui para desarrollar aplicaciones de inteligencia artificial de manera más rápida","fr":"AI Elements est une bibliothèque de composants et un registre personnalisé construit sur shadcn/ui pour développer des applications d''intelligence artificielle plus rapidement","de":"AI Elements ist eine Komponentenbibliothek und ein benutzerdefinierter Registry, der auf shadcn/ui aufbaut, um KI-Anwendungen schneller zu entwickeln","pt":"O ai-elements é uma biblioteca de componentes e registro personalizado construída em cima do shadcn/ui para ajudar a construir aplicativos nativos de IA mais rápido","ru":"ИИ Агенты: ai-elements - это библиотека компонентов и пользовательский реестр, построенный на основе shadcn/ui для быстрой разработки приложений с искусственным интеллектом","ar":"ai-elements هو مكتبة مكونات وسجل مخصص مبني على shadcn/ui للمساعدة في بناء تطبيقات ذكاء اصطناعي أسرع"},"seo":{"title":{"en":"ai-elements: Setup Guide for AI-Native Applications | AI ...","zh":"AI元素快速集成指南 - ai-elements","ja":"AIエージェントのai-elementsセットアップガ