INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vercel/ai-elements/ai-elements', 'ai-elements', 'vercel', 'ai-elements', 'community', 'ai-elements vercel ai-elements community ai-elements is a component library and custom registry built on shadcn/ui, helping developers build AI-native applications faster with pre-built components. ai-elements是shadcn/ui的组件库和自定义注册表，提供预建组件，如会话和消息等 ai-elementsはshadcn/uiのコンポーネントライブラリとカスタムレジストリで、会話やメッセージなどの事前構築コンポーネントを提供 ai-elements는 shadcn/ui 기반의 컴포넌트 라이브러리 및 사용자 정의 레지스트리로서 대화 및 메시지 등의 사전 구축 컴포넌트를 제공 AI Elements es una biblioteca de componentes y registro personalizado construida sobre shadcn/ui para desarrollar aplicaciones de inteligencia artificial de manera más rápida AI Elements est une bibliothèque de composants et un registre personnalisé construit sur shadcn/ui pour développer des applications d''intelligence artificielle plus rapidement AI Elements ist eine Komponentenbibliothek und ein benutzerdefinierter Registry, der auf shadcn/ui aufbaut, um KI-Anwendungen schneller zu entwickeln O ai-elements é uma biblioteca de componentes e registro personalizado construída em cima do shadcn/ui para ajudar a construir aplicativos nativos de IA mais rápido ИИ Агенты: ai-elements - это библиотека компонентов и пользовательский реестр, построенный на основе shadcn/ui для быстрой разработки приложений с искусственным интеллектом ai-elements هو مكتبة مكونات وسجل مخصص مبني على shadcn/ui للمساعدة في بناء تطبيقات ذكاء اصطناعي أسرع how to use ai-elements ai-elements setup guide ai-elements vs shadcn/ui ai-elements install what is ai-elements ai-elements alternative ai-elements custom registry building AI-native applications with ai-elements ai-elements component library ai-elements shadcn/ui AI本地应用 组件库 自定义注册表 快速集成 CLI命令 前端开发 AI开发 Provides pre-built components like conversations and messages Built on top of shadcn/ui for seamless integration Supports installation via dedicated CLI command Integrates with standard shadcn/ui CLI for existing users Offers a custom registry for extended functionality Includes components for building AI-native applications faster ai-elements is a component library and custom registry built on top of shadcn/ui to accelerate AI-native application development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('acartag7/edictum/update-docs', 'community', 'acartag7', 'edictum', 'acartag7/edictum', 'update-docs', 0, 0, 54, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:22.157Z', '1729126bfca7be647201fb970f1da26b94a4e9ab9525dfda0b17a7e11bc46dc2', '{"id":"acartag7/edictum/update-docs","name":"update-docs","description":{"en":"The update-docs skill ensures documentation stays in sync with code changes, providing runtime safety for AI agents. It benefits developers by preventing errors and maintaining accurate documentation.","zh":"更新文档工具确保文档与代码更改保持同步，运行于每个PR之前或期间以防止代码破坏","ja":"ドキュメント更新ツールは、文書をコードの変更と同期させ、PRの実行前にまたは中に実行してコードの破壊を防ぎます","ko":"문서 업데이트 툴은 문서를 코드 변경과 동기화하고, 각 PR 실행 전 또는 중에 코드가 파괴되는 것을 방지합니다","es":"Update-docs es una habilidad que garantiza la seguridad en tiempo de ejecución para agentes de inteligencia artificial, deteniéndolos antes de que causen daños. Mantiene la documentación sincronizada con los cambios de código.","fr":"Update-docs est une compétence qui assure la sécurité d''exécution pour les agents d''intelligence artificielle, les arrêtant avant qu''ils ne causent des dommages. Elle maintient la documentation à jour avec les modifications de code.","de":"Update-Docs ist eine Fähigkeit, die die Laufzeitsicherheit für künstliche Intelligenz-Agenten gewährleistet, indem sie diese vor Schäden stoppt. Sie hält die Dokumentation mit den Code-Änderungen synchron.","pt":"O update-docs é uma habilidade que garante a documentação esteja sincronizada com as alterações de código, utilizando comandos Git e mapeamento de alterações","ru":"update-docs - навык, который обеспечивает синхронизацию документации с изменениями кода, используя команды Git и сопоставление изменений","ar":"update-docs هو مهارة تضمن أن البوثائق تتطابق مع التغييرات في الكود، باستخدام أوامر Git وربط التغييرات"},"seo":{"title":{"en":"update-docs: Runtime Safety Setup Guide | AI Agent Skill","zh":"更新文档工具：AI智能代理安全运行指南","ja":"ドキュメント更新ツール：AIエージェントの安全な実行方法","ko":"문서 업데이트 툴: AI 에이전트 런타임 안전 가이드","es":"Guía de configuración de update-docs para agentes de inte...","fr":"Configurer update-docs pour les agents d''intelligence art...","de":"Update-Docs-Setup-Leitfaden für künstliche Intelligenz-Ag...","pt":"Guia de Configuração do update-docs para Ferramentas de IA","ru":"Настройка update-docs для ИИ Агентов: Руководство","ar":"دليل إعداد update-docs لأدوات الذكاء الاصطناعي"},"description":{"en":"Prevent AI agents from breaking things! Learn how to use update-docs for runtime safety and sync documentation with code changes. Get started now!","zh":"了解更新文档工具如何确保AI智能代理的运行安全，防止代码更改破坏文档","ja":"AIエージェントの実行安全を確保するために、ドキュメント更新ツールがどのように機能するかをご紹介します","ko":"문서 업데이트 툴이 AI 에이전트 런타임 안전을 어떻게 보장하는지 알아보세요","es":"Aprende a mantener la documentación actualizada con los cambios de código en tus agentes de inteligencia artificial con update-docs","fr":"Découvrez comment maintenir votre documentation à jour avec les modifications de code dans vos agents d''intelligence artificielle grâce à update-docs","de":"Erfahren Sie, wie Sie Ihre Dokumentation mit update-docs auf dem neuesten Stand halten, wenn Sie Änderungen am Code Ihrer künstlichen Intelligenz-Agenten vor...","pt":"Aprenda a manter a documentação sincronizada com as alterações de código usando o update-docs para Ferramentas de IA","ru":"Обеспечьте безопасность работы ИИ Агентов с помощью update-docs и поддерживайте документацию в актуальном состоянии","ar":"discover كيفية الحفاظ على توافق الوثائق مع التغييرات في الكود باستخدام update-docs لأدوات الذكاء الاصطناعي"},"definition":{"en":"update-docs is a runtime safety skill that ensures documentation stays up-to-date with code changes, preventing AI agents from causing errors.","zh":"更新文档工具是一种确保AI智能代理文档与代码更改保持一致的技术","ja":"ドキュメント更新ツールは、AIエージェントの文書をコードの変更と一致させる技術です","ko":"문서 업데이트 툴은 AI 에이전트 문서를 코드 변경과 일치시키는 기술입니다","es":"Update-docs es una habilidad que mantiene la documentación actualizada y sincronizada con los cambios de código en agentes de inteligencia artificial","fr":"Update-docs est une compétence qui maintient la documentation à jour et synchronisée avec les modifications de code dans les agents d''intelligence artificielle","de":"Update-Docs ist eine Fähigkeit, die die Dokumentation auf dem neuesten Stand hält und mit den Code-Änderungen in künstlichen Intelligenz-Agenten synchronisiert","pt":"O update-docs é uma habilidade de segurança em tempo de execução para Ferramentas de IA que mantém a documentação atualizada","ru":"update-docs - навык безопасности runtime для ИИ Агентов, который поддерживает документацию в актуальном состоянии","ar":"update-docs هو مهارة أمان زمن التشغيل لأدوات الذكاء الاصطناعي التي تحتفظ بالوثائق محدثة"},"features":{"en":["Runs git diff command to detect changes","Maps changes to affected documentation pages","Requires reading of CLAUDE.md for understanding boundaries","References .docs-style-guide.md for terminology binding","Supports synchronization of documentation with library code changes"],"zh":["自动检测代码更改","映射更改到受影响的文档页面","支持git diff命令","与代码库同步文档"],"ja":["コードの変更を自動で検出","変更を影響を受けるドキュメントページにマッピング","git diffコマンドのサポート","コードリポジトリとドキュメントを同期"],"ko":["코드 변경 자동 감지","변경을 영향 받는 문서 페이지에 매핑","git diff 명령어 지원","코드 저장소와 문서 동기화"],"es":["Detección de cambios de código con git diff","Actualización de documentación con cambios de código","Compatibilidad con bibliotecas de código","Seguridad en tiempo de ejecución para agentes de inteligencia artificial","Integración con CLAUDE.md y .docs-style-guide.md"],"fr":["Détection des modifications de code avec git diff","Mise à jour de la documentation avec les modifications de code","Compatibilité avec les bibliothèques de code","Sécurité d''exécution pour les agents d''intelligence artificielle","Intégration avec CLAUDE.md et .docs-style-guide.md"],"de":["Erkennung von Code-Änderungen mit git diff","Aktualisierung der Dokumentation mit Code-Änderungen","Kompatibilität mit Code-Bibliotheken","Laufzeitsicherheit für künstliche Intelligenz-Agenten","Integration mit CLAUDE.md und .docs-style-guide.md"],"pt":["Detecção de alterações de código usando `git diff`","Mapeamento de alterações para páginas de documentação afetadas","Compatibilidade com bibliotecas de código","Suporte à documentação de estilo com `.docs-style-guide.md`","Leitura de arquivos de configuração como `CLAUDE.md`"],"ru":["Обнаружение изменений кода с помощью `git diff`","Сопоставление изменений с затронутыми страницами документации","Совместимость с библиотеками кода","Поддержка документации стиля с `.docs-style-guide.md`","Чтение файлов конфигурации, таких как `CLAUDE.md`"],"ar":["اكتشاف التغييرات في الكود باستخدام `git diff`","ربط التغييرات مع صفحات الوثائق المتأثرة","التوافق مع مكتبات الكود","دعم توثيق النمط مع `.docs-style-guide.md`","قراءة ملفات التكوين مثل `CLAUDE.md`"]},"keywords":{"en":["how to use update-docs","update-docs setup guide","runtime safety for AI agents","update-docs vs documentation tools","update-docs install","what is update-docs","update-docs alternative","update-docs for developers","git diff command","documentation synchronization"],"zh":["AI智能代理安全","文档更新工具","代码更改检测","git diff命令","文档同步","代码库管理"],"ja":["AIエージェントの安全","ドキュメント更新ツール","コードの変更検出","git diffコマンド","ドキュメントの同期","コードリポジトリ管理"],"ko":["AI 에이전트 런타임 안전","문서 업데이트 툴","코드 변경 감지","git diff 명령어","문서 동기화","코드 저장소 관리"],"es":["update-docs","agentes de inteligencia artificial","seguridad en tiempo de ejecución","documentación actualizada","git diff","CLAUDE.md","bibliotecas de código","configuración de update-docs"],"fr":["update-docs","agents d''intelligence artificielle","sécurité d''exécution","documentation à jour","git diff","CLAUDE.md","bibliothèques de code","configuration de update-docs"],"de":["update-docs","künstliche Intelligenz-Agenten","Laufzeitsicherheit","aktualisierte Dokumentation","git diff","CLAUDE.md","Code-Bibliotheken","Konfiguration von update-docs"],"pt":["update-docs","Ferramentas de IA","segurança em tempo de execução","documentação de código","Git","bibliotecas de código","desenvolvimento de software"],"ru":["update-docs","ИИ Агенты","безопасность runtime","документация кода","Git","библиотеки кода","разработка программного обеспечения"],"ar":["update-docs","أدوات الذكاء الاصطناعي","أمان زمن التشغيل","توثيق الكود","Git","مكتبات الكود","تطوير البرمجيات"]}},"owner":"acartag7","repo":"edictum","repoPath":"acartag7/edictum","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"update-docs","description":"Sync documentation with code changes. Use on every PR that touches library code to keep docs accurate and consistent.","bodyPreview":"# Update Docs\n\nEnsures documentation stays in sync with code changes. Run before or during every PR that touches library code.\n\n## Before anything else\n\n1. **Read CLAUDE.md** — understand boundaries (core vs server), dropped features, and session model\n2. **Read .docs-style-guide.md** — binding terminology reference\n\n## Step 1: Detect what changed\n\n```bash\ngit diff main...HEAD --name-only\n```\n\nMap changes to affected docs:\n\n| Source file | Affected doc pages |\n|---|---|\n| `src/edictum/pipeline.p","body":"# Update Docs\n\nEnsures documentation stays in sync with code changes. Run before or during every PR that touches library code.\n\n## Before anything else\n\n1. **Read CLAUDE.md** — understand boundaries (core vs server), dropped features, and session model\n2. **Read .docs-style-guide.md** — binding terminology reference\n\n## Step 1: Detect what changed\n\n```bash\ngit diff main...HEAD --name-only\n```\n\nMap changes to affected docs:\n\n| Source file | Affected doc pages |\n|---|---|\n| `src/edictum/pipeline.py`, `contracts.py` | concepts/how-it-works.md, architecture.md |\n| `src/edictum/yaml_engine/` | contracts/yaml-reference.md, contracts/operators.md |\n| `src/edictum/adapters/*.py` | corresponding adapters/*.md page |\n| `src/edictum/session.py`, `limits.py` | concepts/contracts.md, architecture.md |\n| `src/edictum/audit.py`, `telemetry.py` | audit/sinks.md, audit/telemetry.md |\n| `src/edictum/cli/` | cli.md |\n| `src/edictum/envelope.py` | concepts/principals.md, architecture.md |\n| `pyproject.toml` (version) | install commands across docs |\n| `src/edictum/__init__.py` (API) | quickstart.md, all adapter pages |\n\nIf no library code changed (docs-only PR), skip to Step 4.\n\n## Step 2: Read the changed code\n\nFor each changed file:\n1. Read the file and the diff (`git diff main...HEAD -- <file>`)\n2. Identify: new public APIs, changed signatures, new classes, removed exports, changed behavior\n\n## Step 3: Update affected docs\n\nFor each affected page:\n1. Read the current doc\n2. Skip if already correct\n3. Update code examples, descriptions, YAML examples\n4. **Verify \"When to use this\" section** exists (see .docs-style-guide.md page structure pattern step 3):\n   - Every page MUST have a `## When to use this` section after the opening/example and before the main content\n   - If missing, add one with: 2-4 concrete scenarios (real situations, not abstract descriptions), user personas who benefit, and how this feature relates to other Edictum features\n   - If new code adds a feature, update the scenarios to cover the new capability\n   - Read the ACTUAL SOURCE CODE for the feature before writing scenarios — reference real method names, real classes, real behavior\n5. **Verify terminology** against .docs-style-guide.md:\n   - \"contracts\" not \"policies\" or \"rules\"\n   - Use `denied` (see .docs-style-guide.md for banned alternatives)\n   - Use `enforces` (not \"governs\")\n   - Use `pipeline` (not \"engine\")\n   - Use `tool call` (not \"function call\")\n   - Use `adapter` (not \"integration\" or \"plugin\")\n   - Use `observe mode` (see .docs-style-guide.md for banned alternatives)\n   - Use `finding` / `findings` (not \"alert\")\n6. **Verify core vs server boundaries** against CLAUDE.md:\n   - All contract evaluation (pre, post, session, sandbox) is core\n   - StdoutAuditSink, FileAuditSink, OTel are core\n   - Production approval workflows (ServerApprovalBackend) require the server\n   - Centralized audit dashboards require the server\n   - Multi-process session tracking requires the server\n   - MemoryBackend is the only local StorageBackend (no Redis/DB)\n   - No references to dropped features or ee/ tier\n\n## Step 3.5: Update repo-level markdown files\n\nThese files live outside `docs/` but track code changes:\n\n1. **CHANGELOG.md** — if the PR introduces user-visible changes (fixes, features, breaking changes), add an entry under the current version heading. Use the existing entry format. Keep descriptions neutral (no exploit details for security fixes).\n2. **CLAUDE.md \"What''s Shipped\" section** — if this is a new version, add a one-line entry to the version history list matching the existing format.\n\n## Step 4: Update README if needed\n\nIf public API, install extras, framework support, or version changed:\n1. Read README.md\n2. Update affected sections\n3. Ensure README matches docs/index.md positioning\n\n## Step 5: Verify the build\n\n```bash\npython -m mkdocs build --strict 2>&1\n```\n\nFix any broken links, missing pages, or YAML errors.\n\n## Step 6: Report\n\nSummarize:\n- Which code files changed\n- Which doc pages were updated (and what changed)\n- Which doc pages were checked but needed no changes\n- Build verification result\n\n## Rules\n\n- **Don''t rewrite for the sake of rewriting.** Only update what the code change actually affects.\n- **Don''t add features that don''t exist.** If code was added but not released, note it as unreleased.\n- **Don''t reference dropped features.** No Redis/DB StorageBackend, no reset_session().\n- **Preserve the voice.** Match existing style — problem first, short paragraphs, code examples.\n- **Check cross-links.** Verify links in updated pages still work.\n- **README and homepage must stay aligned.** If you update one, check the other.\n"},"lastSynced":"2026-03-08T02:01:22.157Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Maintenance Agents needing automated documentation updates.","zh":"非常适合需要自动文档更新的代码维护代理。","ja":"コードメンテナンスエージェントが自動ドキュメント更新を必要とする場合に最適です。","ko":"자동 문서 업데이트가 필요한 코드 유지 보수 에이전트에 적합합니다.","es":"Perfecto para Agentes de Mantenimiento de Código que necesitan actualizaciones de documentación automatizadas.","fr":"Parfait pour les Agents de Maintenance de Code nécessitant des mises à jour de documentation automatisées.","de":"Perfekt für Code-Maintenance-Agenten, die automatisierte Dokumentationsaktualisierungen benötigen.","pt":"Perfeito para Agentes de Manutenção de Código que precisam de atualizações de documentação automatizadas.","ru":"Идеально подходит для агентов по сопровождению кода, которым необходимы автоматические обновления документации.","ar":"مثالي للوكلاء الذين يحتاجون إلى تحديثات وثائقية آلية"},"recommendation":{"en":"Empowers agents to ensure documentation stays in sync with code changes, providing runtime safety through git diff analysis and automated doc updates, utilizing files like CLAUDE.md and .docs-style-guide.md.","zh":"赋予代理确保文档与代码更改保持同步的能力，通过git diff分析和自动文档更新提供运行时安全，利用CLAUDE.md和.docs-style-guide.md等文件。","ja":"エージェントがコードの変更とドキュメントを同期させ、git diff分析と自動ドキュメント更新を使用してランタイムの安全性を提供することを可能にし、CLAUDE.mdや.docs-style-guide.mdなどのファイルを使用します。","ko":"에이전트가 코드 변경과 문서를 동기화할 수 있도록 하며, git diff 분석과 자동 문서 업데이트를 통해 런타임 안전성을 제공하며, CLAUDE.md 및 .docs-style-guide.md와 같은 파일을 사용합니다.","es":"Habilita a los agentes a asegurarse de que la documentación se mantenga sincronizada con los cambios de código, proporcionando seguridad en tiempo de ejecución a través del análisis de git diff y actualizaciones de documentación automatizadas, utilizando archivos como CLAUDE.md y .docs-style-guide.md.","fr":"Permet aux agents de s''assurer que la documentation reste synchronisée avec les modifications de code, en fournissant une sécurité à l''exécution grâce à l''analyse de git diff et aux mises à jour de documentation automatisées, en utilisant des fichiers comme CLAUDE.md et .docs-style-guide.md.","de":"Ermächtigt die Agenten, sicherzustellen, dass die Dokumentation mit den Code-Änderungen synchron bleibt, indem sie Laufzeit-Sicherheit durch git diff-Analyse und automatisierte Dokumentations-Updates bietet, unter Verwendung von Dateien wie CLAUDE.md und .docs-style-guide.md.","pt":"Habilita os agentes a garantirem que a documentação permaneça sincronizada com as alterações de código, fornecendo segurança em tempo de execução por meio da análise de git diff e atualizações de documento automatizadas, utilizando arquivos como CLAUDE.md e .docs-style-guide.md.","ru":"Наделяет агентов возможностью обеспечить актуальность документации при изменениях кода, предоставляя безопасность во время выполнения за счет анализа git diff и автоматических обновлений документации, используя файлы, такие как CLAUDE.md и .docs-style-guide.md.","ar":"يمنح الوكلاء القدرة على ضمان مواكبة الوثائق للتغييرات في الكود، مع توفير سلامة زمن التشغيل من خلال تحليل git diff وتحديثات وثائقية آلية، باستخدام ملفات مثل CLAUDE.md و .docs-style-guide.md"},"useCases":{"en":["Automating documentation updates for library code changes","Detecting affected doc pages through git diff analysis","Maintaining accurate documentation to prevent errors"],"zh":["为库代码更改自动更新文档","通过git diff分析检测受影响的文档页面","维护准确的文档以防止错误"],"ja":["ライブラリコードの変更に対するドキュメントの自動更新","git diff分析を使用して影響を受けるドキュメントページを検出","エラーを防ぐために正確なドキュメントを維持"],"ko":["라이브러리 코드 변경에 대한 문서 자동 업데이트","git diff 분석을 사용하여 영향을 받는 문서 페이지를 감지","오류를 방지하기 위해 정확한 문서를 유지"],"es":["Automatización de actualizaciones de documentación para cambios de código de biblioteca","Detección de páginas de documentación afectadas a través del análisis de git diff","Mantenimiento de documentación precisa para prevenir errores"],"fr":["Automatisation des mises à jour de documentation pour les modifications de code de bibliothèque","Détection des pages de documentation affectées via l''analyse de git diff","Maintenance d''une documentation précise pour prévenir les erreurs"],"de":["Automatisierung von Dokumentations-Updates für Bibliotheks-Code-Änderungen","Erkennung von betroffenen Dokumentationsseiten durch git diff-Analyse","Beibehaltung genauer Dokumentation, um Fehler zu vermeiden"],"pt":["Automatizar atualizações de documentação para alterações de código de biblioteca","Detectar páginas de documentação afetadas por meio da análise de git diff","Manter documentação precisa para prevenir erros"],"ru":["Автоматизировать обновления документации для изменений кода библиотеки","Обнаруживать страницы документации, затронутые анализом git diff","Поддерживать точную документацию для предотвращения ошибок"],"ar":["توفير تحديثات وثائقية آلية لتغييرات كود المكتبة","اكتشاف صفحات الوثائق المتأثرة من خلال تحليل git diff","الحفاظ على وثائق دقيقة لمنع الأخطاء"]},"limitations":{"en":["Requires git repository access","Limited to library code changes","Needs understanding of CLAUDE.md and .docs-style-guide.md"],"zh":["需要git仓库访问","仅限库代码更改","需要了解CLAUDE.md和.docs-style-guide.md"],"ja":["gitリポジトリへのアクセスが必要","ライブラリコードの変更のみ","CLAUDE.mdと.docs-style-guide.mdの理解が必要"],"ko":["git 저장소 접근이 필요","라이브러리 코드 변경만 해당","CLAUDE.md 및 .docs-style-guide.md에 대한 이해가 필요"],"es":["Requiere acceso al repositorio git","Limitado a cambios de código de biblioteca","Necesita comprensión de CLAUDE.md y .docs-style-guide.md"],"fr":["Nécessite un accès au référentiel git","Limité aux modifications de code de bibliothèque","Nécessite une compréhension de CLAUDE.md et .docs-style-guide.md"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf Bibliotheks-Code-Änderungen","Benötigt Verständnis von CLAUDE.md und .docs-style-guide.md"],"pt":["Requer acesso ao repositório git","Limitado a alterações de código de biblioteca","Necessita de compreensão de CLAUDE.md e .docs-style-guide.md"],"ru":["Требует доступа к репозиторию git","Ограничен изменением кода библиотеки","Требует понимания CLAUDE.md и .docs-style-guide.md"],"ar":["يتطلب الوصول إلى مستودع git","محدود بتغييرات كود المكتبة","يحتاج إلى فهم CLAUDE.md و .docs-style-guide.md"]},"version":4},"contentHash":"1729126bfca7be647201fb970f1da26b94a4e9ab9525dfda0b17a7e11bc46dc2","qualityScore":54}');
