INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('acartag7/edictum/update-docs', 'update-docs', 'acartag7', 'edictum', 'community', 'update-docs acartag7 edictum community The update-docs skill ensures documentation stays in sync with code changes, providing runtime safety for AI agents. It benefits developers by preventing errors and maintaining accurate documentation. 更新文档工具确保文档与代码更改保持同步，运行于每个PR之前或期间以防止代码破坏 ドキュメント更新ツールは、文書をコードの変更と同期させ、PRの実行前にまたは中に実行してコードの破壊を防ぎます 문서 업데이트 툴은 문서를 코드 변경과 동기화하고, 각 PR 실행 전 또는 중에 코드가 파괴되는 것을 방지합니다 Update-docs es una habilidad que garantiza la seguridad en tiempo de ejecución para agentes de inteligencia artificial, deteniéndolos antes de que causen daños. Mantiene la documentación sincronizada con los cambios de código. Update-docs est une compétence qui assure la sécurité d''exécution pour les agents d''intelligence artificielle, les arrêtant avant qu''ils ne causent des dommages. Elle maintient la documentation à jour avec les modifications de code. Update-Docs ist eine Fähigkeit, die die Laufzeitsicherheit für künstliche Intelligenz-Agenten gewährleistet, indem sie diese vor Schäden stoppt. Sie hält die Dokumentation mit den Code-Änderungen synchron. O update-docs é uma habilidade que garante a documentação esteja sincronizada com as alterações de código, utilizando comandos Git e mapeamento de alterações update-docs - навык, который обеспечивает синхронизацию документации с изменениями кода, используя команды Git и сопоставление изменений update-docs هو مهارة تضمن أن البوثائق تتطابق مع التغييرات في الكود، باستخدام أوامر Git وربط التغييرات how to use update-docs update-docs setup guide runtime safety for AI agents update-docs vs documentation tools update-docs install what is update-docs update-docs alternative update-docs for developers git diff command documentation synchronization AI智能代理安全 文档更新工具 代码更改检测 git diff命令 文档同步 代码库管理 Runs git diff command to detect changes Maps changes to affected documentation pages Requires reading of CLAUDE.md for understanding boundaries References .docs-style-guide.md for terminology binding Supports synchronization of documentation with library code changes update-docs is a runtime safety skill that ensures documentation stays up-to-date with code changes, preventing AI agents from causing errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Jasrags/ShadowMaster/shadowrun-aesthetic', 'community', 'Jasrags', 'ShadowMaster', 'Jasrags/ShadowMaster', 'shadowrun-aesthetic', 0, 0, 54, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:28.282Z', '6aed86a708cb69b3c2f4485518c7cfeaca9f0089fa8328b705e0796503009f80', '{"id":"Jasrags/ShadowMaster/shadowrun-aesthetic","name":"shadowrun-aesthetic","description":{"en":"The shadowrun-aesthetic skill helps developers create distinctive UI for Shadowrun, supporting multiple editions and interfaces. It balances precision, density, and usability for a character management tool.","zh":"Shadowrun-aesthetic 技能提供了创建独特 UI 设计的指南，捕捉 Shadowrun 的赛博朋克美学风格，支持多个版本和接口","ja":"Shadowrun-aesthetic スキルは、Shadowrun のサイバーパンク美学を捉えた独自の UI デザインを作成するためのガイドを提供します","ko":"Shadowrun-aesthetic 스킬은 Shadowrun의 사이버펑크 미학을 담은 고유한 UI 디자인을 만드는 데 필요한 가이드를 제공합니다","es":"Shadowrun Aesthetic es un sistema de gestión de RPG de mesa con soporte para múltiples ediciones y interfaces","fr":"L''esthétique Shadowrun est un système de gestion de RPG de table avec prise en charge de plusieurs éditions et interfaces","de":"Shadowrun-Aesthetic ist ein Tisch-RPG-Management-System mit Unterstützung für mehrere Editionen und Schnittstellen","pt":"O Shadowrun-Aesthetic é um sistema de gerenciamento de RPG de mesa para Shadowrun com suporte a várias edições e interfaces. Ele fornece uma experiência de usuário personalizada e estendível.","ru":"Shadowrun-Aesthetic - это система управления настольными RPG для Shadowrun с поддержкой нескольких изданий и интерфейсов. Она обеспечивает настраиваемый и расширяемый пользовательский опыт с помощью ИИ Агентов","ar":"Shadowrun-Aesthetic هو نظام لإدارة ألعاب RPG الطاولة لـ Shadowrun مع دعم لعدة إصدارات وواجهات. يوفر تجربة مستخدم مخصصة وقابلة للتوسيع"},"seo":{"title":{"en":"shadowrun-aesthetic: Cyberpunk UI Setup Guide | AI Agent ...","zh":"Shadowrun UI 设计指南：实现赛博朋克美学","ja":"Shadowrun UI デザインガイド：サイバーパンクエステティックの実現","ko":"Shadowrun UI 디자인 가이드: 사이버펑크 미학 구현","es":"Guía de configuración de Shadowrun Aesthetic para herrami...","fr":"Guide de mise en place de l''esthétique Shadowrun pour les...","de":"Einrichtungsleitfaden für Shadowrun-Aesthetic in AI-Tools","pt":"Guia de Configuração do Shadowrun-Aesthetic: Criação de I...","ru":"Настройка Shadowrun-Aesthetic: Создание Интерфейсов в Сти...","ar":"دليل إعداد Shadowrun-Aesthetic: إنشاء واجهات المستخدم الم..."},"description":{"en":"Unlock the Sixth World aesthetic with shadowrun-aesthetic. Learn how to create production-grade UI for Shadowrun with our expert guide and take your tabletop...","zh":"了解如何使用 Shadowrun-aesthetic 技能创建独特的 UI 设计，捕捉赛博朋克的美学风格，适用于多个版本和接口","ja":"Shadowrun-aesthetic スキルを使用して、サイバーパンクの美学を捉えた独自の UI デザインを作成する方法を学びます","ko":"Shadowrun-aesthetic 스킬을 사용하여 사이버펑크 미학을 담은 고유한 UI 디자인을 만드는 방법 알아보기","es":"Descubre cómo crear interfaces de usuario distintivas para Shadowrun con soporte para múltiples ediciones y interfaces","fr":"Découvrez comment créer des interfaces utilisateur distinctives pour Shadowrun avec prise en charge de plusieurs éditions et interfaces","de":"Erfahren Sie, wie Sie eine benutzerdefinierte Oberfläche für Shadowrun erstellen, mit Unterstützung für mehrere Editionen und Schnittstellen","pt":"Aprenda a criar interfaces de usuário personalizadas para o Shadowrun com o skill Shadowrun-Aesthetic, incluindo suporte a várias edições e interfaces","ru":"Узнайте, как создать настраиваемые интерфейсы пользователя для Shadowrun с помощью навыка Shadowrun-Aesthetic, включая поддержку нескольких изданий и интерфе...","ar":"تعرف على كيفية إنشاء واجهات مستخدم مخصصة لـ Shadowrun باستخدام مهارة Shadowrun-Aesthetic، بما في ذلك الدعم لعدة إصدارات وواجهات"},"definition":{"en":"shadowrun-aesthetic is a tabletop RPG management system UI design philosophy that captures the cyberpunk aesthetic of Shadowrun with a focus on precision, density, and usability.","zh":"Shadowrun-aesthetic 是一种 tabletop RPG 管理系统的 UI 设计指南，用于创建捕捉赛博朋克美学风格的独特界面","ja":"Shadowrun-aesthetic は、サイバーパンク美学を捉えた独自の UI デザインを作成するためのテーブルトップ RPG 管理システムのガイドです","ko":"Shadowrun-aesthetic은 사이버펑크 미학을 담은 고유한 UI 디자인을 만드는 데 필요한 테이블톱 RPG 관리 시스템의 가이드입니다","es":"Shadowrun Aesthetic es una guía para crear interfaces de usuario con estética ciberpunk","fr":"L''esthétique Shadowrun est une guide pour créer des interfaces utilisateur avec une esthétique cyberpunk","de":"Shadowrun-Aesthetic ist eine Anleitung zur Erstellung von Benutzeroberflächen mit Cyberpunk-Ästhetik","pt":"O Shadowrun-Aesthetic é um skill que cria interfaces de usuário personalizadas para o Shadowrun, combinando estética ciberpunk com usabilidade","ru":"Shadowrun-Aesthetic - это навык, создающий настраиваемые интерфейсы пользователя для Shadowrun, сочетающий киберпанк-эстетику с удобством использования с помощью ИИ Агентов","ar":"Shadowrun-Aesthetic هو مهارة تتيح إنشاء واجهات مستخدم مخصصة لـ Shadowrun، مما يجمع بين الجماليات الإلكترونية وال kolayية في الاستخدام"},"features":{"en":["Supports multiple Shadowrun editions (SR3, SR5)","Provides multiple interfaces (web and CLI) for user interaction","Allows for extensibility to support future editions","Captures the Sixth World aesthetic with neon-lit interfaces and information density","Balances precision and density for a user-friendly character management tool","Enables creation of production-grade UI for Shadowrun"],"zh":["支持多个版本（SR3、SR5）","多个接口支持（Web 和 CLI）","可扩展性以支持未来版本","实现赛博朋克美学风格的 UI 设计","信息密度和视觉清晰度的平衡","精确度和密度的设计哲学"],"ja":["複数のバージョン（SR3、SR5）をサポート","複数のインターフェース（Web と CLI）をサポート","将来のバージョンをサポートするための拡張性","サイバーパンク美学を捉えた UI デザインの実現","情報密度と視覚的クリアランスをバランス","精密度と密度のデザイン哲学"],"ko":["여러 버전(SR3, SR5) 지원","여러 인터페이스(Web 및 CLI) 지원"," 将来的 버전을 지원하기 위한 확장성","사이버펑크 미학을 담은 UI 디자인 구현","정보 밀도와 시각적 명확도를 균형","정밀도와 밀도의 디자인 철학"],"es":["Soporte para múltiples ediciones de Shadowrun (SR3, SR5)","Interfaz web y CLI","Extensibilidad para futuras ediciones","Diseño de interfaz de usuario con estética ciberpunk","Equilibrio entre precisión y densidad de información","Tecnología que combina lo avanzado con lo desgastado"],"fr":["Prise en charge de plusieurs éditions de Shadowrun (SR3, SR5)","Interface web et CLI","Extensibilité pour les futures éditions","Conception d''interface utilisateur avec une esthétique cyberpunk","Équilibre entre précision et densité d''information","Technologie qui combine l''avancé et l''usé"],"de":["Unterstützung für mehrere Editionen von Shadowrun (SR3, SR5)","Web- und CLI-Schnittstelle","Erweiterbarkeit für zukünftige Editionen","Benutzeroberflächen-Design mit Cyberpunk-Ästhetik","Gleichgewicht zwischen Präzision und Informationsdichte","Technologie, die Avanciertes und Abgenutztes kombiniert"],"pt":["Suporte a várias edições do Shadowrun (SR3, SR5)","Suporte a várias interfaces (web e CLI)","Extensibilidade para futuras edições","Experiência de usuário personalizada e estendível","Interface de usuário em estilo ciberpunk","Densidade de informações sem bagunça visual"],"ru":["Поддержка нескольких изданий Shadowrun (SR3, SR5)","Поддержка нескольких интерфейсов (веб и CLI)","Расширяемость для будущих изданий","Настройка и расширяемость пользовательского опыта","Интерфейс пользователя в стиле киберпанк","Плотность информации без визуального шума с помощью ИИ Агентов"],"ar":["دعم لعدة إصدارات من Shadowrun (SR3, SR5)","دعم لعدة واجهات (ويب و CLI)","امتداد للاصدارات المستقبلية","تجربة مستخدم مخصصة وقابلة للتوسيع","واجهة المستخدم في نمط الجماليات الإلكترونية","كثافة المعلومات بدون فوضى بصرية"]},"keywords":{"en":["how to use shadowrun-aesthetic","shadowrun-aesthetic setup guide","shadowrun-aesthetic alternative","shadowrun-aesthetic vs other RPG management systems","shadowrun-aesthetic install","what is shadowrun-aesthetic","shadowrun-aesthetic UI design","cyberpunk UI aesthetic","tabletop RPG management system","Shadowrun character management tool"],"zh":["Shadowrun-aesthetic","AIエージェント","UI 设计","赛博朋克美学","tabletop RPG","多版本支持","多接口支持","可扩展性","信息密度","视觉清晰度"],"ja":["Shadowrun-aesthetic","AIエージェント","UI デザイン","サイバーパンク美学","テーブルトップ RPG","複数のバージョンをサポート","複数のインターフェースをサポート","将来のバージョンをサポート","情報密度","視覚的クリアランス"],"ko":["Shadowrun-aesthetic","AI 에이전트","UI 디자인","사이버펑크 미학","테이블톱 RPG","여러 버전 지원","여러 인터페이스 지원","将来的 버전 지원","정보 밀도","시각적 명확도"],"es":["Shadowrun Aesthetic","herramientas de AI","RPG de mesa","estética ciberpunk","interfaz de usuario","edición SR3","edición SR5","CLI","web"],"fr":["esthétique Shadowrun","outils d''IA","RPG de table","esthétique cyberpunk","interface utilisateur","édition SR3","édition SR5","CLI","web"],"de":["Shadowrun-Aesthetic","AI-Tools","Tisch-RPG","Cyberpunk-Ästhetik","Benutzeroberfläche","Edition SR3","Edition SR5","CLI","Web"],"pt":["Shadowrun-Aesthetic","Interface de usuário ciberpunk","Sistema de gerenciamento de RPG de mesa","Suporte a várias edições","Suporte a várias interfaces","Extensibilidade","Experiência de usuário personalizada","Desenvolvimento de interfaces de usuário"],"ru":["Shadowrun-Aesthetic","Интерфейс пользователя в стиле киберпанк","Система управления настольными RPG","Поддержка нескольких изданий","Поддержка нескольких интерфейсов","Расширяемость","Настройка пользовательского опыта","Разработка интерфейсов пользователя с помощью ИИ Агентов"],"ar":["Shadowrun-Aesthetic","واجهة المستخدم في نمط الجماليات الإلكترونية","نظام لإدارة ألعاب RPG الطاولة","دعم لعدة إصدارات","دعم لعدة واجهات","امتداد","تجربة مستخدم مخصصة","تطوير واجهات المستخدم"]}},"owner":"Jasrags","repo":"ShadowMaster","repoPath":"Jasrags/ShadowMaster","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"shadowrun-aesthetic","description":"Applies Shadowrun cyberpunk aesthetic to UI components. Use when building character sheets, creation cards, gear panels, modal dialogs, or any SR-themed interface elements. Combines systematic craft principles with the distinctive visual language of the Sixth World.","bodyPreview":"# Shadowrun UI Aesthetic\n\nThis skill guides the creation of distinctive, production-grade UI that captures the cyberpunk aesthetic of Shadowrun while maintaining the usability required for a character management tool.\n\n## Design Philosophy\n\n**The Sixth World aesthetic**: Corporate sleek meets street grit. Neon-lit interfaces emerging from darkness. Information density without visual clutter. Technology that feels both advanced and worn.\n\n**Balance two forces:**\n\n1. **Precision & Density** - User","body":"# Shadowrun UI Aesthetic\n\nThis skill guides the creation of distinctive, production-grade UI that captures the cyberpunk aesthetic of Shadowrun while maintaining the usability required for a character management tool.\n\n## Design Philosophy\n\n**The Sixth World aesthetic**: Corporate sleek meets street grit. Neon-lit interfaces emerging from darkness. Information density without visual clutter. Technology that feels both advanced and worn.\n\n**Balance two forces:**\n\n1. **Precision & Density** - Users spend hours in character creation; every pixel matters\n2. **Cyberpunk Atmosphere** - The UI should feel like a runner''s commlink interface\n\n## Color System\n\n### Primary Palette (Dark Mode Dominant)\n\n```css\n/* Backgrounds - layered darkness */\n--bg-base: #09090b; /* zinc-950 - deepest layer */\n--bg-elevated: #18181b; /* zinc-900 - cards, panels */\n--bg-surface: #27272a; /* zinc-800 - interactive surfaces */\n--bg-hover: #3f3f46; /* zinc-700 - hover states */\n\n/* Text hierarchy */\n--text-primary: #fafafa; /* zinc-50 - headings, important */\n--text-secondary: #a1a1aa; /* zinc-400 - body text */\n--text-muted: #71717a; /* zinc-500 - labels, hints */\n\n/* Borders */\n--border-subtle: #27272a; /* zinc-800 */\n--border-default: #3f3f46; /* zinc-700 */\n--border-emphasis: #52525b; /* zinc-600 */\n```\n\n### Accent Colors (Signature Shadowrun)\n\n```css\n/* Matrix Green - Primary accent for tech/positive */\n--accent-matrix: #00ff41;\n--accent-matrix-dim: #00cc34;\n--accent-matrix-glow: rgba(0, 255, 65, 0.15);\n\n/* Corp Blue - Secondary accent, professional */\n--accent-corp: #0ea5e9; /* sky-500 */\n--accent-corp-dim: #0284c7;\n\n/* Warning/Danger */\n--accent-warning: #f59e0b; /* amber-500 */\n--accent-danger: #ef4444; /* red-500 */\n\n/* Magic Purple - For awakened content */\n--accent-magic: #a855f7; /* purple-500 */\n\n/* Resonance Cyan - For technomancer content */\n--accent-resonance: #22d3ee; /* cyan-400 */\n```\n\n### Usage Guidelines\n\n- **Matrix green** for: success states, positive qualities, essence, magic rating\n- **Corp blue** for: links, selected states, primary actions\n- **Warning amber** for: budget overruns, caution states, negative qualities\n- **Danger red** for: errors, forbidden items, damage\n- **Magic purple** for: spells, rituals, foci, astral content\n- **Resonance cyan** for: complex forms, sprites, matrix content\n\n## Typography\n\n### Font Stack\n\n```css\n/* Body/UI - Clean, technical */\nfont-family:\n  ui-sans-serif,\n  system-ui,\n  -apple-system,\n  sans-serif;\n\n/* Stats & Numbers - ALWAYS monospace */\nfont-family: ui-monospace, \"SF Mono\", \"Fira Code\", monospace;\n```\n\n### Hierarchy Rules\n\n1. **Card titles**: `text-lg font-semibold` - zinc-100\n2. **Section headers**: `text-sm font-medium uppercase tracking-wide` - zinc-400\n3. **Body text**: `text-sm` - zinc-300\n4. **Labels**: `text-xs font-medium` - zinc-500\n5. **Stats/Numbers**: `font-mono text-base font-bold` - zinc-100\n\n### Critical Rule: Monospace for Data\n\nAll numerical data MUST use monospace:\n\n- Attribute values (BOD: 4)\n- Skill ratings\n- Costs (nuyen, karma, essence)\n- Dice pools\n- Damage codes\n\n## Spacing & Grid\n\n### 4px Base Grid\n\nAll spacing uses multiples of 4px:\n\n- `gap-1` (4px) - between inline elements\n- `gap-2` (8px) - between related items\n- `gap-3` (12px) - between sections within a card\n- `gap-4` (16px) - between cards\n- `p-4` (16px) - card padding\n- `p-3` (12px) - compact card padding\n\n### Card Patterns\n\n```tsx\n// Standard creation card\n<div className=\"rounded-lg border border-zinc-800 bg-zinc-900 p-4\">\n  <div className=\"mb-3 flex items-center justify-between\">\n    <h3 className=\"text-lg font-semibold text-zinc-100\">Card Title</h3>\n    <button className=\"text-sky-400 hover:text-sky-300\">Action</button>\n  </div>\n  {/* Content */}\n</div>\n\n// Elevated/modal surfaces\n<div className=\"rounded-lg border border-zinc-700 bg-zinc-800 p-4 shadow-xl\">\n```\n\n## Component Patterns\n\n### Stat Blocks\n\n```tsx\n// Attribute display - grid-based, monospace values\n<div className=\"grid grid-cols-3 gap-2\">\n  <div className=\"rounded border border-zinc-700 bg-zinc-800 p-2 text-center\">\n    <div className=\"text-xs font-medium uppercase text-zinc-500\">BOD</div>\n    <div className=\"font-mono text-xl font-bold text-zinc-100\">4</div>\n  </div>\n</div>\n```\n\n### Budget/Progress Bars\n\n```tsx\n// Essence/Karma/Nuyen tracking\n<div className=\"rounded-lg border border-zinc-700 bg-zinc-800 p-3\">\n  <div className=\"flex justify-between text-sm\">\n    <span className=\"text-zinc-400\">Essence</span>\n    <span className=\"font-mono font-bold text-emerald-400\">5.4 / 6.0</span>\n  </div>\n  <div className=\"mt-2 h-2 overflow-hidden rounded-full bg-zinc-700\">\n    <div className=\"h-full bg-emerald-500\" style={{ width: ''90%'' }} />\n  </div>\n</div>\n\n// Over-budget state\n<div className=\"rounded-lg border border-amber-800 bg-amber-900/20 p-3\">\n  <span className=\"font-mono font-bold text-amber-400\">-15 Karma</span>\n</div>\n```\n\n### List Items (Skills, Gear, Qualities)\n\n```tsx\n// Compact list row\n<div className=\"flex items-center justify-between rounded px-2 py-1.5 hover:bg-zinc-800\">\n  <div className=\"flex items-center gap-2\">\n    <span className=\"text-sm text-zinc-200\">Firearms</span>\n    <span className=\"text-xs text-zinc-500\">(Pistols)</span>\n  </div>\n  <span className=\"font-mono text-sm font-bold text-zinc-100\">6</span>\n</div>\n\n// With rating controls\n<div className=\"flex items-center gap-2\">\n  <button className=\"rounded p-1 text-zinc-400 hover:bg-zinc-700 hover:text-zinc-200\">\n    <Minus className=\"h-4 w-4\" />\n  </button>\n  <span className=\"w-8 text-center font-mono font-bold\">4</span>\n  <button className=\"rounded p-1 text-zinc-400 hover:bg-zinc-700 hover:text-zinc-200\">\n    <Plus className=\"h-4 w-4\" />\n  </button>\n</div>\n```\n\n### Modals\n\n```tsx\n// Modal overlay - use React Aria for accessibility\n<div className=\"fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm\">\n  <div className=\"max-h-[85vh] w-full max-w-2xl overflow-hidden rounded-lg border border-zinc-700 bg-zinc-900 shadow-2xl\">\n    {/* Header */}\n    <div className=\"flex items-center justify-between border-b border-zinc-800 p-4\">\n      <h2 className=\"text-lg font-semibold text-zinc-100\">Modal Title</h2>\n      <button className=\"rounded p-1 text-zinc-400 hover:bg-zinc-800 hover:text-zinc-200\">\n        <X className=\"h-5 w-5\" />\n      </button>\n    </div>\n    {/* Content */}\n    <div className=\"max-h-[60vh] overflow-y-auto p-4\">{/* Scrollable content */}</div>\n    {/* Footer */}\n    <div className=\"flex justify-end gap-2 border-t border-zinc-800 p-4\">\n      <button className=\"rounded-lg bg-zinc-700 px-4 py-2 text-sm font-medium text-zinc-200 hover:bg-zinc-600\">\n        Cancel\n      </button>\n      <button className=\"rounded-lg bg-sky-600 px-4 py-2 text-sm font-medium text-white hover:bg-sky-500\">\n        Confirm\n      </button>\n    </div>\n  </div>\n</div>\n```\n\n### Category Tabs\n\n```tsx\n// Gear/Equipment category selection\n<div className=\"flex gap-1 rounded-lg border border-zinc-700 bg-zinc-800 p-1\">\n  <button className=\"rounded-md bg-sky-600 px-3 py-1.5 text-sm font-medium text-white\">\n    Weapons\n  </button>\n  <button className=\"rounded-md px-3 py-1.5 text-sm font-medium text-zinc-400 hover:bg-zinc-700 hover:text-zinc-200\">\n    Armor\n  </button>\n  <button className=\"rounded-md px-3 py-1.5 text-sm font-medium text-zinc-400 hover:bg-zinc-700 hover:text-zinc-200\">\n    Cyberware\n  </button>\n</div>\n```\n\n## Cyberpunk Accents (Use Sparingly)\n\n### Subtle Glow Effects\n\n```tsx\n// For selected/active states only\n<div className=\"border-sky-500 shadow-[0_0_10px_rgba(14,165,233,0.3)]\">\n\n// For important values (essence, magic)\n<span className=\"text-emerald-400 drop-shadow-[0_0_4px_rgba(52,211,153,0.5)]\">\n```\n\n### Tech Panel Borders\n\n```tsx\n// Accent corner for \"high-tech\" feel\n<div className=\"relative rounded-lg border border-zinc-700 bg-zinc-900\">\n  <div className=\"absolute -top-px left-4 h-px w-8 bg-sky-500\" />\n  <div className=\"absolute -left-px top-4 h-8 w-px bg-sky-500\" />\n  {/* Content */}\n</div>\n```\n\n## Neon Card System (Dashboard & Lists)\n\nThe neon card system provides archetype-based visual identity with automatic light/dark mode adaptation. Defined in `app/globals.css`.\n\n### Archetype Colors (CSS Variables)\n\n```css\n/* Available in :root and .dark with different intensities */\n--accent-mage: #8b5cf6; /* Purple - full mages, aspected mages */\n--accent-sam: #10b981; /* Green - street samurai, mundane */\n--accent-rigger: #06b6d4; /* Cyan - riggers */\n--accent-decker: #3b82f6; /* Blue - deckers, technomancers */\n--accent-face: #f59e0b; /* Amber - faces, adepts */\n--accent-campaign: #6366f1; /* Indigo - campaigns */\n```\n\n### Neon Card Classes\n\n```tsx\n// Base neon card - includes ::before accent bar\n<div className=\"neon-card\">\n  {/* Content */}\n</div>\n\n// Archetype-specific cards (add glow effect)\n<div className=\"neon-card neon-card-mage\">   {/* Purple glow */}\n<div className=\"neon-card neon-card-sam\">    {/* Green glow */}\n<div className=\"neon-card neon-card-rigger\"> {/* Cyan glow */}\n<div className=\"neon-card neon-card-decker\"> {/* Blue glow */}\n<div className=\"neon-card neon-card-face\">   {/* Amber glow */}\n<div className=\"neon-card neon-card-campaign\">{/* Indigo glow */}\n```\n\n### Archetype Detection Helper\n\n```typescript\nimport { Character } from \"@/lib/types\";\n\nfunction getArchetypeCardClass(character: Character): string {\n  const path = character.magicalPath;\n  // Awakened - mage glow\n  if (path === \"full-mage\" || path === \"aspected-mage\" || path === \"explorer\") {\n    return \"neon-card-mage\";\n  }\n  // Adept - face/amber glow\n  if (path === \"adept\") {\n    return \"neon-card-face\";\n  }\n  // Technomancer - decker/blue glow\n  if (path === \"technomancer\") {\n    return \"neon-card-decker\";\n  }\n  // Mundane - sam/green glow (default)\n  return \"neon-card-sam\";\n}\n\n// Usage\n<div className={`neon-card ${getArchetypeCardClass(character)}`}>\n```\n\n### Visual Dividers\n\n```tsx\n// Neon divider with diamond center\n<div className=\"neon-divider\" />\n\n// Section title with accent underline\n<h2 className=\"section-title-accent\">My Characters</h2>\n\n// Alert banner with accent top bar\n<div className=\"alert-banner-accent\">\n  Important message here\n</div>\n```\n\n### Grid Background\n\n```tsx\n// Subtle tech grid overlay (use on containers)\n<div className=\"bg-grid\">{/* Dashboard content */}</div>\n```\n\n### Stat Value Colors\n\n```tsx\n<span className=\"stat-karma\">25</span>    {/* Purple karma values */}\n<span className=\"stat-nuyen\">5,000¥</span> {/* Green nuyen values */}\n<span className=\"stat-essence\">5.4</span>  {/* Cyan essence values */}\n```\n\n### Light vs Dark Mode Behavior\n\n- **Light mode**: Subtle shadows, muted accent bars, professional appearance\n- **Dark mode**: Full neon glow effects, vibrant accent colors, cyberpunk atmosphere\n\nThe CSS variables automatically adjust intensity based on theme.\n\n## Anti-Patterns (AVOID)\n\n1. **Generic Bootstrap/Material look** - No default rounded buttons with solid colors\n2. **Excessive glow/neon** - Reserve for key interactive moments\n3. **Light mode defaults** - Dark mode is primary; light mode should still feel \"tech\"\n4. **Sans-serif for numbers** - ALWAYS use monospace for stats\n5. **Fantasy RPG styling** - No parchment textures, serif fonts, or medieval iconography\n6. **Cluttered dense layouts** - Use whitespace strategically\n7. **Asymmetric padding** - Maintain consistent internal spacing\n8. **Multiple accent colors at once** - One accent per component\n\n## File Reference\n\nKey existing patterns to follow:\n\n- `app/globals.css` - **Neon card system, archetype colors, glow effects, grid patterns**\n- `app/page.tsx` - Dashboard with neon cards and archetype detection\n- `components/creation/shared/CreationCard.tsx` - Card wrapper pattern\n- `components/creation/SkillsCard.tsx` - Modal-based editing\n- `components/creation/AugmentationsCard.tsx` - Category tabs + list\n- `app/characters/create/sheet/components/SheetCreationLayout.tsx` - Three-column layout\n\n## Quick Reference: Tailwind Classes\n\n```\nBackgrounds:  bg-zinc-950, bg-zinc-900, bg-zinc-800, bg-grid\nBorders:      border-zinc-800, border-zinc-700\nText:         text-zinc-100, text-zinc-300, text-zinc-400, text-zinc-500\nAccents:      text-sky-400, text-emerald-400, text-amber-400, text-purple-400\nHover:        hover:bg-zinc-800, hover:bg-zinc-700\nFocus:        focus:ring-2 focus:ring-sky-500 focus:ring-offset-2 focus:ring-offset-zinc-900\n\nNeon Cards:   neon-card, neon-card-mage, neon-card-sam, neon-card-rigger,\n              neon-card-decker, neon-card-face, neon-card-campaign\nDividers:     neon-divider, section-title-accent, alert-banner-accent\nStats:        stat-karma, stat-nuyen, stat-essence\n```\n"},"lastSynced":"2026-03-08T02:01:28.282Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing to capture the cyberpunk aesthetic of Shadowrun in their character management tools.","zh":"非常适合需要在角色管理工具中捕捉Shadowrun网络朋克美学的UI焦点代理","ja":"Shadowrunのサイバーパンク的なエステティックをキャラクターマネジメントツールに取り入れる必要があるUIに焦点を当てたエージェントに最適","ko":"샤도운런의 사이버펑크적인 미학을 캐릭터 관리 도구에 담는 것을 필요로 하는 UI에 중점을 둔 에이전트에게 적합","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan capturar el estético ciberpunk de Shadowrun en sus herramientas de gestión de personajes.","fr":"Parfait pour les Agents axés sur l''interface utilisateur nécessitant de capturer l''esthétique cyberpunk de Shadowrun dans leurs outils de gestion de personnages.","de":"Perfekt für benutzeroberflächenorientierte Agenten, die das Cyberpunk-Ästhetik von Shadowrun in ihren Charakter-Management-Tools erfassen müssen.","pt":"Perfeito para Agentes focados em UI que precisam capturar a estética ciberpunk de Shadowrun em suas ferramentas de gerenciamento de personagens.","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимо уловить киберпанковскую эстетику Shadowrun в их инструментах управления персонажами.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم وهم بحاجة إلى التقاط جماليات Shadowrun السايبربانك في أدوات إدارة الشخصيات الخاصة بهم."},"recommendation":{"en":"Empowers agents to create distinctive, production-grade UI with a balance of precision, density, and usability, incorporating the Sixth World aesthetic with corporate sleek and street grit elements, and utilizing information density without visual clutter.","zh":"赋予代理创建独特的、生产级UI的能力，平衡精确度、密度和可用性，并将第六世界的美学与公司风格和街头风格元素结合，利用信息密度而不产生视觉杂乱","ja":"エージェントが独自の、生産性の高いUIを作成する力を与え、精度、密度、使いやすさのバランスをとり、第六世界のエステティックを企業風とストリート風の要素とともに取り入れ、視覚的な混乱を生じることなく情報密度を利用する","ko":"에이전트가 독특한 생산급 UI를 생성할 수 있는 능력을 부여하여, 정확도, 밀도, 사용 편의성을 균형을 잡고, 여섯 번째 세계의 미학을 기업의 세련된感觉과 거리의 그릿 요소와 결합하여, 시각적인 혼란을 일으키지 않고 정보 밀도를 활용","es":"Habilita a los agentes a crear interfaces de usuario distintivas y de grado de producción con un equilibrio de precisión, densidad y usabilidad, incorporando el estético del Sexto Mundo con elementos de elegancia corporativa y aspereza callejera, y utilizando la densidad de información sin desorden visual.","fr":"Permet aux agents de créer des interfaces utilisateur distinctives et de grade de production avec un équilibre de précision, de densité et d''utilisabilité, en incorporant l''esthétique du Sixième Monde avec des éléments d''élégance corporative et de rudesse de rue, et en utilisant la densité d''information sans désordre visuel.","de":"Ermöglicht es Agenten, distinktive, produktionsreife Benutzeroberflächen mit einem Gleichgewicht von Präzision, Dichte und Benutzbarkeit zu erstellen, indem sie die Ästhetik der Sechsten Welt mit Elementen von Corporate-Eleganz und Straßen-Rauheit einbeziehen und Informationsdichte ohne visuelles Durcheinander nutzen.","pt":"Habilita os agentes a criar UI distintas e de classe de produção, com equilíbrio de precisão, densidade e usabilidade, incorporando a estética do Sixth World com elementos de sofisticação corporativa e aspereza de rua, e utilizando densidade de informações sem bagunça visual.","ru":"Наделяет агентов возможностью создавать отличительную, производственную UI с балансом точности, плотности и удобства использования, включающую эстетику Sixth World с элементами корпоративной элегантности и уличной суровости, и использующую плотность информации без визуального шума.","ar":"تمكن الوكلاء من إنشاء واجهات مستخدم فريدة من نوعها ومن الدرجة الأولى، مع توازن بين الدقة والكثافة وسهولة الاستخدام، وتضمّن جماليات العالم السادس مع عناصر أنيقة ومخضعة للعصابة، واستخدام كثافة المعلومات دون فوضى بصرية."},"useCases":{"en":["Designing character management interfaces with a Shadowrun theme","Creating neon-lit, high-tech UI elements with a worn, advanced feel","Balancing information density and visual clutter in UI design for optimal usability"],"zh":["设计具有Shadowrun主题的角色管理界面","创建带有磨损的先进感觉的霓虹灯照明的高科技UI元素","在UI设计中平衡信息密度和视觉杂乱以实现最佳的可用性"],"ja":["Shadowrunテーマのキャラクターマネジメントインターフェイスを設計する","傷ついた先進的な感覚をもったネオン照明のハイテクUI要素を作成する","UI設計で情報密度と視覚的な混乱をバランスよくして使いやすさを最適化する"],"ko":["샤도운런 테마의 캐릭터 관리 인터페이스를 설계하는 것","마모된 고급 감각을 가진 네온 조명된 하이테크 UI 요소를 생성","UI 설계에서 정보 밀도와 시각적인混乱을 균형있게 하여 사용 편의성을 최적화"],"es":["Diseñar interfaces de gestión de personajes con un tema Shadowrun","Crear elementos de interfaz de usuario con iluminación de neón, de alta tecnología y con una sensación desgastada y avanzada","Equilibrar la densidad de información y el desorden visual en el diseño de la interfaz de usuario para una usabilidad óptima"],"fr":["Concevoir des interfaces de gestion de personnages avec un thème Shadowrun","Créer des éléments d''interface utilisateur avec éclairage au néon, de haute technologie et avec une sensation usée et avancée","Équilibrer la densité d''information et le désordre visuel dans la conception de l''interface utilisateur pour une utilisabilité optimale"],"de":["Entwerfen von Charakter-Management-Schnittstellen mit einem Shadowrun-Thema","Erstellen von Benutzeroberflächenelementen mit Neonbeleuchtung, Hochtechnologie und einem abgenutzten, fortschrittlichen Gefühl","Ausgleichen von Informationsdichte und visuellem Durcheinander im Benutzeroberflächendesign für optimale Benutzbarkeit"],"pt":["Projetar interfaces de gerenciamento de personagens com tema Shadowrun","Criar elementos de UI neon com um aspecto desgastado e avançado","Equilibrar densidade de informações e bagunça visual no design de UI para usabilidade ótima"],"ru":["Проектировать интерфейсы управления персонажами с темой Shadowrun","Создавать неоновые элементы UI с изношенным, продвинутым видом","Балансировать плотность информации и визуальный шум в дизайне UI для оптимальной удобства использования"],"ar":["تصميم واجهات إدارة الشخصيات مع موضوع Shadowrun","إنشاء عناصر واجهة المستخدم المضاءة بمظهر متقدم ومتعب","توازن بين كثافة المعلومات والفوضى البصرية في تصميم واجهة المستخدم لسهولة الاستخدام المثلى"]},"limitations":{"en":["Requires understanding of the Shadowrun universe and its aesthetic","Limited to character management tool UI design","May require additional design elements to fully capture the Sixth World aesthetic"],"zh":["需要了解Shadowrun宇宙及其美学","仅限于角色管理工具UI设计","可能需要额外的设计元素来完全捕捉第六世界的美学"],"ja":["Shadowrun宇宙とそのエステティックを理解する必要がある","キャラクターマネジメントツールのUI設計のみに限定される","第六世界のエステティックを完全に捉えるために追加のデザイン要素が必要になる可能性がある"],"ko":["샤도운런 우주와 그 미학을 이해해야 함","캐릭터 관리 도구의 UI 설계에만 제한됨","여섯 번째 세계의 미학을 완전히 담기 위해 추가적인 디자인 요소가 필요할 수 있음"],"es":["Requiere comprensión del universo Shadowrun y su estética","Limitado al diseño de la interfaz de usuario de herramientas de gestión de personajes","Puede requerir elementos de diseño adicionales para capturar completamente el estético del Sexto Mundo"],"fr":["Nécessite une compréhension de l''univers Shadowrun et de son esthétique","Limité à la conception de l''interface utilisateur des outils de gestion de personnages","Peut nécessiter des éléments de conception supplémentaires pour capturer complètement l''esthétique du Sixième Monde"],"de":["Benötigt das Verständnis des Shadowrun-Universums und seiner Ästhetik","Begrenzt auf das Design der Benutzeroberfläche von Charakter-Management-Tools","Kann zusätzliche Designelemente erfordern, um die Ästhetik der Sechsten Welt vollständig zu erfassen"],"pt":["Exige compreensão do universo Shadowrun e sua estética","Limitado ao design de UI de ferramentas de gerenciamento de personagens","Pode exigir elementos de design adicionais para capturar completamente a estética do Sixth World"],"ru":["Требует понимания вселенной Shadowrun и ее эстетики","Ограничен дизайном UI инструментов управления персонажами","Может потребовать дополнительных элементов дизайна для полного уловления эстетики Sixth World"],"ar":["يتطلب فهمًا للعالم Shadowrun وجمالياته","محدود بتصميم واجهة المستخدم لأدوات إدارة الشخصيات","قد يتطلب عناصر تصميم إضافية لالتقاط جماليات العالم السادس بشكل كامل"]},"version":4},"contentHash":"6aed86a708cb69b3c2f4485518c7cfeaca9f0089fa8328b705e0796503009f80","qualityScore":54}');
