INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brianium/sfere/fx-explore', 'fx-explore', 'brianium', 'sfere', 'community', 'fx-explore brianium sfere community fx-explore provides connection management for Twk apps, enabling developers to discover and understand available effects, actions, and placeholders. It operates on the dispatch function, created via `(s/create-dispatch [registries...])`. fx-explore是Twk应用的连接管理库，提供schema驱动的发现功能 fx-exploreはTwkアプリケーションの接続管理ライブラリで、スキーマ駆動の発見機能を提供します fx-explore는 Twk 애플리케이션의 연결 관리 라이브러리로서 스키마 기반의 발견 기능을 제공합니다 fx-explore es una herramienta para la gestión de conexiones en aplicaciones Twk, que utiliza Clojure y ofrece funciones de descubrimiento de efectos y acciones. fx-explore est un outil pour la gestion des connexions dans les applications Twk, qui utilise Clojure et propose des fonctions de découverte d''effets et d''actions. fx-explore ist ein Tool für die Verbindungsbetriebsverwaltung in Twk-Anwendungen, das Clojure verwendet und Funktionen zur Entdeckung von Effekten und Aktionen bietet. O fx-explore é uma biblioteca de gerenciamento de conexão para aplicativos Twk, permitindo a descoberta de efeitos e ações disponíveis. Ele opera sobre a função de dispatch. Fx-explore - это библиотека управления соединениями для приложений Twk, позволяющая открывать доступные эффекты и действия. Он работает над функцией диспетчеризации. fx-explore هو مكتبة لإدارة الاتصال لتطبيقات Twk، مما يسمح باكتشاف التأثيرات والactions المتاحة. يعمل على وظيفة الإرسال. how to use fx-explore fx-explore connection management fx-explore vs other dispatch libraries fx-explore setup guide fx-explore install for Twk apps what is fx-explore fx-explore alternative for Clojure fx-explore documentation fx-explore GitHub repository fx-explore tutorial for developers fx-explore 连接管理 Twk应用 schema驱动 发现功能 Clojure效果调度库 AI工具 AIエージェント 连接管理库 Operates on the dispatch function, created via `(s/create-dispatch [registries...])` Provides schema-driven discoverability for available effects, actions, and placeholders Supports effects dispatched as vectors, such as `[:myapp/save-user {:name "Alice"}]` Utilizes Clojure for efficient connection management Enables developers to explore available effects, actions, and placeholders Requires GitHub repository access for further development and customization fx-explore is a Clojure effect dispatch library with schema-driven discoverability, enabling efficient connection management for Twk apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Bobby44-max/boston-luxury-re-producer/firecrawl-scraper', 'community', 'Bobby44-max', 'boston-luxury-re-producer', 'Bobby44-max/boston-luxury-re-producer', 'firecrawl-scraper', 0, 0, 54, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:44.556Z', '8b2a43989e56a4110078e2f82fea8be743d3bfede6ef3014bd09940860f4349d', '{"id":"Bobby44-max/boston-luxury-re-producer/firecrawl-scraper","name":"firecrawl-scraper","description":{"en":"The firecrawl-scraper skill transforms real estate listing URLs into structured JSON data for video generation, handling JavaScript rendering and anti-bot measures. It benefits Boston luxury real estate agents using Gemini 3 Pro, Veo 3.1, and Live Audio consultation.","zh":"Firecrawl Scraper是一款AI驱动的视频生产套件，用于Boston豪宅地产代理。它支持JavaScript渲染、反爬虫措施和图像提取","ja":"Firecrawl Scraperは、ボストンの高級不動産エージェント向けのAI駆動のビデオ生成ツールです。JavaScriptレンダリング、反bot対策、画像抽出をサポート","ko":"Firecrawl Scraper는 보스턴 고급 부동산 에이전트를 위한 AI 인텔리전스 비디오 생산 도구입니다. 자바스크립트 렌더링, 반 크롤링 조치 및 이미지 추출을 지원","es":"Firecrawl-scraper es un conjunto de herramientas de producción de video impulsado por IA para agentes de bienes raíces de lujo en Boston","fr":"Firecrawl-scraper est un ensemble d''outils de production de vidéo alimenté par l''IA pour les agents immobiliers de luxe à Boston","de":"Firecrawl-scraper ist ein von KI angetriebenes Video-Produktionstool für Luxus-Immobilienmakler in Boston","pt":"O Firecrawl Scraper é uma ferramenta de extração de dados de imóveis que transforma URLs de listagens em dados JSON estruturados para geração de vídeo","ru":"Firecrawl Scraper — это инструмент для извлечения данных о недвижимости, который преобразует URLs списков в структурированные данные JSON для генерации видео","ar":"Firecrawl Scraper هو أداة لاستخراج بيانات العقارات التي تتحول إلى بيانات JSON منظم للتحويل إلى فيديو"},"seo":{"title":{"en":"firecrawl-scrape