INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Bobby44-max/boston-luxury-re-producer/firecrawl-scraper', 'firecrawl-scraper', 'Bobby44-max', 'boston-luxury-re-producer', 'community', 'firecrawl-scraper Bobby44-max boston-luxury-re-producer community The firecrawl-scraper skill transforms real estate listing URLs into structured JSON data for video generation, handling JavaScript rendering and anti-bot measures. It benefits Boston luxury real estate agents using Gemini 3 Pro, Veo 3.1, and Live Audio consultation. Firecrawl Scraper是一款AI驱动的视频生产套件，用于Boston豪宅地产代理。它支持JavaScript渲染、反爬虫措施和图像提取 Firecrawl Scraperは、ボストンの高級不動産エージェント向けのAI駆動のビデオ生成ツールです。JavaScriptレンダリング、反bot対策、画像抽出をサポート Firecrawl Scraper는 보스턴 고급 부동산 에이전트를 위한 AI 인텔리전스 비디오 생산 도구입니다. 자바스크립트 렌더링, 반 크롤링 조치 및 이미지 추출을 지원 Firecrawl-scraper es un conjunto de herramientas de producción de video impulsado por IA para agentes de bienes raíces de lujo en Boston Firecrawl-scraper est un ensemble d''outils de production de vidéo alimenté par l''IA pour les agents immobiliers de luxe à Boston Firecrawl-scraper ist ein von KI angetriebenes Video-Produktionstool für Luxus-Immobilienmakler in Boston O Firecrawl Scraper é uma ferramenta de extração de dados de imóveis que transforma URLs de listagens em dados JSON estruturados para geração de vídeo Firecrawl Scraper — это инструмент для извлечения данных о недвижимости, который преобразует URLs списков в структурированные данные JSON для генерации видео Firecrawl Scraper هو أداة لاستخراج بيانات العقارات التي تتحول إلى بيانات JSON منظم للتحويل إلى فيديو how to use firecrawl-scraper firecrawl-scraper alternative firecrawl-scraper setup guide what is firecrawl-scraper firecrawl-scraper vs other scrapers firecrawl-scraper install automated property extraction real estate video production AI-powered video generation AI视频生产 Boston豪宅地产 JavaScript渲染 反爬虫措施 图像提取 Gemini 3 Pro Veo 3.1 Live Audio咨询 Handles JavaScript rendering for seamless data extraction Automatically bypasses anti-bot measures for uninterrupted scraping Extracts images from real estate listings for enhanced video production Utilizes Gemini 3 Pro and Veo 3.1 for advanced video generation capabilities Supports Live Audio consultation for personalized video content Generates structured JSON data for easy video production integration firecrawl-scraper is an AI-powered video production suite that extracts property data from real estate listings and converts it into structured JSON format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lucidlabs-hq/agent-kit/design-system-guard', 'community', 'lucidlabs-hq', 'agent-kit', 'lucidlabs-hq/agent-kit', 'design-system-guard', 0, 0, 54, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:50.549Z', 'f7e2dfa171648606a377fb03d6c8f3858fa5ae79a95f0319c1217a817d8ac47b', '{"id":"lucidlabs-hq/agent-kit/design-system-guard","name":"design-system-guard","description":{"en":"The design-system-guard skill validates screen designs against Lucid Labs design system rules, ensuring strict adherence to guidelines. It benefits developers working with Next.js, Mastra, Convex, and n8n.","zh":"设计系统守卫是一种AI Agent Starter Kit，用于构建Next.js、Mastra、Convex和n8n的AI应用","ja":"デザインシステムガードは、Next.js、Mastra、Convex、n8nのAIアプリケーションを構築するためのAI Agent Starter Kitです","ko":"디자인 시스템 가드는 Next.js, Mastra, Convex 및 n8n의 AI 애플리케이션을 구축하기 위한 AI 에이전트 스타터 키트입니다","es":"Design-system-guard es un kit de inicio para aplicaciones con AI que valida diseños con Next.js, Mastra, Convex y n8n. Asegura la coherencia de tu aplicación","fr":"Design-system-guard est un kit de démarrage pour les applications avec IA qui valide les conceptions avec Next.js, Mastra, Convex et n8n. Assurez la cohérence de votre application","de":"Design-system-guard ist ein Starter-Kit für AI-Anwendungen, das Designs mit Next.js, Mastra, Convex und n8n validiert. Stellen Sie die Konsistenz Ihrer Anwendung sicher","pt":"O Design System Guard é uma ferramenta de validação de UX para aplicações AI que utiliza Next.js, Mastra, Convex e n8n","ru":"Design System Guard - это инструмент валидации UX для приложений ИИ, использующий Next.js, Mastra, Convex и n8n","ar":"Design System Guard هو أداة التحقق من واجهة المستخدم للتطبيقات الذكية التي تستخدم Next.js و Mastra و Convex و n8n"},"seo":{"title":{"en":"design-system-guard: Validation Setup Guide | AI Agent Skill","zh":"设计系统守卫 Setup Guide - AIエージェント开发工具","ja":"デザインシステムガード Setup Guide - AIエージェントの開発ツール","ko":"디자인 시스템 가드 Setup Guide - AI 에이전트 개발 도구","es":"Configuración de design-system-guard: Guía de validación ...","fr":"Mise en place de design-system-guard : Guide de validatio...","de":"Einrichtung von design-system-guard: Leitfaden für Design...","pt":"Guia de Configuração do Design System Guard - Ferramenta ...","ru":"Руководство по настройке Design System Guard - Инструмент...","ar":"دليل إعداد Design System Guard - أداة التحقق من واجهة الم..."},"description":{"en":"Unlock strict design system validation with design-system-guard. Learn how to set up and use this AI agent starter kit for Next.js, Mastra, Convex, and n8n a...","zh":"使用设计系统守卫AI Agent Starter Kit，快速构建Next.js、Mastra、Convex和n8n的AI应用","ja":"デザインシステムガードAI Agent Starter Kitを使用して、Next.js、Mastra、Convex、n8nのAIアプリケーションを迅速に構築","ko":"디자인 시스템 가드 AI 에이전트 스타터 키트를 사용하여 Next.js, Mastra, Convex 및 n8n의 AI 애플리케이션을 빠르게 구축","es":"Aprende a configurar design-system-guard para validar diseños con Next.js, Mastra, Convex y n8n. Mejora la coherencia de tu aplicación","fr":"Découvrez comment configurer design-system-guard pour valider les conceptions avec Next.js, Mastra, Convex et n8n. Améliorez la cohérence de votre application","de":"Erfahren Sie, wie Sie design-system-guard einrichten, um Designs mit Next.js, Mastra, Convex und n8n zu validieren. Verbessern Sie die Konsistenz Ihrer Anwen...","pt":"Aprenda a configurar o Design System Guard, uma ferramenta de validação de UX para aplicações AI com Next.js, Mastra, Convex e n8n","ru":"Узнайте, как настроить Design System Guard, инструмент валидации UX для приложений ИИ с Next.js, Mastra, Convex и n8n","ar":"تعلم كيفية إعداد Design System Guard، أداة التحقق من واجهة المستخدم للتطبيقات الذكية مع Next.js، Mastra، Convex و n8n"},"definition":{"en":"design-system-guard is a production-ready boilerplate for AI-powered applications that validates screen designs against predefined design system rules.","zh":"设计系统守卫是一种AI工具，用于验证屏幕是否遵循Lucid Labs设计系统规则","ja":"デザインシステムガードは、スクリーンがLucid Labsデザインシステムのルールに従っているかどうかを検証するAIツールです","ko":"디자인 시스템 가드는 화면이 Lucid Labs 디자인 시스템 규칙을 따르는지 여부를 검증하는 AI 도구입니다","es":"Design-system-guard es un agente de validación de diseño que verifica la coherencia de las pantallas con las reglas del sistema de diseño de Lucid Labs","fr":"Design-system-guard est un agent de validation de conception qui vérifie la cohérence des écrans avec les règles du système de conception de Lucid Labs","de":"Design-system-guard ist ein Designvalidierungsagent, der die Konsistenz von Bildschirmen mit den Regeln des Lucid Labs-Designsystems überprüft","pt":"O Design System Guard é uma ferramenta de validação de UX que verifica se as telas seguem as regras do sistema de design da Lucid Labs","ru":"Design System Guard - это инструмент валидации UX, который проверяет, соответствуют ли экраны правилам системы дизайна Lucid Labs","ar":"Design System Guard هو أداة التحقق من واجهة المستخدم التي تتحقق من مطابقة الشاشات لقواعد نظام التصميم من لوكيد لابس"},"features":{"en":["Validates screen designs against Lucid Labs design system rules","Works with Next.js for server-side rendering and static site generation","Integrates with Mastra for design system management","Utilizes Convex for data modeling and storage","Supports workflow automation via n8n"],"zh":["支持Next.js","集成Mastra","使用Convex进行数据管理","与n8n集成","遵循Lucid Labs设计系统规则"],"ja":["Next.jsをサポート","Mastraを統合","Convexを使用したデータ管理","n8nと統合","Lucid Labsデザインシステムのルールに従う"],"ko":["Next.js 지원","Mastra 통합","Convex를 사용한 데이터 관리","n8n과 통합","Lucid Labs 디자인 시스템 규칙 준수"],"es":["Validación de diseños con Next.js","Integración con Mastra para reglas de diseño","Uso de Convex para la lógica de validación","Conectividad con n8n para automatización","Seguimiento estricto de las reglas del sistema de diseño de Lucid Labs"],"fr":["Validation de conceptions avec Next.js","Intégration avec Mastra pour les règles de conception","Utilisation de Convex pour la logique de validation","Connectivité avec n8n pour l''automatisation","Suivi strict des règles du système de conception de Lucid Labs"],"de":["Designvalidierung mit Next.js","Integration mit Mastra für Designregeln","Verwendung von Convex für die Validierungslogik","Konnektivität mit n8n für Automatisierung","Strenger Nachvollzug der Regeln des Lucid Labs-Designsystems"],"pt":["Validação de telas com base nas regras do sistema de design da Lucid Labs","Integração com Next.js, Mastra, Convex e n8n","Análise estrita e explícita das telas","Flagging de telas incertas ou incorretas","Utilização de tecnologias de ponta para aplicações AI"],"ru":["Валидация экранов на основе правил системы дизайна Lucid Labs","Интеграция с Next.js, Mastra, Convex и n8n","Строгое и явное анализ экранов","Маркировка неопределенных или неправильных экранов","Использование передовых технологий для приложений ИИ"],"ar":["التحقق من الشاشات بناءً على قواعد نظام التصميم من لوكيد لابس","التكامل مع Next.js و Mastra و Convex و n8n","تحليل صارم وضمني للشاشات","تعليم الشاشات غير الواضحة أو غير الصحيحة","استخدام تقنيات متقدمة للتطبيقات الذكية"]},"keywords":{"en":["how to use design-system-guard","design-system-guard setup guide","design-system-guard alternative","design-system-guard vs Mastra","install design-system-guard","Next.js design system validation","Convex data modeling for design systems","n8n workflow automation for design-system-guard"],"zh":["AIエージェント开发工具","设计系统守卫","Next.js AI应用","Mastra集成","Convex数据管理","n8n集成","Lucid Labs设计系统规则"],"ja":["AIエージェント開発ツール","デザインシステムガード","Next.js AIアプリケーション","Mastra統合","Convexデータ管理","n8n統合","Lucid Labsデザインシステムルール"],"ko":["AI 에이전트 개발 도구","디자인 시스템 가드","Next.js AI 애플리케이션","Mastra 통합","Convex 데이터 관리","n8n 통합","Lucid Labs 디자인 시스템 규칙"],"es":["agentes de IA","validación de diseño","Next.js","Mastra","Convex","n8n","sistema de diseño de Lucid Labs","desarrollo de aplicaciones con AI","herramientas de validación de diseño"],"fr":["agents IA","validation de conception","Next.js","Mastra","Convex","n8n","système de conception de Lucid Labs","développement d''applications avec IA","outils de validation de conception"],"de":["AI-Agents","Designvalidierung","Next.js","Mastra","Convex","n8n","Lucid Labs-Designsystem","Entwicklung von AI-Anwendungen","Designvalidierungstools"],"pt":["Design System Guard","validação de UX","Next.js","Mastra","Convex","n8n","aplicações AI","ferramenta de validação","sistema de design da Lucid Labs"],"ru":["Design System Guard","валидация UX","Next.js","Mastra","Convex","n8n","приложения ИИ","инструмент валидации","система дизайна Lucid Labs"],"ar":["Design System Guard","التحقق من واجهة المستخدم","Next.js","Mastra","Convex","n8n","التطبيقات الذكية","أداة التحقق","نظام التصميم من لوكيد لابس"]}},"owner":"lucidlabs-hq","repo":"agent-kit","repoPath":"lucidlabs-hq/agent-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"design-system-guard","description":"Validate UI screens against Lucid Labs design system rules. Use after implementing UI components to verify adherence to brand colors, typography, layout patterns, and service board logic.","bodyPreview":"# Design System Guard\n\nYou are a **Lucid Labs Design & UX Validator Agent**.\n\nYour task is **not to redesign**, **not to optimize creatively**, and **not to guess intent**.\n\nYour sole responsibility is to **validate** whether a given screen follows the **Lucid Labs design system rules**.\n\nYou must be **strict, explicit, and rule-based**.\n\nIf something is unclear, assume it is **incorrect** and flag it.\n\n---\n\n## INPUT YOU RECEIVE\n\nYou will receive one or more of the following:\n\n* Screenshots of a","body":"# Design System Guard\n\nYou are a **Lucid Labs Design & UX Validator Agent**.\n\nYour task is **not to redesign**, **not to optimize creatively**, and **not to guess intent**.\n\nYour sole responsibility is to **validate** whether a given screen follows the **Lucid Labs design system rules**.\n\nYou must be **strict, explicit, and rule-based**.\n\nIf something is unclear, assume it is **incorrect** and flag it.\n\n---\n\n## INPUT YOU RECEIVE\n\nYou will receive one or more of the following:\n\n* Screenshots of a UI\n* File paths to components\n* ASCII layouts\n* Short textual descriptions of a screen\n\nWhen given file paths, read the component code to understand the UI structure.\n\n---\n\n## VALIDATION SCOPE\n\nValidate the screen against **all** of the following dimensions:\n\n---\n\n## 1. BRAND & COLOR RULES\n\n### Must be true\n\n* Indigo/purple tones (`indigo-500`, `indigo-600`) are the dominant accent colors\n* White (`bg-white`) is used for content cards\n* Off-white/light gray (`bg-[#F7F8FA]`, `bg-slate-50`) for section backgrounds\n* Slate tones for text hierarchy (`text-slate-900`, `text-slate-700`, `text-slate-500`)\n\n### Must NOT be true\n\n* No dark mode as default (bg-slate-800, bg-slate-900 for main panels)\n* No black backgrounds\n* No semantic colors for status (red/green/yellow) - use indigo intensity instead\n* No shadows on cards (use borders only)\n\n### Output\n\n* PASS / FAIL\n* Short explanation\n\n---\n\n## 2. TYPOGRAPHY ROLES\n\n### Must be true\n\n* Section titles: `text-lg font-semibold text-slate-900`\n* Labels: `text-sm font-medium text-slate-700`\n* Meta/muted: `text-xs text-slate-500`\n* Uppercase tracking for category labels: `text-xs font-medium uppercase tracking-wider text-slate-500`\n\n### Must NOT be true\n\n* No mixed font weights without purpose\n* No excessive font sizes (max `text-xl` for page titles)\n\n### Output\n\n* PASS / FAIL\n* What typography is wrong if failing\n\n---\n\n## 3. LAYOUT PATTERNS\n\n### Must be true\n\n* Generous spacing (`p-6`, `gap-4`, `mb-6`)\n* Border-based separation (`border border-slate-200`)\n* Rounded corners (`rounded-lg`, `rounded-md`)\n* Empty states have dashed borders (`border-dashed border-slate-300`)\n\n### Must NOT be true\n\n* No tight spacing (p-2, gap-1 for main sections)\n* No heavy visual dividers\n* No card shadows\n\n### Output\n\n* PASS / FAIL\n* Which elements violate layout rules\n\n---\n\n## 4. INTERACTIVE ELEMENTS\n\n### Must be true\n\n* All clickable elements have `cursor-pointer`\n* Buttons use indigo as primary color\n* Secondary buttons have borders, not fills\n* Hover states are subtle (slate-50, slate-100)\n\n### Must NOT be true\n\n* No aggressive hover effects\n* No multiple primary actions competing\n\n### Output\n\n* PASS / FAIL\n* Specific violation if present\n\n---\n\n## 5. STATUS & CONFIDENCE DISPLAY\n\n### Must be true\n\n* Confidence uses IntensityBar (1-5 scale, indigo gradient)\n* Status badges use neutral colors (slate, indigo)\n* Processing states use `Loader2` with `animate-spin`\n\n### Must NOT be true\n\n* No traffic light colors (red/green/yellow badges)\n* No progress bars for confidence\n* No percentage badges\n\n### Output\n\n* PASS / FAIL\n* Explain mismatch if failing\n\n---\n\n## 6. EMPTY STATES\n\n### Must be true\n\n* Centered content\n* Muted icon (`text-slate-300`)\n* Short, helpful text\n* Dashed border container\n\n### Must NOT be true\n\n* No empty states without visual indicator\n* No error-styled empty states\n\n### Output\n\n* PASS / FAIL\n* Missing empty state handling if failing\n\n---\n\n## 7. CALMNESS & READABILITY\n\n### Must be true\n\n* The screen feels calm and structured\n* Visual noise is low\n* No unnecessary borders, lines, or decorations\n* Content is scannable\n\n### Must NOT be true\n\n* No dashboard clutter\n* No dense tables without purpose\n* No aggressive visual density\n\n### Output\n\n* PASS / FAIL\n* What causes overload if failing\n\n---\n\n## REQUIRED FINAL OUTPUT FORMAT\n\nAlways respond in this structure:\n\n```\nLucid Labs Design System Validation\n\n1. Brand & Color: PASS / FAIL\n   - Reason\n\n2. Typography Roles: PASS / FAIL\n   - Reason\n\n3. Layout Patterns: PASS / FAIL\n   - Reason\n\n4. Interactive Elements: PASS / FAIL\n   - Reason\n\n5. Status & Confidence: PASS / FAIL\n   - Reason\n\n6. Empty States: PASS / FAIL\n   - Reason\n\n7. Calmness & Readability: PASS / FAIL\n   - Reason\n\nOverall Verdict:\n- APPROVED\n- APPROVED WITH ISSUES\n- REJECTED\n\nCritical Violations (if any):\n- Bullet list\n\nSuggested Fixes:\n- Bullet list (only if REJECTED or APPROVED WITH ISSUES)\n```\n\n---\n\n## IMPORTANT CONSTRAINTS\n\n* Do **not** suggest redesigns unless asked\n* Do **not** invent intent\n* Do **not** optimize copy\n* Validate **only** against design system rules\n* Be specific about which Tailwind classes are wrong\n"},"lastSynced":"2026-03-08T02:01:50.549Z","agentAnalysis":{"suitability":{"en":"Perfect for UX Validator Agents needing strict adherence to Lucid Labs design system rules in Next.js, Mastra, Convex, and n8n environments.","zh":"非常适合需要严格遵守Lucid Labs设计系统规则的UX Validator Agents，尤其是在Next.js、Mastra、Convex和n8n环境中。","ja":"Next.js、Mastra、Convex、n8n環境においてLucid Labsデザインシステムのルールに厳格に従う必要があるUX Validatorエージェントに最適です。","ko":"Next.js, Mastra, Convex, n8n 환경에서 Lucid Labs 디자인 시스템 규칙을 엄격히 준수해야 하는 UX Validator 에이전트에게 적합합니다.","es":"Perfecto para agentes de validador de UX que necesitan una estricta adherencia a las reglas del sistema de diseño de Lucid Labs en Next.js, Mastra, Convex y entornos de n8n.","fr":"Parfait pour les agents de validateur d''UX nécessitant une stricte adhésion aux règles du système de conception de Lucid Labs dans Next.js, Mastra, Convex et les environnements n8n.","de":"Perfekt für UX-Validator-Agents, die eine strikte Einhaltung der Design-System-Regeln von Lucid Labs in Next.js, Mastra, Convex und n8n-Umgebungen benötigen.","pt":"Perfeito para Agentes de Validador de UX que necessitam de adesão estrita às regras do sistema de design da Lucid Labs em ambientes Next.js, Mastra, Convex e n8n.","ru":"Идеально подходит для агентов-валидаторов UX, которым требуется строгое соблюдение правил системы дизайна Lucid Labs в средах Next.js, Mastra, Convex и n8n.","ar":"مثالي لعميل التحقق من UX الذي يحتاج إلى اتباع صارم لقواعد نظام التصميم في مختبرات لوسيد في بيئات Next.js و Mastra و Convex و n8n."},"recommendation":{"en":"Empowers agents to validate screen designs against Lucid Labs design system rules, ensuring strict adherence to guidelines and providing explicit feedback on design system compliance using screenshots and rule-based validation.","zh":"赋予代理能力以验证屏幕设计是否符合Lucid Labs设计系统规则，确保严格遵守指南并使用截图和基于规则的验证提供明确的反馈关于设计系统的合规性。","ja":"Lucid Labsデザインシステムのルールに従ってスクリーンデザインを検証するエージェントを可能にし、ガイドラインの厳格な遵守を確保し、スクリーンショットとルールベースの検証を使用してデザインシステムのコンプライアンスに関する明確なフィードバックを提供します。","ko":"에이전트가 Lucid Labs 디자인 시스템 규칙에 따라 화면 디자인을 검증할 수 있도록 하여 지침을 엄격히 준수하며 스크린샷과 규칙 기반 검증을 사용하여 디자인 시스템 규정 준수에 대한 명확한 피드백을 제공합니다.","es":"Habilita a los agentes a validar diseños de pantalla contra las reglas del sistema de diseño de Lucid Labs, garantizando una estricta adherencia a las pautas y proporcionando comentarios explícitos sobre el cumplimiento del sistema de diseño utilizando capturas de pantalla y validación basada en reglas.","fr":"Permet aux agents de valider les conceptions d''écran contre les règles du système de conception de Lucid Labs, en garantissant une stricte adhésion aux lignes directrices et en fournissant des commentaires explicites sur la conformité du système de conception à l''aide de captures d''écran et de validation basée sur des règles.","de":"Ermächtigt die Agents, Bildschirm-Designs gegen die Design-System-Regeln von Lucid Labs zu validieren, wodurch eine strikte Einhaltung der Richtlinien sichergestellt und explizites Feedback zur Design-System-Konformität unter Verwendung von Screenshots und regelbasierter Validierung bereitgestellt wird.","pt":"Habilita os agentes a validar projetos de tela contra as regras do sistema de design da Lucid Labs, garantindo adesão estrita às diretrizes e fornecendo feedback explícito sobre a conformidade do sistema de design usando capturas de tela e validação baseada em regras.","ru":"Наделяет агентов возможностью проверять дизайн экрана на соответствие правилам системы дизайна Lucid Labs, обеспечивая строгое соблюдение руководящих принципов и предоставляя явную обратную связь о соответствии системы дизайна с помощью скриншотов и валидации на основе правил.","ar":"يمكن للعميل التحقق من مشاريع الشاشة ضد قواعد نظام التصميم في مختبرات لوسيد، مما يضمن اتباعًا صارمًا للإرشادات وتقديم ملاحظات صريحة حول امتثال نظام التصميم باستخدام لقطات الشاشة والتحقق القائم على القواعد."},"useCases":{"en":["Validating screen designs against Lucid Labs design system rules","Flagging non-compliant design elements in Next.js applications","Ensuring consistent UX across Mastra, Convex, and n8n platforms"],"zh":["验证屏幕设计是否符合Lucid Labs设计系统规则","在Next.js应用程序中标记非合规设计元素","确保Mastra、Convex和n8n平台之间的一致性UX"],"ja":["Lucid Labsデザインシステムのルールに従ってスクリーンデザインを検証する","Next.jsアプリケーションでコンプライアンスに違反するデザイン要素をフラグする","Mastra、Convex、n8nプラットフォーム間の一貫したUXを確保する"],"ko":["화면 디자인을 Lucid Labs 디자인 시스템 규칙에 따라 검증하는 것","Next.js 애플리케이션에서 규정 준수하지 않는 디자인 요소를 플래그하는 것","Mastra, Convex, n8n 플랫폼 간의 일관된 UX를 보장하는 것"],"es":["Validar diseños de pantalla contra las reglas del sistema de diseño de Lucid Labs","Marcar elementos de diseño no compatibles en aplicaciones de Next.js","Garantizar una experiencia de usuario coherente en plataformas de Mastra, Convex y n8n"],"fr":["Valider les conceptions d''écran contre les règles du système de conception de Lucid Labs","Signaler les éléments de conception non conformes dans les applications Next.js","Assurer une expérience utilisateur cohérente sur les plateformes Mastra, Convex et n8n"],"de":["Bildschirm-Designs gegen die Design-System-Regeln von Lucid Labs validieren","Nicht konforme Design-Elemente in Next.js-Anwendungen markieren","Eine konsistente Benutzeroberfläche über Mastra-, Convex- und n8n-Plattformen sicherstellen"],"pt":["Validar projetos de tela contra as regras do sistema de design da Lucid Labs","Sinalizar elementos de design não conformes em aplicações Next.js","Garantir experiência do usuário consistente em plataformas Mastra, Convex e n8n"],"ru":["Проверять дизайн экрана на соответствие правилам системы дизайна Lucid Labs","Выделять не соответствующие элементы дизайна в приложениях Next.js","Обеспечивать согласованность пользовательского опыта на платформах Mastra, Convex и n8n"],"ar":["التحقق من مشاريع الشاشة ضد قواعد نظام التصميم في مختبرات لوسيد","إعلام عن عناصر التصميم غير المتوافقة في تطبيقات Next.js","ضمان تجربة مستخدم متسقة عبر منصات Mastra و Convex و n8n"]},"limitations":{"en":["Requires access to Lucid Labs design system rules","Limited to validating screen designs, not redesigning or optimizing creatively"],"zh":["需要访问Lucid Labs设计系统规则","仅限于验证屏幕设计，不包括创造性地重新设计或优化"],"ja":["Lucid Labsデザインシステムのルールへのアクセスが必要","スクリーンデザインの検証のみ、クリエイティブな再設計や最適化は含まない"],"ko":["Lucid Labs 디자인 시스템 규칙에 대한 액세스가 필요합니다.","화면 디자인의 검증만 가능하며 창의적으로 다시 설계하거나 최적화하는 것은 포함하지 않습니다."],"es":["Requiere acceso a las reglas del sistema de diseño de Lucid Labs","Limitado a la validación de diseños de pantalla, no a la recreación o optimización creativa"],"fr":["Nécessite l''accès aux règles du système de conception de Lucid Labs","Limité à la validation des conceptions d''écran, et non à la révision ou à l''optimisation créative"],"de":["Erfordert Zugriff auf die Design-System-Regeln von Lucid Labs","Begrenzt auf die Validierung von Bildschirm-Designs, nicht auf kreative Neugestaltung oder Optimierung"],"pt":["Requer acesso às regras do sistema de design da Lucid Labs","Limitado à validação de projetos de tela, não redesenho ou otimização criativa"],"ru":["Требует доступа к правилам системы дизайна Lucid Labs","Ограничен проверкой дизайна экрана, не переработкой или творческой оптимизацией"],"ar":["يتطلب الوصول إلى قواعد نظام التصميم في مختبرات لوسيد","محدود بالتحقق من مشاريع الشاشة، وليس إعادة التصميم أو الت优يز الإبداعي"]},"version":4},"contentHash":"f7e2dfa171648606a377fb03d6c8f3858fa5ae79a95f0319c1217a817d8ac47b","qualityScore":54}');
