INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lucidlabs-hq/agent-kit/design-system-guard', 'design-system-guard', 'lucidlabs-hq', 'agent-kit', 'community', 'design-system-guard lucidlabs-hq agent-kit community The design-system-guard skill validates screen designs against Lucid Labs design system rules, ensuring strict adherence to guidelines. It benefits developers working with Next.js, Mastra, Convex, and n8n. 设计系统守卫是一种AI Agent Starter Kit，用于构建Next.js、Mastra、Convex和n8n的AI应用 デザインシステムガードは、Next.js、Mastra、Convex、n8nのAIアプリケーションを構築するためのAI Agent Starter Kitです 디자인 시스템 가드는 Next.js, Mastra, Convex 및 n8n의 AI 애플리케이션을 구축하기 위한 AI 에이전트 스타터 키트입니다 Design-system-guard es un kit de inicio para aplicaciones con AI que valida diseños con Next.js, Mastra, Convex y n8n. Asegura la coherencia de tu aplicación Design-system-guard est un kit de démarrage pour les applications avec IA qui valide les conceptions avec Next.js, Mastra, Convex et n8n. Assurez la cohérence de votre application Design-system-guard ist ein Starter-Kit für AI-Anwendungen, das Designs mit Next.js, Mastra, Convex und n8n validiert. Stellen Sie die Konsistenz Ihrer Anwendung sicher O Design System Guard é uma ferramenta de validação de UX para aplicações AI que utiliza Next.js, Mastra, Convex e n8n Design System Guard - это инструмент валидации UX для приложений ИИ, использующий Next.js, Mastra, Convex и n8n Design System Guard هو أداة التحقق من واجهة المستخدم للتطبيقات الذكية التي تستخدم Next.js و Mastra و Convex و n8n how to use design-system-guard design-system-guard setup guide design-system-guard alternative design-system-guard vs Mastra install design-system-guard Next.js design system validation Convex data modeling for design systems n8n workflow automation for design-system-guard AIエージェント开发工具 设计系统守卫 Next.js AI应用 Mastra集成 Convex数据管理 n8n集成 Lucid Labs设计系统规则 Validates screen designs against Lucid Labs design system rules Works with Next.js for server-side rendering and static site generation Integrates with Mastra for design system management Utilizes Convex for data modeling and storage Supports workflow automation via n8n design-system-guard is a production-ready boilerplate for AI-powered applications that validates screen designs against predefined design system rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TypedDevs/bashunit/add-assertion', 'community', 'TypedDevs', 'bashunit', 'TypedDevs/bashunit', 'add-assertion', 0, 0, 54, '2026-03-08T01:57:15.309Z', '2026-03-08T02:02:24.951Z', 'dc95186c4554b02ce4e99e22a5d8c79a54d6955e62dc4ebd4907e4b394f85594', '{"id":"TypedDevs/bashunit/add-assertion","name":"add-assertion","description":{"en":"The add-assertion skill provides a simple testing library for bash scripts, benefiting developers who need to add new assertions to their framework.","zh":"Add Assertion Skill是一个简单却强大的测试库，用于bash脚本，遵循严格的TDD方法ology","ja":"Add Assertion Skillは、bashスクリプト用のシンプルながら強力なテストライブラリです","ko":"Add Assertion Skill은 bash 스크립트를 위한 간단하지만 강력한 테스트 라이브러리입니다","es":"Add-assertion es una biblioteca de testing simple pero poderosa para scripts bash que sigue la metodología TDD estricta","fr":"Add-assertion est une bibliothèque de testing simple mais puissante pour les scripts bash qui suit la méthodologie TDD stricte","de":"Add-assertion ist eine einfache, aber leistungsstarke Testbibliothek für bash-Skripte, die die TDD-Methodik streng einhält","pt":"O add-assertion é uma biblioteca de teste simples, mas poderosa, para scripts bash.","ru":"Add-assertion - это простая, но мощная библиотека для тестирования bash скриптов.","ar":"أداة Add-Assertion هي مكتبة اختبار بسيطة ولكن قوية للبرامج النصية Bash."},"seo":{"title":{"en":"add-assertion: TDD Testing Library Setup Guide | AI Agent...","zh":"Add Assertion Skill Setup Guide - AIエージェント测试库","ja":"Add Assertion Skill ベストプラクティス - AIエージェントのテストライブラリ","ko":"Add Assertion Skill 구현 가이드 - AI 에이전트 테스트 라이브러리","es":"Guía de configuración de add-assertion para bash scripts","fr":"Configurer add-assertion pour les scripts bash: Meilleure...","de":"Add-assertion-Setup-Anleitung für bash-Skripte","pt":"Guia de Configuração do Add-Assertion para Testes de Bash","ru":"ИИ Агенты: Настройка Add-Assertion для Тестирования Bash","ar":"إعداد أداة Add-Assertion للتحقق من صحة البرامج النصية Bash"},"description":{"en":"Discover how to invoke /add-assertion for bash scripts and enhance your testing framework with strict TDD methodology - get started now!","zh":"学习如何使用Add Assertion Skill添加新的断言函数到bashunit，了解TDD方法ology和测试库的使用","ja":"Add Assertion Skillを使用してbashunitに新しいアサーション関数を追加する方法について学びましょう","ko":"Add Assertion Skill을 사용하여 bashunit에 새로운 assertion 함수를 추가하는 방법을 알아보세요","es":"Aprende a utilizar add-assertion para mejorar la testing de tus scripts bash con esta guía paso a paso","fr":"Découvrez comment configurer add-assertion pour améliorer les tests de vos scripts bash avec cette guide étape par étape","de":"Erfahren Sie, wie Sie add-assertion einrichten, um die Testing Ihrer bash-Skripte zu verbessern","pt":"Aprenda a configurar o add-assertion para testes de bash scripts com essa guia passo a passo","ru":"Узнайте, как настроить add-assertion для тестирования bash скриптов с помощью этой пошаговой инструкции","ar":"تعلم كيفية إعداد أداة Add-Assertion للتحقق من صحة البرامج النصية Bash باستخدام هذا الدليل خطوة بخطوة"},"definition":{"en":"add-assertion is a testing library for bash scripts that allows developers to add new assertion functions following strict Test-Driven Development (TDD) methodology.","zh":"Add Assertion Skill是一种用于bashunit的断言函数添加库","ja":"Add Assertion Skillは、bashunit用のアサーション関数追加ライブラリです","ko":"Add Assertion Skill은 bashunit을 위한 assertion 함수 추가 라이브러리입니다","es":"Add-assertion es una función de aserción que se utiliza para mejorar la testing de scripts bash","fr":"Add-assertion est une fonction d''assertion qui sert à améliorer les tests de scripts bash","de":"Add-assertion ist eine Assert-Funktion, die zur Verbesserung der Testing von bash-Skripten verwendet wird","pt":"O add-assertion é uma ferramenta de teste que adiciona novas funções de asserção ao framework bashunit.","ru":"Add-assertion - это инструмент тестирования, который добавляет новые функции утверждения в фреймворк bashunit.","ar":"أداة Add-Assertion هي أداة اختبار تضيف وظائف التحقق الجديدة إلى إطار العمل bashunit."},"features":{"en":["Invokes /add-assertion command for adding new assertions to the framework","Requires task file creation in .tasks/YYYY-MM-DD-add-assertion-name.md format","Studies tests/unit/assert_test.sh for understanding patterns","Enhances existing assertion capabilities with new assert_* functions","Follows strict TDD methodology for reliable testing"],"zh":["支持TDD方法ology","添加新的断言函数到bashunit","遵循严格的测试库标准","支持bash脚本测试","提供了测试库的使用示例"],"ja":["TDD方法ologyをサポート","bashunitに新しいアサーション関数を追加","厳格なテストライブラリ標準に従う","bashスクリプトのテストをサポート","テストライブラリの使用例を提供"],"ko":["TDD 방법ology 지원","bashunit에 새로운 assertion 함수 추가","엄격한 테스트 라이브러리 표준 준수","bash 스크립트 테스트 지원","테스트 라이브러리 사용 예제 제공"],"es":["Seguimiento de la metodología TDD estricta","Añade nuevas funciones de aserción a bashunit","Mejora de las capacidades de aserción existentes","Requiere la creación de un archivo de tarea","Estudio de patrones en tests/unit/assert_test.sh","Conocimiento de los requisitos de la aserción"],"fr":["Suivi de la méthodologie TDD stricte","Ajoute de nouvelles fonctions d''assertion à bashunit","Amélioration des capacités d''assertion existantes","Nécessite la création d''un fichier de tâche","Étude de modèles dans tests/unit/assert_test.sh","Connaissance des exigences de l''assertion"],"de":["Einhalten der TDD-Methodik","Hinzufügen neuer Assert-Funktionen zu bashunit","Verbesserung der bestehenden Assert-Funktionen","Erfordert die Erstellung einer Task-Datei","Studium von Mustern in tests/unit/assert_test.sh","Kenntnis der Anforderungen der Assert-Funktion"],"pt":["Adiciona novas funções de asserção ao framework bashunit","Segue metodologia TDD estrita","Requer arquivo de tarefa existente","Estuda padrões em tests/unit/assert_test.sh","Conhece os requisitos da asserção"],"ru":["Добавляет новые функции утверждения в фреймворк bashunit","Следует строгой методологии TDD","Требует существующего файла задачи","Изучает шаблоны в tests/unit/assert_test.sh","Знает требования утверждения"],"ar":["تضيف وظائف التحقق الجديدة إلى إطار العمل bashunit","تتبع منهجية التطوير الموجه بالتحقق من صحة القطعة","تتطلب وجود ملف مهمة","دراسة الأنماط في tests/unit/assert_test.sh","معرفة متطلبات التحقق"]},"keywords":{"en":["how to use add-assertion","add-assertion alternative","add-assertion setup guide","what is add-assertion","add-assertion vs bashunit","add-assertion install","TDD testing library for bash scripts","bash script testing framework"],"zh":["Add Assertion Skill","AIエージェント测试库","bashunit","TDD方法ology","测试库","bash脚本测试","断言函数添加","测试库标准"],"ja":["Add Assertion Skill","AIエージェントのテストライブラリ","bashunit","TDD方法ology","テストライブラリ","bashスクリプトのテスト","アサーション関数追加","テストライブラリ標準"],"ko":["Add Assertion Skill","AI 에이전트 테스트 라이브러리","bashunit","TDD 방법ology","테스트 라이브러리","bash 스크립트 테스트","assertion 함수 추가","테스트 라이브러리 표준"],"es":["add-assertion","bash scripts","testing","TDD","bashunit","assertion","herramientas de testing","desarrollo de software","pruebas unitarias"],"fr":["add-assertion","scripts bash","testing","TDD","bashunit","assertion","outils de testing","développement de logiciels","tests unitaires","agents d''IA"],"de":["add-assertion","bash-Skripte","Testing","TDD","bashunit","Assert","Test-Tools","Software-Entwicklung","Einheitstests","KI-Tools"],"pt":["add-assertion","testes de bash","bashunit","TDD","desenvolvimento de software","ferramentas de teste","programação bash"],"ru":["add-assertion","тестирование bash","bashunit","TDD","разработка программного обеспечения","инструменты тестирования","программирование на bash"],"ar":["أداة Add-Assertion","اختبار البرامج النصية Bash","إطار العمل bashunit","التطوير الموجه بالتحقق من صحة القطعة","تطوير البرمجيات","أدوات الاختبار","برمجة البرامج النصية Bash"]}},"owner":"TypedDevs","repo":"bashunit","repoPath":"TypedDevs/bashunit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.309Z","topics":[],"category":"community","skillMd":{"name":"add-assertion","description":"Add new assertion function with comprehensive tests following TDD","bodyPreview":"# Add Assertion Skill\n\nAdd a new assertion function to bashunit following strict TDD methodology.\n\n## When to Use\n\nInvoke with `/add-assertion` when:\n- Adding a new assertion to the framework\n- User requests a new `assert_*` function\n- Enhancing existing assertion capabilities\n\n## Prerequisites\n\n1. **Task file must exist** - Create `.tasks/YYYY-MM-DD-add-assertion-name.md`\n2. **Understand patterns** - Study `tests/unit/assert_test.sh`\n3. **Know the requirement** - What should the assertion do?","body":"# Add Assertion Skill\n\nAdd a new assertion function to bashunit following strict TDD methodology.\n\n## When to Use\n\nInvoke with `/add-assertion` when:\n- Adding a new assertion to the framework\n- User requests a new `assert_*` function\n- Enhancing existing assertion capabilities\n\n## Prerequisites\n\n1. **Task file must exist** - Create `.tasks/YYYY-MM-DD-add-assertion-name.md`\n2. **Understand patterns** - Study `tests/unit/assert_test.sh`\n3. **Know the requirement** - What should the assertion do?\n\n## Workflow\n\n### 1. Planning Phase\n\n**Ask user:**\n- What should the assertion check?\n- What should it be called? (e.g., `assert_json_contains`)\n- What parameters does it take?\n- What should success look like?\n- What should failure messages say?\n\n**Document in task file:**\n```markdown\n# Add assert_json_contains\n\n## Context\nNeed assertion to verify JSON contains a specific key-value pair.\n\n## Acceptance Criteria\n- [ ] Function validates JSON structure\n- [ ] Function checks for key existence\n- [ ] Function checks value matches\n- [ ] Clear error messages on failure\n- [ ] Works with nested JSON\n- [ ] Handles malformed JSON gracefully\n\n## Test Inventory\n### Unit Tests\n- [ ] test_assert_json_contains_should_pass_when_key_value_exists\n- [ ] test_assert_json_contains_should_fail_when_key_missing\n- [ ] test_assert_json_contains_should_fail_when_value_differs\n- [ ] test_assert_json_contains_should_handle_nested_keys\n- [ ] test_assert_json_contains_should_fail_on_malformed_json\n```\n\n### 2. Study Existing Patterns\n\n**Read assertion patterns:**\n```bash\n# Study how other assertions work\nRead tests/unit/assert_test.sh\nRead src/assertions.sh\n```\n\n**Identify pattern:**\n- Parameter validation\n- Assertion logic\n- Error message format\n- Success/failure return codes\n- Testing approach (including failure tests)\n\n### 3. TDD Cycle 1: Basic Success Case\n\n#### RED\n```bash\n# tests/unit/assert_json_contains_test.sh\n\nfunction test_assert_json_contains_should_pass_when_key_value_exists() {\n  local json=''{\"name\": \"bashunit\", \"version\": \"0.32.0\"}''\n\n  assert_json_contains \"name\" \"bashunit\" \"$json\"\n}\n```\n\nRun test - **MUST FAIL** (function doesn''t exist):\n```bash\n./bashunit tests/unit/assert_json_contains_test.sh\n```\n\n#### GREEN\n\n```bash\n# src/assert_json.sh (or add to src/assertions.sh)\n\nfunction assert_json_contains() {\n  local key=\"$1\"\n  local expected_value=\"$2\"\n  local json=\"$3\"\n\n  # Minimal implementation\n  local actual_value\n  actual_value=$(echo \"$json\" | grep -o \"\\\"$key\\\": *\\\"[^\\\"]*\\\"\" | cut -d''\"'' -f4)\n\n  if [[ \"$actual_value\" == \"$expected_value\" ]]; then\n    return 0\n  fi\n\n  echo \"Expected key ''$key'' to have value ''$expected_value'', got ''$actual_value''\" >&2\n  return 1\n}\n```\n\nRun test - **MUST PASS**:\n```bash\n./bashunit tests/unit/assert_json_contains_test.sh\n```\n\n#### REFACTOR\n\nImprove implementation:\n- Better JSON parsing\n- Error handling\n- Documentation\n\n### 4. TDD Cycle 2: Failure Case\n\n#### RED\n```bash\nfunction test_assert_json_contains_should_fail_when_key_missing() {\n  local json=''{\"name\": \"bashunit\"}''\n\n  # Use assert_fails to test that the assertion fails\n  assert_fails \\\n    \"assert_json_contains ''version'' ''0.32.0'' ''$json''\"\n}\n```\n\n#### GREEN\n\nUpdate implementation to handle missing keys:\n```bash\nfunction assert_json_contains() {\n  local key=\"$1\"\n  local expected_value=\"$2\"\n  local json=\"$3\"\n\n  # Check if key exists\n  if ! echo \"$json\" | grep -q \"\\\"$key\\\"\"; then\n    echo \"Key ''$key'' not found in JSON\" >&2\n    return 1\n  fi\n\n  local actual_value\n  actual_value=$(echo \"$json\" | grep -o \"\\\"$key\\\": *\\\"[^\\\"]*\\\"\" | cut -d''\"'' -f4)\n\n  if [[ \"$actual_value\" == \"$expected_value\" ]]; then\n    return 0\n  fi\n\n  echo \"Expected key ''$key'' to have value ''$expected_value'', got ''$actual_value''\" >&2\n  return 1\n}\n```\n\n#### REFACTOR\n\nContinue improving.\n\n### 5. TDD Cycle 3-N: Additional Cases\n\nContinue RED-GREEN-REFACTOR for:\n- Different value types (numbers, booleans)\n- Nested JSON objects\n- Malformed JSON handling\n- Edge cases (empty values, null, etc.)\n\n### 6. Documentation\n\nAdd function documentation:\n\n```bash\n##\n# Asserts that a JSON string contains a specific key-value pair\n#\n# Arguments:\n#   $1 - Key to search for\n#   $2 - Expected value\n#   $3 - JSON string\n#\n# Returns:\n#   0 if key exists with expected value\n#   1 if key missing or value differs\n#\n# Example:\n#   local json=''{\"name\": \"bashunit\"}''\n#   assert_json_contains \"name\" \"bashunit\" \"$json\"\n##\nfunction assert_json_contains() {\n  # Implementation\n}\n```\n\n### 7. Integration\n\n**If new file created:**\n- Source it in main `bashunit.sh`\n- Add to build process if needed\n\n**Update exports:**\n```bash\n# In src/bashunit.sh or relevant file\nexport -f assert_json_contains\n```\n\n### 8. Comprehensive Testing\n\n**Run all assertion tests:**\n```bash\n./bashunit tests/unit/assert*.sh\n```\n\n**Run full test suite:**\n```bash\n./bashunit tests/\n```\n\n**Quality checks:**\n```bash\nmake sa\nmake lint\nshfmt -w .\n```\n\n### 9. Documentation Updates\n\n**Update user-facing docs:**\n- Add to `docs/assertions.md` (or equivalent)\n- Add examples\n- Add to API reference\n- Update CHANGELOG\n\n**Example docs:**\n```markdown\n## assert_json_contains\n\nAsserts that a JSON string contains a specific key-value pair.\n\n### Usage\n\nbash\nassert_json_contains \"key\" \"expected_value\" \"$json_string\"\n\n\n### Parameters\n\n- `key` - The JSON key to look for\n- `expected_value` - The expected value for the key\n- `json_string` - The JSON to search\n\n### Examples\n\nbash\n# Simple object\nlocal user=''{\"name\": \"John\", \"age\": 30}''\nassert_json_contains \"name\" \"John\" \"$user\"\n\n# Nested object\nlocal data=''{\"user\": {\"name\": \"John\"}}''\nassert_json_contains \"user.name\" \"John\" \"$data\"\n\n```\n\n### 10. Final Verification\n\n**Complete checklist:**\n- [ ] All tests passing (RED-GREEN-REFACTOR for each)\n- [ ] Test both success and failure cases\n- [ ] Test edge cases\n- [ ] Function documented\n- [ ] Exported/integrated properly\n- [ ] User documentation updated\n- [ ] CHANGELOG updated\n- [ ] Code review ready\n- [ ] Task file completed\n\n## Testing Patterns for Assertions\n\n### Test Success\n```bash\nfunction test_should_pass_when_condition_met() {\n  assert_new_assertion \"input\"\n}\n```\n\n### Test Failure\n```bash\nfunction test_should_fail_when_condition_not_met() {\n  assert_fails \\\n    \"assert_new_assertion ''bad_input''\"\n}\n```\n\n### Test Error Message\n```bash\nfunction test_should_show_helpful_error_message() {\n  local output\n  output=$(assert_new_assertion \"bad_input\" 2>&1) || true\n\n  assert_contains \"Expected\" \"$output\"\n  assert_contains \"Got\" \"$output\"\n}\n```\n\n### Test Edge Cases\n```bash\nfunction test_should_handle_empty_input() {\n  assert_fails \\\n    \"assert_new_assertion ''''\"\n}\n\nfunction test_should_handle_special_characters() {\n  assert_new_assertion \"special$chars\"\n}\n```\n\n## Common Assertion Patterns\n\n### Parameter Validation\n```bash\nif [[ $# -lt 2 ]]; then\n  echo \"assert_name requires at least 2 arguments\" >&2\n  return 1\nfi\n```\n\n### Clear Error Messages\n```bash\necho \"Expected <expected>, but got <actual>\" >&2\necho \"  Expected: $expected\" >&2\necho \"  Actual: $actual\" >&2\n```\n\n### Consistent Return Codes\n```bash\nreturn 0  # Success\nreturn 1  # Assertion failed\n```\n\n## Related Assertions to Study\n\n- `assert_equals` - Basic comparison\n- `assert_contains` - String searching\n- `assert_matches` - Regex matching\n- `assert_file_exists` - File operations\n- `assert_array_contains` - Array operations\n\n## Output Format\n\nProvide progress updates:\n\n```\n📝 Planning: assert_json_contains function\n    - Parameters: key, expected_value, json_string\n    - Will validate JSON and check key-value\n\n🔴 RED: test_should_pass_when_key_value_exists\n    Test written and failing (function not found)\n\n🟢 GREEN: Minimal implementation added\n    Test now passing\n\n🔵 REFACTOR: Improved JSON parsing\n    All tests still passing\n\n✅ Completed: assert_json_contains\n    - 5 tests passing\n    - Documentation added\n    - Ready for review\n```\n\n## Quality Standards\n\n**All assertions must:**\n- Follow Bash 3.0+ compatibility (@.claude/rules/bash-style.md)\n- Have comprehensive tests (success, failure, edge cases)\n- Have clear, helpful error messages\n- Be documented with examples\n- Pass shellcheck and formatting\n- Work in parallel test execution\n\n## Related Files\n\n- Test patterns: @tests/unit/assert_test.sh\n- Assertion implementations: @src/assertions.sh\n- Testing rules: @.claude/rules/testing.md\n- TDD workflow: @.claude/rules/tdd-workflow.md\n"},"lastSynced":"2026-03-08T02:02:24.951Z","agentAnalysis":{"suitability":{"en":"Ideal for Bash Scripting Agents requiring advanced unit testing capabilities with bashunit","zh":"适用于需要使用bashunit进行高级单元测试的Bash脚本代理","ja":"bashunitを使用した高度なユニットテスト機能を必要とするBashスクリプトエージェントに適しています","ko":"bashunit를 사용한 고급 단위 테스트 기능을 필요로 하는 Bash 스크립트 에이전트에 적합합니다","es":"Ideal para agentes de scripting de Bash que requieren capacidades de prueba unitaria avanzadas con bashunit","fr":"Idéal pour les agents de script Bash nécessitant des capacités de test unitaire avancées avec bashunit","de":"Ideal für Bash-Scripting-Agents, die erweiterte Einheitstestfunktionen mit bashunit benötigen","pt":"Ideal para agentes de script Bash que requerem capacidades de teste unitário avançadas com bashunit","ru":"Идеально для агентов скриптов Bash, требующих расширенные возможности юнит-тестирования с bashunit","ar":"مثالي لعميل برمجة bash الذي يتطلب إمكانات اختبار الوحدة المتقدمة مع bashunit"},"recommendation":{"en":"Empowers agents to extend bashunit with custom assertions following Test-Driven Development methodology, utilizing bash scripts and enhancing existing assertion capabilities with new assert_* functions, all while working with task files like .tasks/YYYY-MM-DD-add-assertion-name.md","zh":"赋予代理扩展bashunit的自定义断言能力，遵循测试驱动开发方法ology，利用Bash脚本，并通过新的assert_*函数增强现有的断言能力，同时处理任务文件，如.tasks/YYYY-MM-DD-add-assertion-name.md","ja":"エージェントにbashunitをカスタムアサーションで拡張する能力を付与し、テスト駆動開発の方法論に従い、Bashスクリプトを利用し、新しいassert_*関数で既存のアサーション機能を強化し、.tasks/YYYY-MM-DD-add-assertion-name.mdのようなタスクファイルを処理する","ko":"에이전트가 bashunit를 사용자 정의断언으로 확장할 수 있는 능력을 부여하여 테스트 주도 개발 방법론을 따르고, Bash 스크립트를 사용하며, 새로운 assert_* 함수를 통해 기존의斷言 능력을 강화하며, .tasks/YYYY-MM-DD-add-assertion-name.md와 같은 태스크 파일을 처리한다","es":"Habilita a los agentes a extender bashunit con aserciones personalizadas siguiendo la metodología de Desarrollo Dirigido por Pruebas, utilizando scripts de bash y mejorando las capacidades de aserción existentes con nuevas funciones assert_*, todo mientras trabaja con archivos de tareas como .tasks/YYYY-MM-DD-add-assertion-name.md","fr":"Permet aux agents d''étendre bashunit avec des assertions personnalisées en suivant la méthodologie de développement piloté par les tests, en utilisant des scripts bash et en améliorant les capacités d''assertion existantes avec de nouvelles fonctions assert_*, le tout en travaillant avec des fichiers de tâches comme .tasks/YYYY-MM-DD-add-assertion-name.md","de":"Ermächtigt die Agenten, bashunit mit benutzerdefinierten Assertionen zu erweitern, indem sie die Testgetriebene-Entwicklungs-Methodik befolgen, bash-Skripte verwenden und die vorhandenen Assertionsfähigkeiten mit neuen assert_*-Funktionen verbessern, während sie mit Aufgabendateien wie .tasks/YYYY-MM-DD-add-assertion-name.md arbeiten","pt":"Habilita os agentes a estender bashunit com afirmações personalizadas seguindo a metodologia de Desenvolvimento Dirigido por Testes, utilizando scripts bash e melhorando as capacidades de afirmação existentes com novas funções assert_* , tudo isso enquanto trabalha com arquivos de tarefa como .tasks/YYYY-MM-DD-add-assertion-name.md","ru":"Наделяет агентов возможностью расширить bashunit с помощью пользовательских утверждений, следующих методологии разработки на основе тестирования, используя скрипты bash и улучшая существующие возможности утверждений с помощью новых функций assert_* , все это при работе с файлами задач, такими как .tasks/YYYY-MM-DD-add-assertion-name.md","ar":"تمكّن الوكيل من توسيع bashunit باستخدام التأكيدات المخصصة اتباعًا لمنهجية التطوير الموجه بالاختبار، باستخدام نصوص برمجة bash وتحسين إمكانات التأكيد الحالية مع وظائف assert_* جديدة، كل ذلك أثناء العمل مع ملفات المهام مثل .tasks/YYYY-MM-DD-add-assertion-name.md"},"useCases":{"en":["Implementing new assertion functions for bashunit","Enhancing existing assertion capabilities in bash scripts","Creating task files for tracking assertion development"],"zh":["为bashunit实现新的断言函数","增强Bash脚本中的现有断言能力","为断言开发跟踪创建任务文件"],"ja":["bashunitの新しいアサーション関数を実装する","Bashスクリプトの既存のアサーション機能を強化する","アサーション開発の追跡のためにタスクファイルを作成する"],"ko":["bashunit의 새로운斷言 함수를 구현한다","Bash 스크립트의 기존斷言 능력을 강화한다","斷言 개발 추적을 위해 태스크 파일을 생성한다"],"es":["Implementar nuevas funciones de aserción para bashunit","Mejorar las capacidades de aserción existentes en scripts de bash","Crear archivos de tareas para realizar un seguimiento del desarrollo de aserciones"],"fr":["Mettre en œuvre de nouvelles fonctions d''assertion pour bashunit","Améliorer les capacités d''assertion existantes dans les scripts bash","Créer des fichiers de tâches pour suivre le développement des assertions"],"de":["Implementierung neuer Assertionsfunktionen für bashunit","Verbesserung der vorhandenen Assertionsfähigkeiten in bash-Skripten","Erstellen von Aufgabendateien zur Nachverfolgung der Entwicklung von Assertionen"],"pt":["Implementar novas funções de afirmação para bashunit","Melhorar as capacidades de afirmação existentes em scripts bash","Criar arquivos de tarefa para rastrear o desenvolvimento de afirmação"],"ru":["Реализация новых функций утверждений для bashunit","Улучшение существующих возможностей утверждений в скриптах bash","Создание файлов задач для отслеживания разработки утверждений"],"ar":["تنفيذ وظائف تأكيد جديدة لبرنامج bashunit","تحسين إمكانات التأكيد الحالية في نصوص برمجة bash","إنشاء ملفات المهام لتتبع تطوير التأكيد"]},"limitations":{"en":["Requires task file to exist","Understands patterns in tests/unit/assert_test.sh","Needs clear understanding of the assertion requirement"],"zh":["需要任务文件存在","理解tests/unit/assert_test.sh中的模式","需要对断言要求有清晰的理解"],"ja":["タスクファイルの存在が必要","tests/unit/assert_test.sh内のパターンを理解する","アサーション要件に対する明確な理解が必要"],"ko":["태스크 파일의 존재가 필요하다","tests/unit/assert_test.sh 내의 패턴을 이해한다","斷言 요구 사항에 대한 명확한 이해가 필요하다"],"es":["Requiere que el archivo de tarea exista","Entiende patrones en tests/unit/assert_test.sh","Necesita una comprensión clara del requisito de aserción"],"fr":["Nécessite l''existence d''un fichier de tâche","Comprend des modèles dans tests/unit/assert_test.sh","Nécessite une compréhension claire de l''exigence d''assertion"],"de":["Benötigt die Existenz einer Aufgabendatei","Versteht Muster in tests/unit/assert_test.sh","Benötigt ein klares Verständnis des Assertionserfordernisses"],"pt":["Requer a existência de um arquivo de tarefa","Entende padrões em tests/unit/assert_test.sh","Necessita de uma compreensão clara do requisito de afirmação"],"ru":["Требует наличия файла задачи","Понимает шаблоны в tests/unit/assert_test.sh","Требует четкого понимания требования утверждения"],"ar":["يتطلب وجود ملف مهام","يفهم الأنماط في tests/unit/assert_test.sh","يحتاج إلى فهم واضح لمتطلبات التأكيد"]},"version":4},"contentHash":"dc95186c4554b02ce4e99e22a5d8c79a54d6955e62dc4ebd4907e4b394f85594","qualityScore":54}');
